-- Hissələri istənilən ardıcıllıqla, istənilən qədər təkrar işlətmək təhlükəsizdir.
-- Cəmi: 12258 UPDATE, 13 hissə
-- ============================================================

UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже умеет одновременно сортировать предметы по двум признакам — например, по цвету и форме. Если на просьбу «Дай мне все маленькие красные машинки» он правильно выбирает их, это говорит о новом этапе когнитивного развития. Во время повседневных домашних дел давайте ему небольшие задания на сортировку.') WHERE id = 'ff1dcdb3-fd81-4345-80ce-058e6b7a0d6b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Прыжки в цель» для физического развития. Ребёнок уже старается прыгнуть в центр нарисованного на земле круга или цветной мишени. Это развивает равновесие и умение оценивать расстояние в пространстве. Поиграйте с ним в парке в «прыжки с камня на камень».') WHERE id = '5d8b4009-8971-48b6-aa55-75a96a823d2d';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Расширение словаря антонимов» в речи. Ребёнок уже понимает такие абстрактные противоположности, как «быстро-медленно», «тёмный-светлый», «пустой-полный». Покажите ему пустой и полный стаканы и спросите, чем они отличаются. Это развивает его способность сравнивать и анализировать окружающий мир.') WHERE id = '18232b0a-482a-40e1-90c7-8a04a56dc3b9';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Мастерство сборки пазлов» в развитии мелкой моторики. Ребёнок уже может собирать сложные пазлы из 10-12 деталей, различая края и центр изображения. Это развивает зрительную память и способность пальцев выполнять точные движения. Если у него не получается, спокойно подсказывайте ему.') WHERE id = '3045e148-b927-4872-8354-b9edb5116d18';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Самостоятельная уборка и помощь». Ребёнок уже с большим энтузиазмом помогает убирать со стола: относит свою тарелку и вытирает крошки. Дайте ему принадлежности для уборки, подходящие по росту. Это укрепляет чувство ответственности и причастности к семейным делам. Возможность увидеть результат собственного труда делает его очень счастливым.') WHERE id = '5fed215f-7140-471a-887f-855f666792ab';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Правила и границы» в социальном поведении. Ребёнок уже немного лучше понимает, почему вы говорите «нет», но по-прежнему любит проверять границы дозволенного. Ваши терпение и последовательность дают ему чувство безопасности. Старайтесь всегда придерживаться одних и тех же правил.') WHERE id = 'ad322e7c-2c29-48c7-ba0d-376889e0bc86';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Познавательное развитие: «Порядковые числительные». Ребёнок уже понимает значения слов «первый», «второй», «последний». Расставьте машинки в ряд и спросите: «Какая машинка первая?». Это развивает понимание последовательности и математическую логику. А слова «Ты пришёл первым!» во время соревнований станут для него отличной мотивацией.') WHERE id = 'ccdeb036-ba4e-49c8-960c-f4271e0fc740';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Ходьба спиной вперёд и боком». Ребёнок уже может ловко двигаться в разных направлениях. Поиграйте с ним в «Зеркало»: сделайте шаг в сторону, а он пусть повторит за вами. Это не только весело, но и помогает вывести координацию движений на новый уровень.') WHERE id = '53f08fbe-8240-4c06-91f5-3a6645fa77af';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Развитие речи: «Углубление абстрактных вопросов». Ребёнок может удивить вас такими вопросами, как «Куда плывут облака?» или «Почему звёзды появляются ночью?». Отвечая, подключайте и его воображение: «Как ты думаешь, что сейчас делают звёзды?». Это стимулирует его творческое мышление.') WHERE id = 'ca368c4f-966b-4846-b9ca-ff68822b1eca';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Радость от умения делиться». Когда ребёнок по собственной воле делится игрушкой или сладостью, он видит вашу радость и хочет повторить это снова. Обязательно подчеркните его щедрость, сказав: «Большое спасибо, что порадовал друга». Мы успешно завершили 1140 дней — вы замечательная мама!') WHERE id = '706c863b-0328-4280-9ae2-b61f0dddff18';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Мы вступаем в 39-й месяц! Ребёнок уже переходит от «двухэтапного» мышления к выполнению «трёхэтапных» заданий. Если на просьбу «Возьми игрушку, положи её в коробку и закрой крышку» он выполняет все действия в правильной последовательности, это большое достижение его рабочей памяти (working memory). В течение дня давайте ему небольшие логичные задания, состоящие из нескольких последовательных действий, чтобы совершенствовать этот навык.') WHERE id = '0f30e0b2-fa18-4fe2-8164-072ae2911569';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая активность: «Быстрый бег и маневрирование». Во время бега ребёнок уже может увидеть препятствие и обогнуть его, не снижая скорости. Это показывает, что чувство собственного тела (proprioception) у него хорошо развито. Устраивайте в парке забеги с препятствиями, чтобы направить его энергию в полезное русло.') WHERE id = 'c69b10fa-3ecf-43fd-9d25-d70589994cb8';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Развитие речи: «Степени сравнения». Ребёнок уже уместно использует такие выражения, как «больше», «самый маленький», «очень вкусный». Разговаривайте с ним, сравнивая предметы: «Какое яблоко слаще — это или другое?». Освоение степеней сравнения прилагательных обогащает описательную речь и помогает точнее выражать мысли.') WHERE id = '10874a8b-618a-44ed-9a23-9c2c3bcf6530';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Мелкая моторика: «Лепка». Работая с пластилином или кинетическим песком, ребёнок уже не просто сжимает их, а создаёт узнаваемые формы — «шарик», «змейку» или «хлеб». Это отличное упражнение для развития творческого мышления и укрепления мелких мышц пальцев.') WHERE id = '8ef81138-3a54-4c5e-ab33-5ab135be888d';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Самостоятельное одевание: где лицевая сторона, а где изнанка». Ребёнок уже пытается определить, где у футболки или брюк лицевая сторона, а где изнанка, а также различать правый и левый ботинок, хотя иногда ещё ошибается. Давайте ему небольшие подсказки: «Посмотри, сторона с рисунком должна быть спереди». Это развивает внимание к деталям и совершенствует навыки самообслуживания.') WHERE id = '0d252040-b7cf-42d1-8e5c-b4a1ea436608';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Командный дух» в социальном поведении. Ребёнок уже может играть вместе с другими детьми ради общей цели — например, строить большую крепость. Это переход от «параллельной игры» к «совместной игре». Наблюдайте, как он находит общий язык с другими детьми, а в сложные моменты помогайте ему выстраивать социальные «мостики».') WHERE id = 'b59f81d2-048d-48f5-8c51-231cd1498118';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Соответствие числа и количества» в познавательном развитии. Ребёнок умеет считать от 1 до 5, а увидев цифру «3», уже может выбрать и отложить 3 игрушки. Это один из важнейших этапов развития математического мышления. Укрепляйте эту связь в повседневной жизни с помощью заданий вроде: «Дай мне 2 ложки».') WHERE id = '5b8b658c-3ba9-46dd-b7e1-a329bde32c59';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Ловля брошенного сверху мяча». Ребёнок уже пытается поймать обеими руками большой мяч, который медленно бросают в его сторону. Это движение требует зрительно-моторной координации и быстрой реакции. Поиграйте с ним в мяч с близкого расстояния, бросая его друг другу.') WHERE id = '9cbfafe8-e2d3-4b4c-a7dd-a7d50a0d73a4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Пик абстрактных вопросов» в развитии речи. Ребёнок уже задаёт вопросы о мире и природных явлениях: «Почему дует ветер?», «Куда солнышко уходит спать?». Отвечая, подключайте воображение: «Солнышко устало и идёт отдыхать, чтобы завтра снова нас разбудить». Это расширяет его кругозор и поддерживает стремление к познанию.') WHERE id = 'be40f099-56c3-42b3-90d0-8aec32c8e2ca';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная зрелость: «Признание эмоций другого человека». Ребёнок уже замечает, когда вы устали или другому ребёнку больно, спрашивает: «Что случилось?» — и пытается утешить. Это показывает, что он растёт чутким и сострадательным человеком. Вы замечательная мама!') WHERE id = '28850826-f8da-4cde-a0f3-c10d2981e7f4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже проверяет понятия «я» и «моё» в общении с другими. Если он не хочет делиться игрушкой, это скорее не эгоизм, а попытка обозначить свои границы. Покажите, что уважаете его право собственности, сказав: «Это твоя игрушка, и ты сможешь дать её другу, когда будешь готов». Благодаря этому в будущем он научится уважать и границы других людей.') WHERE id = '3d0a961f-8311-4c15-82e4-3b93885267b5';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Прыжок с высоты» в развитии двигательной активности. Ребёнок уже любит спрыгивать с невысокой ступеньки или возвышения, приземляясь одновременно на обе ноги. Это движение важно для развития его вестибулярной системы. Положите на пол мягкий коврик, чтобы безопасно поддержать его смелость.') WHERE id = '0680b361-8e77-46ad-a0ea-0e96e9759bdc';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Уточнение будущего времени» в речи. Ребёнок уже не просто говорит «мы пойдём», а строит последовательные планы, например: «Завтра мы пойдём к бабушке и поиграем с кошкой». В конце дня обсуждайте с ним планы на завтра. Это развивает способность заранее представлять события и планировать их (исполнительные функции).') WHERE id = 'e7723585-78f9-489b-95f6-9d306c6417b7';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Более сложные фигуры» в развитии мелкой моторики. Ребёнок уже держит карандаш почти как взрослый (трёхпальцевым захватом) и пытается нарисовать на бумаге треугольник или пересекающиеся линии. Это показывает, что мышцы его руки уже почти готовы к письму. Предложите ему игру «Давай соединим точки».') WHERE id = '23c81011-ddf7-4cf3-aec3-f115d29c3f5e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Самостоятельная гигиена: чистка зубов». Ребёнок уже знает последовательность действий при чистке зубов. Хотя в конце вам всё ещё нужно всё проверить, позвольте ему справляться самостоятельно. Этот навык развивает ответственность за заботу о собственном теле.') WHERE id = '94615e85-6da2-44c7-a201-6901c2a92ddf';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Воображаемые истории и ложь» в социальном поведении. Иногда ребёнок может рассказывать о том, чего не было на самом деле (например: «Я летал по небу»). Это не обман, а проявление воображения через речь. Поддержите его фантазию словами «Какая интересная история!», но при этом мягко объясните тонкую разницу между реальностью и вымыслом.') WHERE id = 'd70b5fda-77b6-4fb1-bc69-d894fe21ca89';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Углубление категорий» в познавательном развитии. Ребёнок уже не просто называет предмет «машиной», а выделяет подкатегории: «быстрая машина», «грузовая машина». Предложите ему эксперимент: «Какие предметы плавают в воде, а какие тонут?». Это закладывает основу навыков научного наблюдения.') WHERE id = '164e0d4f-5849-466c-88ec-e6961c6d0680';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Ведение мяча ногами». Ребёнок уже не просто бьёт по мячу, а пытается двигаться вместе с ним, слегка подталкивая его ногой вперёд. Это отличное упражнение для развития динамического равновесия. Устройте вместе с ним в парке небольшую «футбольную дорожку».') WHERE id = 'c019ed6e-efde-47c2-b2ac-37c3fbd433b5';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Разнообразие прилагательных» в речи. Описывая предметы, ребёнок начинает использовать такие слова, как «мягкий», «колючий», «гладкий», «блестящий». Поиграйте с ним в игру «Потрогай и угадай»: попросите его закрыть глаза, потрогать предмет и описать свои ощущения.') WHERE id = '0b5835ed-17d3-46e9-b2cd-eb9c92154c53';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Помощь другому». Ребёнок уже может заметить, что вам трудно что-то сделать или вы что-то ищете, и предложить помощь. Это показывает, что он выходит из эгоцентрического периода и становится настоящим «социальным партнёром». Обязательно подчеркните ценность его помощи словами: «Без тебя я бы не смогла это найти».') WHERE id = '95ef23e6-3a1e-4eb7-bed7-103fc452a1e2';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже начинает мыслить с учётом последствий. Например, с вашей подсказкой он пытается понять причинно-следственные связи: «Если я съем сладкое, у меня могут заболеть зубы». В этот период очень важно объяснять ему причины правил. Так у него формируется не слепое подчинение, а дисциплина, основанная на внутренней логике.') WHERE id = '602eea29-96df-4d75-b3f3-a89b088efbe3';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Динамическое равновесие» в двигательной активности. Ребёнок уже может пройти, словно канатоходец, по начерченной на земле прямой линии или по верёвке, не теряя равновесия. Это указывает на зрелость вестибулярной системы. Прогулки с ним по бордюрам в парке (держа его за руку) помогут ещё лучше отточить этот навык.') WHERE id = '5465b5ac-4749-433f-99e1-222fda8c10bf';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Подробности событий» в речи. Ребёнок уже может рассказать о произошедшем с ним за день событии с помощью 4-5 последовательных предложений. «Сегодня мы ходили в парк, я увидел Эльджана, мы играли с песком». Внимательно слушайте его рассказы и расширяйте диалог вопросом: «А что было потом?». Это развивает его слухоречевую память и беглость речи.') WHERE id = '7607f78f-a199-4155-af72-552bbd09b140';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«От круга к символам» в мелкой моторике. Ребёнок уже рисует замкнутые круги и добавляет к ним снизу линии, изображая «человечка» (человечка из палочек). Это начало развития визуального символизма. Дайте ему цветные карандаши и стимулируйте воображение вопросом: «Кого ты сегодня рисуешь?».') WHERE id = 'ead2dac9-db7b-47ae-9b92-23aa29cddd39';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Самостоятельное одевание: пуговицы и молния». Ребёнок уже стремится самостоятельно застёгивать крупные пуговицы и молнию. Это требует координации мелких мышц пальцев. Утром во время одевания дайте ему дополнительные 5 минут, чтобы он завершил этот процесс сам. Чувство гордости, которое он испытывает, справившись самостоятельно, бесценно.') WHERE id = '24f54158-6d74-423e-b96c-5270e549d121';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Ожидание своей очереди и терпение» в социальном поведении. Ребёнок уже понимает, что, прежде чем покачаться на качелях, нужно подождать, пока другой ребёнок с них слезет. Понимание фраз «Твоя очередь» и «Моя очередь» помогает уменьшить конфликты в социальной среде. Обязательно похвалите его за терпение, сказав: «Большое спасибо, что дождался своей очереди».') WHERE id = '97f18e0c-30d0-42a5-aa90-ac6015233d99';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Восприятие количества» в познавательном развитии. Ребёнок уже не только умеет считать от 1 до 10, но и может без пересчёта, с первого взгляда, определить 3 или 4 предмета (субитизация). Спросите его: «Сколько здесь яблок?» — и попросите посчитать их, показывая пальцем. Это основа будущего математического мышления.') WHERE id = '6e61f63b-18f2-4f84-b98e-0d07b524e3e9';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Ловля мяча двумя руками». Ребёнок уже начинает ловить медленно брошенный в его сторону мяч, сгибая руки и прижимая кисти к груди. Это свидетельствует о развитии скорости реакции и зрительно-моторной координации. Устраивайте с ним дома небольшие игры в мяч, используя мягкий мяч.') WHERE id = 'eb5816aa-f53e-4699-abf2-d1ff0b98f5f9';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В речи — "Абстрактные понятия: время". Хотя ребёнок ещё не понимает вопрос "который час?", он старается правильно употреблять такие слова, как "завтра", "вчера", "потом". Объясняйте ему время через привычные ритуалы: "Когда проснёшься, наступит завтра". Это помогает ему воспринимать мир как более упорядоченный и предсказуемый.') WHERE id = '6c159ac6-63d6-41de-9c9e-e48fdddeeaef';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: "Не бояться неудач". Если у ребёнка что-то не получается (например, построить башню из кубиков), он уже не сразу начинает плакать, а может посмотреть на вас и спросить: "Попробовать ещё раз?" Хвалите не результат, а его старания: "Ты очень старался и попробовал снова, молодец!" Вы — замечательный спутник на его пути!') WHERE id = '487ce40e-d1a5-42bb-ab35-fd94c37e1b74';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже выражает свои чувства более сложно: "Мне грустно, потому что моя игрушка сломалась". Это большой скачок в развитии эмоционального интеллекта. Не просто принимайте его чувства, но и дайте ему возможность предложить решение: "Как ты думаешь, как мы можем это починить?" Это также развивает у него жизнестойкость.') WHERE id = '72c6a670-175e-4e59-a40a-08a5b3924e43';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В физической активности — "Прыжки в сторону". Ребёнок уже умеет прыгать не только вперёд, но и вбок. Для этого требуется скоординированная работа мышц бёдер и ног в разных направлениях. Устройте с ним соревнование по "боковым прыжкам" через начерченные на полу линии.') WHERE id = '7ad7a096-5914-4eed-80cb-8089f672c249';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В речи — "Полное освоение местоимений". Ребёнок уже не путает понятия "моё", "твоё" и "его". Говоря: "Это моя игрушка, а та — твоя", он обозначает социальные границы владения. Сейчас прекрасное время, чтобы объяснить ему разницу между общими вещами (например, семейной книгой) и личными вещами.') WHERE id = '2b8c7b62-f908-41ef-8972-07466c4a7bd0';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В мелкой моторике — "Попытки соблюдать симметрию". Ребёнок старается складывать бумагу или симметрично располагать детали на своём рисунке. Например, рисуя человека, он добавляет уши или руки с обеих сторон. Это показатель скоординированного развития обоих полушарий мозга.') WHERE id = 'bd356611-73c3-4619-9883-1f920ac53fa9';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '"Самостоятельное поведение за столом". Ребёнок уже умело пользуется вилкой и пытается резать мягкие продукты (например, банан или омлет) ножом (безопасным детским ножом). Предоставьте ему эту самостоятельность. Умение обслуживать себя укрепляет его уверенность в себе изнутри.') WHERE id = 'a07fbd02-0c2f-49de-ba5e-43f31c0bcc20';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В социальном поведении — "Игры по правилам". Ребёнок уже проявляет интерес к играм с простыми правилами, таким как "Прятки" или "Догонялки", и старается не нарушать их. Это важный этап социальной адаптации. Когда он соблюдает правила, обязательно похвалите его: "Молодец, что играешь честно".') WHERE id = 'e172dbdc-63ea-4b2b-afac-30588be411eb';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Познавательное развитие: «Сравнение по высоте и длине». Малыш уже может расставлять предметы по высоте. Дайте ему 3-4 игрушки разного размера и попросите: «Расставь их от самой высокой до самой низкой». Это развивает его зрительное восприятие и способность выстраивать логическую последовательность.') WHERE id = '3281647e-af83-48c8-9e0e-9deebd826a8f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Маневрирование на трёхколёсном велосипеде». Во время езды малыш уже может заметить препятствие впереди, повернуть руль и объехать его. Это сочетание умения крутить педали (физический навык) и следить за дорогой (зрительный навык). Поддержите развитие этого умения, организовав для него в парке безопасную «дорожку для катания».') WHERE id = 'cccc4e73-bd8f-49ce-ac37-8b06ba255913';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Время и последовательность» в речи. Малыш уже строит планы на будущее, например: «Завтра мы пойдём к бабушке, а потом я пойду в парк». Это свидетельствует о развитии способности заранее представлять события (визуализация). В конце дня рассказывайте вместе о планах на завтра как о «сказке» перед сном.') WHERE id = '533647bf-c77f-434e-8420-bd22239f3086';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Терпение и ожидание». Малыш уже понимает, что необходимость несколько минут подождать своей очереди — это не «конец света», а лишь временная ситуация. Это признак развития навыков саморегуляции (исполнительных функций). 1180 дней — ваш малыш уже маленькая личность, которая понимает мир и приспосабливается к нему. Вы — замечательный спутник на его пути!') WHERE id = 'fe96ce06-9654-4a3f-8b50-d93363f0cbca';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Малыш уже описывает себя через свои физические особенности: «Я быстро бегаю» или «Я высокий». Это новый уровень самосознания. Поддерживайте его положительное представление о себе. Задавайте вопросы о том, каким он себя видит: «Как ты думаешь, что ещё у тебя хорошо получается?».') WHERE id = '4f2b9702-c295-43cf-9776-2d9fd4b98c79';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Динамические прыжки» в физическом развитии. Малыш уже может на бегу перепрыгнуть небольшое препятствие на пути (например, лежащую на земле верёвку), не снижая скорости. Это свидетельствует о развитии способности мозга заранее планировать движения (моторное планирование).') WHERE id = '63d363dc-9356-4fa8-bbd3-57a0c8ed1083';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Целенаправленные вопросы» в речи. Теперь малыш спрашивает не только «Что это?», но и «Как это работает?». Он интересуется внутренним устройством предметов. Отвечая, не углубляйтесь в излишне сложные подробности, но сохраняйте логическую последовательность. Такие вопросы — первые искры будущего научного мышления.') WHERE id = 'fda8c637-494b-4891-b635-d2a91f4dbd7b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Сочетание форм» в развитии мелкой моторики. Малыш уже не просто рисует круги, а соединяет их, создавая «гусеницу» или «снеговика». Это показывает его способность объединять визуальные символы и создавать новые смыслы.') WHERE id = 'c2392a7c-85eb-4d9e-aff3-15371b541a80';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Политические» переговоры. Ребёнок уже начинает с вами «торговаться»: «Если я уберу свои игрушки, ты прочитаешь мне ещё одну сказку?». Это показывает, что он осваивает механизмы социального влияния. Будьте справедливы в таких «переговорах», но придерживайтесь основных правил.') WHERE id = '1c3607b2-8132-49bc-b9ba-d3f310a2378b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Воображаемые сценарии» в социальном поведении. Теперь игры становятся сложнее: «Я повар, а ты посетитель и должен заплатить мне». В таких играх ребёнок примеряет на себя общественные роли и знакомится с экономическими отношениями. Подыгрывайте его сценариям, чтобы стимулировать этот творческий процесс.') WHERE id = '74c3e2b6-b59d-47f7-ac39-b3a6571a3f4e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Функции предметов» в познавательном развитии. Ребёнок уже группирует предметы не только по внешнему виду, но и по назначению. «Это режущие инструменты (ножницы, нож)», «А это письменные принадлежности». Это показывает, что информация в его мозге становится более систематизированной и упорядоченной по функциям.') WHERE id = '78693b6d-347d-4486-94dc-37e920221a4d';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Самостоятельность на лестнице». Ребёнок уже уверенно поднимается по лестнице, поочерёдно ставя на каждую ступеньку одну ногу и почти ни за что не держась. Это свидетельствует о высоком уровне развития равновесия и силы мышц ног.') WHERE id = 'cc0be0ea-ed32-4ad7-a00e-446a9d717d47';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Период «Потому что» в развитии речи. Ребёнок пытается объяснять свои действия: «Я не буду это надевать, потому что оно мне колется». Прислушивайтесь к его «потому что». Это укрепляет его способность разумно выражать свои потребности и сообщать о дискомфорте.') WHERE id = '1172f061-c7e1-4517-8b34-e51a76cdf51e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Умение радоваться чужому успеху». Ребёнок уже может сказать «Молодец!», когда видит ваш успех или успех своего друга (например, победу в игре). Это свидетельствует об уменьшении эгоцентризма (сосредоточенности только на себе) и зарождении умения разделять радость других. Вы растите замечательную личность!') WHERE id = 'e58983bd-cd78-4d0a-8590-e07b73fa9e05';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже задаёт вопросы «Почему?» не просто ради ответа, а чтобы понять причинно-следственные связи. Его интерес к природным явлениям растёт, и он спрашивает, например: «Почему листья падают на землю?». Давайте ему простые ответы, основанные на научных фактах. Это формирует у него аналитический взгляд на окружающий мир.') WHERE id = '8335f345-0d57-482d-b821-779e730295ca';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Мастерское равновесие» в физической активности. Ребёнок уже уверенно идёт по узкой тропинке или лежащей на полу верёвке, сохраняя равновесие. Это высокий этап развития вестибулярной системы. Играйте с ним дома в «Канатоходца», чтобы повысить точность движений.') WHERE id = '00cce1f4-ca47-462d-b84a-6205502d4f13';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Единство прошлого и будущего» в речи. Ребёнок правильно использует в одном предложении разные времена, например: «Вчера я ходил в парк, а завтра пойду к бабушке». Чтобы закрепить понимание времени, продолжайте напоминать ему о ежедневных ритуалах в последовательности «сначала, сейчас, потом».') WHERE id = '10538e9b-c203-4dd2-8b24-d807c72fa3fb';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Детализированное изображение человека» в развитии мелкой моторики. Рисуя «человечка из палочек», ребёнок теперь добавляет больше деталей: пальцы, волосы или глаза. Это показывает, насколько развились его зрительная наблюдательность и зрительно-моторная координация.') WHERE id = 'e534e280-1b5b-4f3e-b1db-79a0cf64e3af';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Соблюдение личных границ». Ребёнок уже обозначает своё личное пространство словами «Моя комната», «Мой стол». Уважайте его ощущение личного пространства. Спрашивая: «Можно войти в твою комнату?», вы учите его уважать личные границы и в будущем признавать границы других людей.') WHERE id = '19704700-4f78-4a2f-8063-e34e01705522';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Чувство справедливости» в социальном поведении. Ребёнок уже реагирует на нарушение правил в играх: «Он влез без очереди!». Это свидетельствует о развитии его представлений о социальной справедливости и правилах. Объясняйте ему, почему правила важны, например чтобы игра оставалась интересной. Так вы закладываете основы социально ответственного поведения.') WHERE id = 'bb50baca-3306-43e8-84f0-8ecfe4ce2ed7';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Связь количества и числа» в познавательном развитии. Ребёнок умеет считать до 10, а теперь начинает соотносить числа с количеством. Когда вы говорите: «Я положила сюда 5 орехов», он может визуально оценить их количество. В повседневных делах давайте ему задания, например: «Дай мне 4 ложки».') WHERE id = '3b180a00-84f2-4ef7-b180-bb007866d4c3';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Скорость на трёхколёсном велосипеде». Ребёнок уже увереннее разгоняется на велосипеде и маневрирует, объезжая препятствия. Это свидетельствует о высоком уровне развития мышц нижней части тела и зрительно-моторной координации. Обозначьте для него в парке безопасные «дорожки для катания», чтобы он мог испытать свою скорость.') WHERE id = 'cf35973e-cf99-454b-b4d7-5058e5466945';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Шутки и юмор» в речи. Ребёнок уже играет со словами и пытается рассмешить вас, составляя «странные» предложения. Например, он может сказать: «Собака сказала “мяу”» — и засмеяться. Это показывает, что он знает языковые нормы и намеренно нарушает их, чтобы создать комический эффект. Смейтесь вместе с ним и развивайте его чувство юмора.') WHERE id = '7856919f-0f1f-4c55-9554-5d9226e933f6';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Большое путешествие длиной в 1200 дней! Ребёнку уже исполнилось 40 месяцев. Теперь он — самостоятельная личность, маленький человек со своими мыслями, шутками и мечтами. На протяжении этих 1200 дней вы создавали его мир. В его уверенном взгляде — отпечаток вашей любви. Вы замечательная мама!') WHERE id = '1104a81e-20a0-469a-b38d-bffb8442b875';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Добро пожаловать в 41-й месяц! В этот период у ребёнка формируется понимание «намерения». Он уже начинает различать, произошло ли что-то случайно или было сделано намеренно. Например, если кто-то его заденет, он может спросить: «Ты сделал это специально?». Это важный этап в понимании честности и намерений в социальных отношениях.') WHERE id = 'be82050e-9ad6-486e-9d98-a2c2c31a243e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая активность: «Прыжки на одной ноге». Ребёнок уже пытается несколько раз подряд подпрыгнуть на одной ноге. Для этого нужны как сила, так и хорошо развитое равновесие. Поддержите развитие этого навыка, играя с ним в парке в «соревнование по прыжкам на одной ноге».') WHERE id = '59f9bda8-ddf4-49be-ad49-7ae815287273';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Речь: «Логические союзы». Ребёнок уже умело использует в предложениях союзы «но», «потому что», «если». «Я хочу пойти в парк, но на улице дождь». Это говорит о его способности объединять противоречивые мысли. Продлевайте диалоги с ним, используя эти союзы.') WHERE id = 'b5dc9cdd-e5bc-4c21-ba9e-2e9fe7dbdaee';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Мелкая моторика: «Разрезание бумаги». Ребёнок уже умеет резать бумагу безопасными ножницами, следуя по прямой линии. Это свидетельствует о высоком уровне зрительно-моторной координации. Дайте ему цветную бумагу и шаблоны для вырезания и наклеивания (аппликаций).') WHERE id = '93689350-75d1-4dc3-befa-2516fff9cb92';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Саморегуляция (Self-regulation)». Когда ребёнок злится или расстраивается, он уже может использовать предложенные вами способы, чтобы успокоиться (например, глубоко подышать или обнять любимую игрушку). Это один из важнейших жизненных навыков эмоционального интеллекта.') WHERE id = 'cad2a6f6-14d3-4ac8-a455-240edf668e56';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Социальное поведение: «Командные игры по правилам». Ребёнок уже проявляет интерес к играм в группе по общим правилам. Когда вы говорите: «А теперь мы все прыгаем как зайчики», он подстраивается под команду. Это основа важного для школьной среды умения действовать в группе.') WHERE id = '6f7c2344-f4ee-4701-9810-594e0c930fc0';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Познавательное развитие: «Визуализация времени». Ребёнок уже может последовательно ответить на вопрос: «Что мы делали вчера?». Составьте для него «план дня» с картинками, изображающими события дня. Это помогает сделать абстрактное понятие времени более конкретным.') WHERE id = 'ecad2493-1c0b-4ab4-b089-7a992488d7c5';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Бросание мяча в цель». Ребёнок уже не просто бросает мяч, а старается попасть им в определённую коробку или мишень. Это развивает умение оценивать расстояние в пространстве и регулировать силу броска (spatial estimation).') WHERE id = '6f552613-227f-4085-940c-f293c42bd5f1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Понимание сохранения количества» в когнитивном развитии. Если перелить одинаковое количество воды в ёмкости разной формы, ребёнок всё ещё может думать, что в высокой ёмкости воды больше. Играйте с ним с водой или песком, чтобы он на практике понял, что количество не меняется в зависимости от формы.') WHERE id = '13a54bb2-22dc-4956-ad40-80e7f13eda7c';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Быстрая остановка и поворот». Теперь во время бега ребёнок может сразу остановиться по вашей команде «Стой!» или резко повернуть. Это результат совместной работы мышц и нервной системы. Поиграйте с ним в парке в игру «Красный свет, зелёный свет» — она развивает самоконтроль (тормозной контроль).') WHERE id = '29ee5396-69c9-428e-9152-0052da7ababd';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Вежливость и нюансы» в речи. Ребёнок уже начинает подстраивать тон голоса и выбирать слова в зависимости от того, с кем разговаривает (например, с малышом — мягче, со взрослыми — серьёзнее). Это начало развития социолингвистических навыков. Ваша культура речи — главный и лучший пример для него.') WHERE id = '3eaa8096-e288-4159-9aa2-8223399dd023';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Похвала самого себя». Справившись с задачей, ребёнок говорит: «Посмотри, как здорово у меня получилось!» — и ждёт вашего одобрения. Поддержите это внутреннее чувство гордости словами: «Да, ты очень постарался». Ваша поддержка закладывает основу его уверенности в себе в будущем!') WHERE id = '97ef6f09-4fed-4fcd-abbe-7756d8045e1e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже может одновременно группировать предметы по нескольким признакам: «игрушки, которые и большие, и синие». Это показатель когнитивной гибкости (cognitive flexibility). Предлагайте ему увлекательные задания на поиск, например: «Давай найдём все мягкие и красные предметы».') WHERE id = '0d946fb4-d148-46c8-80fc-f0a7b324c07f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Свободный бег и остановка» в физическом развитии. Теперь ребёнок, даже двигаясь с максимальной скоростью, может сразу остановиться по вашей команде «Стой!», не потеряв равновесия. Это показывает, насколько хорошо развит его нервно-мышечный контроль. Игра «Красный свет, зелёный свет» в парке станет одновременно весёлой и полезной тренировкой.') WHERE id = '824aa9f8-040c-4665-a6d8-64a894fd7261';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Слова с противоположным значением» в речи. Ребёнок уже не только понимает такие противоположности, как «горячий — холодный», «высокий — низкий», «тяжёлый — лёгкий», но и использует их в разговоре. Загадывайте ему загадки на противоположности: «Слон большой, а мышь какая?». Это обогащает его словарный запас и развивает способность сравнивать.') WHERE id = '56f799be-0231-4113-94ee-9fbaa18f177f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Детали в изображении человека» в развитии мелкой моторики. Рисуя человека, ребёнок уже старается добавить ему руки, ноги и даже пальцы. Эти рисунки показывают, как он воспринимает своё тело и окружающих. Выслушивайте рассказ о каждом его «произведении» как маленькую историю.') WHERE id = '0006f22d-7d35-4a7c-abab-057194f6402c';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Углубление вопросов» в речи. Ребёнок может задавать сложные вопросы о существовании: «Что такое смерть?», «Откуда мы появились?». Всегда отвечайте честно, но выбирайте простые, соответствующие его возрасту и успокаивающие объяснения. Такие вопросы — это его попытка осмыслить мир.') WHERE id = '5eb1ed63-47a4-4170-b1fc-b58d4507160b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Творческое самовыражение». Когда ребёнку грустно, он уже может успокаиваться, рисуя или «делясь переживаниями» со своими игрушками. Обращайте внимание на его рисунки: цвета и формы отражают его внутренний мир. Вы — его самая надёжная гавань, а доверие к вам — его главная опора.') WHERE id = '48efdb3a-063c-40d5-837a-9373492693c6';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже проявляет интерес к надписям вокруг него. Он может радоваться, замечая знакомые буквы в названиях магазинов или заголовках книг — например, первую букву своего имени. Это этап «ранней грамотности». Не заставляйте его учить буквы, а просто поддерживайте его интерес.') WHERE id = '4c700caf-0287-4ea7-8bd0-73ca97292800';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В физическом развитии — «Спуск по лестнице чередующимися шагами». Ребёнок уже начинает спускаться по лестнице, ставя на каждую ступеньку одну ногу и чередуя их. Это сложнее, чем подниматься, и требует хорошо развитого равновесия. Просто оставайтесь рядом, чтобы он чувствовал себя в безопасности.') WHERE id = '970cfec9-666d-4324-ad8a-2d2689753b64';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Игра слов и рифмы» в речи. Ребёнку нравится находить похожие по звучанию слова: «кошка-ложка», «дом-сом». Это свидетельствует о развитии фонематического восприятия — способности различать звуки. Читайте вместе короткие рифмованные стихи или играйте в словесные игры. Это создаёт прочную основу для будущего навыка чтения.') WHERE id = '2fa13e97-2173-4c5c-afa8-90f8eaedaa8a';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В мелкой моторике — «Узлы и петли». Ребёнок уже проявляет интерес к шнуркам и верёвочкам, пытаясь переплетать их между собой. Предложите ему бусины с крупными отверстиями или специальные игрушки-шнуровки. Это подготавливает мелкие мышцы пальцев к письму и более сложным занятиям.') WHERE id = '5b2e2766-e73a-4ec2-b386-7bdc27e2bf73';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Воображаемые страхи». В этот период воображение ребёнка настолько развито, что он может бояться темноты или вымышленных «монстров». Не смейтесь над его страхом и не говорите: «Это неправда». Вместо этого станьте для него эмоциональной опорой, сказав: «Я рядом и защищу тебя». Это укрепит его доверие к вам.') WHERE id = 'b420b26f-d658-40bc-93d9-fcbe9a159330';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В социальном поведении — «Попытки дипломатии». Ребёнок уже старается разрешать конфликты с помощью предложений вроде: «Ты дай мне это, а я дам тебе то». Это яркий показатель развития социального интеллекта. Поддерживайте его способности «переговорщика» и помогайте находить справедливые решения.') WHERE id = '4ee1a693-af27-4c8f-b294-06b8239d80b9';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '"Воображаемый товарищ по играм". В этом возрасте некоторые дети могут придумывать воображаемых друзей. Это свидетельствует о богатом творческом потенциале и эмоциональном мире ребёнка. Не ругайте его и не говорите, что это "ложь". Через такого друга ребёнок исследует свои страхи и желания. Наблюдайте за этим терпеливо и с интересом.') WHERE id = '9ce75a82-fd02-47a8-adbb-96eadd2b8653';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '"Лидерство и подчинение" в социальном поведении. Во время игр ребёнок уже иногда устанавливает правила сам, а иногда подстраивается под правила других. Это основа социальной гибкости. Играйте с ним дома, меняясь ролями: "Теперь ты будешь учителем, а я — учеником".') WHERE id = 'd0b4ac9e-9bd0-4b78-83ac-e932a23bb3ff';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '"Причинно-следственная цепочка" в познавательном развитии. Ребёнок уже способен логически рассуждать, например: "Если пойдёт дождь, мы не сможем пойти в парк". Обсуждайте с ним последствия различных событий. Это формирует у ребёнка способность в будущем понимать ответственность за свои поступки и их логические последствия (logical consequences).') WHERE id = '44001e8a-e9dc-4edd-96dc-e3baba2b5ba4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: "Уверенная езда на трёхколёсном велосипеде". Ребёнок уже умеет управлять рулём, одновременно ритмично крутить педали и при необходимости пользоваться тормозом. Это результат слаженной координации верхней и нижней частей тела. Обозначьте в парке небольшую "велосипедную дорожку".') WHERE id = 'ec14848a-2298-473c-80f2-13859ca28476';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '"Вежливые просьбы" в речи. Ребёнок уже целенаправленно использует такие выражения, как "можно?" и "пожалуйста", чтобы получить желаемое. Ваш пример вежливого общения — его лучший учебник. Обязательно отмечайте, когда он проявляет вежливость: "Мне очень приятно помочь тебе, потому что ты так вежливо попросил".') WHERE id = 'c89c5c28-c3bd-46e0-93e1-c16bc60a714b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: "Саморегуляция". Если у ребёнка что-то не получается (например, когда игрушка разбирается на части), он уже не сразу начинает плакать, а смотрит на вас и просит о помощи или пробует ещё раз. Это большой шаг к эмоциональной зрелости. Вы — его самая надёжная опора!') WHERE id = 'a0873db2-259d-4791-a8af-c5e115589858';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже группирует предметы не только по цвету, но и по их назначению. "Это для еды", "Это для того, чтобы носить". Поиграйте с ним дома в игру "Что лишнее?" (например, положите 3 фрукта и 1 игрушку). Это развивает его способность логически анализировать информацию.') WHERE id = 'c4b0066e-1d1d-4a2d-b280-39f147e134fe';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '"Быстрое маневрирование" в физической активности. Ребёнок уже способен, бегая на полной скорости, заметить препятствие впереди и обогнуть его, не упав. Это вершина развития способности мозга к "моторному планированию". Устройте для него в парке небольшую полосу препятствий. Это улучшит контроль над телом и ловкость.') WHERE id = 'b1971b1f-63a0-40cf-bb46-3ba6bb8689b2';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Подробности прошлого» в речи. Ребёнок уже делится сложными воспоминаниями, например: «Вчера, когда мы ходили к бабушке, мы ели мороженое». Разговоры о прошедшем дне укрепляют его эпизодическую память. Помогите ему дополнить рассказ вопросом: «Что ещё ты помнишь?»') WHERE id = 'f5184b0f-58ef-4b72-af3f-546cec7ec971';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Копирование рисунков» в развитии мелкой моторики. Ребёнок уже пытается повторять нарисованные вами крестик (+), круг (O) или некоторые буквы. Это результат совместной работы зрения и рук (зрительно-моторной интеграции). Дайте ему цветные карандаши и предложите рисовать разные геометрические фигуры.') WHERE id = '5ee5e247-d8bd-4375-9669-ceda6b1b0a73';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Справедливость и правила». Ребёнок уже реагирует на нарушение правил в играх: «Он полез без очереди!». Это свидетельствует о развитии социального самосознания. Объясняя, что правила одинаковы для всех, вы укрепляете его внутреннее чувство справедливости и социальную дисциплину.') WHERE id = 'd1358d5f-b48d-4121-a736-887203ecfc67';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Попытки лидерства» в социальном поведении. Ребёнок уже хочет сам придумывать сценарий игры: «Я буду врачом, а ты — пациентом». С помощью таких ролевых игр он познаёт мир и учится принимать решения. Иногда следуйте его сценарию — это формирует в нём лидерские качества и чувство ответственности.') WHERE id = 'd27742a4-8533-4759-aff4-185d7dbf081f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Соответствие количества и числа» в познавательном развитии. Ребёнок уже не только умеет считать до 5, но и, увидев цифру «3», может отложить 3 игрушки. Это основа будущей математической грамотности. В повседневных делах давайте ему задания вроде: «Дай мне 4 яблока».') WHERE id = '0f53eb59-1dad-4d39-84e5-43e97150561c';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Прыжок на двух ногах». Ребёнок уже может свободно перепрыгивать через препятствия, одновременно отталкиваясь обеими ногами. Для этого необходимы как сила нижней части тела, так и скоординированность движений. Положите дома на пол верёвку и поиграйте с ним в «Переправу через реку», перепрыгивая через неё.') WHERE id = '080c3ee9-a0ea-4062-9f79-5fba44d2d0e4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Шутки и юмор» в речи. Ребёнок уже пытается рассмешить вас, намеренно неправильно произнося слова или издавая забавные звуки. Это одна из форм понимания языковых норм. Смейтесь над его шутками и вместе развивайте чувство юмора.') WHERE id = '9fb34927-219f-4b2d-bb9f-dda7da92c634';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Признание своей ошибки». Если ребёнок что-то сломал или разбросал, он уже не всегда пытается сразу это скрыть и может сказать: «Это сделал я». В такой момент искренности не наказывайте его, а предложите вместе всё убрать. Вы — его безопасная гавань!') WHERE id = 'c4b6f5da-e09e-4e7a-8e0a-9a60747fa087';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже может одновременно группировать предметы и по цвету, и по форме. Он объединяет детали, говоря: «Это и красное, и круглое». Это важный показатель когнитивной гибкости. Предлагайте ему игры с различными геометрическими фигурами.') WHERE id = '2b4289d9-5b1f-4994-a054-e4727135705c';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В физической активности — «Динамические прыжки». Ребёнок уже может во время бега перепрыгнуть через небольшое препятствие, не снижая скорости. Это свидетельствует о развитии способности мозга заранее планировать движения (моторное планирование). Вы можете устраивать для него небольшие полосы препятствий в парке.') WHERE id = 'ae389307-05d6-4296-90e1-0a21e776e282';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В речи — «Целенаправленные вопросы». Теперь он спрашивает не просто «Что это?», а «Как это работает?». Он интересуется внутренним устройством предметов, часами, колёсами игрушек. Отвечая, сохраняйте логическую последовательность: эти вопросы — первые искры будущего научного мышления.') WHERE id = 'd2e255d4-c4cb-4992-b207-917bc8c7e987';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В мелкой моторике — «Попытки соблюдать симметрию». Ребёнок старается складывать бумагу или более симметрично располагать детали на рисунке (например, два глаза и две руки у человека). Это показывает, насколько совершенствуется его зрительно-пространственное восприятие (visual-spatial awareness).') WHERE id = 'b4315b1b-9d62-41cc-a063-b3b09c4c589a';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Дипломатические» переговоры. Ребёнок уже торгуется с вами: «Если я съем овощи, мы потом сможем подольше остаться в парке?». Это показывает, что он осваивает механизмы социального влияния. Будьте честны и последовательны в таких «переговорах»: именно так он учится понимать границы.') WHERE id = '431cd610-a165-475a-8f4f-464196e237c1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В социальном поведении — «Воображаемые сценарии». Теперь игры становятся сложнее: «Я продавец, приходи и купи у меня хлеб». В таких играх ребёнок примеряет на себя различные роли в обществе. Следуйте его сценариям, чтобы стимулировать этот творческий процесс.') WHERE id = '81128f46-ecb8-47f0-aa0b-337c398b3230';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В познавательном развитии — «Ритуалы времени». Хотя ребёнок ещё не до конца различает понятия «вчера», «сегодня» и «завтра», он уже знает привычные ритуалы: «После еды — парк» или «Перед сном — сказка». Эти последовательности формируют в его сознании временную ось.') WHERE id = '5cb6d50d-147c-44f7-91b0-1d67f401019b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В физической координации — «Точные манёвры». Ребёнок уже может пронести наполненный жидкостью стакан, почти ничего не пролив, или пройти по узкой тропинке. Это показывает, насколько совершенствуется его зрительно-моторная координация. Давайте ему дома роль «маленького помощника», чтобы укреплять эту внимательность.') WHERE id = 'efc83589-a712-4c32-9e12-c9ee0f9cee01';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Словарь эмоций» в речи. Ребёнок уже не просто говорит «мне плохо» или «мне хорошо». Он уместно использует такие слова, как «я рассердился», «я соскучился», «я рад». Признавайте его чувства: «Плакать, когда скучаешь, — нормально». Это один из главных залогов его эмоционального здоровья.') WHERE id = 'e498f733-de85-4e45-8875-b886111a89f8';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Самый расцвет трёх с половиной лет! Ребёнок уже окончательно вышел из младенческого возраста и находится в самом активном периоде раннего детства. Теперь он представляет собой полноценную личность — как физически, так и эмоционально. За эти 1250 дней вы заложили прочный фундамент его доверия к миру. Гордитесь собой!') WHERE id = 'a45a87d4-253c-4fea-ac32-9cea3f5b1168';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже проявляет интерес к надписям вокруг него. Он может радоваться, узнавая знакомые буквы в названиях магазинов или заголовках книг — например, первую букву своего имени. Это этап «ранней грамотности». Не заставляйте его учить буквы, а просто поддерживайте интерес.') WHERE id = '0aedbd42-1452-4a3e-aa54-4adb1ad4a556';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В физическом развитии — «Спуск по лестнице чередующимся шагом». Ребёнок уже начинает спускаться по лестнице, ставя на каждую ступеньку только одну ногу и чередуя их. Это сложнее, чем подниматься, и требует хорошо развитого равновесия. Просто стойте рядом, чтобы он чувствовал себя в безопасности.') WHERE id = '4a1598de-455f-4bae-a8b3-0f5696c065c6';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Игры со словами и рифмы» в речи. Ребёнку нравится находить похожие по звучанию слова: «дом-сом», «кошка-мошка». Это свидетельствует о развитии фонематического восприятия — способности различать звуки. Читайте вместе короткие рифмованные стихи или играйте в словесные игры. Это создаёт прочную основу для будущего навыка чтения.') WHERE id = '3f6a6fa9-4e7a-4539-93e7-6da1070ea997';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В мелкой моторике — «Узел и петля». Ребёнок уже интересуется шнурками и верёвочками, пытаясь переплетать их между собой. Дайте ему крупные бусины с большими отверстиями или специальные игрушки-шнуровки. Это подготавливает мелкие мышцы пальцев к письму и более сложным занятиям.') WHERE id = 'cf6a8a3d-c742-40b0-a3c1-38fd2db89aec';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Воображаемые страхи». В этот период воображение ребёнка настолько развито, что он может бояться темноты или вымышленных «монстров». Не смейтесь над его страхом и не говорите: «Это всё неправда». Вместо этого станьте для него эмоциональной опорой, сказав: «Я рядом и защищаю тебя». Это укрепляет его доверие к вам.') WHERE id = '09cee55c-899d-468c-bef9-66eb86e868c6';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Попытки дипломатии» в социальном поведении. Ребёнок уже старается разрешать конфликты с помощью таких предложений, как: «Ты дай мне это, а я дам тебе то». Это яркий показатель развития социального интеллекта. Поддерживайте в нём этого маленького «переговорщика» и помогайте находить справедливые решения.') WHERE id = '1f6c2927-0b20-482c-b17f-a447f8fef25d';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Понимание сохранения количества» в когнитивном развитии. Если перелить одинаковое количество воды в сосуды разной формы, ребёнок всё ещё может думать, что в высоком сосуде воды больше. Играйте с ним с водой или песком, чтобы он на практике понял, что количество не меняется в зависимости от формы ёмкости.') WHERE id = '73557d3a-6c9c-4c6a-a67f-c5d4bc801f0d';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Быстрая остановка и поворот». Теперь ребёнок может во время бега сразу остановиться по вашей команде «Стой!» или резко повернуть. Это результат слаженной работы мышц и нервной системы. Поиграйте с ним в парке в игру «Красный свет, зелёный свет» — она развивает навыки самоконтроля.') WHERE id = '2c94b5e7-3f3c-4f5a-97ae-e15891e8c592';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Вежливость и нюансы» в речи. Ребёнок уже начинает подстраивать тон голоса и выбирать слова в зависимости от того, с кем разговаривает: например, с малышом говорит мягче, а со взрослыми — серьёзнее. Это начало развития социолингвистических навыков. Ваша культура речи — главный и лучший пример для него.') WHERE id = '708f00c5-3974-4a48-b57b-7ac187203dd5';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Похвала самого себя». Когда ребёнку удаётся что-то сделать, он говорит: «Посмотри, как хорошо у меня получилось!» — и ждёт вашего одобрения. Поддержите его чувство внутренней гордости словами: «Да, ты очень старался». Ваша поддержка закладывает основу его будущей уверенности в себе!') WHERE id = '1eae35d0-6f20-4979-87f2-c88eacf3b104';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже применяет последовательность «сначала, сейчас, потом» к более сложным событиям: «Сначала я помою руки, потом поем, а в конце поиграю». Это свидетельствует о развитии исполнительных функций мозга, отвечающих за планирование действий. Предлагайте ему составлять небольшие планы на день. Это укрепляет чувство организованности и дисциплины.') WHERE id = 'c4e864cd-f8ff-486c-994b-11d240e723ca';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Маневрирование на трёхколёсном велосипеде» в развитии двигательной активности. Теперь ребёнок во время езды замечает препятствия на пути и успевает вовремя повернуть руль. Это прекрасное сочетание умения крутить педали (физический навык) и следить за дорогой (зрительный навык).') WHERE id = '63226ba2-0699-459a-be66-a4c9af97d876';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Причинно-следственные диалоги» в развитии речи. Теперь ребёнок задаёт вопросы о ваших решениях: «Почему я должен спать?». Отвечайте ему логично: «Потому что твоему телу нужно отдохнуть, чтобы завтра ты снова мог играть с новыми силами». Такой подход формирует у ребёнка не слепое послушание, а осознанную дисциплину.') WHERE id = 'aba02008-e74d-4081-9df9-4e23bad078b6';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Вырезание из бумаги» в развитии мелкой моторики. Ребёнок уже пытается безопасными ножницами разрезать бумагу по прямой линии или вырезать простой круг. Это одно из важнейших упражнений для зрительно-моторной координации. Давайте ему цветную бумагу и шаблоны для вырезания, чтобы тренировать мышцы рук.') WHERE id = 'd337c2b8-8f8a-4037-8a7a-e030f9920b04';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Границы и умение делиться». Ребёнок уже понимает, что некоторые вещи общие для всех (например, качели в парке), а некоторые принадлежат только ему. Уважайте его чувство собственности, говоря: «Это твоя игрушка, и ты сам решаешь, делиться ею или нет». Ребёнку, чью собственность уважают, легче научиться уважать вещи других людей.') WHERE id = '9f384019-50a1-4540-baab-8643e931568a';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Сложные ролевые игры» в социальном поведении. Теперь в играх появляется сюжет: «Ты больной, я врач и сделаю тебе укол». С помощью таких игр ребёнок прорабатывает свои страхи из реальной жизни (например, боязнь врачей). Активно участвуйте в придуманном им сценарии.') WHERE id = '9206ce15-0a76-4431-b07b-049bdcbed6b0';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Соотнесение количества и числа» в познавательном развитии. Ребёнок уже умеет считать до 5 и, услышав «3», может зрительно выделить 3 предмета. Давайте ему задания, например: «Дай мне 4 ложки». Это этап, на котором абстрактные числа впервые начинают прочно связываться с реальным миром.') WHERE id = 'eaf2d09d-f792-4b9d-ab37-65dbbde32f39';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Прыжок на двух ногах». Ребёнок уже может свободно перепрыгивать через препятствия (например, через лежащую на полу верёвку), одновременно отталкиваясь обеими ногами. Для этого необходимы как сила нижней части тела, так и синхронная координация движений. Поиграйте с ним дома в игру «Переправа через реку», чтобы повысить его физическую активность.') WHERE id = '9a61025f-abc9-4c98-bf07-819847137992';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Шутки и юмор» в речи. Ребёнок пытается рассмешить вас, намеренно неправильно произнося слова или издавая забавные звуки. Это показывает, что он знает языковые нормы и намеренно нарушает их, чтобы создать комический эффект. Смейтесь над его шутками — это укрепляет его уверенность в себе и развивает социальный интеллект.') WHERE id = 'b25c4c56-1f97-4223-b20b-689b5e94d1d3';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Умение справляться с неудачами». Если у ребёнка что-то не получается (например, построить башню из кубиков), он уже не сразу начинает плакать, а может посмотреть на вас и спросить: «Попробовать ещё раз?» Хвалите не результат, а его старания: «Ты очень старался, молодец!» Вы — главный источник его мотивации!') WHERE id = 'f9148bba-3642-4b13-ad48-62db8da7ed80';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже различает предметы не только по внешнему виду, но и по материалу: «Это пластик, а это железо». Давайте ему предметы с разной текстурой и спрашивайте, чем они отличаются. Это помогает ему более детально анализировать окружающий мир и систематизировать знания о физических свойствах предметов.') WHERE id = '80e00e5a-2a93-4c1b-a710-db553822e4ae';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Равновесие на одной ноге» в физическом развитии. Ребёнок уже может простоять на одной ноге более 5 секунд. Это свидетельствует о созревании координации между мозжечком и мышцами. Поиграйте с ним в «цаплю» и проверьте, кто сможет простоять дольше.') WHERE id = '18ab2c20-2470-41d2-b5e5-3121b8d7e0c1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Богатство прилагательных» в речи. Описывая предметы, ребёнок называет уже не только их цвет, но и использует такие слова, как «мягкий», «колючий», «гладкий». Поиграйте с ним в игру «Потрогай и угадай»: попросите его закрыть глаза и описать предмет на ощупь.') WHERE id = '6a7056fe-a7e8-4d7e-91b2-4d5b5277e537';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Знакомство с символами» в развитии мелкой моторики. Ребёнок уже пытается копировать некоторые буквы (особенно первую букву своего имени) или цифры. Это показывает, что он понимает связь между визуальными символами и звуком/значением. Предложите ему потренироваться «писать» на песке или цветными карандашами.') WHERE id = 'b57332a7-c381-44a7-bdb8-aef8d6820036';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Самоконтроль и терпение». Ребёнок уже спокойнее воспринимает необходимость подождать желаемого 5-10 минут (например, пока приготовится еда). Ваши слова «немного подожди» он воспринимает не как наказание, а как необходимость подождать некоторое время. Заметив его терпение, обязательно поддержите его словами: «Большое спасибо, что подождал».') WHERE id = '7374ce80-a74f-4d7f-bb0f-135ec7c6d431';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Эмпатия и утешение» в социальном поведении. Заметив, что вы устали или что его друг расстроен, ребёнок уже может принести игрушку или погладить вас либо друга. Это показывает, насколько обогатился его внутренний мир и как он постепенно переходит от «я» к «мы».') WHERE id = '62ab0290-ec13-4b50-86f2-b4a69aba6dda';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Восприятие объёма» в познавательном развитии. Теперь ребёнок пытается предположить, сколько маленьких игрушек поместится в большой коробке. Дайте ему ёмкости разных размеров и спросите: «Как ты думаешь, эта вода поместится в ту ёмкость?». Такие эксперименты закладывают основу для будущего понимания математики и физики.') WHERE id = 'd68476f5-47bc-4622-82c1-31e6c34eeecd';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Ходьба спиной вперёд». Ребёнок уже может уверенно сделать несколько шагов назад, не теряя равновесия. Это движение развивает ощущение собственного тела (проприоцепцию). Поиграйте с ним в парке в «крабьи бега», чтобы одновременно весело провести время и укрепить его мышцы.') WHERE id = 'ff4d4dbc-967a-48e5-b6f7-ae29e0a5390d';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Вежливость и нюансы» в речи. Ребёнок уже начинает менять тон голоса в зависимости от того, с кем разговаривает (например, с малышом говорит мягче, а со взрослыми — серьёзнее). Это начало развития социолингвистических навыков. Ваша культура речи — главный и самый совершенный образец для него.') WHERE id = '3f691af2-a53f-4e9e-bda8-73c25f9784e5';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '1280 дней большого развития! Ребёнок вступил в самый плодотворный этап раннего детства. Теперь он уже полноценная личность — маленький человек со своими предпочтениями, страхами и бесконечными вопросами. Вы прошли этот путь, опираясь на знания и любовь. «Anacan» всегда рядом с вами!') WHERE id = 'cb9230b0-c04d-4749-92fd-37201aec8ecd';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже умеет группировать предметы не по одному, а сразу по двум признакам: «машинки, которые одновременно красные и маленькие». Это важный этап развития когнитивной гибкости. Дайте ему разные игрушки и предложите: «Найди всё мягкое и синее», чтобы потренировать его мышление.') WHERE id = '7f3f7af2-f05b-47b3-bb9a-bf661d551477';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Точные прыжки» в физическом развитии. Ребёнок уже умеет подпрыгивать на месте и прыгать в определённую цель, например внутрь нарисованного на земле круга. Это свидетельствует как о хорошем равновесии, так и об умении оценивать расстояние в пространстве. Игра в парке «Прыжки с камня на камень» станет для него отличной тренировкой.') WHERE id = 'b66ed3bb-08b0-48a9-9270-0f8d21791b6b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Последовательность событий» в речи. Ребёнок уже точнее использует понятия «сначала, сейчас, потом»: «Сначала я помою руки, потом буду есть хлеб». Обсуждение с ним планов на день развивает организованность и создаёт чувство безопасности. На его вопросы «Что мы сейчас будем делать?» всегда отвечайте, последовательно перечисляя действия.') WHERE id = '4a19271e-0252-465e-a5b6-220dfc833dfa';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Копирование фигур: треугольник и крест» в развитии мелкой моторики. Ребёнок уже умеет рисовать крест (+), пересекая прямые линии, и пытается изображать фигуры, похожие на треугольник. Это основа будущих навыков письма. Дайте ему цветные карандаши и чистые листы бумаги, чтобы поддержать его «геометрические открытия».') WHERE id = '5e0bb7b8-fe4c-40a9-87b2-d5ec3dff9314';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Саморегуляция и эмоции». Когда ребёнок сердится или расстраивается, он иногда уже может использовать предложенные вами способы успокоиться, например глубоко подышать. Это один из важнейших жизненных навыков эмоционального интеллекта. Когда он успокоится, обязательно похвалите его за это.') WHERE id = 'cab1e84e-d4d4-48e6-a7cb-8122f2485764';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Командные игры» в социальном поведении. Ребёнок уже умеет сотрудничать с другим ребёнком ради общей цели, например чтобы построить большой замок из песка. Это означает полный переход от «параллельной игры» к «социальной игре». Наблюдайте за его попытками находить общий язык с друзьями и поддерживайте их.') WHERE id = '35da39d6-0c56-4410-8592-5e1cbd4b1e03';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Соответствие числа и количества» в познавательном развитии. Ребёнок может считать до 10 и, увидев цифру «3», уже способен отложить 3 игрушки. Это важнейший этап развития математического мышления. Укрепляйте эту связь в повседневной жизни с помощью заданий вроде «Дай мне 2 ложки».') WHERE id = '4397b751-5eff-493f-b5d9-774c99d1ca07';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Ловля мяча двумя руками». Ребёнок уже пытается поймать обеими руками большой мяч, медленно брошенный в его сторону, иногда прижимая его к груди. Это движение требует как зрительно-моторной координации, так и быстроты реакции. Играйте с ним с близкого расстояния.') WHERE id = '416872cb-a02b-4d4e-ac74-f040d4ce096b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Вежливые просьбы» в речи. Ребёнок уже осознанно использует такие выражения, как «можно?» и «пожалуйста», чтобы получить желаемое. Ваш пример вежливого общения — его главный учебник. Обязательно отмечайте моменты, когда он проявляет вежливость: «Мне очень приятно помочь тебе, когда ты так вежливо просишь».') WHERE id = 'eb838920-fe5c-415a-a9ba-0dabdeaffb4e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Признание своей ошибки». Если ребёнок что-то сломал, он уже не пытается сразу это скрыть, а может сказать: «Это сделал я». В такой момент не наказывайте его за честность — вместо этого предложите вместе всё убрать. Так у него формируется чувство ответственности. Каждый момент 1290-дневного пути бесценен!') WHERE id = 'fba8e58a-849a-4502-b3b8-829b5d503078';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже полностью освоил логику «если... то...». «Если я сломаю игрушку, она больше не будет работать». Это начало способности прогнозировать будущее. Предлагайте ему заранее обдумывать последствия своих действий: «Как ты думаешь, что будет, если поставить стакан на край?». Так формируется чувство ответственности.') WHERE id = '98264d01-8080-47ff-9743-5076f3c1e9fb';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Пик статического равновесия» в физическом развитии. Ребёнок уже может стоять на одной ноге 5-10 секунд, ни к чему не прикасаясь. Это свидетельствует об укреплении как центра равновесия во внутреннем ухе, так и мышц спины и ног. Превратите этот навык в весёлую игру, играя с ним в «Замри».') WHERE id = 'e5ea1656-41df-45ea-937c-07b3a21bce4f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Построение сложного сюжета» в речи. Рассматривая книжку с картинками, ребёнок уже не просто называет предметы, а объясняет связь между событиями: «Заяц убегает, потому что приближается лиса». Чтобы стимулировать его воображение, задавайте вопросы вроде: «Как ты думаешь, что скажет лиса?». Это развивает его когнитивную гибкость.') WHERE id = '991395b5-cce5-4484-973b-52ea93850c86';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Независимые движения пальцев» в развитии мелкой моторики. Ребёнок уже выполняет сложные действия: поочерёдно соединяет пальцы или нанизывает маленькие бусины на нить кончиками пальцев. Это требует координации обоих полушарий мозга. Предлагайте ему игры с застёгиванием пуговиц или расстёгиванием петель.') WHERE id = '7718afa5-181a-4995-b727-92bfdea228d9';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Управление воображаемыми страхами». В этом возрасте дети иногда могут бояться темноты или «монстров». Не отрицайте его страх, а придумайте игру, например с «волшебным фонариком, прогоняющим монстров». Ваша эмоциональная поддержка помогает ему понять, что эти страхи временны.') WHERE id = '5da5688a-9254-4a8e-94a4-a6cdb8624f11';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Сотрудничество ради общего результата» в социальном поведении. Ребёнок уже может делиться «кирпичиками» с другом, чтобы вместе построить большую башню. Теперь это не просто игра рядом, а игра ради общей цели (совместная игра). Поддержите его способности к общению словами: «Какая замечательная у вас получилась команда!».') WHERE id = '12a2b82c-6975-4312-a2f7-fbbdcf5d9909';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Справедливость и правила». Ребёнок уже остро реагирует на нарушение правил в играх: «Он нарушил очерёдность!». Это свидетельствует о развитии социального самосознания и нравственных представлений. Объясняя, что правила одинаковы для всех, вы укрепляете его внутреннее чувство справедливости и социальную дисциплину.') WHERE id = '6e14d59c-92a1-4b52-9746-19ec45e3a240';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Попытки дипломатии» в социальном поведении. Ребёнок старается разрешать конфликты с помощью предложений вроде: «Ты дай мне это, а я дам тебе то». Это один из самых ярких показателей социального интеллекта. Хвалите его за умение договариваться и поддерживайте справедливые способы решения конфликтов.') WHERE id = '1bc59678-d965-4c53-ad57-e91ac3a6bece';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Мгновенное распознавание количества (субитизация)» в познавательном развитии. Ребёнок уже может, не считая, с одного взгляда определить, сколько перед ним предметов — 3 или 4. Показывайте ему карточки с разным количеством точек и просите сразу сказать, сколько их. Это основа будущего навыка быстрых математических вычислений.') WHERE id = '9268aa12-9e8f-498d-a13c-fd38e4e68957';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Бросок мяча из-за плеча». Ребёнок уже не просто роняет мяч, а может бросить его от уровня плеча вдаль и в определённую цель. Для этого требуются координация всего тела и умение контролировать силу. Играйте с ним в парке, бросая мяч в цель.') WHERE id = 'dbdc7993-c5ce-4ff8-a2f5-69daf1b98fea';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Развитие шуток и чувства юмора» в речи. Ребёнок уже шутит, намеренно меняя значение слов. Например, он может назвать вас «дедушкой» и засмеяться. Это показывает, что он хорошо знает языковые нормы и намеренно нарушает их, чтобы создать комический эффект. Веселитесь вместе с ним.') WHERE id = '8c83e3c0-4591-49c2-a059-525f584c28d3';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Проверка терпения». Ребёнок уже может несколько минут молча подождать того, чего хочет, например пока вы разговариваете по телефону. Это свидетельствует об укреплении его навыка самоконтроля. После ожидания обязательно поблагодарите его, сказав: «Большое спасибо, что подождал меня».') WHERE id = '75df2db1-9a5a-4048-99dc-80b484b6d396';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже может узнавать окружающие его логотипы и надписи. Например, увидев логотип любимой марки мороженого или магазина, он называет его. Это свидетельствует о развитии символического мышления. Показывайте ему различные дорожные знаки или простые пиктограммы и спрашивайте, что они означают. Это визуальная основа будущего навыка чтения.') WHERE id = 'bb1f5dc6-7300-4f63-9d44-40f2e54dfb71';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Прыжки назад» в развитии физической активности. Ребёнок уже может совершать небольшие прыжки назад. Это новый уровень развития равновесия и умения управлять своим телом в пространстве. Поиграйте с ним в соревнование «Краб и лягушка», чтобы стимулировать его активность.') WHERE id = '2c74b1f3-a8fd-4086-88da-377857855b8c';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Сравнение противоположностей» в речи. Ребёнок уже уместно использует в предложениях степени сравнения: «самый большой», «меньше», «очень тяжёлый». Дайте ему 3 игрушки разного размера и спросите: «Какая из них самая большая?». Это показывает, что его словарный запас становится богаче как количественно, так и качественно.') WHERE id = 'f9bd7f70-01bc-46e8-8391-e80ede82d1cc';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Соблюдение пропорций в изображении человека» в развитии мелкой моторики. Рисуя человека, ребёнок уже располагает части тела более логично: глаза — посередине лица, руки — по бокам туловища. Эти рисунки отражают развитие представления о собственном теле (body image).') WHERE id = 'b857a3b6-e216-49cf-a9c0-e7adabf3fdba';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Описание себя». Ребёнок уже может охарактеризовать себя: «Я светловолосый», «Я быстро бегаю». Это свидетельствует об укреплении индивидуальной идентичности. Помогайте ему лучше понимать себя, задавая вопросы вроде: «А что ещё тебе нравится?». Положительное представление ребёнка о себе — основа его будущей уверенности в себе.') WHERE id = '9ca9132e-1f05-4086-b977-373ac1739718';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Дипломатия и переговоры» в социальном поведении. Чтобы получить желаемое, ребёнок уже предлагает варианты обмена, например: «Если ты дашь мне это, я дам тебе то». Это важное проявление социального интеллекта и умения решать проблемы. Поддерживайте и положительно воспринимайте его попытки честно «договариваться».') WHERE id = '68e14866-1913-4e48-a5b0-15a89d136783';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Ритуализация времени» в познавательном развитии. Ребёнок уже различает части дня с помощью выражений «когда просыпаюсь утром», «когда ложусь спать вечером». Обсуждайте с ним планы на завтра в формате «сначала, потом, в конце». Это создаёт у него ощущение безопасности и порядка.') WHERE id = 'fc45f60c-b22c-4712-b519-43e1ec159d0a';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Ведение мяча ногами». Ребёнок уже не просто бьёт по мячу, а старается перемещаться вместе с ним, слегка подталкивая его ногой вперёд (dribbling). Это требует динамического равновесия и внимания. Устройте для него в парке небольшую «футбольную дорожку» и предложите вести мяч к цели.') WHERE id = '27b3b770-0010-4e27-a15b-7e39df48e572';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Вежливость и социальный этикет» в речи. Ребёнок уже уместно использует такие выражения, как «извините», «можно?». Ваши диалоги с другими людьми — главный пример для него. Когда он ведёт себя вежливо, обратите его внимание на приятное впечатление, которое это производит на окружающих: «Все тебе улыбаются, потому что ты такой вежливый».') WHERE id = 'eddeff81-68cf-4451-8b49-9db4335c7821';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Принятие неудачи». Если у ребёнка что-то не получается (например, собрать пазл), он уже не сразу сердится, а пробует снова или просит о помощи. Хвалите не результат, а его усилия: «Ты очень старался и не сдался, молодец!».') WHERE id = '3c009bb9-dfc9-4682-a20a-9afa3ba74f26';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Тест на сохранение количества» в когнитивном развитии. Ребёнок всё ещё может считать, что расплющенный пластилин больше, чем пластилиновый шарик. Проводите с ним такие опыты: расплющите шарик, а затем снова скатайте его. Это поможет ребёнку понять неизменные законы физического мира.') WHERE id = 'ae824ed0-4f75-4515-b7bf-83483a6c043d';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Ведение мяча ногой». Ребёнок уже не просто бьёт по мячу, а пытается перемещать его, слегка подталкивая ногой вперёд (дриблинг). Для этого необходимы динамическое равновесие и зрительно-моторная координация ног. Устройте для него в парке небольшую «футбольную дорожку» и предложите вести мяч к цели.') WHERE id = '6f891729-8e3d-4c9f-bdb3-588b6de557c3';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Вежливость и этикет» в речи. Ребёнок уже использует слова «извините», «пожалуйста» не просто по памяти, а осознанно. Тон, которым вы разговариваете с другими, — его главный учебник. Когда ребёнок проявляет вежливость, помогите ему заметить, какое положительное впечатление это производит на окружающих.') WHERE id = '8553307b-a429-4fdd-a8d5-b4776f0fb3d5';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Великолепный путь длиной в 1300 дней! Ребёнок уже полностью оставил позади привычки раннего детства и вступает в самый активный этап дошкольного периода. Он уже осознаёт себя как отдельное «я» и готов менять мир. Все эти 1300 дней вы были для него самым надёжным проводником. Поблагодарите себя за свою любовь и терпение!') WHERE id = '7883dc4b-dac2-42dc-8a35-51e8d5b489b1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Добро пожаловать в 44-й месяц! Ребёнок уже глубоко ощущает: «Я большой». В этот период поручайте ему небольшие обязанности, например самостоятельно выбрать одежду или накрыть на стол. Это направляет его стремление к самостоятельности в позитивное русло и укрепляет уверенность в себе.') WHERE id = 'aad2ad75-5a11-4a2d-9c7c-2bc5d48aa312';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Плавное маневрирование» в физической активности. Ребёнок уже может на полном ходу заметить препятствие впереди и обежать его, не упав. Это вершина развития навыка «моторного планирования» в мозге. Устройте для него в парке небольшую полосу препятствий. Это улучшит контроль над телом и ловкость.') WHERE id = '5ff72db7-e0be-4353-a758-f27d398fc0b7';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Качество вопросов» в речи. Теперь ребёнок спрашивает не просто «что это?», а «почему это так?». Он пытается понять внутреннюю логику событий. Отвечая, задействуйте и его воображение: «Как ты думаешь, почему идёт дождь?». Это стимулирует творческое и научное мышление ребёнка.') WHERE id = '104d37cc-f454-4cee-bc62-45a7dd638317';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Копирование фигур: квадрат и треугольник» в развитии мелкой моторики. Ребёнок уже пытается рисовать фигуры с углами. Это сложнее, чем нарисовать круг, поскольку нужно остановить карандаш в определённой точке и изменить направление. Покажите ему, как, соединяя угловатые фигуры, нарисовать «дом» или «машину».') WHERE id = '72c3574b-2a9a-4755-8727-8d01b439e56e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже умеет одновременно группировать предметы и по цвету, и по материалу: «Это и синее, и мягкое». Это важный показатель когнитивной гибкости. Предлагайте ему игры с предметами разной текстуры (дерево, ткань, пластик).') WHERE id = 'b98d1c0b-fdd1-4aeb-a1f1-d636c58ba6b7';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Динамические прыжки» в физической активности. Теперь ребёнок во время бега может перепрыгнуть небольшое препятствие, не снижая скорости. Это свидетельствует о развитии способности мозга заранее планировать движения (моторное планирование). Вы можете устраивать для него небольшие полосы препятствий в парке.') WHERE id = '60d3fdb2-caa2-4bc5-bc84-452616921b80';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Ритуалы времени» в развитии речи. Хотя ребёнок ещё не до конца различает понятия «вчера», «сегодня» и «завтра», он уже понимает привычные ритуалы: «После еды — парк» или «Перед сном — сказка». Эти последовательности формируют в его сознании представление о течении времени.') WHERE id = '95122e91-e077-4e38-a3b4-27a4e9e756f1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Попытки соблюдать симметрию» в развитии мелкой моторики. Ребёнок старается складывать бумагу или более симметрично располагать детали рисунка (например, два глаза и две руки у человека). Это показывает, насколько совершенствуется его зрительно-пространственное восприятие.') WHERE id = '27b05f17-57a4-4b79-9091-f702b81309dd';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Политические» переговоры. Ребёнок уже начинает с вами «торговаться»: «Если я съем овощи, мы потом сможем подольше остаться в парке?» Это говорит о том, что он осваивает механизмы социального влияния. Будьте честны и последовательны в таких «переговорах» — именно так ребёнок учится понимать границы.') WHERE id = '0875811d-7343-4ba3-a29e-c235cba78b04';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Воображаемые сценарии» в социальном поведении. Теперь игры становятся сложнее: «Я продавец, а ты приходи покупать у меня хлеб». В таких играх ребёнок примеряет на себя различные социальные роли. Следуйте его сценариям, чтобы поддерживать этот творческий процесс.') WHERE id = 'c35d44af-1b5b-4a3a-b44c-143278463e37';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Функции предметов» в познавательном развитии. Теперь ребёнок группирует предметы не только по внешнему виду, но и по их назначению: «Это инструменты, которыми режут», «А это инструменты, которыми пишут». Это показывает, что информация в его мозге становится более систематизированной и функциональной.') WHERE id = '52b43fec-3fc9-4135-bc89-1ca56d2c89c9';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Точные манёвры» в физической координации. Теперь ребёнок может перенести наполненный жидкостью стакан, почти ничего не расплескав, или пройти по узкой тропинке. Это показывает, насколько совершенствуется его зрительно-моторная координация. Поручайте ему дома роль «маленького помощника», чтобы укреплять внимательность и этот навык.') WHERE id = 'b2a95188-79e5-4c80-963a-2302704140ca';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Словарь эмоций» в речи. Ребёнок уже не просто говорит «мне плохо» или «мне хорошо». Он уместно использует такие слова, как «я разозлился», «я соскучился», «я рад». Признавайте его чувства: «Плакать из-за того, что ты соскучился, — нормально». Это один из главных залогов его эмоционального здоровья.') WHERE id = '8d118e2f-9e48-4f84-bdd9-4688744f285c';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Вершина 1330-го дня! Ребёнок официально вступил в самый активный и осознанный период этапа «раннего детства». Теперь он уже полноценная личность как физически, так и эмоционально. Вы прошли этот путь с опорой на науку и любовь. «Anacan» всегда рядом с вами!') WHERE id = 'ee7d4f4f-acca-4792-810c-9ebdc339da81';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Добро пожаловать в 45-й месяц! Ребёнок уже начинает искать знакомые буквы в надписях вокруг него. Особенно часто он может узнавать первую букву своего имени. Это начальный этап формирования навыка чтения. Не заставляйте его учить буквы — просто в игровой форме называйте буквы, которые он замечает, и произносите соответствующие им звуки.') WHERE id = 'c1854d46-26a3-452c-9eb7-697ec5a92d6c';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Полное управление трёхколёсным велосипедом» в физическом развитии. Ребёнок уже может проходить крутые повороты, не переставая крутить педали и поворачивая руль. Это свидетельствует о высоком уровне развития силы нижней части тела и зрительно-пространственной координации.') WHERE id = 'ee3c0b22-95f2-4059-93bc-287ff0eb00cf';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Навык прогнозирования» в речи. Во время чтения сказки ребёнок уже может давать логичные ответы на вопрос: «Как ты думаешь, что будет дальше?». Это показывает, что он начинает понимать скрытые связи между событиями и делать выводы. Стимулируйте его воображение вопросом: «А что бы ты сделал на его месте?».') WHERE id = '8651dfdb-b093-4f7c-b25e-9846200e12c4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Вырезание из бумаги: создание формы» в развитии мелкой моторики. Ребёнок уже пытается вырезать по контуру простой круг или квадрат безопасными ножницами. Это требует высокой степени контроля мелких мышц кисти.') WHERE id = '9727b126-febe-431d-a82a-db6a6416efff';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Защитник справедливости и правил». Ребёнок уже реагирует на нарушение правил не только им самим, но и другими: «Папа, ты прошёл без очереди!». Это признак формирования совести и чувства социальной справедливости. Объясняйте ему, почему правила должны быть одинаковыми для всех.') WHERE id = 'a0bdfa22-2c16-417c-bc41-62353716c069';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Дипломатические решения» в социальном поведении. Во время конфликта ребёнок уже может предлагать: «Давай играть по очереди». Это один из самых ярких показателей социального интеллекта. Обязательно поддержите его миролюбивый подход словами: «Ты нашёл очень хорошее решение».') WHERE id = '1c1d5af4-d669-4eee-8938-97dcf06fd2d8';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Когнитивное развитие: «Понимание сохранения количества». Поиграйте с ребенком с песком или водой. Налейте одинаковое количество воды в разные емкости. Ребенок пока может думать, что в высокой емкости воды больше. Такие опыты подготавливают его мозг к пониманию физических свойств окружающего мира.') WHERE id = '32e16fdb-1a45-43a1-8bb5-fea77db311d2';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Бросок мяча из-за плеча». Ребенок уже может бросать мяч в цель сильнее и точнее. Это результат слаженной работы мышц рук и плеч. Поиграйте с ним в парке в небольшую игру «Забрось мяч в корзину». Это не только весело, но и улучшает контроль над телом.') WHERE id = '5eff2db7-b37a-4ebb-9335-292fea3a6331';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Развитие речи: «Абстрактные понятия: право и лево». Ребенок проявляет интерес к понятиям «правая рука» и «левая нога». Пока он может их путать — это нормально. Включайте эти понятия в повседневную жизнь, например, надевая ему носки, скажите: «Теперь вытяни правую ногу».') WHERE id = 'dcd74d19-3308-4446-89b6-05aecfc53aed';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Саморегуляция (Self-regulation)». Если у ребенка что-то не получается, он уже не сразу сердится, а может посмотреть на вас и спросить: «Попробовать еще раз?». Это одна из важнейших ступеней эмоциональной зрелости. Хвалите его не за результат, а за проявленные терпение и старание. Вы замечательная мама!') WHERE id = 'b36ad394-fd9c-40bc-963f-954848c1c743';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребенок уже применяет последовательность «сначала, сейчас, потом» к сложным действиям. «Сначала я уберу игрушки, потом вымою руки и поем». Это свидетельствует о развитии навыков стратегического планирования (executive function) в мозге. Позволяйте ему активно участвовать в составлении плана на день — это укрепляет его внутреннюю дисциплину.') WHERE id = 'a41e3209-8dbf-44ce-98bb-5a5b64b4268c';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая активность: «Статическое и динамическое равновесие». Ребенок уже может стоять на одной ноге 5-10 секунд или идти по узкому бордюру, не теряя равновесия. Это говорит о полном созревании вестибулярной системы. Самое время поиграть с ним в «Канатоходца».') WHERE id = '696cb686-c625-440d-93fe-4e04eee0ca77';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Развитие речи: «Причинно-следственная цепочка». Ребенок уже ищет логическое объяснение вашим запретам: «Почему сейчас нельзя сладкое?». Вместо ответа «Потому что я так сказала» объясните: «Потому что, если ты сейчас съешь сладкое, ты насытишься и не сможешь поесть полезный обед». Это оттачивает его логическое мышление.') WHERE id = '1bdc4f44-d5e0-42ee-9d67-dc1beca39c22';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Мелкая моторика: «Детали в изображении человека». Рисуя человека, ребенок уже добавляет мелкие детали: пальцы, ресницы, пуговицы или шапку. Такие рисунки — результат его внимательного наблюдения за окружающим миром и развития зрительно-моторной координации.') WHERE id = 'dd86234a-f54a-432f-bcb2-f0fc25c1a9f2';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Воображаемые страхи и смелость». В этом возрасте воображение настолько развито, что в темноте ребенок может видеть «монстров». Не отрицайте его страх, а вместе придумайте ритуалы, которые «прогоняют страх» — например, волшебную подушку или фонарик. Это укрепляет его чувство эмоциональной безопасности.') WHERE id = '30d373fa-79f5-41e2-b2ee-ce7f265298c1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Лидерство и сотрудничество» в социальном поведении. Ребенок уже сам придумывает сценарий игры и распределяет роли между друзьями: «Ты будешь кошкой, а я — твоим хозяином». Так он учится понимать социальную иерархию и роли. Иногда следуйте его сценарию, поддерживая такие проявления творческого лидерства.') WHERE id = 'ec5ff997-3ed4-4645-be9c-2d361314cc2f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Количество и числовой символ» в познавательном развитии. Ребенок уже хорошо понимает, что цифра «4» обозначает 4 яблока, а цифра «1» — один предмет. Давайте ему задания вроде «Дай мне 5 карандашей», чтобы укрепить связь между абстрактными числами и реальным количеством.') WHERE id = 'c8eb9b80-1c81-4e02-86f3-e8fdf448ffb9';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Ловля мяча двумя руками». Ребенок уже начинает ловить медленно брошенный в его сторону мяч, сгибая руки и прижимая их к груди, а иногда — ловя его прямо ладонями. Это свидетельствует о развитии скорости реакции и навыка зрительного слежения. Тренируйтесь вместе, перебрасывая мягкий мяч с близкого расстояния.') WHERE id = 'e3704303-d02a-47ea-9a47-f1164a3046e0';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Временные ориентиры» в речи. Ребенок всё уместнее использует понятия «вчера», «сегодня» и «завтра». Говоря: «Завтра я пойду к бабушке», он мысленно представляет последовательность событий во времени. В конце дня рассказывайте ему о планах на завтра как сказку перед сном. Это также формирует его представление о будущем времени.') WHERE id = '58a4bd7b-b429-45cf-92c2-f503f4e7d474';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Большой рубеж развития — 1350 дней! Ребенок уже официально покинул берега младенчества и свободно плывет по океану раннего детства. Его индивидуальность, чувство юмора и характер теперь вызывают у вас особый интерес. Все эти 1350 дней вы были самой надежной гаванью в его мире. Вы большая молодец, мама!') WHERE id = '647eb338-5057-4cf4-a29d-e4970189abc1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребенок уже применяет различие между «я» и «мы» в совместных играх. Если он распределяет обязанности, например: «Давай вместе построим дом: ты приноси кирпичики, а я буду их складывать», — это высшее проявление его способности к сотрудничеству. Создавайте условия, в которых он сможет попробовать себя в роли лидера или помощника при выполнении групповых задач. Так формируются его будущие навыки командной работы.') WHERE id = '56b16411-749d-48ab-a1c9-aec6ee4d3f2b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Быстрый бег и резкие повороты» в физическом развитии. Ребенок уже может резко менять направление во время бега, не теряя равновесия. Это показывает, насколько развились чувство собственного тела (проприоцепция) и мышечный контроль. Игра «Зигзагообразный бег» в парке станет для него отличной тренировкой.') WHERE id = '3acf9991-6e18-469c-8243-5255e3b47e73';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже различает предметы не только по внешнему виду, но и по материалу: "Это пластик, а это металл". Давайте ему предметы с разной текстурой и спрашивайте, чем они отличаются. Это помогает ему более детально анализировать окружающий мир и систематизировать свои знания о физических свойствах предметов.') WHERE id = '657efc38-ed5e-4e3a-9572-7dbdb9184154';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В физическом развитии — "Пик статического равновесия". Ребёнок уже может стоять на одной ноге 5-10 секунд, ни за что не держась. Это свидетельствует об укреплении как центра равновесия во внутреннем ухе, так и мышц спины и ног. Поиграйте с ним в игру "Замри", чтобы превратить тренировку этого навыка в весёлое занятие.') WHERE id = '2f039b11-24db-4020-90d7-1c5f7a16c171';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В развитии речи — "Цепочка причин и следствий". Теперь ребёнок ищет логическое объяснение вашим запретам: "Почему сейчас нельзя сладкое?". Вместо ответа "Потому что я так говорю" объясните: "Потому что, если ты сейчас съешь сладкое, ты наешься и не сможешь пообедать полезной едой". Это развивает его логическое мышление.') WHERE id = 'c914eb21-6b42-48f0-8ec0-5b93a47ae392';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В развитии мелкой моторики — "Детали в изображении человека". Рисуя человека, ребёнок уже добавляет мелкие детали: пальцы, ресницы, пуговицы или шапку. Такие рисунки показывают, насколько внимательно он наблюдает за окружающим миром, а также отражают развитие зрительно-моторной координации.') WHERE id = 'fdd8b340-0697-4aeb-8d02-8988eb7da642';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '"Управление воображаемыми страхами". В этом возрасте дети иногда боятся темноты или "монстров". Не отрицайте страх ребёнка — лучше придумайте игру, например с "волшебным фонариком, прогоняющим монстров". Ваша эмоциональная поддержка помогает ему понять, что эти страхи временны.') WHERE id = 'd0348641-27c7-4875-b24e-5d2722f25676';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В социальном поведении — "Сотрудничество ради общей цели". Ребёнок уже может вместе с другом распределять "кирпичики", чтобы построить большую башню. Теперь дети не просто играют рядом, а объединяются ради общей цели (совместная игра). Поддержите эту способность ребёнка договариваться словами: "Какая замечательная у вас команда!".') WHERE id = 'bd3e5f00-1925-4d9d-bea8-7fc43abbb171';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В познавательном развитии — "Проверка понимания сохранения количества". Ребёнок всё ещё может думать, что расплющенный кусок пластилина больше, чем пластилиновый шарик. Проводите с ним такие опыты: расплющите шарик, а затем снова скатайте его. Это помогает ребёнку понять неизменные законы физического мира.') WHERE id = '34ed2954-3007-40b2-9228-8e5bbced6cd6';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: "Ведение мяча ногами". Ребёнок уже не просто бьёт по мячу, а старается перемещаться, слегка подталкивая его ногой вперёд (дриблинг). Это требует динамического равновесия и зрительно-моторной координации ног. Сделайте для него в парке небольшую "футбольную дорожку" и предложите вести мяч к цели.') WHERE id = 'f67ac937-be10-4065-8ce0-71169b977a25';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Логическая цепочка вопросов «Почему?» в речи. Ребёнок уже не удовлетворяется вашим ответом и продолжает задавать вопросы: «А почему это так?». Отвечая, побуждайте его тоже размышлять: «Как ты думаешь, куда уходит солнце?». Это помогает объединить его воображение с интересом к науке. Расширяйте круг его интересов с помощью небольших энциклопедий.') WHERE id = '09e33fb1-46b4-4ad6-a2f6-bb3ee2d41636';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Складывание бумаги (основы оригами)» в развитии мелкой моторики. Ребёнок уже старается складывать бумагу ровно пополам и совмещать уголки. Эти движения не только укрепляют мышцы рук, но и помогают усвоить понятие геометрической симметрии. Научите его создавать простые фигурки из цветной бумаги.') WHERE id = 'b9689a6f-2bcb-421e-acea-f03b1095905f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Самоконтроль и выражение эмоций». Когда ребёнок злится, он уже может не просто кричать, а выразить свои чувства словами: «Я сейчас очень злюсь!». Признавайте его чувства: «Я тебя понимаю, злиться — это нормально». Это способствует развитию его эмоциональной зрелости.') WHERE id = '7a0c1e64-9ecb-47f6-83f4-aa32390210cd';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Дипломатические переговоры» в социальном поведении. Чтобы получить желаемое, ребёнок может начинать «торговаться»: «Если ты дашь мне эту машинку, я дам тебе шоколад». Это первые проявления навыков социального влияния и дипломатии. В игровой форме учите его правилам честных «переговоров».') WHERE id = '2dd70517-4599-4775-b1e7-2b11f39244da';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Понимание сохранения количества (объёма)» в познавательном развитии. Проведите с ребёнком эксперимент на кухне: налейте одинаковое количество воды в две ёмкости — одну широкую, а другую высокую и узкую. Он всё ещё может утверждать, что в высокой ёмкости воды больше. Такие опыты помогают ему разрешить противоречие между зрительным восприятием и логическим мышлением.') WHERE id = 'eb9fac33-252a-4cde-bb98-95be1aaf831f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Ведение мяча ногами». Ребёнок уже не просто бьёт по мячу, а старается вести его, слегка подталкивая ногой вперёд. Это требует динамического равновесия и внимания. Устройте вместе в парке небольшую «футбольную дорожку» и предложите ему провести мяч к цели.') WHERE id = 'f40621db-c962-42bd-85b1-429800b2b4ef';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Вежливость и социальные нормы» в речи. Ребёнок уже использует такие выражения, как «извините» и «можно?», не просто потому, что выучил их, а уместно, в зависимости от ситуации. Ваше общение с другими людьми — главный пример для него. Когда он ведёт себя вежливо, обязательно помогите ему почувствовать, какое приятное впечатление это производит на окружающих.') WHERE id = '3804d992-5f37-4fb4-bfb6-18ad143039e9';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Большое путешествие длиной в 1360 дней! Ребёнку уже исполнилось 45 месяцев. Теперь он — самостоятельная личность, маленький человек со своими мыслями, шутками и мечтами. Все эти 1360 дней вы были архитектором его мира. В его уверенном взгляде — отпечаток вашей любви. Вы замечательная мама!') WHERE id = '333176ec-4bc6-4177-b76d-921996ec28d4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Вежливость и этика» в речи. Ребенок уже использует слова «извините» и «пожалуйста» не просто потому, что заучил их, а осознанно. Тон, которым вы разговариваете с другими, — его главный учебник. Когда ребенок проявляет вежливость, помогите ему почувствовать, какое положительное впечатление это производит на окружающих.') WHERE id = '81b527f9-bc6c-4fa6-a384-bfac0dbe1b99';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Потрясающий путь длиной в 1370 дней! Ребенок уже полностью оставил позади привычки раннего детства и вступает в самый активный этап дошкольного периода. Он уже осознает себя как отдельное «я» и готов менять мир. Все эти 1370 дней вы были его самым надежным проводником. Поблагодарите себя за любовь и терпение!') WHERE id = '7f1e62d7-6f8c-466a-917b-3acd9000a197';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребенок уже начинает искать знакомые буквы в окружающих надписях, особенно первую букву своего имени. Это этап «визуального чтения». Не заставляйте его учить буквы — просто рассказывайте, какой звук обозначает каждый увиденный символ, превращая это в увлекательное открытие.') WHERE id = '395ee563-1ee4-4a29-8a28-f145933f9a6e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Динамическое маневрирование» в физической активности. Во время бега ребенок уже может легко обогнуть препятствие или резко изменить направление. Это свидетельствует о совершенствовании навыков моторного планирования в мозге. Поиграйте с ним в парке в «Зигзагообразную гонку», чтобы развить его ловкость.') WHERE id = 'cad61f20-8263-4b3a-bfc8-ed14fb447f18';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Прогнозирование и логика» в речи. Читая ребенку сказку, спросите: «Как ты думаешь, что произойдет дальше?» Он уже способен делать логичные предположения, соответствующие развитию событий. Это совершенствует как его воображение, так и способность понимать причинно-следственные связи.') WHERE id = '9337ce82-dd36-4b6f-a92e-336053ee8590';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Копирование фигуры: квадрат» в развитии мелкой моторики. В отличие от круга, рисование квадрата требует останавливать карандаш на углах и менять направление. Это важная физическая подготовка к освоению письма. Покажите ребенку, как нарисовать дом или машину, соединяя разные геометрические фигуры.') WHERE id = '90518b08-497d-4de6-998e-df3fea30a1f5';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Самоконтроль и терпение». Ребенок уже понимает, что необходимость ждать своей очереди или невозможность немедленно получить желаемое — это не «конец света». Он спокойнее реагирует на ваши слова «Подожди 5 минут». После ожидания обязательно скажите ему: «Спасибо, что проявил терпение», чтобы закрепить это положительное поведение.') WHERE id = '24183c71-3661-48ff-a107-410bfbd38523';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Командные игры по правилам» в социальном поведении. Ребенок уже проявляет интерес к совместным играм с другими детьми, в которых есть правила, например к пряткам. Это важный этап социальной адаптации. Когда он соблюдает правила, похвалите его словами: «Молодец, что играешь честно».') WHERE id = '04f3027e-9e30-43e8-bafb-f6c237c97831';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Распознавание количества (субитизация)» в когнитивном развитии. Ребёнок уже способен, не пересчитывая 4–5 предметов, с одного взгляда определить их количество. Показывайте ему карточки с разным количеством точек и спрашивайте: «Сколько здесь точек?». Этот навык закладывает основу для быстрых математических вычислений в будущем.') WHERE id = '494bf11b-00d7-4571-8a96-04e2a73dc57c';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Прыжки на одной ноге». Ребёнок уже пытается несколько раз подряд прыгнуть на одной ноге. Для этого необходимы как сила, так и хорошо развитое равновесие. Поиграйте с ним дома в игру «Прыжки по следам», чтобы укрепить мышцы ног и улучшить равновесие.') WHERE id = 'e519a6cc-28f9-4dbb-80e3-d4aaf6533df1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Визуализация времени» в развитии речи. Ребёнок уже хорошо понимает части дня и последовательность событий. «Утром, когда мы просыпаемся, восходит солнце, а вечером появляется луна». Обсуждение с ним завтрашних планов в формате «сначала, потом, в конце» также создаёт у него чувство безопасности.') WHERE id = '22058766-30d2-4299-8138-dbe3e33f7a99';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Дипломатия и поиск решений». Во время конфликта ребёнок уже не просто плачет, а предлагает: «Давай поделимся игрушкой» или «Дай мне это, а я дам тебе то». Это вершина социального интеллекта. Всегда поддерживайте его миролюбивый подход. Вы растите замечательную личность!') WHERE id = '29c7e41f-162a-440d-ad79-c662956e2e8e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже может одновременно группировать предметы и по цвету, и по размеру: «Давай сложим сюда все маленькие зелёные кубики». Это важный показатель когнитивной гибкости. Предлагайте ему игры «Найди и покажи» с разными критериями, чтобы развивать внимательность.') WHERE id = '428720ac-8db6-44a9-825f-ab25eee4d54f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Меткий бросок» в развитии двигательных навыков. Ребёнок уже может точнее бросить мяч или небольшой мешочек в определённую цель, например в корзину. Это свидетельствует о развитии способности оценивать расстояние в пространстве (spatial estimation) и регулировать силу броска. Устройте дома соревнование «Попади в цель» — оно также укрепляет зрительно-моторную координацию.') WHERE id = '5a34a884-0d1a-4ecc-8aaf-0538071d5d58';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Переход в речи от «Почему?» к «Как?». Теперь ребёнок спрашивает не только о причинах событий, но и о том, как всё устроено: «Как едет машина?», «Как идёт дождь?». Отвечая, объясняйте простые физические законы, например: «Колёса вращаются», — чтобы стимулировать его интерес к науке.') WHERE id = '43f973d1-c670-48fb-b082-c963d974b2cb';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Создание композиции» в развитии мелкой моторики. Рисуя, ребёнок уже изображает на одном листе несколько связанных между собой объектов: «Это дом, а это дерево рядом с ним». Это показывает, что он начинает воспринимать окружающий мир целостно и системно.') WHERE id = '4fc62a39-6aec-4659-8e0d-de5a572b7f58';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Саморегуляция (Self-regulation)». Теперь, когда ребенок злится, он старается заменить физическую реакцию (например, удар) словами: «Я злюсь!». Это огромный скачок в развитии эмоционального интеллекта. Когда он выражает свои чувства, выслушайте его и поддержите словами: «Я горжусь тобой за то, что ты выразил свои чувства словами».') WHERE id = '2e78bbc8-d3e0-46e9-b6f4-fd06f0ff0e92';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Диалог в ролевых играх» как часть социального поведения. Теперь во время игр ребенок выстраивает длинные диалоги: «Ты пришел в магазин и просишь у меня хлеб...». С помощью таких игр он осваивает социальные нормы и правила общения. Следуйте его сценарию и участвуйте в этом творческом процессе.') WHERE id = 'c878d5a6-c839-4863-9ea6-c1e45caf4ee6';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Классификация противоположностей» в когнитивном развитии. Ребенок уже хорошо различает понятия «горячий — холодный», «высокий — низкий», «тяжелый — легкий». Поиграйте с ним в игру «Назови противоположность»: вы говорите «большой», а он — «маленький». Это развивает как его словарный запас, так и абстрактное сравнительное мышление.') WHERE id = '96a1b8b4-4a53-4821-8a70-36e9af7db4b1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Маневрирование на лестнице». Ребенок уже уверенно поднимается и спускается по лестнице и иногда может сохранять равновесие, даже держа в руке игрушку. Это свидетельствует о высоком уровне динамического равновесия. Всегда оставайтесь рядом, но дайте ему уверенность и возможность двигаться самостоятельно.') WHERE id = 'e31518b3-755f-43f6-a042-c5c881774776';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Воображение и рассказы» в развитии речи. Ребенок может рассказывать вам придуманные им короткие сказки, в которых реальность переплетается с фантазией. Поддерживайте его рассказы заинтересованными вопросами, например: «Правда?» или «А что произошло потом?». Это поможет ему в будущем говорить свободно и выразительно.') WHERE id = '1285abea-7296-4d22-a83f-6877ea839c11';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Победа и поражение». Ребенок уже спокойнее воспринимает проигрыш в играх, хотя и не всегда. Его готовность попробовать снова со словами «Давай сыграем еще раз» свидетельствует о развитии силы воли. Всегда подчеркивайте этот важный жизненный навык, говоря: «Главное — играть».') WHERE id = 'ab47da7b-7dd4-423e-bf69-3500dd83cc2f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребенок уже применяет логику «если... то...» к сложным социальным ситуациям: «Если я дам ему свою игрушку, то и он даст мне свою». Это основа взаимных отношений. Поиграйте с ним в игру «Что произойдет?» (например: «Что произойдет, если мы не будем поливать цветок?»). Это развивает его способность предвидеть последствия.') WHERE id = 'd6bf3a90-b7f5-4d81-9101-4bd23f1bc25d';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Прыжок с высоты» в развитии физической активности. Ребенок уже может спрыгнуть с определенной высоты (например, с невысокой ступеньки) на обе ноги, не теряя равновесия. Это свидетельствует об укреплении коленных и голеностопных суставов. Научите его «мягко приземляться», слегка сгибая колени.') WHERE id = '2795a26f-4a85-42cd-9860-03afd8411f60';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Добро пожаловать в 47-й месяц! Ребёнок уже лучше понимает, что такое «ответственность». Давайте ему небольшие домашние «поручения» — например, полить растения или разложить салфетки на столе. Это поможет ему почувствовать себя важным и полезным членом семьи. Обязательно отмечайте его старания и благодарите за помощь.') WHERE id = '13b68bb4-0e80-4802-bd12-f626258d3f54';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В физическом развитии — «Бег с чередованием ног». Во время бега ребёнок уже может ритмично преодолевать ступеньки или препятствия, поочерёдно ставя ноги. Это показывает, насколько хорошо развились сила нижней части тела и зрительно-моторное планирование.') WHERE id = '8fba68a9-4860-41c9-9d6a-0aabd4a4dc7d';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В развитии речи — «Звуки и буквы». Ребёнок уже различает, с какого звука начинаются слова: «Арбуз начинается со звука „А“». Поиграйте с ним в «Охоту на звуки»: попросите найти в комнате предметы, названия которых начинаются с определённого звука. Это важнейшая основа будущих навыков чтения и письма.') WHERE id = '4c5fdac9-9874-4896-80d4-6960b6675b1b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В развитии мелкой моторики — «Правильный трёхпальцевый захват карандаша». Ребёнок уже увереннее держит карандаш большим, указательным и средним пальцами. Это позволяет ему рисовать более детальные изображения и копировать буквы. Предлагайте ему карандаши разной толщины, чтобы тренировать мышцы пальцев.') WHERE id = '01cf8b7d-9668-4ab1-a360-d6968cb99749';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Самоконтроль: понимание смысла правил». Ребёнок уже старается соблюдать правила не просто потому, что вы так сказали, а потому, что понимает их смысл: «Когда мы идём по улице, я держу тебя за руку, потому что рядом машины». Продолжайте объяснять ему, что правила важны для безопасности и порядка. Это основа внутренней дисциплины.') WHERE id = 'd91c45ef-c67b-4312-9a1e-572e86ed0a0e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В социальном поведении — «Справедливое распределение». Ребёнок уже проявляет интерес к тому, чтобы поровну делить игрушки или сладости с друзьями: «Одно тебе, одно мне». Это сочетание социальной эмпатии и начальных математических представлений о делении.') WHERE id = '2a9fd489-5479-4444-9ad0-d9ca9e6d37c8';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В познавательном развитии — «Классификация предметов». Ребёнок уже группирует предметы как по виду, так и по месту использования: «Это для кухни, а это для спальни». Это показывает, насколько системно и иерархично организована информация в его сознании.') WHERE id = 'b49a3e45-1e44-429c-b3ab-7432f30a4a37';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Ловля и бросок мяча». Ребёнок уже может поймать мяч и сразу же бросить его в цель. Это демонстрирует способность плавно переходить от одного последовательного движения к другому. Устройте с ним в парке игру «Бросай — лови», чтобы развивать скорость реакции и ловкость.') WHERE id = 'b2cee277-0949-412e-af09-df96b2fd9cfd';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Сложные предложения» в речи. Ребёнок уже строит длинные и логичные предложения, используя такие союзы, как «если», «потому что», «но». Слушайте его, не перебивая, и помогайте развивать мысль, говоря: «Значит, ты думаешь, что...». Это улучшает навыки самовыражения и помогает активнее использовать словарный запас.') WHERE id = 'eaf98320-82a4-46ba-81fe-43fd023e6b82';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: «Умение успокаивать себя». После небольшого падения или неудачи ребёнок уже может не расплакаться сразу, а сказать себе: «Ничего страшного» — и подняться. Это важный показатель эмоциональной устойчивости. Поддерживайте его смелость словами: «Ты такой сильный!».') WHERE id = 'c0cb0b02-4a51-4012-b51b-53868aad0bf0';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже начинает интересоваться понятием времени. Он может спросить: «Который час?». Объясняйте ему время не в минутах, а через события: «Когда большая стрелка дойдёт сюда, мы пойдём гулять». Это поможет ему понять, что время можно измерять.') WHERE id = '3a58737c-1dc5-47f3-86ee-31c959892712';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Перекрёстная координация» в двигательной активности. Ребёнок уже может, шагая на месте, касаться правой рукой левого колена и наоборот. Это движение требует одновременной работы обоих полушарий мозга и в будущем облегчает освоение чтения и письма.') WHERE id = '86960e2f-7035-4c14-a9a6-baeb23c3ea3d';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Подробности прошлого» в речи. Ребёнок уже может последовательно рассказать о событии, произошедшем несколько дней назад: «Когда мы ходили к бабушке, мы увидели там кошку, и она залезла на дерево». Чтобы укреплять его «эпизодическую память», в конце дня спрашивайте: «Что сегодня было самым интересным?».') WHERE id = '6caf0def-6055-4b83-9a80-442193cfb9e1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Вырезание из бумаги: сложные формы» в развитии мелкой моторики. Ребёнок уже пытается вырезать ножницами не только по прямой линии, но и по волнистым линиям или вырезать большой круг. Это свидетельствует об очень высоком уровне развития зрительно-моторной координации.') WHERE id = '64c3b0ce-8c21-4147-b606-f32ae65475bf';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Понятия правого и левого». Ребёнок уже может различать правую и левую руку, хотя пока не всегда безошибочно. Укрепляйте его ориентацию в пространстве, говоря: «Возьми ложку правой рукой» или «Надень носок на левую ногу». Этот навык важен для того, чтобы в будущем не путать направление написания букв.') WHERE id = '51c70f08-e08e-4a17-97ca-6373b3c435eb';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Лидерство в группе» в социальном поведении. Во время игры ребёнок уже распределяет роли между другими детьми, говоря: «Ты иди сюда, а ты сделай это». Так он проверяет своё понимание социальной иерархии и организаторские способности. Наблюдайте за его попытками проявлять лидерство и помогайте ему быть справедливым.') WHERE id = 'ed221959-c928-4692-880d-29170d62352e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Абстрактные понятия времени» в речи. Малыш уже понимает более широкие временные периоды, такие как «на выходных», «в праздник», «в день рождения». Разговаривая с ним о предстоящем важном событии (например, о прогулке), используйте выражения вроде «через 3 дня», чтобы углубить его восприятие времени.') WHERE id = '4dbdf376-fb0e-469f-bb2e-b3be32d8d1c8';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Копирование букв» в развитии мелкой моторики. Малыш уже пытается копировать некоторые простые буквы (например, А, О, Т), глядя на их написание. Так символы закрепляются одновременно в зрительной и моторной памяти. Предложите ему «писать» буквы на подносе с песком или пальчиковыми красками.') WHERE id = '83f43947-4f06-425b-801a-dd053a64d6b1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Самоконтроль: умение откладывать желание». Малыш уже принимает, что ради вознаграждения нужно немного подождать (например, «сладкое после еды»). Это свидетельствует о развитии силы воли и самоконтроля (отсроченного вознаграждения). Обязательно отмечайте и хвалите его терпение — в будущем оно станет залогом успешной учёбы.') WHERE id = '51891c5d-a6e3-40d4-8ba5-38112ce2f223';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Групповая солидарность» в социальном поведении. Когда друг плачет, малыш уже не просто смотрит на него, а спрашивает: «Что случилось?» — или сообщает вам. Это активный этап развития эмпатии. Поддержите его заботливость, сказав: «Ты очень добрый друг».') WHERE id = '9932ed27-e891-4fec-aac9-e64c5a418a49';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Основы сложения» в познавательном развитии. Малыш уже может понять, что если к 2 игрушкам добавить ещё 1, то всего получится 3, не пересчитывая их или считая очень быстро. В повседневных делах задавайте ему небольшие математические задачки, например: «У тебя было 2 яблока, я дала тебе ещё 1. Сколько стало?»') WHERE id = '5f9e5aa3-02e0-4bd3-85bf-ad954730aed0';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Прыжки на одной ноге (Hop-stop)». Малыш уже может 2-3 раза подряд подпрыгнуть на одной ноге. Для этого необходимы хорошее равновесие и сильные мышцы ног. Играйте с ним дома в «Классики», чтобы вывести его координацию на новый уровень.') WHERE id = '5d319604-f8fa-4e75-83e3-e78cf306cb47';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Описательный рассказ» в речи. Малыш уже может последовательными предложениями рассказать о своём рисунке или увиденном событии. «Здесь была собака, она побежала, а потом забралась на дерево...». Обращайте внимание на последовательность его речи. Она показывает, как в его мозге формируется логический порядок событий.') WHERE id = '5e32473e-0836-4d23-8816-7e98014c394b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Большая победа — 1400 дней! Вашему малышу уже исполнилось 46 месяцев. Теперь он — маленький «учёный», который осознаёт себя, сопереживает чувствам других и познаёт мир с помощью логики. Все эти 1400 дней вы были для своего малыша самой надёжной гаванью и лучшим учителем. Вы замечательная мама!') WHERE id = 'af7c9867-8fc8-42cc-b62a-1044c801bdef';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Когнитивное развитие — «Сохранение количества: число». Если разложить одинаковое количество камней с одной стороны близко друг к другу, а с другой — на большом расстоянии, ребёнок уже начинает понимать, что камней с обеих сторон поровну. Это этап перехода от зрительного восприятия к логическим выводам.') WHERE id = '55c3f5e4-d3a4-465e-b035-b83e41b450d4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация — «Прыжки на одной ноге». Ребёнок уже может несколько раз подряд прыгнуть вперёд на одной ноге. Для этого необходимы как равновесие, так и взрывная сила мышц ног. Сейчас отличное время, чтобы поиграть с ним дома в «классики».') WHERE id = 'ddfca79d-8eb7-4cbd-84fd-61e54d7153db';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Развитие речи — «Звуки внутри слов». Ребёнок уже различает и звуки в конце слов (например, может сказать, что слово «яблоко» оканчивается на звук «о»). Это свидетельствует о высоком уровне развития фонематического слуха. Играйте с ним в «Назови слово на последний звук» — словесную цепочку, чтобы расширять словарный запас и развивать слуховое внимание.') WHERE id = '3863c552-322d-4dc8-a917-02d61270f313';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость — «Неудача и стратегия». Если у ребёнка что-то не получается, он уже не сразу начинает плакать, а задумывается: «Может, попробовать по-другому?». Это основа «мышления роста» (growth mindset). Обязательно хвалите его не за результат, а за стремление найти новый способ.') WHERE id = 'da0d4f8a-08c6-45ad-9022-933f9025eb01';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже различает предметы не только по внешнему виду, но и по материалу: «Это пластик, а это металл». Давайте ему предметы с разной текстурой и спрашивайте, чем они отличаются. Это помогает ему подробнее анализировать окружающий мир и систематизировать знания о физических свойствах предметов.') WHERE id = 'ec9b72ac-4600-4d72-8d5e-3a0bc232d29c';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическое развитие — «Точный прыжок». Ребёнок уже может прыгнуть к определённой цели, например внутрь нарисованного на земле круга. Это свидетельствует как о способности сохранять равновесие, так и об умении оценивать расстояние в пространстве. Игра в «прыжки с камня на камень» в парке станет для него отличной тренировкой.') WHERE id = 'f6611b06-b8bc-42ff-84b4-2e17ea2e10d6';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Развитие речи — «Различение противоположностей». Ребёнок уже хорошо различает понятия «горячий — холодный», «высокий — низкий», «тяжёлый — лёгкий». Поиграйте с ним в игру «Назови противоположность»: вы говорите «большой», а он — «маленький». Это развивает и словарный запас, и абстрактное сравнительное мышление.') WHERE id = '00735398-0d89-4428-a943-f4a27fc19021';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Мелкая моторика — «Копирование фигур: треугольник и крест». Ребёнок уже может нарисовать крест (+), пересекая прямые линии, и пытается изображать фигуры, похожие на треугольник. Это первые основы навыка письма. Дайте ему цветные карандаши и чистые листы бумаги, чтобы поддержать эти «геометрические открытия».') WHERE id = '1b117df4-43a4-4780-a2e3-365c2acc3518';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Самоконтроль: умение откладывать желаемое». Ребёнок уже понимает, что ради награды нужно немного подождать (например, «сладкое после еды»). Это свидетельствует о развитии силы воли и самоконтроля (отложенного удовлетворения). Обязательно отмечайте его терпение — это залог будущих успехов в учёбе.') WHERE id = '93c7b1b4-9941-4328-bd03-c48ffc7f605f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Групповая солидарность» в социальном поведении. Теперь, когда друг плачет, ребёнок уже не просто смотрит на него, а спрашивает: «Что случилось?» — или сообщает вам. Это активный этап развития эмпатии. Поддерживайте его заботливость словами: «Ты очень добрый друг».') WHERE id = 'e9a7f349-2186-4929-ba3f-64f7d951af57';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Основы сложения» в когнитивном развитии. Ребёнок уже может понять, что если к 2 игрушкам добавить ещё 1, то всего получится 3, не пересчитывая их или делая это очень быстро. В повседневных делах предлагайте ему небольшие математические задачки, например: «У тебя было 2 яблока, я дала тебе ещё 1. Сколько стало?»') WHERE id = '6d1eeaa2-0164-4cca-94b4-9c14e8d79d60';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Передвижение по лестнице». Ребёнок уже уверенно поднимается и спускается по лестнице и иногда может сохранять равновесие, даже держа в руке игрушку. Это высокий уровень динамического равновесия. Всегда будьте рядом, но давайте ему возможность двигаться самостоятельно и уверенно.') WHERE id = '28cfd5f7-ecbc-4133-9e9d-cc5c82140054';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Воображение и рассказы» в развитии речи. Ребёнок уже может рассказывать вам небольшие сказки, которые придумал сам. В них реальность переплетается с фантазией. Поддерживайте его рассказы заинтересованными вопросами: «Правда?» или «А что было потом?». Это поможет его речи в будущем стать плавной и выразительной.') WHERE id = 'c414dc79-8944-48c3-a5d5-e50145e600bc';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Победа длиной в 1430 дней! Ребёнку уже исполнилось 47 месяцев. Теперь он — маленький «учёный», который осознаёт себя, сопереживает чувствам других и познаёт мир с помощью логики. Все эти 1430 дней вы были для своего ребёнка самой надёжной гаванью и лучшим учителем. Вы замечательная мама!') WHERE id = '8f2e9299-bb7b-4d28-9fbc-c07c7ba2a262';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Начался обратный отсчёт до 48-го месяца (4 лет)! Ребёнок уже в полной мере применяет различие между «я» и «мы» в совместных играх. Если он распределяет роли, например: «Давай вместе построим корабль: ты держи парус, а я буду у штурвала», — это вершина развития навыков сотрудничества. Поддерживайте его командный дух — это важно для будущей школьной жизни.') WHERE id = 'b940be7d-ee82-4c09-8760-e2ce9294193f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Точные повороты» в физической активности. Ребёнок уже может внезапно остановиться во время бега на полной скорости или резко повернуть, не потеряв равновесия. Это результат полностью скоординированной работы вестибулярной системы и мышечного контроля. Устройте для него в парке небольшую «полосу препятствий».') WHERE id = 'ce453995-5119-4943-ace6-1439bc5d5820';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В речи — "Анализ звуков". Ребёнок уже начинает выделять звуки не только в начале, но и в конце слов: "Слово «мама» заканчивается на «А»". Это свидетельствует о развитии фонематического слуха. Поиграйте с ним в игру "Придумай новое слово на последний звук", чтобы развить его языковое чутьё.') WHERE id = 'e258838d-b844-4e68-840e-2eb0ef520682';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В мелкой моторике — "Вырезание из бумаги: сложные фигуры". Ребёнок уже пытается вырезать ножницами по контуру сложные формы, например звезду или силуэт маленького животного. Это показывает, насколько усовершенствовалась зрительно-моторная координация. Предложите ему бумагу разных цветов.') WHERE id = '619d1623-d881-46f6-a718-4a537172efc7';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '"Самоконтроль: эмоциональная дипломатия". Если ребёнок не получает желаемого, он уже может не кричать, а объяснить вам причину: "Но я так этого хотел, потому что...". Цените его попытки вести диалог. Признайте его чувства, но при этом терпеливо объясните, почему правила остаются неизменными.') WHERE id = 'd8f54a1a-d4b0-4c91-b361-1e6376bfa2db';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В социальном поведении — "Соблюдение правил". Ребёнок уже придаёт особое значение тому, чтобы не нарушать правила в настольных играх, например в домино или простых играх с числами. Это важный этап социальной адаптации. Когда он соблюдает правила, поддержите его словами: "Ты играл очень честно и терпеливо".') WHERE id = '111e7db0-d36d-44a0-97d8-10b28cd566ca';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В познавательном развитии — "Понимание сохранения количества: проверка объёма". Если одинаковое количество пластилина сначала скатать в шар, а затем придать ему форму длинной "змейки", ребёнок уже начинает понимать, что количество осталось прежним. Это этап перехода от зрительного восприятия к логическим выводам. Проводите такие эксперименты вместе.') WHERE id = '0655a03a-60b9-48e1-b285-1d3c83082836';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: "Прыжки на одной ноге". Ребёнок уже может несколько раз подряд прыгнуть вперёд на одной ноге. Это требует как равновесия, так и силы мышц ног. Сейчас отличное время, чтобы поиграть с ним дома в "Следы" — эта игра также развивает ориентацию в пространстве.') WHERE id = 'c5a0358e-6841-4ba2-8c21-cb976413e324';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В речи — "Сочетание воображения и логики". Ребёнок уже может рассказывать вам придуманные им сказки с логичной последовательностью событий. "Однажды жил робот, и он остановился, потому что у него разрядилась батарея...". Поддерживайте его рассказы вопросами вроде "А что произошло потом?". Это поможет ему в будущем говорить связно и выразительно.') WHERE id = '5fe788e8-9a0a-4448-9455-65cf7a8679b1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Эмоциональная устойчивость: "Новая стратегия при неудаче". Если у ребёнка что-то не получается, например собрать пазл, он уже не сразу сердится, а ищет новые способы: "Может быть, попробовать положить это сюда?". Это основа "мышления роста" (growth mindset). Обязательно хвалите не результат, а его старания найти новый способ.') WHERE id = '19cb7d19-f480-4e1f-805a-267dba1df2a8';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Календарь времени» для развития мышления. Ребёнок уже понимает такие выражения, как «осталось 3 дня» или «мы пойдём в выходные». Незадолго до дня рождения сделайте «календарь обратного отсчёта». Отмечая каждый прошедший день, ребёнок сможет наглядно представить течение времени.') WHERE id = 'e9a169de-bc44-43dd-b6f0-9adaff7e3796';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Попадание мячом в цель». Ребёнок уже не просто пинает мяч, а старается направить его в определённую цель — например, между двумя камнями. Это требует умения оценивать расстояние в пространстве и точно координировать работу мышц ног.') WHERE id = '1c5a132d-9357-46a5-b5fe-17d6baae9cac';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Создание сложных историй» в развитии речи. В придуманных сказках ребёнок уже выстраивает сюжет, используя такие союзы и выражения, как «потому что», «но», «поэтому». Внимательно слушайте его истории и побуждайте добавлять новые подробности вопросами вроде: «Как ты думаешь, что герой сделал потом?»') WHERE id = '24dad4d0-2c9d-4d1c-bb0a-41d9b402e0e7';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'До 4-летия осталось всего 20 дней! Ребёнок уже полностью оставил позади младенческие привычки и превратился в маленькую личность со своим неповторимым характером. Все эти 1460 дней вы были для него самым ярким светом на пути развития. Его успехи — результат вашей любви. Вы великолепны!') WHERE id = 'd76fe554-fd7b-4db0-9296-a5ba3be690d0';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Воображение и рассказы» в речи. Ребёнок может рассказывать вам небольшие сказки, которые придумал сам. В этих сказках реальность переплетается с фантазией. Поддерживайте его рассказы заинтересованными вопросами, например: «Правда?» или «А что было потом?». Это поможет в будущем сделать его речь плавной и выразительной.') WHERE id = 'e96b1dc7-ba0c-47d3-b15a-cb6918e2bc9b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'До 4 лет осталось всего 30 дней! Сейчас ребёнок находится в самом продуктивном периоде дошкольного возраста. Он уже самостоятельная личность — маленький человек со своими предпочтениями, страхами и бесконечными вопросами. Вы прошли этот путь, опираясь на знания и любовь. Anacan всегда рядом с вами!') WHERE id = '34fd4a41-2c8b-49b5-b2b0-6911f5bb04ab';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже группирует предметы не только по внешнему виду, но и по принадлежности к определённой категории: «Это морские животные, а это — лесные». Это показывает, что информация в его мозге уже распределяется по научным категориям. Поиграйте с ним в игру «Кто где живёт?».') WHERE id = 'bacec645-5384-4fc1-94d1-94b2914a27a1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Быстрый бег и координированная остановка» в физической активности. Теперь ребёнок, даже когда бежит на полной скорости, может по вашей команде «Стоп!» сразу остановиться, не упав и не споткнувшись. Это свидетельствует о высоком уровне мышечного контроля и слухомоторной реакции. Регулярно повторяйте эту игру в парке.') WHERE id = 'ea737131-3977-4085-b4c4-94dd4ae125f1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Вежливое обсуждение» в речи. Чтобы получить желаемое, ребёнок уже не только говорит: «Пожалуйста, можно?», но и объясняет причину: «Потому что мне это очень нравится». Ваш вежливый ответ формирует его язык социального общения. Хвалите его за каждую вежливую просьбу, говоря: «Когда ты так красиво просишь, мне приятно тебе отвечать».') WHERE id = '0bfff590-18d1-438c-bef2-c5dac59fc7e3';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Визуальное копирование букв и цифр» в мелкой моторике. Ребёнок уже пытается изобразить на бумаге буквы своего имени или такие цифры, как «1, 2, 3». Это результат объединения движений со зрительной памятью. Дайте ему карандаши разных цветов и повесьте его «записи» на видном месте в доме.') WHERE id = '65fb665a-a079-4bde-be1e-8536275e5fd6';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Саморегуляция: эмоциональная самостоятельность». Столкнувшись с небольшой проблемой (например, если игрушка развалилась), ребёнок уже не сразу бежит к вам, а сначала пытается всё исправить сам. Это укрепляет ощущение «я справлюсь». Наблюдайте за его самостоятельными попытками и вмешивайтесь только тогда, когда ему действительно нужна помощь.') WHERE id = '5a2e55ce-3f97-41a9-965d-b857b33a020f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Объяснение правил» в социальном поведении. Ребёнок уже объясняет правила игры малышам или своим игрушкам: «Сначала я, потом ты». Это признак внутренней дисциплины и лидерских способностей. Поддерживайте в нём стремление быть «учителем».') WHERE id = '1e4b1da3-fa3d-4b83-9554-7fdd901b9dfb';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ребёнок уже различает предметы не только по внешнему виду, но и по материалу: «Это пластик, а это металл». Давайте ему предметы с разной текстурой и спрашивайте, чем они отличаются. Это помогает ему более детально анализировать окружающий мир и систематизировать знания о физических свойствах предметов.') WHERE id = '0ec14802-bab2-45c4-8cbf-788bdfa85e13';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Точный прыжок» в физическом развитии. Ребёнок уже может прыгнуть к определённой цели, например внутрь нарисованного на земле круга. Это свидетельствует как о развитии равновесия, так и об умении оценивать расстояние в пространстве. Игра «Прыжки с камня на камень» в парке станет для него отличной тренировкой.') WHERE id = '0ddedeb7-e832-48ca-923d-05838885cdc1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Классификация противоположностей» в развитии речи. Ребёнок уже хорошо различает такие понятия, как «горячий — холодный», «высокий — низкий», «тяжёлый — лёгкий». Поиграйте с ним в игру «Назови наоборот»: вы говорите «большой», а он — «маленький». Это развивает как словарный запас, так и абстрактное сравнительное мышление.') WHERE id = '3810cfc8-49ab-40fa-b90d-2edf9dc84fae';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Копирование фигур: треугольник и крест» в развитии мелкой моторики. Ребёнок уже может нарисовать крест (+), пересекая прямые линии, и пытается изображать фигуры, похожие на треугольник. Это первые основы навыка письма. Дайте ему цветные карандаши и чистые листы бумаги, чтобы поддержать его «геометрические открытия».') WHERE id = 'dfeb7b05-cea8-4a6f-b41b-005f3d3c488e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Самоконтроль: умение откладывать желаемое». Ребёнок уже понимает, что ради награды нужно немного подождать, например: «Сладкое — после еды». Это свидетельствует о развитии силы воли и самоконтроля — способности откладывать получение удовольствия. Обязательно отмечайте его терпение: в будущем оно станет одним из ключей к успешной учёбе.') WHERE id = '988ae101-5f2f-4a86-a365-28a27e843965';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Групповая сплочённость» в социальном поведении. Теперь, когда друг плачет, ребёнок не просто смотрит на него, а спрашивает: «Что случилось?» — или сообщает вам. Это активный этап развития эмпатии. Поддерживайте его заботливость словами: «Ты очень добрый друг».') WHERE id = 'ed4539aa-f1cf-4dd1-97f9-a5cf3f6b499d';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Основы сложения» в познавательном развитии. Ребёнок уже может понять, что если к 2 игрушкам добавить ещё 1, то всего получится 3, не пересчитывая их или посчитав очень быстро. В повседневных делах предлагайте ему небольшие математические задачки, например: «У тебя было 2 яблока, я дала тебе ещё 1. Сколько стало?»') WHERE id = '321e201a-5cd6-485a-a700-1c1f11885a2b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Физическая координация: «Маневрирование на лестнице». Ребёнок уже уверенно поднимается и спускается по лестнице и иногда может сохранять равновесие, даже если держит в руках игрушку. Это свидетельствует о высоком уровне динамического равновесия. Всегда оставайтесь рядом, но показывайте, что доверяете ему, и позволяйте двигаться самостоятельно.') WHERE id = '26b9ae52-0022-4e15-934b-ad179ba90589';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Добро пожаловать, дорогая мама! Сегодня открывается самая новая и, пожалуй, самая волнующая страница вашей жизни. Сейчас для вас важнее всего одно — отдыхать и наладить первый физический контакт с малышом; домашние дела, телефонные звонки и гости могут подождать. Знайте: то густое желтоватое молоко первого дня (молозиво) хоть и невелико по объёму, но обладает чудесным составом и играет роль первой прививки для вашего малыша. Не бойтесь, что молока мало: желудок малыша пока размером с вишенку, и этих капель ему совершенно достаточно. Не старайтесь вести себя как героиня — боль и усталость совершенно естественны. Просто прилягте, вдохните запах малыша, почувствуйте его тепло и насладитесь этим моментом, ведь именно сейчас закладывается основа вашей связи.') WHERE id = 'ced035b3-8303-4f5d-95fd-7e29e2539509';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ваше тело проделало великолепную работу за 9 месяцев, и теперь внутренние органы понемногу возвращаются на свои места. Особенно во время кормления грудью вы можете чувствовать схваткообразные боли внизу живота — не волнуйтесь, это положительный признак того, что матка сокращается и возвращается к прежним размерам. Не поддавайтесь распространённым заблуждениям вроде «молока мало, ребёнок не наедается, поэтому плачет». Малыш может часто просить грудь не только от голода, но и чтобы почувствовать ваш запах, услышать стук вашего сердца и ощутить себя в безопасности. Дайте ему эту уверенность, берите на руки и кормите почаще; помните: чем чаще малыш сосёт грудь, тем больше становится молока.') WHERE id = 'f5dc2c0a-cfb4-4205-ad61-5a643545c576';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В эти дни грудь может начать наполняться (прилив молока), что вызывает ощущение тяжести и жара. Одновременно из-за резких гормональных изменений вы можете чувствовать беспричинную грусть, плаксивость или раздражительность; в медицине это называется «Baby blues». Эти чувства не означают, что вы «плохая мама» или не справляетесь, — это просто физиологический процесс, и он пройдёт. Не сдерживайте слёзы: если хочется плакать, дайте волю чувствам и не стесняйтесь говорить об этом с близкими. Вы не одни — этот переходный период проживают тысячи мам, как и вы. Дышите глубже и просто позвольте времени делать своё дело.') WHERE id = '04d25f7c-e375-4514-ac39-dc2728da56e3';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Чтобы восстановить силы, уделите особое внимание питанию, но отбросьте устаревшие запреты вроде «застудишься», «не ешь фрукты», «не пей воду». Разнообразное, богатое витаминами питание и обильное питьё важны не столько для качества молока, сколько для восстановления ваших физических сил и душевной бодрости. Что касается пуповинного остатка малыша: прижигать его спиртом или заматывать не нужно. Просто следите, чтобы он оставался сухим и чистым, а застёгивая подгузник, оставляйте область пупка открытой для доступа воздуха; контакт с воздухом — лучшее средство, ускоряющее заживление.') WHERE id = '5cdec801-b16c-449e-bf65-9a37a9e133f1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Добро пожаловать в дни, когда ночь и день меняются местами и даёт о себе знать недосып, сильная мама! Вокруг могут говорить: «не приучай ребёнка к рукам», но знайте: в первые месяцы «избаловать» малыша невозможно. Вы ему нужны, и ношение на руках, контакт кожа к коже — самый действенный способ и для развития его мозга, и для увеличения вашего молока. Домашние дела не убегут, посуда может подождать, а вот ваш сон и отдых важнее всего. Как только малыш уснёт, постарайтесь и вы закрыть глаза и отдохнуть — даже 15-минутный сон придаст вам сил.') WHERE id = '726dd7ee-a857-41fc-aad0-622f7b5ddf29';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Вы не обязаны делать всё в одиночку и создавать образ «супермамы»; просить о помощи — не слабость, а наоборот, проявление силы. Просите мужа, маму или близких о конкретных делах: например, принести еду или присмотреть за малышом, пока вы принимаете душ. Уход за собой, душ и чашка горячего чая — не эгоизм, а необходимость, чтобы лучше справляться с материнскими заботами. Помните: счастливая и отдохнувшая мама — это счастливый малыш, поэтому не стесняйтесь делить свою ношу с другими.') WHERE id = '1ddced84-3654-418b-9996-21c50802a72f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Поздравляем, вы мама уже целую неделю и, несмотря на трудности, успешно прошли эти дни! Глядя в зеркало, вы, возможно, видите, что живот ещё не подтянулся, а волосы растрёпаны, но вы растите чудо — и вы прекрасны такой, какая есть. С этого дня можно начинать ненадолго (1–2 минуты) выкладывать малыша на животик (tummy time), когда он бодрствует и находится под присмотром. Это маленькое упражнение укрепит мышцы его шеи и спины, поможет при коликах и заложит основу его будущего физического развития.') WHERE id = '33d098f8-b80c-478c-bb61-a7d57cd72e57';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Вы можете заметить лёгкую желтизну кожи или белков глаз малыша; это физиологическая желтуха, и в большинстве случаев она проходит благодаря частым кормлениям грудью. Но если желтизна опускается к ножкам и малыш стал очень вялым, обязательно проконсультируйтесь с врачом. Кроме того, не бойтесь проветривать комнату; мнение «пока не прошло сорока дней — никакого свежего воздуха» — просто миф, чистый кислород важен и для вашего мозга, и для мозга малыша. Откройте окно, проветрите комнату или, если есть возможность, оденьте малыша по погоде и ненадолго вынесите на свежий воздух (если врач разрешил).') WHERE id = '55de4073-ef7d-4cff-84f4-bf2b8f830118';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Наши бабушки любят туго пеленать, «чтобы ножки были ровными», но современная медицина доказала: для здорового развития тазобедренных суставов ножки малыша должны свободно двигаться. Если малыш вздрагивает от собственных движений ручек и просыпается, можно слегка запеленать только ручки (свободное пеленание), но обязательно оставьте ножки свободными, в позе «лягушки». Тугое пеленание, сковывающее движения, может плохо влиять на кровообращение и развитие мышц. Дайте малышу свободу — пусть открывает мир ручками и ножками.') WHERE id = '94a133da-1fcc-4ffe-a24b-b9755a414c0b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Вот уже 10 дней всё ваше внимание и мысли заняты малышом, но сегодня постарайтесь выделить хотя бы 15–20 минут только для себя. Примите тёплый душ, послушайте любимую музыку, поухаживайте за кожей или просто помечтайте, глядя в окно. Понемногу пробуйте чувствовать мышцы тазового дна (самая лёгкая форма упражнений Кегеля), чтобы ускорить восстановление, но для серьёзного спорта пока слишком рано. Слушайте своё тело, относитесь к нему бережно и помните: вы — главная опора для своего ребёнка, и ваше физическое и душевное здоровье — самый большой подарок для него.') WHERE id = '4ba69869-3aaa-471c-bba8-3e9678c5f231';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Пуповинный остаток малыша, возможно, уже подсох и отпал или вот-вот отпадёт; это совершенно естественный процесс, и не пугайтесь, если увидите на месте пупка небольшое пятнышко крови. После отпадения остатка важно и дальше держать эту область сухой и чистой, ведь влажная среда благоприятна для размножения бактерий. Иногда мам беспокоит «выпуклая» форма пупка, но по мере укрепления мышц живота он чаще всего занимает своё место; поэтому избегайте старинных способов вроде прикладывания монетки или тугого стягивания. Если заметите вокруг пупка покраснение, неприятный запах или гной, сразу сообщите врачу, а в остальном — просто позвольте природе делать своё дело.') WHERE id = '4412d0c9-03dd-43c8-bb46-87b4fecadda2';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В эти дни вы можете заметить, что малыш как будто не наедается и хочет сосать грудь постоянно, порой каждый час; в медицине это называется «скачок роста» (growth spurt). Мамы часто принимают это за «молоко пропало, ребёнок голодный», впадают в панику и спешат перейти на смесь, но на самом деле так малыш подаёт вашему организму сигнал «вырабатывай больше молока», чтобы покрыть свои растущие потребности. Будьте терпеливы, это временно и обычно длится один-два дня; просто следуйте за желанием малыша и чаще прикладывайте его к груди. Пейте больше воды и отдыхайте — и помните: количество молока естественным образом подстроится под потребности малыша.') WHERE id = '8aab5133-1153-4e9f-bfa1-1ddc76290148';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Если по вечерам малыш плачет без видимой причины, поджимает ножки к животу и краснеет, это может быть началом колик; они говорят лишь о том, что его пищеварительная система ещё созревает. Не паникуйте: эти боли не означают проблем со здоровьем малыша — ему просто нужна небольшая помощь. Мягкий массаж животика по часовой стрелке или упражнение «велосипед» помогут ему расслабиться. Также может облегчить колики ношение малыша животиком вниз на вашем предплечье («поза тигра»). Наберитесь терпения: это может казаться «бесконечными ночами», но после 3–4 месяцев колики полностью исчезнут.') WHERE id = 'bcbaede0-1b13-4f10-af2e-89c520ee8eac';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Поздравляем, малышу уже целых 2 недели! В этот период врачи обычно назначают малышам капли витамина D: грудное молоко прекрасно, но витамина D в нём обычно недостаточно, а солнечного света не всегда хватает. Не забывайте давать витамин в назначенной врачом дозе — для правильного развития костей и профилактики рахита. Кроме того, сейчас хорошее время для первого визита к врачу; можно запланировать встречу с педиатром, чтобы проверить прибавку в весе и задать вопросы о развитии малыша. Вы отлично справляетесь — самый трудный первый этап уже позади!') WHERE id = '6f0bc18f-ecc7-4ad9-915b-db7cdf9694f7';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Сегодня снова немного внимания вашему телу: послеродовые выделения (лохии) должны постепенно светлеть, становясь желтоватыми или белыми. Если кровотечение вдруг усилилось или появился неприятный запах, это может быть сигнал тела: «вы слишком устаёте» или «есть инфекция»; поэтому категорически избегайте подъёма тяжестей. Уделяйте особое внимание гигиене: частый душ важен и для физической чистоты, и для хорошего настроения. Помните, что полное восстановление займёт ещё несколько недель, поэтому, даже если вы пока не чувствуете себя бодрой, отнеситесь к своему телу с терпением и заботой.') WHERE id = '924b5e58-de0f-4e99-ae9e-3a1b97775596';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Правила безопасного сна жизненно важны для малыша: всегда укладывайте его на спинку, на жёсткий матрас. Мягкие подушки, толстые одеяла или игрушки в кроватке, которые советуют бабушки, могут создать риск удушья, поэтому держите кроватку максимально простой и пустой. Специальные ортопедические подушки «для ровной головки» чаще всего не нужны: малыш должен свободно двигать головой. Следите за температурой в комнате (идеально 20–22 градуса) и не одевайте малыша слишком тепло: перегрев тоже опасен во время сна.') WHERE id = '00815f0c-e81b-4156-a3e1-eda10e9b02f3';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Вы наверняка слышали, как важно выкладывать малыша на животик (tummy time), когда он бодрствует, но ему это может совсем не нравиться — вплоть до плача. Это нормально, только не сдавайтесь: несколько подходов в день всего по 1–2 минуты незаменимы для укрепления мышц шеи, плеч и рук. Это также самый естественный способ предотвратить уплощение затылка (плагиоцефалию). Чтобы было веселее, положите перед малышом зеркальце или чёрно-белые карточки, а можете и сами лечь рядом и наладить зрительный контакт.') WHERE id = '442f3095-2fe9-4071-b81b-22bb923583fd';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Поговорка «пока не прошло сорока дней, ребёнка на улицу не выносят» — просто устаревший миф; если позволяет погода и малыш здоров, свежий воздух будет как лекарство для вас обоих. Спёртый воздух, пыль и бактерии дома могут быть вреднее, чем чистый воздух на улице; просто держитесь подальше от людных торговых центров и закрытых помещений. Одевая малыша, достаточно надеть на него всего на один слой больше, чем на себя: укутывание «как капусту» приведёт к потливости и болезням. Короткая прогулка поднимет вам настроение, а малышу поможет спать крепче.') WHERE id = '0f0e26dc-de3c-4b42-ba38-4351bd00e821';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Ногти малыша тонкие, как бумага, но острые, как бритва, и непроизвольными движениями он может поцарапать себе лицо. Стрижка ногтей может казаться очень волнительным делом; проще всего аккуратно подстригать их специальными детскими ножницами, когда малыш крепко спит. Некоторые мамы предпочитают царапки (варежки), но малыш познаёт мир руками, и постоянно закрытые ручки могут замедлить его развитие и нарушить механизм самоуспокоения. Не бойтесь: даже если случайно появится маленькая царапинка, достаточно прижать чистым ватным тампоном — быстро заживёт. Смелее!') WHERE id = '3eb8e784-2dc2-4db5-bcf8-7391a821ce01';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В этот послеродовой период вы порой можете чувствовать себя отрезанной от мира — как «робот», который только кормит и меняет подгузники. Но помните: вы не только мама — вы ещё и подруга, жена и личность со своими интересами. Сегодня, когда малыш уснёт, позвоните подруге, почитайте что-нибудь интересное в соцсетях или просто посмотрите в окно и скажите: «я здесь, и всё в порядке». Душевное здоровье не менее важно, чем физическое; если чувствуете себя как в четырёх стенах, поделитесь этими чувствами с близкими — разговор облегчит ношу.') WHERE id = 'e0cd0853-270f-4ca4-a662-76294120406b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Пусть вас не пугает, что в эти дни малыш будто не наедается молоком, постоянно просит грудь и хуже спит; скорее всего, это «скачок роста третьей недели» (growth spurt). В этот период организм малыша быстро растёт и нуждается в большем количестве энергии, а ваше тело старается подстроиться под этот запрос и вырабатывать больше молока. Самая большая ошибка мам на этом этапе — решить «молоко пропало» и перейти на смесь; на самом деле это временный кризис, и единственное решение — кормить малыша столько, сколько он хочет, не глядя на часы. Наберитесь терпения: это напряжение обычно проходит за 24–48 часов, и количество молока снова выравнивается.') WHERE id = '2fdd98da-1e6c-412b-96b1-b850d42327b4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'На гладком, шелковистом личике малыша вы можете вдруг заметить мелкие красные высыпания или прыщики; не спешите винить себя мыслями «что же я такого съела?». Это называется «акне новорождённых» — так организм малыша очищается от гормонов, которые вы передали ему во время беременности. Эти высыпания — не аллергия, поэтому выдавливать их, протирать спиртом или мазать разными кремами категорически нельзя: так можно только повредить кожу. Достаточно каждый день протирать личико тёплой кипячёной водой — высыпания сами исчезнут за несколько недель.') WHERE id = 'c3f99f3b-1467-413f-94c0-72c3e11f5099';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Те самые знаменитые вечерние приступы плача, длящиеся часами (колики), в этот период могут достигать пика; попробуйте успокаивать малыша «белым шумом» (white noise). В утробе малыш постоянно слышал звуки кровотока и работы органов, поэтому звук фена, пылесоса или приложения с «белым шумом» на телефоне кажется ему знакомым и дарит чувство безопасности. Крепко обнимите малыша, ритмично покачивайте его и включите эти звуки — это может успокоить его нервную систему. Помните: этот плач — не ваша вина, а просто реакция ещё не созревшей пищеварительной системы малыша.') WHERE id = '401736ab-8891-41f0-a7a6-17ce6782e7e4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Зрение малыша начинает развиваться, но он пока не различает цвета полностью и видит мир скорее как размытые тени. Чтобы привлечь его внимание и поддержать развитие мозга, используйте чёрно-белые карточки или контрастные игрушки; держать их нужно на расстоянии примерно 20–30 см от его лица. Вы увидите, как малыш вглядывается в эти карточки и внимательно их изучает. Эта простая игра и тренирует глазные мышцы, и способствует образованию новых связей между клетками мозга (нейронами).') WHERE id = '6acb903b-f503-4e0a-bf5a-5cedae1d83e4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Если вас утомили распространённые запреты вроде «не ешь помидоры — ребёнка обсыпет», «не ешь чечевицу — ребёнка будет пучить», знайте: современная медицина эти идеи не подтверждает. Газы из съеденной вами пищи не переходят напрямую в молоко; молоко образуется из крови, а не из содержимого желудка. Если после конкретного продукта вы не замечаете у малыша реального беспокойства (такое бывает очень редко, при аллергии на белок коровьего молока), не сажайте себя на ненужную диету. Ваше витаминное, белковое и разнообразное питание намного полезнее и для качества молока, и для вашего душевного здоровья, чем голодание.') WHERE id = '0f643a6c-2b94-498e-845b-b4547838a7e6';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Постоянное ношение малыша на руках может вызывать боли в спине, поэтому правильно подобранный слинг или эрго-рюкзак (не «кенгуру»!) станет вашим лучшим помощником. Не слушайте слова вроде «привыкнет к рукам», «испортится позвоночник»; напротив, эргономичные переноски, в которых ножки малыша принимают форму буквы «М» (как у лягушки), очень полезны для развития тазобедренных суставов. Такой способ напоминает малышу тесноту маминого живота и успокаивает его, а у вас освобождаются обе руки — можно заняться делами или просто спокойно выпить чаю. Чувство близости подарит вам обоим серотонин (гормон счастья).') WHERE id = 'a2fbf383-d8f0-4347-a3ef-d35f626ab799';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Если вас беспокоит, что пришедшие гости хотят целовать малыша и передавать его из рук в руки, не стесняйтесь говорить «нет» и выставлять границы. Иммунитет малыша ещё очень слаб, и обычный для взрослых вирус герпеса («простуда» на губах) может быть опасен для его жизни. Вежливо попросить гостей вымыть руки, не приходить больными и не целовать малыша в лицо и ручки — ваше самое естественное право. Если кто-то обижается — это его трудности; ваша главная задача — защищать малыша, а не угождать окружающим.') WHERE id = '7b5d5e0e-5e56-4eb3-b899-1d95dce7cd83';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Поздравляем, великолепная мама! Сегодня малышу исполнился ровно 1 месяц! Вспомните, сколько трудностей и бессонных ночей было за этот месяц и как стойко вы держались, — и гордитесь собой. Это также время ежемесячного осмотра у врача (измерение веса и роста); каждый набранный им грамм — плод вашего труда. Сделайте сегодня памятное фото малыша в один месяц, запишите даты и обязательно отметьте этот маленький юбилей — пусть даже просто кусочком торта. Время летит очень быстро, и запечатлённые моменты станут в будущем самым дорогим воспоминанием.') WHERE id = '520fba19-0b3a-4361-9ce1-dac3a718ebb0';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Если вы боитесь, что при купании малышу в ушко попадёт вода, — не волнуйтесь; барабанная перепонка защищает внутреннее ухо, и попавшая вода обычно не создаёт серьёзных проблем (если перепонка не повреждена). Купание для малыша — не только гигиена, но и развлечение, и способ расслабиться; если он любит воду, купание каждый вечер в одно и то же время перед сном может стать отличным ритуалом засыпания. Тёплая вода расслабляет мышцы, действует успокаивающе и подаёт малышу сигнал: «уже ночь, пора спать». После купания заверните его в тёплое полотенце и сделайте лёгкий массаж — это облегчит переход ко сну.') WHERE id = 'd1cd229a-65ce-4753-a5dc-ce53e13d2100';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'После первого месяца после родов тот грустный, чувствительный период под названием «Baby blues» обычно должен закончиться; если вы всё ещё постоянно чувствуете печаль, безнадёжность, усталость или безразличие к малышу — будьте внимательны. Это может быть послеродовая депрессия, и это ни в коем случае не ваша вина, не каприз и не слабость, а гормональный и химический дисбаланс. Не корите себя словами «я мама, я должна терпеть»; если чувство пустоты внутри не проходит, обязательно поговорите с врачом или психологом. Ваше душевное здоровье так же важно, как физическое здоровье малыша, а может быть, и важнее.') WHERE id = '792d4a29-1f99-4846-89d2-54738a980f78';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Добро пожаловать во второй месяц! Вы с малышом уже лучше узнаёте друг друга, и в вашей жизни начинает появляться определённый «ритм». Обратите внимание: мы говорим не «режим», а «ритм», потому что малыш ещё не готов жить по часам, но последовательность «сон — кормление — бодрствование» уже складывается. Не пытайтесь сейчас выстраивать жёсткое расписание — просто следите за сигналами сонливости малыша (зевота, потирание глазок) и старайтесь укладывать его, пока он не переутомился. Если всё по-прежнему кажется хаосом, не переживайте: даже в этом хаосе есть большой порядок, и вы отлично справляетесь.') WHERE id = '014f9c15-8f59-4b13-b689-2c5db7a165c4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Выкладывая малыша на животик (tummy time), вы можете заметить, что он уже пытается приподнимать голову хотя бы на несколько секунд; это первый признак того, что мышцы шеи крепнут. Чтобы сделать эти упражнения интереснее, положите перед ним яркую игрушку или просто лягте напротив и поговорите с ним. Если он пока не может поднять голову, не тревожьтесь: каждый ребёнок развивается в своём темпе. Просто терпеливо продолжайте — эти маленькие попытки станут фундаментом для будущего ползания и ходьбы.') WHERE id = 'edef290e-ee82-45c6-adef-de36a35e9688';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'До сих пор вы видели, как малыш улыбается во сне, — в народе говорят «играет с ангелами» (на самом деле это рефлекс), но уже приближается время «социальной улыбки». Малыш может осознанно улыбнуться, глядя на вас, в ответ на ваш голос или выражение лица; это не просто мимика, а его первый способ сказать вам: «я тебя узнаю и люблю». Разговаривая с ним, смотрите ему в глаза и улыбайтесь — он будет стараться ответить вам тем же. Это взаимодействие — сильнейший стимул для развития его эмоционального интеллекта.') WHERE id = '33d46eab-d81b-465a-acf9-3431f678ba0a';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Бывает, вы заходите в комнату и думаете: «зачем я сюда шла?» — или не можете вспомнить самые простые слова? Это в шутку называют «мамин мозг» (Mom brain), и это совершенно реальное физиологическое состояние. Недосып и гормональные изменения смещают фокус внимания мозга: он словно направляет все ресурсы на малыша и стирает остальное, «неважное». Не чувствуйте себя «поглупевшей» — это временный туман. Записывайте важные дела в блокнот или телефон, так этот период пройдёт легче; ясность ума скоро вернётся.') WHERE id = 'd8c08c2a-72db-44c1-9834-75d63110369c';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Зрение малыша развивается, и он уже может начинать следить глазами за движущимися предметами (трекинг). Держите палец или яркую игрушку на расстоянии 20–30 см от его лица и медленно двигайте вправо-влево; он будет стараться следить за вами взглядом. Эта простая игра развивает глазные мышцы и координацию «глаза — мозг». Если он не реагирует сразу, возможно, он устал; не заставляйте его и попробуйте в другой раз.') WHERE id = '8bc192a0-eebe-4dd4-8ce3-ca56d11958b8';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Хотя малыш ещё не умеет говорить, он отличный слушатель; рассказывать ему обо всём, что вы делаете в течение дня («сейчас поменяем подгузник», «смотри, это окно»), — решающий вклад в его будущее речевое развитие. Исследования показывают: у детей, с которыми родители много разговаривают, словарный запас в будущем богаче. Задавайте ему вопросы и делайте паузу, будто он отвечает (например: «Попил молочко? Молодец!»). Такой «диалог» учит его правилам общения и укрепляет вашу связь.') WHERE id = '99451123-a037-4f29-a96e-5e981ce03fe5';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Массаж для малыша — чудесное средство и от колик, и для успокоения. Нанесите на руки немного натурального детского масла, убедитесь, что в комнате тепло, и нежными движениями массируйте малыша, начиная со стоп и продвигаясь вверх. Окситоцин, выделяющийся при прикосновениях, успокоит и вас, и малыша. Повторяя этот ритуал каждый вечер после купания, вы поможете ему легче засыпать на ночь.') WHERE id = '030269db-0cd6-4191-b990-5149723f7ac1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Пока всё внимание приковано к малышу, может казаться, что отношения с мужем отошли на второй план, и это совершенно нормально. Но, становясь «родителями», старайтесь не забывать, что вы — «пара»; когда малыш спит, выпейте вместе чаю, обнимитесь или просто 10 минут поговорите о том, как прошёл день, — это растопит холодок между вами. Создайте папе условия для собственной связи с малышом (например, пусть за ним будет закреплено «выпустить воздух после кормления» или купание). Ощущение, что вы команда, придаст вам обоим сил в эти непростые дни.') WHERE id = '7b078d0d-8755-48b3-a240-4b2c014cdd7f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Хотя малыш ещё не ползает, он может непроизвольно пытаться перевернуться, а это поднимает вопрос безопасности. Золотое правило: никогда, даже на секунду, не оставляйте малыша одного на высоте (диван, кровать, пеленальный столик). Не успокаивайте себя мыслью «он ещё не двигается» — первый переворот обычно случается в самый неожиданный момент. Одного его можно оставлять только на расстеленном на полу ковре или специальном игровом коврике (разумеется, под присмотром). Привычки безопасности, выработанные уже сейчас, предотвратят будущие происшествия.') WHERE id = '0720bc24-8ac8-43a4-b347-e7e20231713d';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'И вот наступил тот день, которому в народе придают особое значение, — «малышу исполнилось сорок дней»! Поздравляем! По старинным обычаям в этот день проводят особый ритуал купания («чилля суйу» — вода сорокового дня), и мама с малышом уже могут свободно выходить в люди. С медицинской точки зрения это означает завершение шестинедельного восстановительного периода (окончание лохий, сокращение матки). Отметьте этот день как праздник: нарядитесь, устройте себе красоту и, может быть, выйдите с малышом на первую долгую «официальную» прогулку. «Сорок» — не просто число: это символ вашего перехода из статуса «новоиспечённой мамы» в статус «опытной мамы». Вы справились!') WHERE id = '1ce90c4b-f9a4-402a-a99b-4457322248d1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, '«Сорок дней» в нашем обществе воспринимаются словно финишная черта, но на самом деле это лишь начало марафона. Не поддавайтесь давлению вроде «я уже должна всё успевать», «дом должен блестеть». Восстановление ещё продолжается; особенно если вы кормите грудью, под влиянием гормонов (пролактина) вы можете чувствовать размягчение суставов или боли в пояснице. В этот период «новой свободы» не нагружайте себя резко — возвращайтесь к прежнему темпу постепенно, шаг за шагом.') WHERE id = '0928cbd6-fa37-455a-a682-9515f253a752';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Малыш уже начинает лучше различать цвета; красный и оранжевый могут стать первыми яркими цветами, привлекающими его внимание. В подвесных вращающихся игрушках над кроваткой (мобиле) его теперь интересует не только музыка, но и движение. Если вы ещё не купили мобиль, выберите простой, из геометрических фигур и с медленным движением — он будет развивать способность малыша концентрировать внимание. Но учтите: укладывая его спать, убирайте эти игрушки, чтобы они не отвлекали от сна.') WHERE id = 'c21766cd-a78b-4676-9247-d0b2e0b3de2f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Недели 6–8 (то есть нынешний период) могут быть временем, когда плач малыша достигает пика. Иногда он может плакать без всякой причины — даже сытый и с чистым подгузником. Это перегрузка его нервной системы окружающими звуками, светом и стимулами. Не вините себя: это не про то, что вы «плохая мама», это естественная часть развития. Просто будьте рядом, обнимайте и говорите себе: «и это пройдёт». И действительно — через несколько недель этот плач резко пойдёт на убыль.') WHERE id = 'c94543e8-f599-4ccd-918b-88ff573157bb';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Малыш уже начал «агукать» или издавать гортанные звуки? Это первый этап развития речи! Когда он издаёт звук, отвечайте ему тем же звуком — словно вы «беседуете». Исследования показывают: когда родитель повторяет звуки малыша, он передаёт ему послание «я тебя слышу и понимаю». Эта простая игра укрепляет его уверенность в себе и закладывает основу для более раннего развития речи.') WHERE id = '045f5830-2fde-4a82-b369-03b2e1dcea23';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Глядя в зеркало, вы можете расстраиваться из-за оставшихся после беременности килограммов или обвисшего живота. Помните: этот живот растягивался 9 месяцев, и для полного восстановления нужно как минимум столько же времени. Жёсткие диеты (особенно для кормящих мам) могут привести к уменьшению молока и выпадению волос. Думайте сейчас не о похудении, а о здоровом питании. Много воды, овощи и белок — ваши лучшие друзья. Не испытывайте неприязни к своему телу — оно подарило вам самый прекрасный подарок на свете.') WHERE id = '772a8327-4bbe-46b7-9c90-09e5deaa584b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Чтобы сделать «время на животике» (tummy time) веселее, попробуйте игру «самолётик». Лягте на спину, согните колени и положите малыша животиком на свои голени, слегка покачивая (разумеется, придерживая руками). Это даёт ему новый ракурс обзора, налаживает зрительный контакт с вами и развивает вестибулярный аппарат (чувство равновесия). Малыши гораздо больше любят упражняться на маминых ногах, чем лежать на полу в одиночестве.') WHERE id = 'f63c5890-33d1-4cec-a07d-853961a0ca97';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Хотя ночной сон ещё не наладился полностью, дневные сны (nap) могут начать укорачиваться. Если малыш днём спит всего 20–30 минут и просыпается, не воспринимайте это как «поспал — и хватит». Иногда малыши просыпаются между циклами сна (каждые 40–45 минут), хотя на самом деле ещё не выспались. Не включайте сразу свет и не начинайте играть; прилягте рядом, пошепчите «ш-ш-ш» или продлите сон кормлением.') WHERE id = '2c5835b8-b6ba-41d1-b215-505864265cfb';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Пора поговорить с врачом о приближающихся прививках в 2 месяца. Согласно Национальному календарю прививок Азербайджана, в этот период предусмотрены вакцины против коклюша, дифтерии, столбняка, гепатита B и др. (Гексаксим или аналог), а также прививки от ротавируса и пневмококка. Не верьте лишённым научной основы пугалкам вроде «прививки вредны», «ребёнок не заговорит». Прививка — самый мощный щит, защищающий малыша от смертельно опасных болезней в будущем. Задавайте вопросы не «соседке», а своему педиатру.') WHERE id = '28360eb0-4c71-4798-a428-29239685c45f';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Тема интимной жизни после родов часто считается табу, но вы должны быть информированы. После разрешения врача (обычно через 6 недель) близость возможна, однако совершенно нормально чувствовать нежелание (снижение либидо) или сухость. Это влияние гормонов лактации и усталости. Откровенно поговорите об этом с мужем, дайте друг другу время и не торопитесь. Близость — это не только интимный акт: просто обниматься и прикасаться друг к другу в этот период тоже очень важно.') WHERE id = 'a59bf56c-999f-4547-b139-eaa70223118e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Наступил период, когда малыш открывает для себя свои ручки; он может тянуть их в рот и сосать пальчики. Это не значит «он голоден» (хотя может быть и признаком голода) — это его механизм самоуспокоения и способ познания мира. Не пытайтесь убирать его руки ото рта или надевать варежки. Пусть изучает своё тело. Просто следите, чтобы ручки были чистыми, а ноготки — подстриженными.') WHERE id = '15366f98-572a-4b0c-8fda-af7cf85e56b4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Пришло время прививок в 2 месяца (если вы их ещё не сделали). Согласно календарю прививок, применяемому в Азербайджане, в этот период малышу обычно вводят комбинированную 5- или 6-валентную вакцину (коклюш, дифтерия, столбняк и др.) и прививку от пневмококка. После прививки у малыша может немного подняться температура или он может стать беспокойным; это не страшно — наоборот, это показывает, что иммунитет «включился» и организм вырабатывает защиту. По совету врача обязательно держите дома детские свечи или сироп с парацетамолом, но не спешите давать лекарство, пока температура не превысила 38 градусов.') WHERE id = '947283f7-9c09-4c76-a0bb-7ff92f24aad4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'У малыша потекли слюнки, и он грызёт кулачки? Бабушки сразу скажут «зубки режутся», но 2 месяца для зубов обычно рано (хотя бывают исключения). В этот период слюнные железы начинают активно работать, а малыш ещё не научился полностью сглатывать слюну, поэтому она вытекает наружу. К тому же эти ферменты готовят его пищеварительную систему к твёрдой пище (в будущем). Просто почаще меняйте слюнявчик, чтобы шейка не оставалась влажной и не появились опрелости.') WHERE id = '99be53c6-0b63-4846-ac0b-fd476ca9e54e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Если во время душа у вас в руках остаются целые пряди волос — не пугайтесь, лысой вы не останетесь! Это называется «послеродовое выпадение волос», и это полностью гормональный процесс. Во время беременности повышенный эстроген удерживал волосы от выпадения, а теперь эти гормоны снижаются — и все «просроченные» волосы выпадают разом. Это временно и восстановится примерно к 6–12 месяцам. Вместо того чтобы тратить деньги на дорогие шампуни, следите за питанием и уровнем железа — со временем всё наладится.') WHERE id = 'f657e712-ddb7-463c-a1f6-51d68e963ec9';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Малыш уже начинает немного различать день и ночь, поэтому сейчас идеальное время создать «ритуал сна». Это не жёсткий режим, а просто последовательность: тёплая ванна → надевание пижамы → приглушённый свет → колыбельная или белый шум → сон. Повторение одной и той же последовательности каждый день посылает мозгу малыша сигнал: «пора спать». Даже если сегодня эта привычка не даст результата, через несколько недель она станет вашим спасением.') WHERE id = '2614d60b-6450-43ee-a569-f20e3ea56045';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Зрительный мир малыша становится всё более красочным; он начинает различать уже не только красный и оранжевый, но и зелёный с жёлтым. Чтобы поддержать его развитие, носите его по разным комнатам, показывайте его отражение в зеркале (малыши очень любят своё отражение, хотя ещё не понимают, что это они). Разговаривайте с ним: «Ну-ка посмотрим, кто это тут?». Такие социальные игры стремительно развивают нейроны его мозга.') WHERE id = '34645ca6-b752-434e-a340-59af7488ff61';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Иногда мамы кормят грудью, а вес не снижается, наоборот, растёт. Это может быть связано с гормоном кортизолом, повышающимся из-за недосыпа и стресса: организм чувствует себя «в опасности» и запасает жир. Есть сладкий чай, халву и мучное, «чтобы было молоко», — миф; молоко увеличивают только обильное питьё и частые прикладывания малыша. Сократив сахар и перейдя на овощи, вы и энергии прибавите, и поможете весу постепенно прийти в норму.') WHERE id = '70fa5f2d-ef18-4d50-b156-41acde57d635';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Лёжа на животике (tummy time), малыш уже пытается поднимать не только голову, но и грудь? Это движение — «мини-спортзал»! Его руки и мышцы спины крепнут. Если пока не получается, помогите ему: сверните маленькое полотенце валиком и подложите под подмышки — это станет опорой. Положите перед ним любимую игрушку, чтобы он тянулся к ней. Эти движения важны для будущего ползания и сидения.') WHERE id = '8cfe7b98-ab62-49f4-b9ea-ef363b224769';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'В этот период у малышей силён рефлекс «непитательного сосания»: он не голоден, а просто хочет что-то пососать, чтобы успокоиться. Если он сосёт пальчики и вы думаете о пустышке (соске), старайтесь выбирать «ортодонтическую» форму. Пустышка — не вредная привычка: она считается вспомогательным средством профилактики синдрома внезапной детской смерти (СВДС). Но не используйте её как «глушилку» при каждом плаче — сначала постарайтесь понять, в чём проблема.') WHERE id = '4ec5ed37-79da-4c46-9571-b8e74147be8d';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Замечаете, что одна сторона головы малыша стала более плоской? Это называется «позиционная плагиоцефалия» и возникает от постоянного лежания на одной стороне. Кости черепа ещё мягкие, и это легко исправляется. Простое решение: укладывая малыша в кроватку, каждую ночь меняйте направление его головы (день — направо, день — налево). А во время бодрствования держите его на животике как можно дольше, чтобы на затылок не было давления.') WHERE id = '248e6415-444f-4d09-8609-b540277d00d1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Поздравляем! Сегодня малышу исполнилось 2 месяца! Вы официально оставили позади период «новорождённости» — теперь он считается «младенцем» (infant). Сравните то маленькое беспомощное существо первых дней с нынешним ребёнком, который улыбается вам и издаёт звуки. Трудные дни ещё будут — прорезывание зубов, регресс сна и прочее, — но вы уже опытная мама и справитесь с любыми трудностями. Обнимите себя — вы делаете великолепную работу!') WHERE id = 'd3b345c6-e91a-402d-9918-ceed5b8d37b4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Добро пожаловать, третий месяц! Вы приближаетесь к концу первых трёх месяцев адаптации, которые называют «четвёртым триместром». Малыш уже не просто существо, которое ест и спит, — он превращается в социальную личность, которая воспринимает окружающее и реагирует на звуки. С этого месяца время его бодрствования будет увеличиваться, а сон (будем надеяться!) станет чуть более упорядоченным. На этом новом этапе он будет хотеть больше «беседовать» с вами, так что готовьтесь много разговаривать и петь песни.') WHERE id = '8828f855-f7c6-48a8-aae1-636ec24ccff1';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Малыш держит ручки перед лицом и изумлённо их разглядывает? Это он открывает свою первую «игрушку»! Это называется «зрительно-моторная координация». Он понимает, что руки принадлежат ему и что он может ими управлять. Не мешайте этому процессу и не прячьте его ручки. Наоборот, наденьте ему на запястья цветные или звенящие (с бубенчиками) браслетики — так открытие станет ещё интереснее. Это великолепная тренировка для развития его мозга.') WHERE id = 'c44f54e6-bd35-4121-9f0f-f6748ef02647';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Хотя тема сна всё ещё болезненна, есть хорошая новость: мозг малыша уже начинает вырабатывать мелатонин (гормон сна), и формируется циркадный ритм (биологические часы). Вероятность перепутать день с ночью снижается. Чтобы помочь ему, по утрам наполняйте комнату солнечным светом, а вечером пораньше выключайте свет и создавайте тишину. Такой естественный световой режим будет передавать его мозгу сигналы «сейчас время бодрствовать» и «сейчас время спать».') WHERE id = 'f3bdc990-29cc-452b-b018-a1508cec7d80';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Мышцы шеи уже заметно окрепли: лёжа на животике, малыш может поднимать голову на 45–90 градусов и осматриваться. Иногда он даже раскачивается, подняв руки и ноги в воздух, как «самолётик». Это готовит мышцы его спины к будущим этапам ползания и сидения. Если он пока не держит голову уверенно, не волнуйтесь — у каждого ребёнка свой темп; просто не исключайте время на животике (tummy time) из ежедневного распорядка.') WHERE id = '72ecbac3-10ef-45d2-898d-f50326e4aca5';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Заметили на головке малыша, особенно в области родничка, желтоватые жирные корочки? В народе их называют «молочными корочками», а в медицине — себорейным дерматитом. Не пугайтесь: это не признак плохой гигиены и не заразно. Корочки возникают из-за активной работы сальных желёз под влиянием маминых гормонов. Не пытайтесь их отдирать: перед купанием смягчите оливковым или миндальным маслом, а затем вычешите мягкой щёточкой и вымойте головку. Со временем это пройдёт само собой.') WHERE id = 'ebf4f9a7-c423-4f9b-a35f-e6aea203cbf5';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Улыбки малыша уже не рефлекс — они совершенно осознанные! Когда вы улыбаетесь ему, щекочете его или играете в «ку-ку» (прятки), он может начать смеяться в голос. Этот звук — самая прекрасная музыка на свете, не правда ли? У него формируется чувство юмора. Ему очень понравятся смешные звуки и забавные гримасы. Смех к тому же развивает его лёгкие и снижает уровень гормонов стресса.') WHERE id = '1fddfb5f-0320-4827-b223-17100c2c0495';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Подушка или одежда часто становятся мокрыми? На третьем месяце усиленное слюнотечение — это совершенно нормально. Оно вовсе не обязательно означает скорые зубки (хотя дёсны могут чесаться). Это показывает, что пищеварительная система развивается и формируется естественная защита от бактерий в полости рта. Просто используйте слюнявчик и держите область вокруг рта сухой, чтобы не появились высыпания.') WHERE id = '65b4b1d4-9f03-4890-8a26-60e163757dc4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Вопрос «нужно ли давать воду?» в эти месяцы очень волнует мам. Особенно бабушки могут говорить: «бедняжка, пить хочет». Однако Всемирная организация здравоохранения (ВОЗ) рекомендует в первые 6 месяцев не давать малышу НИЧЕГО, кроме грудного молока или смеси (даже воду). Грудное молоко на 88% состоит из воды и полностью покрывает потребность малыша в жидкости. Его желудок ещё очень мал: наполнив его водой, можно сократить потребление молока и затормозить развитие.') WHERE id = 'daa57941-307c-46d4-ad44-8c2b7828cf2e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Добавьте в свою повседневную жизнь кнопку «пауза». Когда малыш уснёт, не бросайтесь сразу убирать дом. Вашей «батарейке» тоже нужна подзарядка. 20-минутный сон, книга или просто разглядывание потолка — это ваше право. Вы не обязаны быть «идеальной хозяйкой», но обязаны быть «здоровой мамой». Пыль может подождать, а ваше душевное здоровье — нет.') WHERE id = '8ae3c3ee-3ed1-4cce-8f50-41530ca784cb';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'С этого месяца можно начинать выстраивать цикл «кормление — активность — сон». То есть: малыш просыпается → ест → играет → спит. Мамы часто укладывают малыша, кормя грудью (это не ошибка, но может закрепиться как привычка). Если применять последовательность «поел — поиграл — уснул», малыш будет меньше связывать еду со сном, и в будущем ему будет легче засыпать самостоятельно. Конечно, это не жёсткий закон, а просто метод, который стоит попробовать.') WHERE id = '2c9372ab-3791-4b09-9ac2-4545b2a50eba';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Руки малыша уже действуют не «сами по себе» — он осознанно тянется к предметам и пытается их схватить. Если раньше он рефлекторно сжимал ваш палец, вложенный в ладошку, то теперь, увидев игрушку, сам тянется к ней. Это прекрасный прогресс, но будьте осторожны: сидя у вас на руках, он захочет дёргать вас за волосы, ожерелье или очки. Также держите подальше от него горячие чашки с чаем — одним внезапным движением он может опрокинуть их на себя. Соблюдать безопасную дистанцию теперь действительно важно.') WHERE id = '851b7601-c8f0-43b8-a2e5-3708104c42ba';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Если ночной недосып всё ещё продолжается, попробуйте метод «сонного кормления» (Dream Feed). Это значит покормить малыша, не разбудив его полностью, в полусонном состоянии (например, в 23:00, перед тем как сами ляжете спать), и снова уложить. Иногда этот приём предотвращает пробуждение малыша посреди ночи и дарит вам чуть более долгий непрерывный сон. Если метод не работает и малыш просыпается с плачем, не настаивайте: у каждого ребёнка свой биоритм.') WHERE id = '1a681284-0141-4b15-bc3b-3b5a269a1b94';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Выкладывая малыша на животик (tummy time), вы можете заметить, что он пытается перекатиться набок. Некоторые шустрые малыши в этот период уже умеют переворачиваться с живота на спину (случайно, под тяжестью головы). Это большая радость, но и предупреждающий сигнал: теперь его нельзя ни на секунду оставлять без присмотра на пеленальном столике, диване или любой возвышенности. Риск падения с этого месяца резко возрастает; самое безопасное место — пол (ковёр или игровой коврик).') WHERE id = '51999bec-e90a-4151-af89-e280275c886e';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Звуки малыша уже не сводятся к плачу: он умеет тянуть гласные («а», «о», «у») и «воркует». Это тренировка его голосовых связок. Если вы работаете на кухне, а он подаёт голос из комнаты, обязательно ответьте ему голосом («Да, я слышу тебя, уже иду»). Такое «общение на расстоянии» дарит ему чувство безопасности: «Хоть я и не вижу маму, слышу её голос — значит, я не один». Это помогает уменьшить тревогу разлуки (separation anxiety).') WHERE id = '4b396ede-815b-4edd-bee5-1ab95bd630c3';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'По мере того как малыш набирает вес, у вас могут появиться боли в спине и руках (особенно синдром «маминого запястья»). Следите за осанкой, когда берёте его на руки или кормите: не поднимайте плечи к ушам, сидите прямо и обязательно используйте подушки для поддержки поясницы. Поднимая малыша с пола, сгибайте колени, а не спину. Ваш позвоночник будет нужен вам ещё долгие годы — берегите его уже сейчас.') WHERE id = 'dc8afbc6-14c7-4301-94dd-c5e5a4b2292b';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'От окружающих вы можете слышать давление вроде «ребёнку уже 3 месяца, дай попробовать бульона», «дай кусочек хлебного мякиша, пусть привыкает». Будьте твёрды и говорите «НЕТ». Всемирная организация здравоохранения (ВОЗ) однозначно заявляет: первые 6 месяцев — ТОЛЬКО грудное молоко (или смесь). Желудочно-кишечный тракт малыша ещё не готов переваривать крахмал и другую пищу; ранний прикорм может привести к аллергии, вздутию и в будущем к ожирению. Не торопитесь: на еду у него впереди целая жизнь.') WHERE id = '0739a3ba-203e-453e-b9ac-6bd4bfdbcdf4';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Самая интересная игрушка этого периода — зеркало! Поставьте перед малышом безопасное (небьющееся) зеркальце. Он будет улыбаться «другому малышу», пытаться дотронуться до него и удивляться. Пока он не понимает, что это он сам (это происходит примерно к 18 месяцам), но наблюдение за выражениями лица и движениями великолепно развивает его социальные навыки. К тому же эта игра — отличная хитрость, чтобы продлить время на животике.') WHERE id = 'd5f46289-84de-4aa8-8cc6-e208423016ca';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'По мере роста интереса малыша к окружающему миру кормление грудью может усложниться. Он хочет повернуть голову на каждый звук и каждое движение — и отпускает грудь. Это называют «синдромом любопытного малыша». Не раздражайтесь, просто выбирайте для кормления более тихую, тёмную и «скучную» комнату. Снимите яркое ожерелье и привлекающие внимание вещи. Вы заметите, что ночью и в сонном состоянии он сосёт лучше, — это нормально.') WHERE id = '9cc144a8-c429-4c7c-b711-108cf929ab92';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Открытие собственных ручек иногда заканчивается царапинами на лице от ноготков. Если вы боитесь стричь ногти, делайте это, когда малыш спит, или отложите на время после купания, чтобы ногти немного размягчились. Носить царапки уже не рекомендуется: малыш познаёт мир, трогая всё руками и поднося к рту. Маленькая царапинка быстро заживёт, а вот блокировать осязание его ручек — значит замедлять развитие.') WHERE id = '4516cd0b-d8f9-4d0b-92cb-3f43fabc6642';
UPDATE public.mommy_daily_messages SET message_ru = COALESCE(message_ru, 'Поздравляем: первые 3 месяца адаптации, которые называют «четвёртым триместром», почти позади! Малыш уже полностью освоился во «внешнем мире». В часы бодрствования не держите его только в кроватке: носите по дому, смотрите вместе в окно, бывайте в разных комнатах. Он уже наблюдатель. Чем больше визуального и звукового контакта вы установите с ним в этот период, тем крепче будут нейронные связи в его мозге. Вы — его первый и лучший учитель.') WHERE id = 'ef4c7b42-edd4-4ffb-87e6-5505b04254f6';

-- ── baby_daily_info → ru (1457 sətir) ──
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'После долгих месяцев беременности вы наконец встретились со своим малышом. Мы, семья Anacan, будем рядом с вами в каждом счастливом дне, который вы проведёте с малышом! 😊 Вы наверняка уже заметили, что с момента рождения малыш проводит во сне почти весь день. Иногда это может даже вызывать у вас беспокойство. Знайте: сон — незаменимая потребность новорождённого для здоровья, роста и развития. Кроме кормлений и смены подгузника, малыш посвящает сну почти всё своё время. Гормон мелатонин, выделяющийся в его организме во время сна, укрепляет иммунную систему и помогает гипофизу вырабатывать больше гормона роста. Но по мере взросления продолжительность сна будет сокращаться. Поэтому вам стоит провести эти дни, отдыхая как можно больше.') WHERE id = '31cd50a4-c6f5-4862-b0ff-2fa89b11b67b';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вы наверняка заметили на коже малыша при рождении кремовый, белый маслянистый слой. Этот слой называется верникс (первородная смазка) — защитное тонкое вещество, которое на 80% состоит из воды и содержит много липидов и белков. Распределение этого слоя по поверхности кожи может различаться в зависимости от недели беременности, на которой произошли роды, и способа родоразрешения. У малышей, рождённых позже срока, часть этого слоя обычно уже впиталась кожей. А у малышей, рождённых до 37-й недели, этот слой более плотный. В составе верникса есть защитные клетки, способные уничтожать микробы, и около 40 различных белков, поддерживающих естественный иммунитет малыша. Поэтому не следует купать малыша как минимум 24 часа после рождения — дайте коже хорошо впитать этот слой.') WHERE id = '01b8c794-e427-40d5-a912-edbb2df87798';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'С момента появления на свет малыш обладает сильными рефлексами. Самый важный из них — конечно, сосательный рефлекс, обеспечивающий его питание. При прикосновении к щёчкам и уголкам рта малыш сразу поворачивается в ту сторону и ищет источник пищи. Сосательный рефлекс — это механическое движение, с помощью которого малыш удовлетворяет потребности в питании и эмоциональной близости. Этот рефлекс начинает формироваться ещё в утробе, на 14-й неделе развития, и осуществляется благодаря мышцам щёк, создающим вакуум, которые формируются по мере развития полости рта и нёба. Возникая на очень ранних сроках беременности, этот рефлекс позволяет малышу тренироваться всё время, пока он находится у вас в животе. Благодаря этому малыш с первого мгновения после рождения обладает нужным опытом и навыком для кормления.') WHERE id = '4db7f0d9-f7be-435d-a305-5bea20ce135c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'После рождения малыш инстинктивно узнаёт вас среди множества людей. Считается, что этому инстинкту помогают ваш запах и голос. В эти первые дни встречи с малышом нужно много практиковаться в кормлении грудью, разговаривать с ним, глядя в глаза, и нежно прикасаться к нему. Каждый момент контакта с малышом стимулирует выработку в вашем организме гормона окситоцина. Окситоцин заставляет сокращаться мышечные клетки, продвигающие молоко к соску. Другой гормон, обеспечивающий кормление малыша, — пролактин, который вырабатывается гипофизом в вашем мозге. Эти два гормона работают вместе, слаженно: когда малыш сосёт, они обеспечивают выработку молока и его продвижение к соску.') WHERE id = 'a25dea37-57a2-46fc-889c-23e73ad36d76';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Сразу после рождения малыша врач проводит проверку его здоровья. В первые минуты после родов врач также делает малышу первую прививку — вакцину от гепатита B, в ножку. Если вы носитель гепатита B, вместе с вакциной малышу вводят и иммуноглобулин. Кроме прививки от гепатита B, в первый месяц других вакцин малышу не делают. Затем, ещё до выписки из роддома, малыша подробно осматривает педиатр. Медсестра, назначенная роддомом, также даёт инструктаж о том, как ухаживать за малышом в первые дни и на что обращать внимание. Вся эта информация даст вам очень важные подсказки по уходу за малышом.') WHERE id = '0d9fa9e8-940a-4ec4-b501-2f30433e0030';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Рост и вес малыша говорят нам о его общем здоровье. А измерение окружности головы очень важно для оценки работы мозга. При первых измерениях окружность головы малыша обычно составляет от 32 до 37 см. Эти цифры показывают, что мозг развивается здоровым образом. Рост окружности головы — показатель развития мозга, поэтому за ним нужно следить. Обязательно регулярно отслеживайте рост, вес и размеры головы малыша. Для этого найдите хорошего педиатра и составьте вместе с ним календарь наблюдений. Для контроля развития рекомендуется показать малыша врачу в среднем на 5-й, 14-й и 30-й дни после рождения.') WHERE id = '8c627179-a029-49ba-9226-4fa26ffce0a7';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Укладывая малыша, вы наверняка замечали, что он всё время остаётся в согнутом положении. Он провёл 9 месяцев в утробе в позе эмбриона, поэтому эта привычка сохранится ещё некоторое время. Примерно на втором месяце она начнёт ослабевать, а к третьему полностью пройдёт. После той безопасной и закрытой среды маминого живота внешний мир может казаться ему пугающим и хаотичным. Поэтому он хочет постоянно быть в контакте с вами. Дайте ему время — он привыкнет. Помните: ваши объятия, в которых он чувствует ваш запах, — самое надёжное место для него. Та крепкая связь между мамой и малышом рождается именно в первые дни. Когда он голоден или нуждается в чистом подгузнике, не заставляйте его ждать — сразу удовлетворяйте его потребности. На время забудьте о внешнем мире и занимайтесь только малышом.') WHERE id = '990edf71-6742-4577-9d2f-dadba792cf8a';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вот вы с малышом и оставили позади первую неделю. Как же быстро летит время, правда? 😊 Всю беременность кишечник малыша был стерильным, без каких-либо микроорганизмов. Если роды прошли путём кесарева сечения, бактерии, помогающие пищеварению, начинают заселять кишечную флору малыша именно с этого дня. При естественных родах этот процесс начался с четвёртого дня. Часть этих бактерий полезна, часть — вредна. Присутствие обоих видов создаёт в пищеварительной системе равновесие и не даёт друг другу чрезмерно размножаться. То есть эти организмы важны для баланса кишечной флоры малыша.') WHERE id = 'ea7ac5e6-2b68-47b7-9578-f87a52623334';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Не изводите себя мыслью «у меня мало молока», дорогая мама. При рождении объём желудка малыша — всего с вишенку. Поэтому не переживайте, что молока не хватает. В эти дни подросший после родов желудок уже размером с абрикос, то есть вмещает около 50 мл. Поэтому то молоко, которое кажется вам «маленьким», на самом деле полностью достаточно, чтобы он наелся. Пока желудок мал, малыш будет сосать понемногу, но часто. Если после кормления он срыгивает, обычно это происходит, когда он съел больше объёма желудка. Так что разговоры о том, что «молоко не подходит», как говорят в народе, — просто миф, не верьте этому.') WHERE id = 'f7f368ac-9bca-4520-b0e3-f83cfbd455a4';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Молоко, которое приходит сразу после родов, называется молозивом. Это густая, желтоватая, очень ценная пища с высоким содержанием белка, богатая антителами, защищающими малыша от инфекций. Примерно через 5–7 дней после родов его сменяет переходное молоко. В переходном молоке больше жира и лактозы, чем в молозиве, то есть оно калорийнее. Этот вид молока сохраняется примерно до 14-го дня. А через 2 недели после родов начинает приходить уже зрелое молоко. Оно очень богато и водой, и белком, и жирами.') WHERE id = '4794b2b1-e590-4e29-b9bf-54af8c8dcab5';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Уход за малышом, особенно если вы стали мамой впервые, поначалу может пугать. Если думаете, что не справитесь, — вы ошибаетесь. 😊 Пусть это и звучит как классика, но со временем вы будете ухаживать за малышом совершенно спокойно. Одна из таких процедур — уход за пуповинным остатком, который подсыхает и готовится отпасть. Пуповина всю беременность передавала малышу кислород и питательные вещества, необходимые для питания и развития. Пуповину длиной около 50 см после родов врач обрезает, оставляя около 2 см. Пуповинный остаток отпадает между 5-м и 15-м днём. Если не ухаживать за пупком до и после отпадения остатка, возрастает риск инфекции. Из-за этого риска нужно два-три раза в день протирать область пупка 70-процентным спиртовым раствором, рекомендованным врачом, и давать ей проветриваться.') WHERE id = '403ffca4-6096-4cf2-9210-17a6a3a59df5';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'То, что голова малыша непропорционально велика по сравнению с телом, совершенно нормально и не означает проблем со здоровьем. На голове также могут быть некоторые неровности и асимметрия. Причина в том, что кости черепа малыша ещё не затвердели, чтобы он мог пройти через родовые пути. Мягкие кости черепа состоят из богатой волокнами хрящевой ткани. К тому же эти открытые участки нужны малышу, чтобы мозг мог продолжать развиваться. В среднем к концу первого месяца голова малыша принимает свою округлую форму. Малыш рождается с шестью родничками; к концу второго месяца все они, кроме переднего верхнего, закрываются. Большой родничок, расположенный спереди сверху, начинает затвердевать на седьмом месяце и закрывается до двухлетнего возраста.') WHERE id = '878511ba-a575-4d79-8fa5-80ca329e838e';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Грудное молоко, вырабатываемое молочными железами, — самое ценное, что вы можете дать малышу. Молоко содержит два вида белка, жиры, углеводы, различные витамины и антитела, помогающие малышу бороться с вирусами и бактериями. Жиры в составе молока необходимы для развития мозга, как источник энергии и для усвоения жирорастворимых витаминов. Благодаря всем этим свойствам это лучшая пища, способная в одиночку обеспечить малыша всеми необходимыми питательными веществами первые 6 месяцев, без какой-либо другой еды. Смеси, называемые искусственным питанием, — единственная альтернатива для кормления малыша в случаях, когда вашего молока недостаточно. Эти смеси, основой большинства из которых является коровье молоко, производятся путём добавления одних веществ в натуральное молоко и удаления других. Но поскольку они содержат больше казеина, чем грудное молоко, малыш переваривает их медленнее.') WHERE id = 'a9c4f35f-77e6-4302-9bda-fc0e36e3f3da';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В первые дни вес малыша может снизиться примерно на 10% от веса при рождении. После этого снижения ожидается, что он вернётся к весу при рождении не позднее 10-го дня. Период новорождённости — время самого быстрого развития за всю жизнь малыша. В первые месяцы малыш может вырасти на 2–6 см и набрать от 700 до 1500 граммов. Помните, что эти значения могут различаться в зависимости от пола малыша, а у недоношенных детей какое-то время прогресс будет медленнее. Кроме того, мышцы, рефлексы и физические навыки малыша в первые месяцы развиваются очень быстро, параллельно росту тела. Поэтому в этот период нужно обеспечивать малышу правильные стимулы, поддерживающие развитие, и регулярно встречаться с врачом.') WHERE id = '379e34a9-be36-4930-a59c-af93a24eb449';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Подмывание и смена подгузника поначалу могут казаться новоиспечённой маме довольно пугающими. Перед сменой подгузника позаботьтесь, чтобы всё необходимое было под рукой, и начинайте с мытья рук. На этапе привыкания можно просить помощи у медсестёр, близких и родственников. В первые месяцы после рождения малышу будет нужна частая смена подгузников. И всё же, пока малыш спит и подгузник не слишком мокрый, будить его только ради смены подгузника не нужно. Поэтому, если во время ночных кормлений он не проявляет беспокойства, менять подгузник всю ночь не стоит. Потревожив спящего малыша, вы прервёте его сон, и ему может быть трудно уснуть снова.') WHERE id = 'd0704bed-eb75-4a28-b892-e481bca3aba6';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'После рождения малыша пуповинный остаток полностью высыхает и отпадает примерно за 10–14 дней. Но иногда этот срок может затянуться. Если пуповинный остаток всё ещё не отпал, обязательно обратитесь к ближайшему детскому врачу. Если остаток не отпал к 20-му дню, это может указывать на некоторые проблемы в иммунной системе малыша. При купании старайтесь не мочить область пупка, а если она намокла — обязательно просушите. Влажный пуповинный остаток и отпадает позже, и может стать причиной различных инфекций. Кроме того, чтобы остаток отпал быстро и без осложнений, не используйте никакие лекарства или лосьоны, если их не рекомендовал врач.') WHERE id = '46a30d17-6906-4dd1-9f3a-fa10b39a15db';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Частый контакт с малышом в течение дня и кормление грудью значительно облегчают его адаптацию к новому миру. Давно известно, что даже самый современный кувез не может дать малышу такую сильную заботу, как мамины объятия. При контакте такие ощущения, как прикосновение, тепло и запах, укрепляют эмоциональную связь между вами и малышом. Кроме того, этот контакт считается важным условием продолжения успешного грудного вскармливания. Прочная чувственная связь, которую малыш выстраивает на этом этапе, ускоряет его душевное и физическое развитие. А для обретения чувства доверия в последующие периоды детства она чрезвычайно важна. Так что отложите все дела и побольше контактируйте с малышом кожа к коже! 😊') WHERE id = 'd3f6fa0e-5b44-4a86-8dac-648c5ea0fb9f';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Послеродовой период охватывает примерно 6 недель после родов. Особенно в это время, когда вы привыкаете к малышу и новой жизни, вы можете переживать эмоциональные взлёты и падения. Этот период — процесс, когда изменения, произошедшие за беременность в обмене веществ и репродуктивной системе, поворачивают вспять. Уровень гормонов и размеры матки быстро возвращаются к добеременному состоянию. То, что физиологические и гормональные изменения, происходившие постепенно на протяжении примерно 9 месяцев, откатываются за такие короткие 6 недель, может влиять на вас психологически. Если у вас за плечами трудные роды, этот период может проходить тяжелее обычного. Примите, что этот сложный процесс — временный, и, если вы чувствуете себя плохо, не стесняйтесь просить помощи у близких или специалиста.') WHERE id = 'ee31cac0-139c-4b54-962e-0e0cfd50ac5a';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В послеродовой период уделяйте гигиене интимной зоны больше внимания. Помните: после родов эта область становится особенно уязвимой для бактерий, вызывающих инфекции. Если при естественных родах была сделана эпизиотомия (разрез), может понадобиться уход с антисептическими кремами, рекомендованными врачом. А в первые недели после кесарева сечения особое внимание уделяйте области шва. Учитывайте рекомендации оперировавшего врача и не пропускайте осмотры. Принимая душ, следите, чтобы вода не была слишком горячей, и заходите в душ только тогда, когда рядом кто-то есть. Если вы рожали путём кесарева сечения, во время душа оберегайте места швов и следите, чтобы в эту область не попала инфекция.') WHERE id = '146cc0cd-e1d3-412a-82e1-01fb76131db8';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Малыш может часто плакать в течение дня, и иногда этот плач переходит в приступы с заходом. Приступы плача, особенно в моменты, когда вы не можете его успокоить, могут заставлять вас чувствовать себя совершенно беспомощной. Сохраняйте спокойствие и помните: плач — единственный способ общения, доступный малышу. У плача может быть много разных причин. Одна из них — неудобная одежда, а также то, что ему холодно или жарко. Мамы-новички из страха, что малыш простудится, часто одевают его теплее, чем нужно. Чтобы соблюсти баланс, достаточно надевать на малыша всего на один слой больше, чем на себя.') WHERE id = '92bf1f12-3409-4d88-8829-221346b3ee91';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Контакт чрезвычайно важен для развития и укрепления связи между вами и малышом. Малыш, находящийся в физическом контакте с вами, успокаивается от стука вашего сердца — первого звука, который он слышал в утробе. К тому же этот способ помогает ему спать глубже и спокойнее. Во многих культурах мира малыша сразу после рождения кладут обнажённым на грудь матери. Согласно научным исследованиям, этот первый физический контакт обеспечивает удовлетворение базовых биологических потребностей малыша. Этот контакт приходится на очень чувствительный период формирования будущей психологии и поведения ребёнка. Исследования показывают: у малышей, часто контактирующих с мамой, доля исключительно грудного вскармливания в 3 и 6 месяцев в 2 раза выше. В том же исследовании отмечено, что благодаря этому методу малыши до двухлетнего возраста плачут в 12 раз меньше, чем другие дети.') WHERE id = 'c9ec86c3-ffa1-4c34-8c50-574a23ddec68';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В первые дни после родов нормально иметь характерные для послеродового периода ярко-красные выделения, по объёму близкие к менструальному кровотечению. Эти выделения, называемые лохиями, могут закончиться за 1–2 недели, а могут продолжаться до 6 недель. С каждым днём их количество уменьшается, а цвет меняется. К концу послеродового периода они превращаются в выделения беловатого оттенка. В это время для ухода за интимной зоной часто меняйте гигиенические прокладки и используйте специальные средства для интимной гигиены. Чрезмерные и затяжные кровотечения в послеродовой период могут указывать на остатки плацентарной ткани в матке или инфекцию. Хотя это встречается редко, при таких признаках не относитесь к ним легкомысленно и обязательно проконсультируйтесь с врачом.') WHERE id = '8438f645-667d-4bb4-ad8d-04104669e5fa';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Новорождённые очень нуждаются в маме, а самое развитое их чувство — именно осязание. Лучшие моменты для удовлетворения этой потребности в контакте — кормления, когда малыш чувствует ваш запах. В первые месяцы жизни малыш хочет сосать грудь не только когда голоден. Поскольку единственное место, где он чувствует себя в безопасности, — там, где он ощущает ваш запах, он может хотеть засыпать у груди. Поэтому желание сосать важно не только для насыщения, но и эмоционально. К социальному контакту малыши переходят только после трёх месяцев. Так что не отдаляйтесь от малыша из-за ошибочного мнения «привыкнет к рукам». Частые объятия в первые месяцы облегчают его адаптацию к внешнему миру и укрепляют чувство доверия.') WHERE id = 'a82a92d2-bea2-44d6-bcce-77b7bcd63519';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваша матка после родов всё ещё значительно больше своего добеременного размера. Сейчас вы обычно можете прощупать её на уровне пупка или чуть выше. Примерно за месяц матка полностью вернётся к прежним размерам. Весившая к моменту родов около 1500 граммов, она с каждым днём уменьшается и снова достигает 60 граммов, как до беременности. Время от времени, особенно при кормлении грудью, под действием гормона окситоцина могут возникать боли, связанные с сокращениями матки. Эти спазмы, довольно ощутимые в первые дни после родов, день ото дня становятся мягче. Считается, что эти сокращения нормальны и даже помогают очищению внутреннего слоя матки.') WHERE id = '79a8c317-465e-48a5-8158-982eb6d5f890';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Проголодавшись, новорождённые сначала начинают не плакать, а ворочаться. Вслед за этими движениями они постепенно могут проявлять беспокойство. Если после этих реакций они всё ещё не наелись, начинается плач, и чем дольше малыш остаётся голодным, тем сильнее он плачет. Если на этом этапе сразу пытаться его накормить, в некоторых случаях он может отказываться от груди или бутылочки. Поэтому плачущего малыша сначала нужно взять на руки и успокоить, а уже потом кормить. Если, несмотря на объятия, малыш не успокаивается, можно попробовать кормить стоя. Вы с малышом ещё привыкаете друг к другу, поэтому наблюдайте за его реакциями и старайтесь понять, чего он хочет.') WHERE id = '9e7fdf66-075d-494d-b199-11e006ca39c4';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'С самого рождения из вашей груди начинает выделяться грудное молоко — самая важная потребность малыша. Поэтому в первые недели пейте много жидкости и по возможности избегайте стресса. С этой недели и у вас, и у малыша могут появиться жалобы на газики. Капли от газиков, которые может порекомендовать врач для облегчения колик, обычно дают после первого месяца. Поэтому старайтесь избегать газообразующих продуктов и включите в рацион несладкие компоты, свежевыжатые соки и овощные супы. Молоко и молочные продукты, бобовые, кислые фрукты вроде апельсинов и мандаринов могут вызывать колики. Поэтому добавляйте эти продукты в меню, проверяя реакцию. Если молочные продукты вызывают газики, можно перейти на безлактозное молоко.') WHERE id = 'bbfc25e1-805a-4de5-a48e-49b8bc100ff1';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Формирование режима сна малыша может занять некоторое время. В первые месяцы малыш обычно спит и просыпается весь день напролёт, и неспособность отличать день от ночи — один из факторов, задерживающих наладку режима. Чрезмерная усталость и недосып заставляют малыша плакать. Малыш, которому в первые месяцы положено спать до 15–16 часов в сутки, очень страдает, когда не может уснуть. Кроме того, слишком шумная обстановка и зрительные раздражители могут мешать ему засыпать и заканчиваться плачем. Режим сна малыша начинает понемногу формироваться между 8-й и 12-й неделями. Удлинение интервалов между кормлениями тоже помогает этому распорядку. Но каждый малыш индивидуален, поэтому то, что некоторые привыкают к режиму позже, считается нормальным.') WHERE id = 'a4331c8d-b2a0-435c-af06-870f5fad8fab';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'С первого мгновения жизни малыш очень чувствителен к человеческим голосам. Считается, что причина связана с частотными диапазонами. К тому же за 9 месяцев в утробе он чаще всего слышал звуки работы ваших органов и ваш голос во время разговоров. Используйте эту возможность, чтобы успокаивать малыша, и побольше разговаривайте с ним. Слыша ваш голос, а на руках — и стук вашего сердца, малыш чувствует себя очень спокойно и защищённо. Возможно, малыш уже начал издавать звуки, чтобы выражать чувства и потребности. Для эффективного общения важно отвечать ему звуками, похожими на те, что издаёт он сам. Так малыш начинает учиться разговаривать и использовать звуки для общения.') WHERE id = '1ec6d652-1eca-417a-9067-3ad2a20a5f4b';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Около 20% малышей, несмотря на полное здоровье, могут заходиться в непрекращающихся приступах плача. Это состояние, называемое коликами, обычно начинается в вечерние часы, и успокоить малыша часами не удаётся. Точная причина колик до сих пор неизвестна, но считается, что они связаны с незрелостью пищеварительной системы, некоторыми аллергическими реакциями или нервной системой. Если врач поставил малышу диагноз «колики», ваше беспокойство понятно. Прежде всего знайте: это состояние временное. Обычно к концу третьего месяца эти приступы плача начинают ослабевать и вскоре проходят. Во время приступов пробуйте разные способы успокоения, чтобы найти тот, что работает именно для вашего малыша. Проверенные варианты: тёплая ванна, тёплая пелёнка на животик или включение приборов с монотонным звуком, например фена.') WHERE id = 'd6246f09-676f-479b-ac15-8f1e83a043b1';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вы с малышом оставляете позади ещё один месяц! В 1 месяц по календарю прививок вводится вторая доза вакцины от гепатита B, первая доза которой была сделана сразу после рождения. На ножке в месте укола могут появиться покраснение и припухлость. Не волнуйтесь из-за этого. Также вы можете заметить кратковременное повышение температуры и беспокойство после прививки. Это частые и безвредные побочные эффекты. Беспокойство наблюдается почти у всех привитых малышей. Температура после прививки обычно не превышает 38 градусов. По совету врача при температуре, которая быстро не снижается, можно использовать сироп или свечи. Хотя это случается редко, если вам кажется, что у малыша необычные симптомы, не забудьте связаться с врачом.') WHERE id = '418e11ce-7ef6-4382-bb9b-0ee9fe10e295';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В первое время вы можете замечать, что малыш засыпает во время кормления. Как и многим мамам, вам это может даже нравиться. Но будьте внимательны: если это станет привычкой, малышу будет трудно засыпать без груди. Привыкнув к такому порядку, он не захочет засыпать, не пососав грудь. Поэтому, как только почувствуете, что он сонный и беспокойный, кладите его в кроватку и пробуйте другие способы укладывания. Привыкая к новым способам, малыш поначалу может плакать. Но если не сдаваться и продолжать, со временем вы увидите, что он привык. Если во время таких попыток малыш сильно сопротивляется сну, успокойте его, а затем снова дайте ему возможность уснуть самому.') WHERE id = '9210140f-4b86-4445-aa81-e541ebeace13';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Матка на протяжении 9 месяцев обеспечивала малышу очень тёплую и уютную среду. Попасть с рождением во внешний мир, полный внезапных звуков и света, — для малыша маленький шок. Поэтому привыкание к новой среде может занять время. Если, укладывая малыша, вы видите, что он всё ещё спит, свернувшись, как в утробе (поза эмбриона), — причина именно в этом. Примерно в течение месяца вы заметите, что эта привычка ослабевает. В этот адаптационный период он нуждается в вас больше, чем когда-либо. Ему очень нравится, когда вы берёте его на руки, целуете, разговариваете с ним — словом, уделяете ему внимание, и это способствует выработке в его организме гормонов счастья.') WHERE id = 'd3c1171d-ec50-4947-af33-82084d44686e';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Дни летят быстро, и вы с каждым днём всё больше привыкаете к материнству. Связь между вами и малышом, возможно, уже сложилась — в виде неописуемой любви и сильного чувства защиты. Но мнение, что это чувство должно возникать у каждой женщины сразу и одинаково, неверно. Как чувства у всех разные, так и привязанность к малышу у некоторых женщин из-за родового стресса и послеродового периода формируется дольше. Если временами вы чувствуете отчуждение к малышу, не вините себя за это. Резкое изменение после родов гормонов, постепенно нараставших в крови 9 месяцев, может влиять на психику. Если же, несмотря на прошедшие недели, отчуждение к малышу сохраняется, возможно, у вас послеродовая депрессия. В этом случае настоятельно рекомендуем проконсультироваться с врачом и получить психологическую поддержку.') WHERE id = '08ca900e-fc32-45d6-bd75-a4633391d4f9';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'После рождения малыши в определённые недели переживают периоды быстрого роста и развития (скачки развития). Пятая неделя, в которой вы сейчас находитесь, — первая неделя таких скачков роста. Поэтому в эти дни совершенно нормально, что малыш плачет больше обычного, капризничает, испытывает проблемы со сном или меняет аппетит. Возросший аппетит — это и потребность в большей энергии для роста, и стремление чаще сосать, чтобы запустить гормоны, увеличивающие выработку молока. Во время скачка пятой недели малыш начинает активно использовать органы чувств и замечать всё вокруг. Словом, он открывает, что мир больше не состоит только из еды и сна. В результате, получая больше раздражителей, он иногда может беспокоиться сильнее. Встречайте этот период, который продлится всего несколько дней, с максимальным терпением и помните: он пройдёт.') WHERE id = '3c3db532-5b9a-41a9-8a5e-67563130c5c0';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'С завершением первого месяца во внешнем мире вы наверняка почувствовали, что малыш стал любопытнее к окружающему. Он начинает проявлять интерес к занятным предметам вокруг, крупным формам, ярким и контрастным цветам. Если в первые дни после рождения малыш открывал глаза лишь ненадолго, теперь он бодрствует дольше. Это значит, что он начал использовать чувства, необходимые для исследования мира. В короткие периоды бодрствования показывайте ему цветные ткани или давайте потрогать их, устраивая разные занятия. Вы увидите, что такие игры ему очень нравятся. А поскольку зрение ещё не сформировалось полностью, приближайте своё лицо к нему, чтобы он мог лучше вас рассмотреть и узнать. 😊') WHERE id = '676e6646-3ff2-4bc0-82e0-4614c3d8096a';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, '«Колыбельная шапочка» — известное у малышей состояние кожи, вызывающее корочки и шелушащиеся пятна на волосистой части головы, часто встречается в первые месяцы. Эти красноватые шелушащиеся высыпания могут распространяться на лоб, за уши, на шею и подмышки. Если у малыша появились такие корочки, волноваться не нужно. Обычно они не чешутся и не беспокоят малыша. Иногда при смене подгузника вы можете заметить, что высыпания распространились и туда. В редких случаях в зоне подгузника это состояние может сопровождаться грибковой инфекцией. Точная причина корочек неизвестна, но к ним могут приводить генетическая предрасположенность, естественно живущие на коже дрожжевые грибки, раздражающие вещества, сухой и холодный воздух.') WHERE id = 'dc08af3a-ac5d-4bd3-9ab0-537157d76301';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш, как и все малыши, в первые месяцы очень уязвим. Иммунная система ещё не сформирована полностью, поэтому он может быть беззащитен перед некоторыми болезнями. Хотя вы переживаете счастье встречи с долгожданным крохой, естественно чувствовать огорчение и ранимость, когда ему нездоровится. Особенно если у малыша возникнет какая-то проблема со здоровьем, вы можете сильно расстраиваться. Но на этом этапе не вините себя — направьте всю энергию на малыша и на себя, чтобы преодолеть трудности. Словом, не тревожьтесь, старайтесь быть счастливой. Помните: малыш понимает каждое чувство, которое вы испытываете, и его душевное состояние напрямую зависит от вас.') WHERE id = '90453aab-3c85-45f7-a53b-d1654064425e';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Регулируя позу сна малыша, будьте внимательны к риску срыгивания и удушья. Нет проблемы в том, чтобы укладывать малыша на живот с повёрнутой набок головой, на спину или на бок. Однако долгое лежание в одной и той же позе может привести к изменению формы ещё мягких костей черепа. Поэтому во время сна время от времени меняйте положение малыша. Укладывая его на бок, возможно, понадобится поддержать спинку маленькой подушечкой для равновесия. По совету врача, для снижения риска удушья во сне можно выбрать матрасы с наклоном. А используя плоскую подушку для головы, можно предотвратить уплощение затылка малыша и сохранить округлую форму головы.') WHERE id = '82ca4410-dc4b-42c9-8de1-8024396fe373';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Иммунная система малыша, который 9 месяцев жил в вашей матке в полностью стерильной среде, ещё не готова к внешнему миру. Причина, по которой иммунитет не развивается полностью до рождения, — чтобы он и ваша иммунная система не навредили друг другу. Молоко, которое начинает вырабатываться с родами при помощи гормонов, создаёт для малыша временный иммунитет. Антитела, передающиеся малышу из вашего организма через молоко, усиливаются во время болезни и защищают его тело. Поэтому без особых показаний и рекомендации врача не давайте малышу дополнительные добавки. В первые месяцы нет строгого правила о частоте кормлений — главный ориентир здесь аппетит малыша. Если после кормления вам кажется, что он не наелся, знайте: в первые месяцы желание сосать — это рефлекс, и оно не всегда означает, что малыш голоден.') WHERE id = '376e500c-ed21-4d44-817e-05fcffb83c34';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этом месяце нужно начать давать малышу капли витамина D — их можно бесплатно получить в поликлинике или купить по рекомендации врача. Главный источник витамина D — солнечные лучи: определённое время на солнце покрывает эту потребность организма на 90%. Однако, по научным данным, дефицит витамина D — одна из самых распространённых проблем со здоровьем. Витамин D — регулятор формирующейся иммунной системы малыша. Запас витамина D в организме особенно важен при аутоиммунных заболеваниях. Малыш, питающийся с первого дня жизни грудным молоком или смесью, получает в достаточном количестве все витамины, кроме витамина D. Но витамин D не может поступать в организм малыша с пищей в достаточном объёме. Поэтому этот дефицит обязательно нужно восполнять добавкой витамина D, назначенной врачом.') WHERE id = '4c2feb95-7f80-4a6f-9d8b-18f61f673c70';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Процесс возвращения организма к добеременному состоянию после родов называется послеродовым периодом. Но «сороковины» охватывают лишь 40 дней, или 6 недель после родов. А восстановление после родов у каждой женщины разное и длится дольше. Вы уже держите на руках то чудо, о котором мечтали 9 месяцев. Однако недосып, усталость, физическая боль, невозможность уделить время себе и дому могут продолжаться, порождая чувство «я не успеваю». Иногда вы можете беспричинно нервничать и резко реагировать на окружающих. Словом, послеродовая психология сложна, и ограничивать её 40 днями неправильно. Объясните родным свои чувства и ждите от них понимания. Помните: весь этот процесс временный. Каждая женщина — идеальная мама для своего малыша. В любой трудности мы будем рядом с вами. 😊') WHERE id = 'bad42002-8275-46dc-b1ad-174066cad7e7';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если вы используете для ношения или укладывания малыша поддерживающие приспособления, такие как шезлонг, на их верхнюю часть можно поместить привлекающие внимание игрушки — так, чтобы они не могли навредить малышу. Эти предметы притягивают его внимание, способствуя развитию зрения и восприятия, укрепляют способность понимать. Игрушки со светом, звуком и те, что можно двигать, малышу очень понравятся. Открывать новое для него и волнующе, и весело. Одновременно встреча с разноцветными стимулами вокруг помогает ему познавать самого себя. Но делайте этот выбор осмотрительно. Хотя такие устройства, как телевизор, с их обилием движения, красок и звуков, привлекают внимание малыша, неизбежная правда в том, что они влияют на развитие отрицательно.') WHERE id = '3ad7f64e-f78d-46bd-a402-26a3f15d1d22';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Найти правильную позу для кормления очень важно и для того, чтобы малыш получал от молока максимум пользы, и для здоровья вашего тела. Кормите в удобном положении, поддерживая спину и поясницу подушкой. Кроме того, подложите что-нибудь под руку со стороны кормления, чтобы не держать её на весу весь процесс. Во время кормления держите малыша как можно ближе к себе, лицом к вам. Идеальнее всего расположить тело малыша вдоль внутренней поверхности вашей руки, а голову — в сгибе локтя. Правильная поза имеет решающее значение и для развития малыша. Ведь если продолжать кормить его в неправильном положении, у него быстро заболит шея, и он будет раньше прекращать сосать.') WHERE id = '4be7fa1f-7739-407d-aa85-d7577ebd4d3a';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Газики у малыша, возможно, уже начали ощутимо досаждать. Понаблюдайте за языком его тела: если он подтягивает ножки к животу, краснеет, плачет и делает движения, будто крутит педали велосипеда, то, скорее всего, у него газики. Если эти признаки появляются после кормления и малыш не успокаивается, причина, вероятно, в газах. Понять это несложно: малыш с газиками беспокоен, хочет сосать, но вскоре снова начинает плакать. К тому же животик у таких малышей выглядит твёрдым и вздутым. Движение поможет разогнать воздух в кишечнике и облегчит его состояние. Хотя газики и колики очень мучительны, это временный период. Поэтому сохраняйте спокойствие и знайте: это пройдёт. В такие моменты очень помогает перейти в тихую комнату, говорить с малышом мягким голосом, приглушить свет и помассировать животик.') WHERE id = '16924675-e88b-458a-9fb7-e716fc169d02';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Регулярное купание малыша очень важно и для иммунитета, и для здоровья кожи. Но в купальной рутине есть моменты, требующие внимания. Самый важный — температура воды. Вода для детской ванночки должна быть около 37 градусов. Более холодная или горячая вода может и повредить кожу малыша, и привести к болезни. Температуру в комнате держите в пределах 22–24 градусов. Другой важный вопрос — уровень воды в ванночке. В момент невнимательности малыш может выскользнуть из рук, поэтому глубина воды не должна превышать 15 см. Во время мытья старайтесь не мочить голову и тело малыша одновременно. Через голову тепло теряется очень быстро. Чтобы малыш не замёрз, сначала вымойте тело и, только полностью закончив с ним, вымойте голову и завершите купание.') WHERE id = '9a3356cb-31bb-4c91-8c4b-755f5e18597d';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если малыш питается в основном грудным молоком, его стул может быть довольно жидким. Но иногда вы можете столкнуться и с запором или диареей. Проблемы с пищеварением у малышей встречаются часто, потому что их кишечник очень чувствителен. Поэтому запор, диарея и газики физиологически считаются нормой. Особенно смеси: они перевариваются труднее и дольше остаются в пищеварительной системе, чем грудное молоко, поэтому время от времени вызывают запоры — это частое явление. Как и у всех малышей, работа кишечника и частота стула у вашего малыша индивидуальны. Одни малыши какают несколько раз в день, другие — раз в 5 дней. Если стул мягкий, малыш не тужится с усилием, вес прибавляется нормально и общее состояние хорошее — беспокоиться не о чем.') WHERE id = '315efeec-966c-4318-a08f-5aee7f235a22';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В хорошую погоду выносить малыша на улицу полезно: и вы отдохнёте, и поддержите его развитие. Перемена воздуха и звуков, воздействие окружающей среды могут стать для малыша особым способом успокоения. Выходить на улицу с малышом многим мамам кажется сложным. На самом деле это лишь вопрос привычки. Чем чаще вы будете выходить с малышом, тем спокойнее это будет со временем. Не забудьте взять с собой всё нужное для комфортной и приятной прогулки. Самое важное — конечно, подгузники, пелёнка для смены и влажные салфетки. Также очень пригодятся запасной слюнявчик и комплект одежды на случай срыгивания. Так что отложите все дела и наслаждайтесь свежим воздухом вместе с малышом! 😊') WHERE id = '1dffb4b0-c92d-41f6-b1a5-adde26593736';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Самый важный фактор, повышающий питательность и количество молока, — объём выпиваемой вами воды. Чтобы молоко не убавлялось и вырабатывалось стабильно, выпивайте не менее 2–3 литров жидкости в день и восполняйте потери после каждого кормления. К тому же достаточное питьё — очень действенный способ быстрее сбросить набранные за беременность килограммы. Получая в достаточном количестве все нужные организму питательные вещества, вы и увеличите количество молока, и избавитесь от лишнего веса. Суточную потребность в белке можно покрывать как растительными, так и животными источниками. Но поскольку сейчас период, когда малыш часто страдает от газиков, стоит следить за составом того, что вы едите. И помните: чем чаще вы кормите малыша грудью, тем больше будет молока и тем стабильнее его выработка.') WHERE id = '8b7bb2b5-f77d-4347-879b-67f02bacb220';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Благодаря заметно развившемуся слуху малыш уже может реагировать улыбкой на ваш голос и успокаивающую музыку. В то же время на внезапные громкие звуки он может выражать беспокойство, меняя выражение лица, напрягаясь всем телом, раскидывая ручки в стороны и прижимая их к груди, а также плачем. Ещё в утробе малыш начинает ощущать и записывать в память стук вашего сердца, голоса — ваш и папин — и разные звуки извне. А после рождения звуки, сохранённые в памяти, действуют на него успокаивающе. В беспокойные часы включайте спокойную музыку и обращайтесь к малышу мягким голосом — это его расслабит. А чтобы использовать этот успокаивающий эффект, пойте колыбельные, особенно при засыпании, — это полезно и для когнитивного развития малыша. Кстати, напомним: малыши больше всего любят колыбельные с повторяющимися словами. 😊') WHERE id = '187e9ca9-650d-40db-aa1f-2e28314ee7e9';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'У газиков малыша может быть много разных причин. Знание этих причин очень поможет вам в борьбе с коликами. Самые известные причины — слишком частые и беспорядочные кормления. Для малыша, чья кишечная флора ещё формируется, налаженный режим питания обеспечивает работу кишечных бактерий в самых благоприятных условиях. Это поможет малышу легче переносить колики. В желудке малышей первые 6 месяцев вырабатываются ферменты, переваривающие только молоко. Поэтому давайте лишь грудное молоко или смеси, максимально близкие к нему по составу. Сладкая вода, дошаб, мёд, варенье и другие продукты, кроме молока и молочных смесей, только зря перегрузят пищеварительную систему малыша. А поскольку некоторые лекарства тоже могут усиливать газики, не давайте малышу лекарств без рекомендации врача.') WHERE id = 'a098a0a5-9cf9-4830-b539-70c7b71e29f4';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Как же быстро летят дни, правда? Малыш уже вышел из того самого «новорождённого» состояния и стал лучше воспринимать окружающий мир. На этом этапе он очень любит прикосновения, ласку и объятия. Для малыша, который всю беременность жил в вашем теле, ваши объятия — наверняка самое любимое место. Особенно когда он испуган или встревожен, быстрее всего его успокаивает именно эта безопасная гавань в ваших руках. Засыпая на руках у вас или у папы, он принимает форму вашего тела, словно вьёт себе гнёздышко. А в ближайшие месяц-два он отправится на поиски свободы и вместо того, чтобы умещаться в объятиях, начнёт расширять своё пространство. Поэтому, хоть иногда и трудно, постарайтесь насладиться этими днями обнимашек. :)') WHERE id = '3ff154d9-4a5e-4705-b55a-c139a97509b8';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Малыш, который днём просыпается чаще, ночью уже начинает спать дольше. Чтобы здоровым образом сформировать режим сна и помочь ему засыпать самостоятельно, кладите сонного малыша в кроватку, пока он ещё бодрствует. Эти положительные перемены во сне происходят потому, что он уже умеет различать день и ночь. Чтобы закрепить эту привычку, есть несколько советов. Самое главное — днём держать комнату малыша светлой и оживлённой. А в вечерние часы освещайте комнаты приглушённым светом, ведите себя тише и говорите шёпотом. Эти маленькие перемены — важнейшие условия регулярного и качественного сна малыша.') WHERE id = '854dcb61-ea42-4d37-9176-c3af87b58986';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Послеродовой период уже завершился, поэтому эмоциональные качели, тревоги и чувство собственной «недостаточности» должны постепенно ослабевать. Усталость и истощение после родов уменьшаются, и вы всё больше привыкаете к малышу, ставшему частью семьи. Если вы рожали естественным путём, в области швов после эпизиотомии или при походе в туалет иногда ещё может быть дискомфорт, но контроль мочевого пузыря и кишечника заметно улучшился. Тем не менее сухость влагалища и снижение полового влечения из-за гормональных изменений могут сохраняться ещё какое-то время. Хотя гормоны в основном вернулись к прежнему уровню, вам всё ещё нужно время, чтобы полностью освоиться с психологией новоиспечённой мамы и изменившейся жизнью. Если чувствуете, что вам трудно справляться с этими переменами, обязательно попросите поддержки у врача.') WHERE id = '56bf65a1-60b7-4dfd-848c-0b69df37fbad';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Сейчас очень важно следить за здоровьем — и ради малыша, и ради себя. Главное условие сильного иммунитета, способного бороться с инфекциями, — сбалансированное питание. Ни в коем случае не садитесь на шоковые диеты, чтобы избавиться от оставшихся после родов килограммов. Врач может попросить вас ещё некоторое время продолжать принимать витамины, которые вы пили при беременности. Помимо покрытия потребностей организма в витаминах A, C, D и E, для качества молока принимайте и такие минералы, как цинк, омега и железо. Для этого очень важно есть фрукты и овощи свежими и по сезону. Включая в рацион продукты, богатые цинком и селеном, вы сможете держать иммунитет сильным в любое время года.') WHERE id = '8b8bfabb-ad49-47f5-ad53-ea528bf3b3c1';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Поскольку глазные мышцы малыша ещё не развились полностью, косоглазие может сохраняться ещё некоторое время. Иногда «уплывать» в сторону может один глаз, иногда оба сразу. Когда он хочет проследить за предметом, глаза могут двигаться не параллельно. Такие «соскальзывания» глаз называют ложным косоглазием. Ложное косоглазие возникает и из-за физиологически широких век. Вопреки распространённому мнению, это состояние не влияет на зрение и развитие глаз малыша. По мере роста, с формированием носовой кости и «усадкой» век, этот вид исправляется. А некоторые малыши из-за строения лица лишь выглядят косоглазыми, хотя на самом деле их глаза смотрят в одном направлении. Если это вас беспокоит, для уверенности можно показать малыша детскому офтальмологу.') WHERE id = 'f12655d4-4f11-4cf4-949d-d3c74399a9bf';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Среди пищевых аллергий у малышей самая распространённая — аллергия на молоко, то есть на белок коровьего молока. Она возникает как аллергическая реакция организма малыша на белки коровьего молока (бета-лактальбумин). Поскольку этот белок есть в большинстве смесей, у малышей на искусственном вскармливании она встречается часто. Но проблема не ограничивается смесями: у малышей на грудном вскармливании аллерген может передаваться через молоко, когда мама употребляет молочные продукты. К тому же у большинства малышей с этой аллергией может развиваться чувствительность и к козьему молоку, и к соевым напиткам. Самые явные признаки аллергии на коровье молоко: чрезмерный плач и сильные колики в первые месяцы, срыгивания после кормления, недобор веса, прожилки крови в стуле и запоры. Если вы замечаете у малыша эти признаки и подозреваете аллергию на коровье молоко, обязательно проконсультируйтесь с врачом.') WHERE id = '06a7caf5-4128-4600-83b6-7c3d296c2485';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Существуют способы предотвратить газики у малыша или облегчить эти боли. Кормите малыша по возможности грудным молоком: как самая подходящая пища для его пищеварительной системы, оно обеспечивает лёгкое переваривание. Благодаря этому в кишечнике малыша скапливается минимум газов, а бактерии, расщепляющие их, работают лучше. Интервал между кормлениями настройте не менее 2 часов. Это и делает молоко более жирным, поддерживая развитие малыша, и помогает легче переваривать полученное молоко. Старайтесь не держать малыша в слишком жарких или холодных условиях и не надевать на него несколько слоёв тесной одежды. Это плохо влияет на пищеварение и кровообращение малыша и может вызывать скопление газов в кишечнике. Кроме того, после каждого кормления помогайте малышу отрыгнуть воздух, чтобы убедиться, что в желудке его не осталось.') WHERE id = '37fe650b-ff02-444b-9514-314d6f5df25d';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Малыш, чей режим сна начинает налаживаться, уже заметно оживился и реагирует на вас. Он может показывать, что узнаёт не только вас, но и папу, и людей, которых часто видит. Одна из главных причин — его глаза теперь видят лучше; благодаря этому он начинает изучать окружающее и реагировать на увиденное. С завершением второго месяца, по мере набора веса, у малыша понемногу округляются щёчки, ручки и ножки. Словом, он уже расстался с обликом новорождённого. И всё же помните: каждый здоровый малыш может развиваться со своим ростом и весом. Для устоявшегося режима и качественного сна больше не нужно специально будить его по ночам для кормления. Будить малыша, чтобы покормить, когда он не голоден, или менять подгузник, когда он не беспокоится, — значит снижать качество его сна.') WHERE id = '6bb455df-6ea4-41c3-8194-cb7bda47e257';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если кормить малыша в неправильной позе, проблемы могут возникнуть не только у него, но и у вас. Самая частая из них — мастит. Мастит — это проблема со здоровьем, вызванная закупоркой молочных протоков, с такими симптомами, как температура, слабость, усталость, боль и покраснение груди. При этом состоянии, обычно сопровождающемся инфекцией, если переполненные молочные протоки не опорожнять, возникает закупорка. Столкнувшись с этим, по совету врача можно принять обезболивающее, совместимое с кормлением. При этом очень важно опорожнять грудь с маститом, несмотря на боль. При правильном лечении мастит быстро проходит, и вы сможете спокойно продолжать кормить малыша. Но без нужного лечения закупорка в груди может привести к тому, что организм остановит выработку молока.') WHERE id = '68a7f9bc-02a4-47e7-80eb-cfc071e562a7';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вы с малышом оставили позади два месяца. Можете быть уверены: третий месяц пройдёт спокойнее и увереннее предыдущих. В первые месяцы во внешнем мире малыш развивается очень быстро и может прибавлять в месяц от 700 до 1500 граммов. Иными словами, ожидается, что малыш набирает не меньше 150–200 граммов в неделю. По этим расчётам к концу этой недели средний вес малыша — от 4 до 6 кг. Если малыш мочит подгузник в среднем 5 раз в день, это показывает, что он наедается и в дополнительном питании не нуждается. А с учётом того, что рост увеличивается в среднем на 1,5–2 см в месяц, сейчас он может составлять 57–62 см. Помните: всё это средние значения, у каждого малыша они могут отличаться, и единственный ориентир в этом вопросе — мнение вашего врача.') WHERE id = 'c4b87e12-4678-4aea-8944-a0c3b90a105f';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ради зрительно-моторной координации и развития малыша пора отложить царапки в сторону. Долгое использование варежек может плохо влиять на контакт малыша с окружающим миром и его развитие. Малыш, который уже вовсю изучает свои ручки, может брать предмет, который вы даёте, и тянуть его в рот. Сжимая кулачки и пытаясь тянуть в рот всё, что попадает в руки, малыш так учится распознавать предметы. Этот опыт играет очень важную роль в развитии его интеллекта. Интеллект во многом формируется через опыт, который малыш получает благодаря активным движениям и действиям. Руки — первый инструмент, которым малыш исследует окружающее и собирает информацию, формирующую его ум. Поэтому очень важно поощрять его в этом. Поддерживайте развитие малыша игрушками, которые он сможет схватить, цветными тканями и звучащими предметами вроде погремушки.') WHERE id = '42c11358-bbe1-48ad-b54d-e26f562016b7';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Мозг малыша уже настолько развит, что он реагирует на колыбельные, песни, музыку и даже звуки со стороны. Чтобы развитие мозга шло здорово и правильно, найдите в повседневной жизни место и для музыки. К тому же пение песен и колыбельных укрепит связь между вами. Согласно исследованиям, у малышей, которым с раннего возраста включали музыку, развитие мозга и речи идёт быстрее, чем у остальных. Замечено также, что такие дети чаще проявляют интерес к музыкальным инструментам в будущем. Поскольку малыш ещё в утробе научился отличать ваш голос от других, пение песен и колыбельных подарит вам обоим качественное и весёлое время вместе и ускорит формирование словарного запаса и языковых способностей малыша. А если малыш трудно засыпает, классическая или спокойная музыка успокоит его и облегчит засыпание.') WHERE id = '161206e9-2801-48d5-bf23-ba2c2a393a9f';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Малыш плачет без причины, а беспокойство в последние дни усилилось? Добро пожаловать во второй скачок развития! 😊 Скачок восьмой недели — это увлекательный период, после которого малыш приобретёт новые навыки. В этом рывке роста малыш начнёт лучше узнавать своё тело, откроет для себя ручки и ножки. Вы увидите, как он пытается сосать пальчики, а получив предмет в руку, ловко пользуется пальцами, чтобы его удержать. 😊 Уже не новорождённый, ставший подвижнее малыш, оказавшись на полу, может сам занимать себя. Хотя вдаль он видит ещё нечётко, яркие предметы, фигурные игрушки и огоньки начинают привлекать его внимание. Поскольку для малыша начинается более активный период во внешнем мире, у него может появляться кратковременная рассеянность, из-за чего он меньше хочет сосать. В этом случае полезнее кормить его в более тихой и тёмной комнате или во время засыпания.') WHERE id = 'ba812bc8-8097-4c97-a28f-220a769e0dd9';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Малыш уже начинает отвечать вам осознанными, настоящими социальными улыбками. В этот период мышцы его шеи быстро развиваются, поэтому короткие ежедневные упражнения на животике под присмотром очень важны для правильного формирования позвоночника. Кроме того, с улучшением восприятия малыш уже может следить глазами за цветными предметами и делать первые попытки общения с вами с помощью тихих звуков. А лёгкое недомогание и снижение аппетита после плановых прививок в 2 месяца, которые могут быть в эти дни, снимайте частыми кормлениями и объятиями.') WHERE id = '3c33ef6c-ad69-4a43-8495-e0ff0a641f32';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Рождаться лысым или с волосами — и то и другое нормально. Если малыш родился с волосами, их быстрое выпадение именно в этот период может вас немного тревожить. Это состояние называется «телогеновая алопеция» (telogen effluvium) — выпадение волос, связанное с гормональными изменениями. Во время беременности волосяные луковицы малыша постоянно находятся в фазе роста и развития. А с рождением, в том числе под влиянием гормонов, луковицы на определённое время переходят в фазу покоя. У некоторых малышей выпадение может доходить и до полного облысения. Особенно если вы всё время укладываете малыша в одной позе, вы заметите, что там, где голова соприкасается с поверхностью, облысение сильнее. Это физиологическое выпадение, не связанное с дефицитом питательных веществ; примерно к 6 месяцам оно уменьшается, и на месте выпавших волос начинают расти новые.') WHERE id = '902d6d84-5a76-4be3-852e-11ae4442029d';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В эти дни вы можете наблюдать у малыша постоянное беспокойство, частое желание сосать для самоуспокоения и даже нежелание отрываться от груди. Эти признаки указывают на газики. Это физиологически нормальное состояние: у одних малышей оно проходит легко, у других вызывает колики. С завершением скачка восьмой недели и ускорением развития мозга малыш начинает осознавать мышцы, суставы и нервы своего тела. До этого газы выходили у него непроизвольно и легко. А теперь малыш пытается управлять этими мышцами сознательно. Ему нужно время, чтобы научиться сжимать и расслаблять мышцы, необходимые для выпуска газов. В первые месяцы малыш не может полностью управлять этими мышцами и держит их в постоянном напряжении, поэтому газы выходят с трудом — отсюда и колики. В эти непростые моменты успокаивайте малыша и примите, что это временный период. В ближайшие недели, по мере развития мозга, малыш научится владеть этими мышцами и будет выпускать газы гораздо легче.') WHERE id = 'f2315e81-cb4e-4e16-ad43-3687f3cbaef0';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В течение дня малыш может плакать по-разному и по разным причинам. А вы замечали, что при плаче у него не текут слёзы? Хотя слёзные каналы и железы малыша работают, пока они вырабатывают ровно столько слёз, сколько нужно для защиты и увлажнения глаз. Слёзные железы малыша сразу после рождения входят в фазу быстрого развития и в среднем к 2–3 месяцам развиваются настолько, что появляются слёзы. В некоторых случаях — примерно у 5–6% малышей — встречается непроходимость слёзных каналов. Она может проявляться закисанием глаз, слезотечением, слипанием ресниц, гнойными выделениями и припухлостью вокруг глаз. Причина непроходимости — нераскрывшаяся плёнка в месте выхода слёзного мешка в нос. Без лечения глаза малыша становятся уязвимыми для микробов. Поэтому, если вы видите у малыша эти признаки, не теряя времени проконсультируйтесь с окулистом.') WHERE id = 'e03b8fab-73de-4cff-bd15-34280044bd83';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'У вас могут быть вопросы о том, давать ли малышу пустышку. Малыш приходит в мир с сильным сосательным рефлексом. Это называется «оральный период» и продолжается примерно до 2 лет. Американская академия педиатрии рекомендует пустышку до 1 года, так как считается, что она снижает риск синдрома внезапной детской смерти. Сильный сосательный рефлекс в этот период — функция, удовлетворяющая и пищевые, и душевные потребности малыша. Пустышку можно выбрать, чтобы малыш физически удовлетворял потребность в сосании, эмоционально чувствовал себя защищённым, успокаивался, а грудь использовалась только для кормления. При всём этом пустышка со временем может стать привычкой. Если не ограничивать время использования, может пострадать питание малыша, а в итоге возникнуть отставание в развитии. К тому же долгое использование пустышки может нарушить прикус и задержать развитие речи.') WHERE id = '9bf80a49-be8d-491a-9e0b-6671644690ad';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если вы кормите грудью, менструальный цикл, возможно, ещё не вернулся. У кормящих мам месячные могут восстановиться примерно через шесть-восемь недель после родов, но этот срок может растянуться и до 24 месяцев. Время возвращения цикла у каждой женщины своё. Причина — присутствие в организме гормонов пролактина и окситоцина, обеспечивающих выработку и выделение молока. Пролактин, содержащийся в крови в большом количестве и отвечающий за образование молока, подавляет выработку репродуктивных гормонов, обеспечивающих созревание яйцеклеток. А пока яичники не созревают яйцеклетку, о менструальном цикле говорить не приходится. Поэтому для мам, кормящих малыша своим молоком, точное время возвращения месячных остаётся неопределённым.') WHERE id = 'ed5d9752-70a1-4d4a-938d-22777462f998';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Особенно в период кормления грудью у вас могут быть опасения по поводу лекарств. Как и при беременности, во время лактации ваш организм обладает разными механизмами защиты малыша. Грудное молоко — чудесная пища, создаваемая в вашем организме под все потребности малыша. В вашей физиологии есть защитные системы, не пропускающие некоторые вредные вещества из крови в молочные протоки. Эта физиологическая особенность называется гемато-молочным барьером. Одни лекарства могут проходить этот барьер, другие — нет, и в молоко не попадают. Часть врачей категорично относится к лекарствам при кормлении грудью, а часть взвешивает соотношение пользы и вреда. Поэтому обязательно консультируйтесь с врачом, уточняйте состав принимаемых препаратов и выясняйте, совместимо ли лекарство с грудным вскармливанием.') WHERE id = '23d4091f-e3fa-4f6e-82ab-2f668868b04f';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Плач — важнейшее средство общения малыша. Малыш может плакать от колик, голода, сонливости, холода, жары, желания на ручки и по многим другим причинам. Манера плача тоже различается в зависимости от потребности. Наверняка вы, наблюдая, уже начали понимать, из-за какой потребности он плачет. Малыш, плачущий от голода, замолкает, когда его кормят. Очень важно выстраивать кормление по желанию малыша. Малыш может вздрагивать во сне, просыпаться и плакать. В этом случае его успокоит так называемое свободное пеленание: заверните только ручки тонким одеяльцем, не слишком туго. А если, несмотря на удовлетворение всех потребностей, он успокаивается на руках и снова плачет, как только вы кладёте его, — это поиск физического контакта. Для малыша, прожившего 9 месяцев в утробе, искать этот контакт в первые месяцы после рождения естественно. Не переживайте, что малыш «привыкнет к рукам». Единственное место, где он чувствует себя защищённым, ощущая ваш запах и тепло, — это ваши объятия.') WHERE id = 'd2ed38a5-2867-473a-a048-a7488c8a0f81';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Потовые железы малыша ещё не развились полностью, поэтому он не может потеть, чтобы регулировать температуру тела. Поэтому избегайте слишком жаркой обстановки и не одевайте его теплее, чем нужно. Малышу достаточно температуры в комнате около 22–24 градусов. Дома не нужно одевать его слоями — жилетка, кофта, пинетки поверх носочков. Достаточно боди или тонкого белья, поверх — комбинезон и пара носочков на ножки. Но если малыш родился раньше срока, он ещё не удерживает тепло полностью, и может понадобиться один слой одежды сверх обычного. Чтобы понять, достаточно ли он одет, потрогайте его затылок или животик. У малышей руки и ноги обычно прохладные, поэтому они могут сбивать вас с толку при попытке определить, замёрз ли он. Основная потеря тепла у малыша идёт через голову. Чтобы это предотвратить, дома можно надевать не слишком плотную шапочку. Но помните: на ночь малыша обязательно укладывать без шапочки — она может помешать дыханию и создать риск удушья.') WHERE id = '48c1b6b4-184f-478a-85ac-ef677c12d146';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Самое развитое чувство малыша по-прежнему осязание. Поэтому постоянный контакт кожа к коже укрепляет связь между вами. Осязание, чрезвычайно важное в первые месяцы, — один из главных помощников малыша в установлении контакта с окружающим миром и его познании. С этой точки зрения массаж, поглаживания, контакт кожа к коже считаются самыми действенными и естественными способами развить вашу связь. Общение малыша с миром начинается, когда его трогают, гладят и берут на руки, — так поддерживается и его психосоциальное развитие. Распространённое в народе мнение «не бери на руки — привыкнет» глубоко ошибочно и вредит отношениям мамы и малыша. Пробуждение осязания малыша и постоянный телесный контакт развивают его чувство доверия и, увеличивая выработку молока, поддерживают успех грудного вскармливания. К тому же исследования показывают: малыши, с которыми поддерживают физический контакт и которым часто делают массаж, прибавляют в весе и росте больше остальных.') WHERE id = 'aa7f3500-7164-43a7-9fa5-208e7d522806';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ротавирусная инфекция, проявляющаяся у малышей зловонной диареей, неукротимой рвотой и температурой, особенно в первые месяцы может быть очень опасна. Этот вирус, названный «рота» из-за круглой формы, устойчив к желудочной кислоте. Пройдя через желудок и достигнув тонкого кишечника, ротавирус заражает его клетки и начинает размножаться. Иммунная система, атакованная вирусом, может поднимать температуру до 39°C. Симптомы ротавирусной инфекции начинаются в течение 48 часов после заражения. Она может протекать как водянистая диарея, проходящая сама, а может — как диарея с опасной температурой и рвотой, вызывающая серьёзную потерю жидкости. Из-за таких потерь жидкости, особенно у малышей, может понадобиться госпитализация и внутривенное лечение. Прививка от ротавируса не защищает малыша на 100%, но болезнь у привитых проходит намного легче, поэтому сделать её очень важно. Почти все врачи настоятельно рекомендуют эту вакцину.') WHERE id = '1b640d9c-64b4-46e3-adef-12469bcc8075';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Периодические обильные срыгивания «полным ртом» могут вас тревожить. Обычно они случаются в первые месяцы, вскоре после кормления. Проблема срыгиваний, начинающаяся в первые дни после рождения, связана с тем, что сфинктер (клапан) между желудком и пищеводом ещё не созрел. Эти срыгивания могут закончиться за 3–4 месяца по мере развития, а могут продолжаться и до двух лет. Молоко или смесь, смешанные с воздухом при кормлении, могут подниматься по пищеводу — это повышает вероятность срыгивания. Если вы сталкиваетесь с подобным, стоит пересмотреть способ кормления. Полностью лежачее положение малыша при кормлении грудью или из бутылочки, заглатывание воздуха, слишком медленное или быстрое сосание усиливают срыгивания. А если после кормления помогать малышу отрыгнуть воздух, срыгивания заметно сократятся.') WHERE id = '5fefb883-23f7-42f1-b985-be875f76a7d5';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Самая сильная защита малыша от инфекций — ваше молоко и сделанные прививки. Антитела, получаемые с молоком с самого рождения, закладывают фундамент его иммунной системы и оберегают от болезней. Но помните: эта естественная защита вскоре теряет силу. Если на этом этапе малыша не привить, при встрече с микробами и вирусами его организм может оказаться недостаточно сильным для борьбы. Каждый год в мире миллионы людей умирают от болезней, предотвратимых прививками. Большая часть болезней младенчества и детства — именно инфекционные. Некоторые из них могут вызывать серьёзные эпидемии и осложнения. Поэтому точное соблюдение календаря прививок очень важно, чтобы малыш имел крепкий иммунитет на всю жизнь, дорогая мама.') WHERE id = '9a1ea20d-ced6-455d-9f64-c58e6cf75bea';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'После рождения, особенно в первый год, малыш развивается с невероятной скоростью. Иногда кажется, что он вырос за один день или даже за одну ночь. Но этот процесс роста редко проходит тихо и незаметно. У фазы быстрого роста есть свои физиологические проявления. Время от времени вы можете видеть у малыша проблемы со сном, приступы плача или сбои в питании — и сталкиваться с ситуациями, причину которых не находите. Эти состояния, о которых многие не знают, пока не станут родителями, но которые встречаются почти у каждого малыша, называются скачками роста. Как и у всех малышей, эти скачки у вашего ребёнка — совершенно нормальный и необходимый процесс. В периоды скачков малыш и физически развивается стремительно, и одновременно делает новые открытия о внешнем мире или осваивает новые навыки.') WHERE id = 'bf8343fd-c467-4ff0-b59e-adf0ca316a49';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Кожа малыша тоньше, нежнее и чувствительнее к внешним воздействиям, чем у взрослых. К тому же жировая прослойка у него меньше нашей, поэтому он хуже переносит холод. Поэтому, особенно в первые месяцы, одевайте его внимательно и следите за составом одежды. Так как одежда напрямую касается кожи малыша, отдавайте предпочтение мягким натуральным тканям из хлопка. Выбранная одежда должна быть достаточно свободной для движений и не сковывать ручки и ножки. Чтобы не нарушать кровообращение, и носочки выбирайте мягкие, с нетугой резинкой. При покупках обязательно проверяйте, чтобы рукава, горловина и пояс не были жёсткими, а кнопки и пуговицы — качественными.') WHERE id = '03d19ce6-58a4-42e4-a4c9-562747272e51';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Влияние цветов на психологию, энергию и развитие малыша — научно доказанный факт. Малыш, который уже начинает различать цвета, с этого периода становится чувствительнее к оттенкам вокруг. Влияние цвета не ограничивается настроением. Некоторые цвета, которые вы используете в его комнате, одежде и даже игрушках, активизируют мозг, влияют на привычки сна и укрепляют память. Поэтому знать язык цветов очень важно. Например, тёмные тона синего могут создавать гнетущее впечатление, а светлые действуют на малыша успокаивающе и дают отдых нервной системе. Кирпичные и земляные тона дарят малышу чувство умиротворения, а тёмно-красный может вызывать напряжение. В целом тёплые цвета создают для малыша энергичную среду, а холодные действуют скорее успокаивающе и расслабляюще.') WHERE id = '1a3eb5d8-5f3e-4a88-8c08-5b1025f3faf7';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если у вас возобновились месячные, вы можете заметить некоторые изменения в количестве молока и реакции малыша на него. Причина в том, что гормональные изменения, регулирующие цикл, слегка влияют на выработку и состав молока. Но эти перемены не должны отталкивать вас от кормления. Возвращение месячных не означает, что малыша нужно отлучать от груди; кормить в этот период совершенно безопасно. В дни овуляции в молоке возрастает количество натрия и хлоридов, а калия и лактозы становится меньше. Из-за этого вкус молока может стать чуть более солёным или менее сладким. К тому же в период овуляции и перед началом кровотечения уровень эстрогена и прогестерона меняется, поэтому вы можете чувствовать наполненность и чувствительность груди.') WHERE id = '94e7a1fa-9551-4f9b-be28-3651b7e35a86';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Сейчас всё ваше внимание на малыше, и мысль о новой беременности может пугать. Хотя во время кормления грудью способность к зачатию снижается, она не исчезает полностью. В первые месяцы после родов овуляция, как и при беременности, на время останавливается. Но полностью полагаться на народное «молоко защищает» и не предохраняться неправильно. Если малыш питается только грудным молоком, месячные могут задержаться на 6–8 месяцев. Но если малыш получает смесь, овуляция и месячные могут вернуться уже через 3 недели после родов. Помните: даже без месячных риск забеременеть составляет около 1–2%, а овуляция может произойти и до первого кровотечения. Поэтому, если вы не планируете новую беременность, важно использовать методы контрацепции при каждой близости.') WHERE id = 'a67e120d-50f6-40f7-8148-f8a30d4ac88d';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Жёсткость или волоски, которые вы нащупываете, поглаживая спинку малыша, могут вас беспокоить. В народе это называют «щетинкой», но путать её с пяточной шпорой у взрослых не стоит — обычно в этом нет ничего страшного. Эти волоски, часто встречающиеся у малышей, но обычно незаметные глазу, чаще наблюдаются у девочек и, как правило, ощущаются при купании. Хотя медицинский вред не доказан, если это состояние беспокоит вас или, как вам кажется, малыша, можно делать массаж для облегчения. Для массажа используйте натуральные масла без химических добавок, не раздражающие нежную кожу малыша. Такой массаж и расслабит малыша, и поможет этим волоскам выпасть. О рекомендуемых маслах и уходе можно также спросить своего врача.') WHERE id = 'd55543a0-5e2c-48fc-9829-ce7e9fdddd6c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Как и с любым малышом, одевание вашего крохи может превращаться в настоящее приключение. Малыш не сидит на месте и постоянно двигает ручками и ножками, поэтому переодевание, особенно зимой, может отнимать немало времени. Поэтому стоит выбирать практичную одежду, которая легко надевается и экономит ваше время. При покупках отдавайте предпочтение вещам с широкой горловиной, через которую легко проходит голова. Кожа малыша намного чувствительнее взрослой, поэтому обязательно выбирайте хлопковые, неаллергенные изделия. Безопасность тоже очень важна: избегайте крупных пуговиц, которые малыш может проглотить, и жёстких молний, не прикрытых тканью. Малыши из любопытства могут оторвать такие пуговицы и потянуть в рот. Лишние ленты, банты и кружева для этого периода тоже не лучший выбор.') WHERE id = 'b8aa2eab-ff56-4ab9-8b20-121fbd2d3ec4';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Самый распространённый в нашей стране вид анемии — железодефицитная. Железо — очень важный элемент для человеческого организма. Особенно в периоды быстрого роста потребность клеток и тканей в железе возрастает. Поэтому дефицит железа часто встречается между 6-м и 24-м месяцами — временем самого быстрого роста малышей. Пока малышу не исполнилось 6 месяцев, если он на грудном вскармливании, важно включать железосодержащие продукты в ваш собственный рацион. А у малышей на смеси нужно следить за содержанием железа в питании — посоветуйтесь об этом с врачом. После 6 месяцев грудного молока уже недостаточно, поэтому при переходе на прикорм составьте меню, богатое железом. Яичный желток на завтрак очень богат железом. И не забывайте добавлять в овощные супы для малыша ягнятину или телятину.') WHERE id = 'd050305e-c358-4c29-9151-2db694755a43';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Для каждого малыша самая правильная пища — молоко его собственной мамы, ведь оно создаётся именно под его потребности. Но иногда по состоянию здоровья или личным причинам мамы не могут кормить грудью. В таких случаях лучшая альтернатива — специально разработанные детские молочные смеси. Их получают, изменяя состав коровьего или козьего молока с помощью современных технологий, чтобы приблизить его к грудному. Хотя натуральное коровье молоко по структуре похоже на грудное, исследования показывают, что оно трудно переваривается и его состав не подходит малышам. Поэтому врачи не советуют давать коровье молоко раньше 1 года. Смеси для первого года жизни бывают разных видов: на основе коровьего молока, соевые или с расщеплённым белком. Смеси на коровьем молоке обогащаются веществами, нужными малышу, а соевые обычно рекомендуются малышам с аллергией на белок коровьего молока.') WHERE id = '54371049-7cba-412e-931d-3ce67181ed5e';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш стал заметно подвижнее! 😊 Одна из главных причин — конечно, развивающиеся мышцы. Вы наверняка уже почувствовали, что малыш, приближающийся к 3 месяцам, стал активнее. На этом этапе он начинает держать голову и, лёжа, приподниматься примерно на 45 градусов — он вступил в период быстрого развития. Другая причина подвижности — желание исследовать окружающее. Он уже лучше различает цвета и с развивающимся зрением хочет познавать среду вокруг. В этот период, известный как месяц открытий, ожидаются такие навыки, как изучение своих ручек, желание схватить показанные предметы и способность следить за вами. Малыш, который уже хорошо различает вас и папу, может чаще искать с вами зрительный контакт. Слуховое и зрительное внимание развивается, поэтому в этом месяце вы можете ловить его взгляд, будто он понимает, что вы говорите. У всего этого, конечно, есть и последствия. Например, малыш может спать меньше, предпочитая исследовать мир. А ещё готовьтесь к нескончаемым радостным визгам! 😊') WHERE id = '5ea89e0c-0d1c-402a-8337-a40bace39e26';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Грудное молоко — великолепная пища. Это чудо-питание растёт и меняется вместе с малышом, отвечая его потребностям. Формирование молочных протоков начинается с первых мгновений беременности. Молочные железы, развивающиеся весь первый триместр, ближе к родам наполняются молоком и готовятся к появлению малыша. То, что молоко не спускается в протоки до родов и дополнительная выработка приостановлена, регулируется гормонами плаценты. А в период кормления гормоны окситоцин и пролактин обеспечивают постоянство молока и сам процесс кормления. Молоко покрывает все пищевые потребности малыша первые 6 месяцев — белки, жиры, железо, витамины, а после 6 месяцев для его развития нужно постепенно переходить на прикорм. По мере роста объёма желудка малыша и его потребности в калориях количество молока и насыщенность его состава тоже растут. Так малыш получает от вашего молока максимум пользы до самого конца грудного вскармливания.') WHERE id = 'e67478e1-350c-4cf1-9917-9b4bd3ed801c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Благодаря современным технологиям и медицинским знаниям для женщин, не планирующих новую беременность, существует много разных методов контрацепции. Самые популярные — противозачаточные таблетки, но эстрогенсодержащие при кормлении грудью не рекомендуются, так как могут уменьшить количество молока. Таблетки без эстрогена можно безопасно принимать через 6 недель после родов. Метод, известный как «трёхмесячный укол», содержит прогестерон и не представляет никакой опасности при лактации. В отличие от него, ежемесячные инъекции содержат эстроген, поэтому при кормлении грудью не рекомендуются. Имплант — метод с гормоном, размещаемый под кожей и защищающий три года. Хотя гормон из импланта проникает в молоко, на малыша он не влияет. А самый рекомендуемый врачами метод — внутриматочная спираль с очень высокой степенью защиты. Спираль, у которой есть гормональные и негормональные варианты, можно устанавливать через 6 недель после родов.') WHERE id = 'e001d0c5-46e0-40b1-82c7-a4a7f2a5f692';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Выбор одежды для малыша, как и всё остальное, — деликатная тема со своими тонкостями. Один из главных моментов здесь — безопасность. С точки зрения безопасности очень важно выбирать вместо одежды с пуговицами или длинными завязками простые вещи на кнопках. Кроме того, выбирайте качественные изделия, не линяющие краской, которая может накапливаться в организме как токсин и обладать канцерогенным действием. Организм малыша вырабатывает защитные механизмы против всего, что может ему навредить. Аллергия — как раз результат работы этой защиты. Поскольку красители в одежде могут вызывать у малыша аллергию, отдавайте предпочтение сертифицированной продукции. Изделия с таким сертификатом проходят анализ на подозрительные вещества, способные навредить телу малыша, и производятся в рамках норм безопасности. Поэтому одежду, отвечающую этим стандартам, можно надевать на малыша со спокойной душой.') WHERE id = '8bcfa34a-ab3b-47cd-8082-d8d412e4c0f8';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш третий месяц вместе с малышом! В этом месяце, открывающем новый этап, готовьтесь к сюрпризам, которые сделают вас по-настоящему счастливой. Моторные навыки малыша развились уже настолько, что он может, пусть и ненадолго, удерживать предметы, которые вы вкладываете ему в руку. Причём это уже не рефлекс, а произвольное действие. Хватательный рефлекс ладоней начинает угасать, а вот рефлексу стоп нужно ещё несколько месяцев. Другой момент перехода от рефлекса к осознанному поведению связан с питанием. Рефлекс новорождённого — открывать ротик при прикосновении к щёчке — с этого месяца понемногу превращается в произвольное действие. То есть если малыш не голоден, он уже не откроет рот. Эти перемены в поведении происходят, конечно, благодаря стремительно развивающемуся мозгу малыша.') WHERE id = '327fd5ec-447f-4d93-a81c-c3fdb4d5f652';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'На плановом осмотре в этом месяце врач проверит некоторые показатели развития малыша. Первый и самый важный — умение держать голову. Малыши, которым исполнилось 3 месяца, должны свободно управлять головой, держать её прямо и поднимать до 45 градусов. А родничок ещё должен оставаться мягким и незакрытым. Эта открытость очень важна для эффективного продолжения развития мозга. Другой показатель развития мозга — окружность головы. С этого месяца она должна составлять в среднем 37–43 см. Другие показатели, которые врач будет регулярно отслеживать, — рост и вес. В этом месяце вес малыша может колебаться в пределах 4200–7500 граммов, а рост — 55–65 см. Помните: это средние значения, и у каждого малыша они могут отличаться. Пока показатели остаются в пределах нижней и верхней границ, беспокоиться о развитии малыша не нужно.') WHERE id = '76c150ee-bf0f-46cc-b728-a8452683e29c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Третий скачок роста малыша должен начаться в эти дни. Так что если увидите беспокойство, нарушения сна и перемены аппетита — не паникуйте. Третий скачок происходит в среднем около 12-й недели, хотя сроки могут смещаться из-за разницы между датой рождения и предполагаемой датой родов. После этого скачка малыш начинает больше интересоваться звуками и благодаря обострившемуся слуху улавливает даже перемены в тоне голоса. Кроме того, клетки ствола мозга, отвечающие за слух, начинают работать так, что определяют, с какой стороны идёт звук, и реагируют на это. Это значит, что малыш уже может различать направление звука и поворачиваться к нему. Ещё одна перемена этого периода — малыш начинает открывать собственный голос. Узнав свой голос, он может удивлять вас звуками разной формы и громкости. Весёлого времяпрепровождения! 😊') WHERE id = '7157ab6b-c70f-4177-b181-d8ea3a2d459e';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если вы кормите малыша смесью или используете докорм из-за нехватки своего молока, один из важнейших вопросов — выбор бутылочки. К выбору бутылочки ни в коем случае нельзя относиться небрежно — это здоровье малыша. Правильные бутылочки играют большую роль в питании малыша и, будучи удобными, заметно облегчают вам жизнь. Выбирайте модели, при которых малыш широко открывает ротик — так же, как при кормлении грудью. Кроме того, у выбранной бутылочки должна быть клинически доказанная способность не перегружать пищеварение и уменьшать колики. Материал, объём, форма, антиколиковая система, форма соски и количество отверстий — всё это моменты, на которые стоит обратить внимание. На этом этапе малышу рекомендуются бутылочки объёмом 240–260 мл со соской среднего потока и системой вентиляции воздуха.') WHERE id = '20a065b0-2b51-4884-b57e-e72acfd3836c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Темп роста и развития малыша меняется с возрастом. В некоторые периоды он растёт медленнее, но при вступлении в скачок — период быстрого развития — темп роста увеличивается. Снижение аппетита в периоды замедленного роста с научной точки зрения считается нормой. В первый год жизни малыш растёт очень быстро, поэтому серьёзных проблем с аппетитом, требующих вмешательства, обычно не бывает. И всё же при прорезывании зубов и в периоды активного исследования мира возможна кратковременная потеря аппетита. Почти для каждого малыша прорезывание зубов — трудное время. В эти дни малыш капризничает и испытывает физическую боль, поэтому нерегулярное и сниженное питание нормально. Но важно не путать «ест мало» с отсутствием аппетита. Для новоиспечённой мамы это тревожно, но на самом деле паниковать не нужно. Кроме того, у малышей, рано начавших прикорм, аллергические реакции из-за неготовности пищеварительной системы тоже могут вызывать снижение аппетита.') WHERE id = '87f56862-dda9-454a-a541-34481c8ca235';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'С малышом можно заниматься множеством разных вещей. Внимание к малышу, который уже активно общается с окружающим миром, — лучшая инвестиция в его будущее. Обоняние у малыша очень острое: давайте ему нюхать самые разные запахи, чтобы клетки мозга работали эффективнее. Для развития речи нужно часто разговаривать и общаться с ним. Важно, чтобы он слышал как можно больше разных слов. Постоянно говорите с малышом, часто обращайтесь к нему по имени, помогая запомнить его, прикасайтесь и целуйте. Малыш, чувствующий любовь и внимание, растёт здоровее и физически, и душевно. Вместо того чтобы сидеть с малышом дома и закрывать лишь физиологические потребности, создавайте ему возможности для новых впечатлений. Выходите на улицу, дайте ему почувствовать солнце на свежем воздухе. А когда выйти не получается, вместе смотрите на улицу с балкона или из окна. Главная цель — раскрывать восприятие малыша через движение, задействовать его органы чувств и тренировать память.') WHERE id = 'd229dd79-f389-4db8-9b5a-34c760b0f5c0';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если при смене подгузника вы видите на коже малыша шелушение, покраснение и воспаление, кроха мог подхватить грибковую инфекцию. Грибки, вызывающие эти реакции, — микроскопические организмы, быстро размножающиеся во влажной среде. Для их размножения нужны тепло и влага. Найдя благоприятные условия, они легко распространяются. В местах, контактирующих с водой и остающихся влажными, как интимная зона малыша, вероятность грибка высока. Поэтому после подмывания не оставляйте кожу влажной — тщательно просушивайте. Чтобы отличить грибок от опрелости, важен осмотр врача. Визуально в местах с грибком наблюдается шелушение кожи. У малышей с опрелостями, особенно при приёме антибиотиков без контроля врача, риск грибка очень высок. Поэтому относитесь к опрелостям на коже малыша внимательно и бережно.') WHERE id = 'b63be385-2a69-41af-ad23-38c2f405d961';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Срыгивания после кормления с физиологической точки зрения чаще всего считаются нормой. И всё же наблюдать за ними важно. Особенно в первые месяцы малыш может вскоре после кормления обильно срыгнуть безо всякого напряжения. С возрастом это уменьшается, и обычно к восьми месяцам срыгивания после еды проходят. Заглатывание воздуха при кормлении, слишком быстрое или слишком медленное сосание, а также то, что после еды малышу не помогли отрыгнуть воздух, могут вызывать срыгивания. Если исправить эти ошибки в технике кормления, срыгивания у малыша тоже прекратятся. Срыгивание обычно происходит после еды, потому что мышца в нижней части пищевода, препятствующая обратному забросу содержимого желудка, физиологически ещё не сформирована. Хотя срыгивания встречаются с самого рождения, к 4-му месяцу их частота возрастает, затрагивая почти 3 из 4 малышей. После 6 месяцев они обычно идут на убыль и с переходом на твёрдую пищу исчезают полностью.') WHERE id = '94ce13b4-bc4e-480c-a364-11de1e4c0330';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'У колик малыша есть две основные причины. Первая — газ, который выделяют полезные бактерии в желудке малыша, расщепляя непереваренные компоненты грудного молока или смеси. Вторая — воздух, который малыш заглатывает при плаче, глотании, сосании груди или бутылочки. К тому же, если вы кормите грудью, употребление вами газообразующих продуктов тоже может вызывать газики у малыша. Поэтому полезно сократить такие продукты в рационе. Против колик можно принять много мер. Одна из них — не дожидаться, пока малыш сильно проголодается. Слишком голодные малыши пьют молоко быстро и заглатывают много воздуха. А если вы кормите из бутылочки, следите, чтобы отверстия в соске не были слишком маленькими или большими, — так вы сведёте жалобы на газики к минимуму.') WHERE id = '14cce317-1232-45b9-96bd-2281d87ef8be';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Несколько изменений в кормлении малыша предотвратят рефлюкс и сведут к минимуму риск проблем в будущем. Самое важное — частота и режим питания. Кормите малыша по возможности в вертикальном положении. Схема «чаще, но понемногу» уменьшает рефлюкс и обеспечивает спокойное пищеварение. Между приёмами пищи и после них избегайте встрясок — подбрасываний и перекатываний; наоборот, после каждого кормления держите малыша вертикально около 20 минут. Также следите, чтобы подгузник не был слишком тугим. Слишком туго застёгнутый подгузник повышает давление в животике и может вызывать срыгивания. Использование тонкой подушечки, чтобы во время сна голова малыша была чуть приподнята, облегчает выход газов и предотвращает возможные попёрхивания. Вдыхание малышом сигаретного дыма, помимо прочего вреда, тоже вызывает рефлюкс — это ещё один важный момент, которого нужно избегать.') WHERE id = '4db7b0e8-8a13-4223-9f1c-396106b58bfc';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Качество, которое вы больше всего хотите развить в растущем малыше, — конечно, его интеллект и мозг. Один из самых действенных путей — читать ему книги. Знакомство с книгами и любовь к ним на этом этапе заложат основу его будущих школьных успехов, базовых навыков речи, языкового чутья и способности рассуждать. Научно доказано, что у детей, интересовавшихся книгами до школы, академические успехи выше. Читая малышу, вы закладываете фундамент его речевых навыков: он перенимает у вас основные звуки, нужные для речи. Более того, в активном общении, благодаря связи с вами, малыш освоит правильные способы коммуникации задолго до школьных лет. Регулярно и постоянно слыша из книг правильные структуры предложений, малыш ещё с дошкольного возраста разовьёт чутьё к грамматическим правилам. Поэтому очень важно читать ему уже сейчас — до того, как он начнёт читать сам.') WHERE id = '847c3222-1e8f-4ee7-af36-660c53f7b72c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Качественно проводить время с малышом — значит сосредоточиться не на продолжительности общения, а на пользе и содержании совместных интерактивных занятий. Поэтому, даже если вы находитесь с малышом в одной комнате, но не занимаетесь с ним и не уделяете ему внимания, это нельзя считать качественно проведённым временем. Одно из главных условий полноценного развития малыша — с самого его рождения спокойно, заботливо и мягко разговаривать с ним, чётко произнося слова, а также объяснять ему свои действия. Хотя малыш ещё не достиг того уровня физического и умственного развития, который позволяет говорить и понимать ваши слова, уже на этом этапе он начинает запоминать различные слова, которые слышит. Частые разговоры с малышом и использование разнообразных слов очень важны для будущего развития речи, языковых навыков и интеллекта. Например, меняя малышу подгузник, не молчите, а поэтапно рассказывайте ему, что вы делаете. Если вы будете применять этот подход в повседневной жизни, это поможет сформировать у малыша богатый словарный запас и станет стимулом для развития его интеллекта.') WHERE id = 'b5b55ba0-7239-4a48-97b0-39887b3f6198';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Клетки головного мозга малыша развиваются по мере приобретения нового опыта. Чтобы поддерживать это развитие, вам следует регулярно знакомить малыша с чем-то новым. Например, новые игры, игрушки или движения, добавленные в ваши занятия, помогут ускорить формирование связей между клетками головного мозга. Даже если вы покажете другой способ игры с уже знакомыми игрушками или познакомите малыша с предметами необычной формы, это может оказаться очень полезным для его развития. Во время таких занятий важно давать малышу возможность многократно повторять новые действия. Чем чаще малыш повторяет какое-либо действие, тем прочнее новый опыт закрепляется в его памяти. Поскольку малыш вступил в этап активного обучения, старайтесь относиться к нему позитивно и придерживаться определённого режима. Замечено, что малыши лучше запоминают счастливые моменты и любые стимулы, напоминающие о них. Поскольку малыш очень чутко реагирует на ваше эмоциональное состояние, ваше хорошее настроение и радость во время совместных занятий также окажут на него положительное влияние.') WHERE id = '6974552e-5545-418f-9e3a-c5909451e194';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Каждый малыш растёт в своём темпе и проходит этапы развития в разное время. Поэтому сравнивать развитие вашего малыша с развитием других детей не имеет смысла. Хотя малыш ещё не способен умственно и физически контролировать органы, участвующие в речи, он проводит много времени, слушая ваш голос. Слушая вас, малыш запоминает разнообразную информацию о языке. Поэтому, даже если ему ещё нужно время, чтобы начать говорить, он может выражать свои потребности разными оттенками плача, смехом и «гулением». Во время кормления или смены подгузника малыш может отвечать на вашу любовь и внимание, двигая ножками или издавая звуки. Здесь могут проявляться индивидуальные особенности. Одни малыши постоянно пытаются произносить осмысленные звуки, а другие ждут, пока не будут полностью к этому готовы. Исследования показывают, что способ общения с малышом связан с развитием его речи. Чтобы поддержать развитие малыша, рекомендуем вам чаще разговаривать и играть с ним, читать ему книги, а во время общения использовать простые и понятные слова. 😊') WHERE id = '51f1030e-fc36-4b12-b1d7-a64348ea081b';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'На этом этапе существует множество разных занятий, которые позволят вам проводить время вместе и поддерживать развитие малыша. Например, вы можете создать условия, чтобы он слышал разнообразные звуки. Потрясите звучащей игрушкой или погремушкой справа и слева от малыша, побуждая его поворачивать голову в сторону источника звука. Когда малыш в хорошем настроении, особенно после купания или кормления грудью, можно включать ему звуки разных животных. Сначала познакомьте его с более знакомыми звуками, например мяуканьем кошки и лаем собаки, а затем — со звуками, которые издают лошадь, пчела или осёл. Для этого можно воспользоваться интернетом и развивающими книгами. Вы даже можете сами имитировать эти звуки. Наблюдайте за реакцией малыша на разные звуки. Вы увидите, сколько радости принесёт ему это совместное занятие. 😊') WHERE id = 'e2c4c53d-e6ae-41f3-83d4-6473c78c7fb7';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вероятно, ваш малыш уже начал переворачиваться. Некоторые малыши осваивают этот навык ещё раньше. Но если ваш малыш пока не переворачивается, волноваться не стоит. Каждый малыш уникален, и темпы развития могут значительно различаться. Способность малыша свободно переворачиваться зависит от развития мышц головы и шеи. Когда малыш научится уверенно контролировать их, это заложит основу для таких двигательных навыков, как сидение, ползание и ходьба. Чтобы побудить малыша переворачиваться, выкладывайте его на живот на мягкую поверхность и давайте ему возможность тренироваться. Поскольку мышечная и нервная системы недоношенных малышей функционируют иначе, они могут позже научиться контролировать голову и шею. Если ваш малыш родился раньше срока, он может освоить перевороты вплоть до 9-го месяца. И кто знает? Возможно, он пропустит этап переворотов и сразу начнёт сидеть? 😊') WHERE id = '4f657a4a-e832-4fda-9834-e8fa08bd9d44';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Слюнотечение и попытки тянуть всё в рот... Вероятно, вы уже догадываетесь, в чём причина. Начиная с этого месяца у малыша может начаться период прорезывания зубов. Конечно, видеть зубки, которые так очаровательно дополняют его улыбку и смех, очень приятно. Однако у большинства малышей прорезывание зубов сопровождается болезненными ощущениями. Из-за отёка дёсен малыш может испытывать боль и беспокойство. Самый известный признак прорезывания зубов — конечно же, усиленное слюнотечение. К другим признакам относятся стремление кусать всё, что попадается под руку, небольшое повышение температуры, отказ от груди или еды. Эти симптомы могут появиться за несколько месяцев до прорезывания зубов. Однако в зависимости от наследственности зубки могут появиться в этом месяце и без каких-либо предшествующих признаков. Повышение температуры малыша до 37 градусов при прорезывании зубов врачи считают нормальным и не требующим вмешательства. Но если температура поднимается до 38 градусов и выше, это не является признаком прорезывания зубов и требует консультации с врачом.') WHERE id = 'fd702e8d-6a0f-4f31-a1a0-b330e1d04288';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'На этом этапе зрительно-моторная координация малыша значительно улучшилась. Благодаря развитию хватательного навыка малыш обнаруживает, что может брать игрушки и другие предметы руками, и начинает сосредотачиваться на этих действиях. Например, теперь он не выпустит погремушку из руки, пока сам этого не захочет. А поняв, что она издаёт звук, малыш может попробовать потрясти её. Такое поведение — один из первых шагов в умственном развитии малыша, помогающий ему устанавливать причинно-следственные связи. Вскоре все эти связи станут более функциональными, и малыш начнёт тянуть в рот предметы, которые держит в руках. На этом этапе, называемом "оральным периодом", малыш благодаря сосательному рефлексу — одному из первых врождённых рефлексов — тянет в рот всё, что вызывает у него интерес и что он хочет исследовать. Этот период продолжается до достижения малышом одного года. В это время он взаимодействует с внешним миром всей поверхностью тела, но особенно активно — с помощью рта. Поэтому вам следует убрать все мелкие предметы, которые малыш может проглотить, и не оставлять его одного надолго.') WHERE id = '60021b19-b43c-4324-8e67-4e9b5d399b4d';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если во время кормления грудью или из бутылочки малыш отстраняется и плачет, скорее всего, вы столкнулись с отказом от груди или кормления. В такой ситуации малыш по разным причинам может не хотеть сосать, даже если он голоден. Одна из самых частых причин — заложенность носа. Из-за заложенности малышу приходится дышать ртом, поэтому, даже будучи голодным, он может часто отпускать грудь или отказываться от неё. Если нос малыша заложен, перед кормлением очистите его с помощью аспиратора или используйте рекомендованные врачом капли для носа, чтобы малыш мог свободно дышать. Кроме того, нарушение привычного режима и изменение времени кормлений могут вызвать у малыша беспокойство и нежелание сосать. Неправильная техника кормления грудью также может затруднять правильный захват груди. Узнав больше о правильных техниках грудного вскармливания и попробовав разные положения, в которых малышу будет удобно захватывать грудь, вы сможете помочь ему снова начать сосать.') WHERE id = '923618b2-185f-4d48-8595-207ec8b1f1d7';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Волосяные фолликулы малыша начинают развиваться ещё в утробе матери, примерно в первом триместре. До дня рождения волосы, называемые лануго, становятся гуще в области головы малыша, помогая предотвращать потерю тепла. Поскольку густота и продолжительность роста этих волос зависят от генетических факторов, совершенно нормально, если малыш рождается с густыми или редкими волосами либо совсем без них. На самом деле количество волос при рождении не указывает на наличие каких-либо проблем со здоровьем. Особенно в эти месяцы волосы малыша могут активно выпадать. На затылке даже может появиться небольшая лысинка. Это может быть связано как с тем, что малыш постоянно спит в одном и том же положении, так и с переходом волосяных фолликулов в фазу покоя в период от рождения до 6-го месяца. Даже если вам жаль стричь волосы малыша, специалисты рекомендуют сделать это, когда придёт время, независимо от того, густые они или редкие.') WHERE id = '1a637264-ed95-4fa6-842a-a26e3ce3729a';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Мозг малыша непрерывно развивается ещё во время его пребывания в вашей утробе. После рождения это развитие продолжается ещё быстрее. Наиболее интенсивно мозг развивается в период 0-48 месяцев. В это время малышу необходим новый опыт, чтобы познавать окружающий мир и учиться. Одна из важнейших составляющих такого опыта — игрушки, которые привлекают внимание малыша и поддерживают его развитие. Яркие игрушки разных форм активируют нейроны и способствуют формированию связей в мозге, помогая малышу осмысливать окружающий мир. В отличие от предметов повседневного обихода, игрушки развивают творческие способности и очень полезны для формирования только зарождающегося воображения. На этом этапе слух малыша развит лучше, чем зрение. Поэтому в течение первых 6 месяцев особенно полезны игрушки со звуковыми элементами. Например, это могут быть лёгкие игрушки, издающие разные звуки, музыкальные игрушки, подвешенные над кроваткой или игровым ковриком, а также погремушки, которые малыш сможет держать в руках.') WHERE id = '341dbb77-f89b-4786-ae5e-27fe6c263105';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вы заметили, что в течение первых 1-2 месяцев ладони малыша обычно были сжаты в кулачки, а теперь начали раскрываться? На 3-м месяце малыш начинает обращать внимание на собственные руки. Он всё чаще двигает ими, а наблюдение за их движениями становится одним из его любимых занятий. Исследуя свои руки, малыш одновременно развивает зрение. Вы можете сделать этот период ещё интереснее! Поддержите его стремление к открытиям с помощью звуковых игрушек, которые крепятся на запястья. Но обязательно используйте их только под вашим присмотром: маленькие ручки могут двигаться очень быстро.') WHERE id = 'ad6180ec-951a-4399-9c9f-0798090c6244';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'На этом этапе малыш всё ещё может сохранять многие врождённые рефлексы. По мере роста эти инстинктивные реакции угасают, уступая место более сложным двигательным навыкам и осознанным движениям. К важным для малыша рефлексам относятся: сосательный и поисковый рефлексы, рефлекс Моро, асимметричный шейный тонический рефлекс, шаговый рефлекс, хватательный рефлекс, рефлекс Бабинского, рефлекс сгибания, а также глотательный и рвотный рефлексы. Некоторые из них на этом этапе могут уже исчезнуть, а другие — начать ослабевать. Например, поисковый и сосательный рефлексы появляются при рождении малыша и связаны с инстинктивной потребностью в питании, необходимой для выживания. Примерно между 2-м и 4-м месяцами развития, особенно в дневное время, эти рефлексы начинают сменяться осознанными действиями. Поэтому вы можете заметить, что малыш уже не открывает рот при прикосновении к щеке, а делает это только тогда, когда вы подносите к нему пищу.') WHERE id = 'f9a31ada-1c4c-4cc8-a19f-e08982dace02';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш растёт прямо на глазах с невероятной скоростью. Каждый день он осваивает новые навыки и демонстрирует их вам. 😊 Игрушки, которые вы выбираете для малыша, имеют большое значение: они помогают ему приобретать новые навыки, развивают творческие способности и поддерживают развитие мозга. В этот период малыш всё больше интересуется окружающим миром, поэтому вы можете покупать ему новые и необычные игрушки или придумывать другие способы игры с теми, что уже есть. При выборе игрушки важно учитывать, соответствует ли она возрасту малыша и как может повлиять на формирование его личности. Научные исследования показывают, что игрушки играют важную роль в развитии малышей. Каждая игрушка, с которой ребёнок играет в дошкольном возрасте, помогает ему познавать мир и способствует развитию личности. Поэтому при выборе игрушек обращайте внимание на то, чтобы они задействовали все органы чувств, развивали двигательные навыки и воображение, а также поддерживали формирование социальных навыков.') WHERE id = '86e946c1-ab86-4301-9ac4-7f795adc1bfa';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Поскольку ваш малыш рождается с уже развитыми органами чувств и миллионами клеток мозга, готовых к активной работе, с момента появления на свет он начинает запоминать всю поступающую информацию. При рождении у малыша есть лишь несколько рефлексов, помогающих ему выжить, но за короткое время он освоит множество навыков, таких как ползание, речь и ходьба. Согласно исследованиям, одной из главных причин, по которым малыш так быстро приобретает эти удивительные навыки, является дневной сон. Он позволяет малышу отдохнуть и усвоить новое, а также помогает закрепить пережитый опыт в памяти. Регулярный режим сна способствует своевременному освоению таких важных навыков, как ходьба и речь. Со временем продолжительность сна сокращается, и малыш, который начинает активно исследовать окружающий мир, иногда может сопротивляться укладыванию. В этом возрасте привычки формируются легко, поэтому рекомендуем уже сейчас наладить режим сна малыша. 😊') WHERE id = '12adf52f-ce6e-45aa-88f8-a01f2005b356';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш часами держит руки перед лицом и с восхищением рассматривает их? Кажется, мы слышим, как вы говорите: "Да!" 😊 В эти недели почти каждая мама замечает, что малыш рассматривает свои руки, исследуя их, и тянет в рот. Такое поведение на этом этапе развития совершенно нормально, и препятствовать ему не следует. Пусть малыш тянет руки в рот столько, сколько ему хочется. 😊 Всё больше интересуясь своими кистями и пальцами, малыш, особенно лёжа на спине, поднимает руки, двигает ими и рассматривает их. Он даже может быстро двигать руками и следить за собственными движениями глазами и головой. Проходя эти этапы развития, малыш научится управлять руками как полезным инструментом и использовать их для изучения окружающих предметов. Вам нужно лишь следить за чистотой его рук и вовремя подстригать ногти, чтобы малыш не повредил слизистую рта. Приятных открытий! 😊') WHERE id = 'caffa322-fe7d-4bfd-9362-04360cd00a6c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В мозге малыша на 3-м месяце жизни уже начинают формироваться воспоминания и сохраняться впечатления. На первом этапе это происходит благодаря постоянно повторяющимся действиям. Малыш уже начинает запоминать и различать людей, предметы и выражения лица, которые видел раньше, поэтому понимает, что плач поможет привлечь внимание. Одно из самых прекрасных достижений этого месяца — малыш учится отвечать улыбкой на вашу улыбку. Готовьтесь к улыбкам. 😊 На самом деле память малыша начинает формироваться ещё в утробе. Как только у него развивается слух, он начинает воспринимать и запоминать звуки, поэтому после рождения легко отличает ваш голос от других. Теперь благодаря быстро развивающемуся мозгу малыш может осмысливать сохранённую в памяти информацию и реагировать на неё. Например, 3-месячный малыш способен до 7 дней помнить показанный мамой предмет и при повторной демонстрации отреагировать, показывая, что узнал его.') WHERE id = 'a7c25396-4991-4496-8a65-64211f7dd866';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Благодаря быстро развивающейся нервной системе и органам чувств малыш начинает активнее взаимодействовать с окружающим миром. Поэтому его нежелание спокойно лежать на месте, плач в одиночестве и постоянное стремление находиться у вас на руках вполне нормальны. Хотя время от времени это может вас утомлять, постарайтесь относиться к этому с пониманием и помогайте малышу исследовать окружающий мир. Если во время прогулок и ношения на руках вы будете держать малыша в разных положениях, это поможет укрепить его мышцы и доставит ему большое удовольствие. Кроме того, так он сможет полноценно общаться с вами и знакомиться с окружающим миром. В этом месяце сон, игры и кормление малыша уже начинают подчиняться определённому распорядку. Поэтому 3-й месяц считается поворотным моментом и для вас, и для малыша. Продолжайте играть с малышом, проводить с ним время и чаще ему улыбаться. Качественно проведённое вместе время показывает, что вы заботитесь о нём, и имеет большое значение для его здорового эмоционального развития.') WHERE id = 'c7c7ac0c-0d6e-4513-8d30-65a89768a3af';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вероятно, вы уже некоторое время замечаете, что малыш стал реже опорожнять кишечник. Частота стула у малышей может сильно различаться, и большинство вариантов считается нормой. Если малыш питается исключительно грудным молоком, нормальным может быть стул как один раз в неделю, так и 5-6 раз в день. Стул малыша на грудном вскармливании обычно жёлтый, жидкий и слегка зернистый. Если малыш питается смесью и у него нет запора, мягкий стул один раз в 3-4 дня или до 5 раз в день также считается нормой. Стул малыша, получающего смесь, может быть как жёлтого, так и зелёного цвета. Помимо способа кормления, частота стула может меняться при смене марки смеси или во время приёма антибиотиков. Главное, на что следует обратить внимание, — консистенция стула. Если он твёрдый, сухой и выходит отдельными фрагментами, у малыша, скорее всего, запор. Если вы заметили, что малыш испытывает из-за этого дискомфорт и беспокойство, желательно как можно скорее связаться с врачом.') WHERE id = '0aa04f59-8956-4168-94d6-7cbf1b5d04b5';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В эти дни малыш может преподнести вам сюрприз: лёжа на животе, он может перевернуться на бок или даже на спину. Благодаря развивающимся мышцам спины и шеи такие попытки перевернуться часто заканчиваются успехом. Начиная с этого месяца малыш может даже пробовать садиться. Хотя некоторые врачи не рекомендуют усаживать малыша до 6 месяцев, важно помнить, что каждый ребёнок развивается в своём темпе. Когда мозг и тело малыша будут готовы, то есть мышцы достаточно окрепнут и разовьётся чувство равновесия, он сам сможет принять сидячее положение. Если малыш приподнимается и пытается сесть, можете ненадолго позволить ему это. Возможность увидеть, на что он способен, порадует и воодушевит его. Но не забывайте поддерживать его спину. Хотя некоторые малыши начинают садиться уже в этом месяце, важно помнить, что их мышцы спины ещё недостаточно окрепли, чтобы сидеть без поддержки.') WHERE id = '3e15f79b-7870-4c1b-9ff8-0d7695190d48';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вес малыша уже в среднем вдвое превышает вес при рождении, и, если вы кормите его грудью, иногда вам может казаться, что молока недостаточно. Поскольку 4-й и 5-й месяцы — период быстрого физического развития малыша, его потребность в энергии возрастает. Чтобы удовлетворить эту растущую потребность, вы можете задуматься о введении прикорма. Однако помните, что на этом этапе кишечная микрофлора малыша ещё не готова к твёрдой пище. Прикорм дают в очень небольших количествах, чтобы познакомить малыша с твёрдой пищей, а для здорового развития кишечника начинать этот процесс следует после 6-го месяца. Всемирная организация здравоохранения (ВОЗ) рекомендует до достижения полных 6 месяцев кормить малыша исключительно грудным молоком, а при его отсутствии — детской смесью как единственной альтернативой. Введение любого прикорма до 6 месяцев может вызвать у малыша анемию, расстройство пищеварения, колики, проблемы с желудком и кишечником. Поэтому не стоит торопиться с введением прикорма, Anacan.') WHERE id = '63dc3b2b-9b88-4480-8d80-226d9607b848';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Слюнные железы малыша уже работают активнее, поэтому повышенное слюноотделение и вытекание слюны, которую он пока не умеет контролировать, совершенно нормальны. Эти признаки также могут предвещать начало прорезывания зубов: из-за зуда в дёснах малыш может часто тянуть руки в рот. Специалисты советуют не мешать малышу, а, наоборот, дать ему возможность изучать свои руки. Однако не забывайте, что малыш, который пытается тянуть в рот всё, что попадётся ему под руку, может проглотить мелкие предметы. Особенно важно избегать игрушек, которые легко ломаются или распадаются на части, и следить за тем, чтобы все предметы, с которыми он играет, были чистыми и стерильными. Из-за зуда в дёснах малыш хочет всё грызть и, когда вы не видите, может взять в рот опасный предмет. Чтобы предотвратить возможное удушье, внимательно выбирайте игрушки и усильте меры безопасности.') WHERE id = 'ff292524-4cb1-4b4f-9235-43064f330adc';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Малыш уже умеет перекатываться, поворачиваться вокруг себя, лёжа поднимать голову до 45 градусов, а также покачивать головой и телом из стороны в сторону. Эти движения соответствуют нормальному ходу развития. Вы даже можете заметить, что, когда малыш лежит на животе, он совершает движения, словно пытается ползти вперёд. Как и любой ребёнок, малыш с большим интересом осваивает новые навыки и часто повторяет то, чему научился. Но помните, что каждый малыш развивается индивидуально. Если ваш малыш ещё не освоил некоторые из этих навыков, не беспокойтесь. Чтобы правильно поддерживать его развитие, также важно учитывать некоторые нюансы. Один из них — использование ходунков. Хотя малыш, который постоянно хочет двигаться и исследовать окружающий мир, порой может вас утомлять, не стоит прибегать к помощи ходунков. Если принуждать малыша младше 6 месяцев, который ещё не готов сидеть, или помещать его в ходунки, это может помешать развитию мышц, необходимых в дальнейшем для таких важных навыков, как ползание на четвереньках и по-пластунски.') WHERE id = 'ea44cd71-5051-4dfc-bbf3-dac92612f0a6';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вероятно, один из вопросов, который вызывает у вас больше всего сомнений, — как одевать малыша перед ночным сном. Теперь малыш стал гораздо активнее, поэтому он может часто сбрасывать покрывающее его одеяло или плед. Почти все малыши не любят чрезмерное тепло и чувствуют себя некомфортно в жаре. Оптимально поддерживать в комнате, где спит малыш, температуру 22-24 градуса и влажность 40-60%. Готовя его ко сну, можете надеть на него хлопковый спальный мешок, а под него — тонкую хлопковую пижаму по сезону. Чтобы понять, достаточно ли тепло он одет, можно измерить температуру тела в подмышечной впадине. Если температура находится в пределах от 36.2 до 37.2 градуса, значит, малыш не мёрзнет. Если она ниже этих значений, малышу холодно, и вы можете надеть на него ещё один слой одежды.') WHERE id = '3719fbec-0855-4e9e-bd59-1324c629c2ce';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Малыш уже умеет узнавать знакомые лица и проявляет интерес к окружающим. Не удивляйтесь, если он будет улыбаться в ответ, особенно знакомым людям. 😊 На 4-м месяце малыш осваивает множество новых навыков. Они связаны как с физическим, так и с умственным развитием. Благодаря заметно улучшившейся зрительно-моторной координации малыш теперь получает ещё больше удовольствия от общения. Именно поэтому он может минутами с восхищением рассматривать свои руки, тянуть вас за волосы и брать в рот всё, что найдёт. С малышом, который с вашей помощью уже может тянуться к предметам и хватать игрушки, которых касается, можно играть во множество простых игр. Кроме того, игрушки для активных занятий, соответствующие его возрасту, помогут поддержать как физическое, так и умственное развитие. При выборе игрушек рекомендуем отдавать предпочтение тем, которые помогают малышу понимать причинно-следственные связи.') WHERE id = 'aeb00407-e412-4f78-961f-30f7b120bf0d';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если вы решили подстричь малыша дома, следует обратить внимание на несколько важных моментов. Прежде всего, перед началом стрижки убедитесь, что малыш сыт и его ничто не беспокоит, например колики из-за скопления газов. Испытывая дискомфорт, малыш может капризничать и совершать резкие движения, что может привести к травме или неудачной стрижке. Если малыш уже умеет сидеть, вы можете посадить его в удобное место, например в стульчик для кормления, или поддерживать у себя на коленях, чтобы он оставался в устойчивом положении. Для стрижки используйте небольшие ножницы с закруглёнными концами. Дайте малышу любимую игрушку, чтобы отвлечь его, и постоянно разговаривайте с ним во время стрижки — это поможет ему сохранять спокойствие. Подстригая волосы возле ушей, шеи и лба, будьте особенно осторожны. При необходимости попросите помощника неподвижно придерживать голову малыша. Пока стрижка не закончена, не оставляйте малыша одного рядом с ножницами и не отходите от него. Поэтому заранее подготовьте всё необходимое, например полотенце и расчёску.') WHERE id = '4c05c1b9-816f-4b3a-9570-73a5e8523f06';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Наверняка вы помните день, когда впервые взяли малыша на руки, словно это было вчера. Как же быстро летит время, не правда ли? 😊 Ваш малыш достиг 4-го месяца и уже даёт понять, что подрастает. Он хочет, чтобы вы постоянно уделяли ему внимание, и при любой возможности напоминает, как любит играть. Лёжа на животе, малыш приподнимается, опираясь на ладони и локти, может поднять верхнюю часть туловища до уровня груди и удерживать голову под углом 90 градусов. В этот период он начинает гораздо чаще громко смеяться и кричать, чтобы привлечь внимание. Вы даже можете заметить, что малыш уже настойчиво пытается сесть. Хотя некоторые специалисты не рекомендуют сажать детей до 6-го месяца, другие врачи подчёркивают, что каждый малыш развивается индивидуально. Поэтому очень важно наблюдать за малышом и стараться понять, чего он хочет. Если малыш очень стремится сесть, можно ненадолго посадить его с надёжной поддержкой — это может его очень обрадовать. И всё же, поскольку каждый малыш развивается по-своему, лучше проконсультироваться по этому вопросу с врачом. 😊') WHERE id = '2ec8f436-2faa-47d9-bf8d-3c7a85cda289';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Предстоящие недели могут оказаться немного непростыми и для вас, и для малыша. Четвёртый скачок развития, охватывающий 14-19-ю недели, — один из самых продолжительных этапов развития. В преддверии этого скачка многие малыши могут отказываться от груди или молочной смеси. Даже если вам казалось, что режим сна уже наладился, малыш может начать сопротивляться засыпанию. Кроме того, он может стать беспокойным, постоянно проситься на руки и немного утомлять вас. Однако после завершения этого непростого периода для малыша начнётся совершенно новый этап. Он начнёт понимать последовательность событий. Например, увидев какой-либо предмет, малыш может заинтересоваться им, крепко схватить и захотеть изучить. Подержав предмет некоторое время в руке, он может поднести его ко рту, чтобы познакомиться с ним поближе. В конце этого скачка развития вы можете заметить, что малыш узнаёт себя в зеркале и улыбается своему отражению. Теперь малыш понимает, когда насытился, и, получив достаточно молока, может сам отпустить грудь или бутылочку, что помогает свести к минимуму срыгивания.') WHERE id = '57457675-a7c5-476e-b444-66d0b8d0364f';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Во время осмотра на 4-м месяце врач оценивает развитие малыша: измеряет его рост, вес и окружность головы, проверяет зрение, а также мышцы спины и шеи. На этом этапе вес малыша обычно находится в диапазоне 4800-9100 грамм, а рост — 58-69 см. Если показатели близки к нижней или верхней границе этих диапазонов, это не означает, что у малыша есть какие-либо нарушения развития. Окружность головы в этот период составляет 39-45 см. Поскольку этот показатель отражает здоровое развитие мозга, очень важно, чтобы окружность головы находилась в пределах данного диапазона. Зрение малыша уже достаточно сформировано, и теперь он может видеть предметы в их настоящих цветах. Благодаря этому окружающий мир становится ещё интереснее: малыш может меньше времени уделять сну и сосанию и больше интересоваться тем, что происходит вокруг. В то же время 4-й месяц приходится на продолжительный скачок развития, поэтому на фоне всех этих изменений может возникнуть регресс сна. В связи с этим малышу может потребоваться больше вашего внимания, чем обычно. Постарайтесь насладиться временем, проведённым вместе. Весёлого вам времяпрепровождения! 😊') WHERE id = '3e04c60c-ae8b-4665-9ca2-95ef5bdb8192';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Во время осмотра малыша в 4 месяца необходимо ввести вторые дозы двух вакцин, полученных во 2-м месяце, за исключением вакцины против туберкулёза. Это пневмококковая вакцина и пятикомпонентная комбинированная вакцина против дифтерии, коклюша, столбняка, Hib-инфекции и полиомиелита. Если малыш получил первую дозу вакцины против ротавируса во 2-м месяце, в этом месяце необходимо ввести вторую дозу. Если после вакцинации в 4 месяца у малыша появятся повышенная температура и беспокойство, вы можете дать жаропонижающее средство, рекомендованное врачом. Реакция у каждого малыша индивидуальна, но обычно температура может повыситься через 2-4 часа после вакцинации. Иногда она может сохраняться до 2-3 дней. После любой вакцинации в месте инъекции также могут наблюдаться боль, отёк и покраснение. Чтобы уменьшить дискомфорт и неприятные ощущения у малыша, можно приложить к месту инъекции холодный компресс, а в качестве обезболивающего — по рекомендации врача использовать препараты, содержащие парацетамол.') WHERE id = 'ecec54a9-6b16-4860-9c1c-01c24cd2eac2';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш уже находится на этапе активного обучения, и вы можете заметить, что он с интересом реагирует на все новые впечатления. Один из важных навыков, формирующихся на этом этапе развития, — речь. Малыш уже реагирует на ваш голос и любит подражать услышанным звукам. Когда он особенно счастлив, то может тоненько вскрикивать, громко смеяться и произносить звуки вроде «а-гу». Чтобы способствовать развитию речи малыша, рекомендуем почаще разговаривать с ним. 😊 На 4-м месяце малыш очень интересуется окружающим миром, поэтому его внимание может часто переключаться. Например, если во время кормления что-то привлечёт его внимание, он может прервать сосание. По этой же причине время от времени малыш может отказываться от сна. Вам следует запастись терпением, ведь мир для него огромен и в нём ещё так много всего предстоит открыть! 😊') WHERE id = '0479afbe-b14f-457d-b226-70e3d4f9bf7b';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Внешний мир для вашего малыша — бескрайнее пространство для открытий, и вам уже пора отнестись к этому с пониманием. Желание постоянно быть на руках, отказ от сна или кормления грудью, неусидчивость и стремление часто играть совершенно нормальны. При этом физические упражнения и активность очень важны для физиологического развития малыша. Чтобы сделать с ним гимнастику, возьмите его за щиколотки и осторожно сгибайте ножки, двигая их вверх и вниз. Также можно взять малыша за обе ручки, свести их на груди, а затем скрещивать и разводить в стороны. Чтобы во время этих упражнений малыш чувствовал себя комфортнее, не забывайте разговаривать с ним и часто улыбаться. Такие моменты, проведённые вместе, — один из самых естественных и здоровых способов социализации малыша.') WHERE id = '77bdf252-33eb-455c-b59d-8af7012e078c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Многие доношенные малыши уже в три месяца могут проявлять готовность к твёрдой пище. Однако рефлекс «выталкивания языком», препятствующий переходу на твёрдую пищу, обычно начинает угасать с четвёртого месяца. Этот рефлекс, который на самом деле играет важную роль при сосании, заставляет малыша выталкивать языком предлагаемую ему пищу. Начиная с этого месяца пищеварительная система малыша уже способна переваривать некоторые продукты. Однако это лишь постепенный этап развития, который не означает, что малыш полностью готов к твёрдой пище. ВОЗ рекомендует следующее: если малыш здоров, растёт и не теряет вес, до 6-го месяца следует кормить его исключительно грудным молоком. Если до 6-го месяца грудного молока недостаточно и малыш набирает менее 500 граммов в месяц, основой его питания должны стать адаптированные молочные смеси. Даже после того, как малышу исполнится 6 месяцев, основным источником питания всё равно должно оставаться грудное молоко. ВОЗ рекомендует, чтобы у 9-месячного малыша 70% рациона составляло грудное молоко.') WHERE id = '8360a204-f867-4fb6-bb2c-9a237526ca1c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В эти дни ваш малыш может впервые перевернуться. Обычно малыши осваивают это движение примерно на 4-м месяце, переворачиваясь из положения на животе на бок или на спину. Почти все малыши, поняв, что умеют это делать, хотят повторять движение снова и снова — так начинаются бесконечные перевороты. Однако некоторые малыши после первого переворота могут испугаться и некоторое время не решаться повторить попытку. Округлая и упругая форма животика значительно облегчает малышу это движение. Чтобы побуждать его переворачиваться и укреплять мышцы спины, можно предлагать ему упражнения на потягивание. Например, попытка дотянуться до игрушки или другого предмета поможет малышу перевернуться. Однако внимательно следите, чтобы при перевороте он не остался лежать лицом вниз в положении, затрудняющем дыхание, и не находился там, откуда может упасть. Во время таких упражнений ни в коем случае не оставляйте малыша одного.') WHERE id = '74e1e965-f81e-44cc-a407-7883c6451cc2';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В отличие от первых месяцев, вам может показаться, что малыш стал есть меньше. Хотя это может вызывать беспокойство, на самом деле это естественный процесс. Главная причина заключается в том, что малыш уже научился эффективнее сосать грудь. Теперь он может получать больше молока за более короткое время, а значит, быстрее насыщается. Поэтому количество кормлений в течение дня может сократиться до 4-5 раз. Кроме того, скачок роста, который произойдёт в этом месяце, может вызвать пусть и кратковременные, но заметные изменения в питании. Теперь, наблюдая за поведением малыша, вы сможете легко понять, когда он голоден, и соответствующим образом регулировать время кормлений. Например, начиная с 4-го месяца вам уже необязательно будить малыша для кормления грудью. Кроме того, перерыв примерно в 4 часа до следующего кормления поможет малышу получить больше пользы от питательных веществ, содержащихся в грудном молоке.') WHERE id = 'ea6d6e3a-c957-436f-ac9c-f0c52e449526';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш продолжает наблюдать за вами, вашим лицом, мимикой — словом, за каждым мгновением вашего общения с ним. Постоянное наблюдение помогает ему обогащать и расширять свои представления о мире. Каждое новое открытие способствует образованию связей между нервными клетками мозга, благодаря чему малыш начинает гораздо быстрее воспринимать информацию и учиться. Для формирования этих связей достаточно даже того, что погремушка в его руке издаёт звук, он изучает форму игрушек или просто следит за вами глазами. Малыш старается всё внимательнее наблюдать за вашей мимикой, тоном голоса и даже поведением. Это означает, что он уже лучше вас понимает. Поэтому именно с этих месяцев вы можете начать замечать результаты внимания, которое ему уделяете. Каждое мгновение общения и заботы будет ещё больше укреплять связь между вами.') WHERE id = '170aa164-55dd-45ac-8848-491ec6187f44';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Из-за простуды, смены сезонов, гриппа или аллергии у малыша может часто возникать заложенность носа. Она не только затрудняет дыхание, но и может отрицательно влиять на режим кормления и сна. Более того, заложенность носа — одна из основных причин отказа от груди: малышу приходится дышать ртом, поэтому он естественным образом не хочет сосать. Чтобы облегчить это состояние, доставляющее малышу значительный дискомфорт, можно использовать рекомендованные врачом детские назальные спреи, физиологический раствор и увлажнитель воздуха. Физиологический раствор (изотонический раствор хлорида натрия), также известный как солевой раствор и не содержащий дополнительных химических веществ, поможет быстро освободить нос малыша. Если вы впервые стали мамой, поначалу проводить такую процедуру может быть непросто. Если физиологического раствора окажется недостаточно, можно также воспользоваться назальным аспиратором, специально предназначенным для малышей.') WHERE id = '9c8572cd-a48b-4b37-a542-edfc74817a74';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Для физического развития малыша и подготовки к ползанию специалисты рекомендуют специальное упражнение. Эта активность называется tummy time («время на животе») и заключается в том, что малыша выкладывают на живот. Она развивает мышцы спины, которые малыш обычно задействует меньше, а также укрепляет мышцы ног, шеи, плеч и живота. Эти упражнения развивают двигательные навыки и помогают предотвратить возможную деформацию головы малыша — уплощение затылка. Разложив вокруг игрушки, вы можете помочь мозгу малыша создавать разнообразные нейронные связи. Малышу может быстро надоесть лежать на животе, или он может отвлекаться, поэтому оставайтесь рядом и переключайте его внимание. Разговаривайте с ним, рассказывайте стихи, показывайте любимые игрушки и включайте успокаивающую музыку — это значительно облегчит задачу. Приятного времяпрепровождения! 😊') WHERE id = '3d1db687-2705-4040-8e81-a914b3ab0052';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Благодаря миллиардам нервных клеток в головном мозге наиболее благоприятный для обучения период длится с рождения до 48-го месяца жизни малыша. Поэтому качественное и продуманное общение с малышом в этот период даст мощный импульс его развитию. Согласно исследованиям, дети, которые правильно развивались ещё в младенчестве, в школьном возрасте демонстрируют более высокие результаты в учёбе, что положительно влияет на их дальнейшую жизнь. Время, которое вы проводите с малышом с самого рождения, и качественное взаимодействие с ним благотворно влияют на развитие его мозга и эмоциональной сферы. Ваше внимание к малышу и содержательно проведённое вместе время поддерживают развитие его центральной нервной системы. Это укрепляет его ощущение собственного «я», помогает формировать надёжную привязанность к другим людям, повышает уверенность в себе и позволяет чувствовать себя ценным. Так как насчёт того, чтобы немного отложить дела и провести время с малышом? 😊') WHERE id = '4e220ec0-af8b-4430-ab5f-7ff3954ffb65';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если у вас дочь, у вас могут возникнуть вопросы о том, когда лучше проколоть ей уши. Точного возраста для прокалывания ушей у малышей не существует. Хотя это в основном вопрос личного выбора, вы можете посоветоваться с врачом. Поскольку хрящи у малышей ещё очень мягкие, в этом возрасте прокалывание ушей причиняет меньше боли. Однако некоторые всемирно известные педиатрические организации не рекомендуют прокалывать уши в первые месяцы жизни из-за незавершённого курса вакцинации и сложностей последующего ухода. Вместе с тем, если процедура прокалывания ушей и последующий уход проведены правильно, вероятность возникновения проблем со здоровьем у малыша крайне мала. Если вы решите проколоть малышу уши, для профилактики воспаления рекомендуем выбирать серьги из нержавеющей стали или, по возможности, из золота.') WHERE id = '622d780e-3a5e-48fd-b009-10a81d465be2';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Постоянное желание малыша сосать грудь особенно часто встречается в период новорождённости, однако важно помнить, что это может наблюдаться и позднее. По мнению специалистов, грудное вскармливание, которое рекомендуется продолжать до 2 лет, создаёт особую связь между вами и малышом. Поэтому, инстинктивно стремясь быть ближе к вам, малыш может часто просить грудь, предпочитать засыпать во время кормления и не хотеть отпускать грудь в течение дня. Хотя с 4-го месяца проблемы с газообразованием обычно уменьшаются, у некоторых малышей они могут сохраняться до 6-го месяца. При коликах малыш может стремиться успокоиться там, где чувствует себя наиболее защищённым и близким к вам, — у вас на руках и во время кормления грудью. Кроме того, когда малыш начинает больше двигаться, его потребность в энергии возрастает, что также усиливает желание чаще сосать грудь. Физический контакт во время частых кормлений в течение дня укрепляет привязанность малыша к вам. Поэтому, даже если у малыша нет никаких проблем, постоянное желание сосать грудь может означать, что ему требуется больше контакта «кожа к коже».') WHERE id = '15a9163c-c7da-40c2-a76c-38c778e04718';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если на коже малыша появляются высыпания различной формы, это может быть аллергическая экзема. Аллергия — это реакция, возникающая, когда организм малыша воспринимает на самом деле безвредное вещество как чужеродное и опасное. Помните, что причиной аллергии необязательно должна быть пища. Пыль на столе, пыльца, появляющаяся при смене сезонов, и даже сигаретный дым могут вызвать у малыша аллергическую реакцию. Если вы заметили у малыша сыпь, покраснение или вкрапления крови в кале, рекомендуется проконсультироваться с врачом. Ведь продукт или вещество, безопасное для большинства малышей, при отсутствии необходимых мер может вызвать серьёзные проблемы у малыша с аллергией. Аллергия обычно возникает из-за определённых нарушений в работе иммунной системы и может быть наследственной. Поэтому аллергия, которая есть у вас, может проявиться и у малыша.') WHERE id = 'e82d9ae2-ed27-40cb-9366-8cbbd0962327';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Для здорового роста и развития малыша очень важно полноценное питание. Однако иногда он может отказываться от груди или молочной смеси. Если вы кормите грудью, рекомендуем терпеливо и часто предлагать малышу грудь. Причин отказа может быть много, в том числе прорезывание зубов, кризисный период или заложенность носа. В последующие месяцы вы сможете изменять питание в соответствии с потребностями малыша, но сейчас не следует принуждать его, пытаясь установить строгий режим. Если малыш отказывается от кормления, помните, что через некоторое время эта проблема пройдёт и всё наладится. В таких ситуациях не стоит слишком рано вводить прикорм из-за страха, что малыш останется голодным. Начинайте прикорм только после того, как малышу исполнится 180 дней, и обязательно следите за его сигналами, чтобы убедиться, что он к этому готов. Поэтому на протяжении всего процесса проявляйте терпение, старайтесь понимать малыша и отвечать на его потребности.') WHERE id = '63e83115-0a58-4fb8-af8e-8058860fc7f2';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Период от 0 до 12 месяцев, когда малыш находится в младенческом возрасте, чрезвычайно важен для здорового развития мозга. Среда, в которой он растёт в это время, и его общение с окружающими, особенно с вами, закладывают основы формирования его мозга. Поэтому разнообразие и уместность стимулов, с которыми сталкивается малыш, продолжают влиять на его когнитивное, эмоциональное, социальное и физическое развитие. Общение между вами и малышом воспринимается его органами чувств как стимул. Чем больше таких стимулов он получает, тем активнее развивается. Чтобы поддерживать развитие малыша, важно обеспечивать ему достаточно стимулов и постоянно взаимодействовать с ним. Согласно некоторым научным исследованиям, важнейшим фактором развития мозга малыша является человеческий голос. Поэтому сегодня включите спокойную музыку, сделайте малышу массаж и во время него расскажите, как прошёл ваш день, что с вами происходило и как сильно вы его любите. Приятного времяпрепровождения! 😊') WHERE id = 'b51f395b-32bc-4a20-bb23-ec95e7590add';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Одним из наиболее распространённых кожных заболеваний в младенческом и детском возрасте является атопический дерматит — экзема. Спровоцировать это заболевание могут бактерии, моющие средства, смена сезонов и различные аллергены. Чтобы снизить риск его возникновения у малыша, следует принять некоторые меры. В этот период кожа малыша очень чувствительна, поэтому важно оберегать её от контакта с шерстяной одеждой, пылью и песком, мылом, косметическими средствами с сомнительным составом и моющими средствами. Это кожное заболевание может возникнуть и в том случае, если надеть на малыша новую одежду, предварительно не постирав её. Поэтому для чувствительной кожи малыша лучше выбирать одежду из хлопка, а во время купания не растирать кожу, чтобы не вызвать раздражение. Если не принимать профилактических мер и не лечить это заболевание, проявляющееся в младенческом возрасте в виде экземы, в дальнейшем оно может привести к респираторной аллергии, астме и экземе кистей рук.') WHERE id = '31c813fe-83a6-475d-b451-c6545ed0cadd';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вы можете использовать молочную смесь как единственный источник питания малыша или, если грудного молока недостаточно, давать её дополнительно по рекомендации врача. Однако если вы кормите малыша смесью, необходимо учитывать несколько важных моментов. Самое главное — выбрать продукт, состав которого максимально приближен к грудному молоку. В этом вопросе следует прислушаться к совету врача и внимательно изучить состав смесей. Старайтесь не использовать продукцию брендов, о которых вы раньше не слышали или которые не рекомендовал ваш врач, а также обращайте внимание на соблюдение производителем этических норм. На этом этапе вы всё ещё можете пробовать смеси разных марок. Со временем вы обязательно найдёте ту, которая больше всего понравится малышу и не будет вызывать проблем с кишечником. Для развития иммунной системы и поддержания здоровой микрофлоры кишечника убедитесь, что выбранная смесь содержит пробиотики с полезными микроорганизмами, такими как лактобациллы и бифидобактерии. Кроме того, наличие в смеси для малыша жирных кислот LC-PUFA способствует регуляции иммунной системы за счёт усиления выработки цитокинов.') WHERE id = '20390cc9-8cbc-4417-abec-6230f65f2f2f';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Есть одно очень увлекательное и в то же время чрезвычайно важное для развития малыша занятие — смотреться в зеркало! 😊 Хотя представители старшего поколения обычно не советуют показывать малышам их отражение, врачи настоятельно рекомендуют это делать. Когда малыш смотрит в зеркало, он видит и изучает себя, что в значительной степени способствует развитию мозга. Важно правильно выбрать время для первого такого занятия. Если малыш беспокоен или не в настроении, он может испугаться зеркала. Поэтому для этой игры лучше выбрать момент, когда малыш в хорошем настроении и сыт, но не перекормлен. Встаньте вместе перед зеркалом, покажите малышу его глаза, руки, ноги и рот, называя каждую часть тела. Затем по очереди прикасайтесь к ним и повторяйте названия. Уверены, эта игра будет очень интересна вашему малышу. Приятного времяпрепровождения! 😊') WHERE id = 'b0d88192-6e24-4e64-b343-6477a77e7840';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вам кажется, что во время грудного вскармливания малыш неправильно захватывает грудь, кормление длится слишком долго, он часто делает паузы, беспокоится и не набирает ожидаемый вес? Если да, у малыша может быть короткая уздечка языка. Рекомендуем обратиться к врачу для осмотра. Из-за короткой уздечки малыш не может полностью захватить грудь, получает недостаточно питания и вследствие этого может терять вес. Кроме того, поскольку ему трудно выталкивать языком молоко или смесь из бутылочки, могут возникать некоторые нарушения кормления. Уздечка языка — это складка ткани, соединяющая язык с дном полости рта. Чтобы язык мог свободно двигаться, эта ткань должна быть в определённой степени отделена от языка. Иногда, особенно по наследственным причинам, этого не происходит, и движения языка оказываются ограничены. Врачи не всегда проверяют уздечку языка, а самостоятельно заметить проблему бывает непросто. Однако даже если врач малыша поставит диагноз не сразу, это состояние поддаётся лечению.') WHERE id = '2904fd26-1eca-4d37-8e98-2e316a3eec9b';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'До появления первых зубов у малыша осталось совсем немного времени, хотя, возможно, придётся подождать ещё несколько месяцев. Во время прорезывания зубов дёсны малыша могут сильно зудеть, у него может обильно течь слюна, он будет постоянно тянуть руки в рот и пытаться жевать всё, что попадётся. От зуда можно использовать прорезыватель, от боли — гель для дёсен по рекомендации врача, а для защиты одежды от слюны — слюнявчик. Кроме того, этот непростой и для вас, и для малыша период можно облегчить с помощью подручных средств. Как? Используйте чистую салфетку для полости рта! Слегка намочите её, а затем на некоторое время положите в холодильник, чтобы она охладилась. Прохладная и плотная салфетка поможет облегчить боль малыша. Давая её малышу, обязательно следите за ним.') WHERE id = '8cafc042-a915-4258-a3c2-d05a6d6f4956';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Независимо от того, питается ли малыш грудным молоком или смесью, вы можете задуматься: нужна ли его организму вода? Согласно общепринятому мнению, до введения прикорма малышам не нужна дополнительная вода. Причина в том, что если в первые 6 месяцев давать малышу воду в дополнение к основному питанию, его чувство жажды уменьшится. Из-за этого малыш будет получать меньше грудного молока или смеси, что может привести к недостатку энергии и задержке развития. Поэтому регулярно предлагать малышу воду следует с началом введения прикорма. По мере увеличения количества и густоты пищи потребность организма малыша в жидкости будет возрастать. Самый полезный способ восполнить эту потребность — вода. Не забудьте проконсультироваться с врачом о том, сколько воды давать малышу.') WHERE id = '8768c9bb-7bc9-40eb-8d2e-760fead026b4';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Позади 5 насыщенных месяцев вместе... Как же быстро летит время, правда? 😊 Пятый месяц жизни малыша, который развивается день за днём и ежедневно удивляет вас, тоже будет особенным и очень интересным. На этом этапе органы чувств малыша развиты уже почти как у взрослого. Благодаря этому быстро совершенствуются его навыки общения и способность выражать себя. Теперь вам будет гораздо легче понимать чувства малыша. Начиная с 5-го месяца малыш начинает открыто показывать вам свою радость, симпатию и недовольство, беспокойство, любовь и желание получить внимание. Например, увидев вас или свою бутылочку, если он питается смесью, малыш может понять, что пришло время кормления, оживиться и попытаться выразить радость криком. Кроме того, благодаря развитию памяти и чувств он уже может беспокоиться при виде незнакомых людей и относиться к ним настороженнее.') WHERE id = '12aa96ec-7101-441e-a8b6-16b0a453ee5a';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этом месяце малыш стал активнее, чем в первые 4 месяца, поэтому меньшая прибавка в весе считается нормальной. Не стоит ожидать, что он, как в первые месяцы, будет прибавлять по 800-1200 граммов в месяц. Для малыша на 5-м месяце жизни достаточной считается прибавка в 450-750 граммов. За исключением отдельных случаев, такая прибавка указывает на то, что дополнительная поддержка не требуется. Начиная с 5-го месяца вес малыша может составлять 5100-9000 граммов, а рост — 58-70 см. Помните, что показатели роста и веса у мальчиков и девочек немного различаются, а каждый малыш развивается по-своему. Если вам кажется, что вес или рост малыша ниже или выше этих значений, рекомендуем проконсультироваться с врачом. Не забывайте также, что на эти показатели могут влиять срок беременности, на котором родился малыш, а также его рост и вес при рождении.') WHERE id = '57b48e89-533e-4812-870a-767029538ffe';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Теперь малыш прилагает больше усилий, чтобы взять привлёкшие его внимание предметы, находящиеся в поле зрения. Заинтересовавшись каким-либо предметом, он может оживляться, смеяться, пытаться дотянуться до него или хлопать в ладоши. Поскольку зрение и восприятие малыша значительно улучшились, разнообразие цветов и форм, которые он видит, помогает ему устанавливать мысленные связи и лучше понимать окружающий мир. Кроме того, в этом месяце вы заметите, что малыш стал общительнее. Если в предыдущие месяцы вы ещё не слышали его заливистого смеха, велика вероятность, что услышите его в этом месяце. Став более общительным, малыш может смеяться и визжать, когда его щекочут. В моменты радости он может сам издавать весёлые звуки. Ещё один способ рассмешить малыша — ответить смехом на его улыбку. В этом возрасте малыши очень любят смеяться вместе со взрослыми. Его могут развлекать сосание бутылочки, ваш разговор с другим человеком, музыка или любые окружающие звуки. "Агуканье", визг и хихиканье — первые шаги малыша на пути к речи. 😊') WHERE id = '57cd3a11-aa81-4f90-bfb2-f69a0e71ee24';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этот период малыш начинает проявлять больше внимания к происходящему вокруг, различать звуки и реагировать на них. Начиная с этого месяца психологическое состояние малыша требует особого внимания. Когда ему хочется внимания, скучно или он желает установить с вами контакт, он может пытаться привлечь вас внезапными криками или громким плачем. Такие попытки привлечь внимание показывают, что малыш уже способен понимать причинно-следственные связи. Поэтому, когда вы начинаете спокойно разговаривать с малышом и уделять ему внимание, он может внезапно перестать плакать и улыбнуться вам. Это не каприз, поэтому беспокоиться не нужно. Поскольку малыш ещё не умеет полноценно говорить, в ситуациях, вызывающих дискомфорт, он пытается привлечь внимание таким способом и сообщить вам о своей проблеме.') WHERE id = 'c9b55f11-f202-4070-8d6a-fc7359809c90';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'У малышей важно следить не только за ростом и весом, но и за окружностью головы. Измерение окружности головы — стандартная процедура, позволяющая оценить развитие мозга малыша. Начиная с этого месяца окружность головы малыша должна составлять от 39 см до 45 см. Увеличение окружности головы в пределах соответствующих значений — показатель здорового развития мозга. Некоторые проблемы с развитием мозга у малышей часто выявляют именно по отклонению окружности головы от нормы. Однако если окружность головы вашего малыша меньше или больше указанных значений, не стоит сразу тревожиться. Это состояние нельзя связывать с питанием, а приведённые цифры не являются строгой нормой. Как и у любого другого малыша, у вашего малыша свой потенциал роста. У генетически миниатюрных малышей окружность головы может быть меньше средних значений, несмотря на хорошее здоровье, а у крупных малышей она может быть больше из-за особенностей строения костей.') WHERE id = '7475597a-0083-4ac8-af52-e9ec4b5f2395';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Правильное питание очень важно для здорового роста и развития малыша. С самого рождения он должен получать белки, углеводы, жиры, витамины и минералы в сбалансированном количестве, соответствующем его возрасту. Поскольку период от 0 до 12 месяцев — время наиболее интенсивного роста, потребность малыша в энергии особенно высока. В этот период из-за формирования новых тканей и развития мышц возрастает потребность организма в белках, минералах и витаминах. Рост тканей требует непрерывного синтеза белка, поэтому малышу необходимо получать качественный белок. Ваше грудное молоко — прекрасный источник белка для малыша, а усвояемость содержащихся в нём белков может достигать 95%. Поэтому в период грудного вскармливания вам также очень важно придерживаться здорового и сбалансированного рациона, чтобы поддерживать непрерывное развитие малыша.') WHERE id = '896cbb45-0cf7-4486-ad2b-a52c32d44051';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Даже если сейчас малыш не переживает кризисный период, у него могут возникать трудности с засыпанием. Режим сна 5-месячного малыша может немного нарушиться из-за того, что он каждый день осваивает новые двигательные навыки. Желая практиковать их, малыш может отказываться от сна и кормления, а также рано будить вас по утрам. Если, проснувшись, малыш не плачет, а самостоятельно играет и проводит время в своей кроватке, вечером при укладывании можно положить рядом с ним игрушку для сна. Через некоторое время, увидев эту игрушку рядом, малыш начнёт ассоциировать её со сном. Чтобы такая привычка сформировалась правильно, не выносите игрушку для сна из кроватки и кладите её рядом с малышом только тогда, когда приходит время спать. Выбирая игрушку для сна, убедитесь, что она изготовлена из органической пряжи или ткани, не содержит вредных красителей и мелких деталей, которые малыш может проглотить.') WHERE id = '1fa3a9be-2b21-41b0-8e90-923545dc6c0e';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Период прорезывания зубов у малышей обычно начинается с 5-го месяца. Если у вашего малыша зубы ещё не прорезались, в этом месяце он может столкнуться с болезненными ощущениями. Прорезывание зубов — естественный процесс, однако в этот период малыш может быть очень беспокойным. Дискомфорт вызван зудом дёсен и время от времени может сопровождаться болью. Первые зубы у малыша обычно появляются в возрасте от 5 до 9 месяцев. У некоторых малышей первый зуб может прорезаться уже в 3 месяца, а у других этот процесс затягивается до 13-14 месяцев. Если у малыша нет проблем со здоровьем, скорость прорезывания зубов не связана напрямую с его ростом и развитием. Это в большей степени зависит от генетики, и, вероятно, процесс будет проходить примерно так же, как в младенчестве у вас, родителей.') WHERE id = '2b63b86d-359a-4b54-8d2d-d3bc2859ca20';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Волосы малыша очень чувствительные и нежные, поэтому уход за ними должен стать важной частью ежедневной гигиены. Малыш мог родиться с густыми или редкими волосами. Возможно, он даже родился без волос, и они только начали расти. В любом случае волосы и кожа головы малыша требуют особого ухода. Летом малыша можно купать каждый день, а зимой — раз в два или три дня. Чтобы предотвратить аллергию, покраснение или зуд, следует избегать магазинных средств с агрессивными химическими компонентами. Используйте средства, не содержащие парабенов, сульфатов, синтетических ароматизаторов и вредных веществ, способных вызвать раздражение кожи малыша. Если вам трудно найти средства с безопасным составом, можно отдать предпочтение качественному натуральному твёрдому или жидкому кастильскому мылу.') WHERE id = '9f4a8a9d-785a-42f3-bcb2-0880d1571c96';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Переход малыша на прикорм рекомендуется начинать через 180 дней после предполагаемой даты его рождения. Это означает, что конец 6-го месяца — наиболее подходящее время для знакомства с прикормом. В некоторых случаях по рекомендации врача прикорм можно ввести раньше, поскольку к этому времени малыш уже осваивает навык глотания. Тем не менее для здоровья кишечной микрофлоры, если у малыша нет задержки развития, лучше ещё немного подождать. В 5 месяцев продукты прикорма, которые вы даёте малышу, обязательно должны быть жидкими; с пюре пока следует немного повременить. Малышу могут подойти бульоны из натуральных овощных супов и не вызывающие аллергию фруктовые соки. Из-за риска пищевой аллергии продукт, который малыш пробует впервые, рекомендуется дать в очень небольшом количестве — 1 чайную ложку.') WHERE id = '57b7991c-272a-4ed5-898c-f9700be1db2a';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Массаж улучшает кровообращение малыша и способствует правильному развитию его мышц и костей. Он также помогает при газообразовании и спазмах (коликах), успокаивая малыша. Главная цель детского массажа — расслабить малыша с помощью правильной техники, а при регулярном проведении положительно влиять на его рост, умственное и двигательное развитие. Особенно важны для развития малыша простые гимнастические упражнения, которые можно выполнять после 4-го месяца. Делайте массаж каждый день, когда малыш не голоден, спокоен и готов к процедуре. Наиболее подходящее время — через 1-1.5 часа после кормления. Перед началом массажа не забудьте снять украшения с рук, убедитесь, что ногти коротко подстрижены, а руки чистые и тёплые. Во время массажа также поддерживайте комфортную температуру в комнате и никогда не оставляйте малыша одного. Приятного времяпрепровождения! 😊') WHERE id = '98edcdb5-d642-4617-8cc5-e7bd1fc8f734';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Когда малыш лежит на спине, он уже поднимает ножки вверх и с восхищением разглядывает их! Пытаясь исследовать свои ножки, совсем скоро он начнёт хвататься за них. Вот увидите 😊 На этом этапе очень важно выбирать игры, которые стимулируют органы чувств малыша и поддерживают его развитие. Также в этот период будут очень полезны игры, помогающие малышу познакомиться со своим телом. Снимите с малыша носочки и слегка пощекочите ему стопы. Вы увидите, как он улыбнётся вам в ответ. 😊 Щекотка и ваш совместный смех создают механизм социальной привязанности, который укрепляет общение и теплоту между вами и малышом. А заливистый смех малыша в ответ на щекотку будет укреплять вашу эмоциональную связь. Но напоминаем: всё хорошо в меру! :)') WHERE id = '85434c2c-c541-44d1-bc15-24301977fe06';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ночные кормления малыша сейчас так же важны, как и в первые месяцы. Если малыш просыпается по ночам, в зависимости от его потребностей следует кормить его грудью или из бутылочки каждые 3-4 часа. Но если малыш спит и у него нет проблем со здоровьем, мы не рекомендуем будить его только ради кормления. Когда он проголодается, то обязательно даст вам об этом знать. Чтобы в будущем у малыша сформировался здоровый режим сна, возможно, стоит избегать кормления непосредственно перед засыпанием или сразу после пробуждения. Поэтому следует поощрять малыша засыпать самостоятельно и помогать ему в этом. Если малыш привык засыпать во время кормления грудью, дайте ему немного времени и наберитесь терпения. Будьте уверены: совсем скоро всё наладится! :)') WHERE id = '25c161ab-8831-4065-a3ec-22240c22edb0';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Малыш уже в полной мере открыл для себя мир звуков. Он может трясти всё, что попадётся ему в руки, пытаясь извлечь звук, а вы можете помочь ему в этом исследовании. Больше всего малышам нравится издавать звуки с помощью погремушек. В магазинах можно найти погремушки самых разных цветов и форм. Но вы также можете легко сделать игрушку самостоятельно из домашних предметов. Для этого достаточно двух пластиковых стаканчиков. Насыпьте в них сухую крупу или бобовые, которые есть дома (рис, чечевицу и т. п.). Плотно соедините края стаканчиков прозрачной клейкой лентой, чтобы содержимое не высыпалось. Чтобы получать разные звуки, можно использовать крупные и мелкие зёрна. Например, рис будет издавать более тонкий звук, а фасоль — более глухой и низкий.') WHERE id = 'c96c4837-c392-4247-ae1b-3dcef1d0e562';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вам тоже кажется, что в последние дни малыш стал гораздо активнее? В этот период мышцы его рук и ног уже заметно окрепли. Когда малыш учится ползать, переворачиваться и передвигаться, держась за предметы, его мышцы продолжают развиваться. Поскольку теперь он очень подвижен, в целях безопасности необходимо создать для него безопасные границы. Например, не оставляйте его одного на высоте и уберите из зоны доступа острые и режущие предметы. Малыш уже может захватывать заинтересовавшие его предметы большим и другими пальцами, словно щипцами. Чтобы исследовать предмет, он захочет потянуть его в рот. Поэтому рекомендуем не оставлять в доступном месте мелкие игрушки, монеты, бусины и другие предметы, которыми малыш может подавиться.') WHERE id = '5d03d27f-629c-43d8-acc3-6fa2f69ef287';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Малыш очень чувствителен к вашим прикосновениям и телесному контакту с вами. В его коже находятся миллионы мельчайших нервных окончаний, которые при прикосновении передают сигналы головному мозгу и нервной системе. Особенно много таких нервных окончаний в наиболее чувствительных областях тела малыша, например в подмышках, на пятках, животе и шее. Когда вы прикасаетесь к этим участкам, нервные окончания активируются, и мозг вызывает такие реакции, как ощущение щекотки, мурашки и смех. При этом у малыша повышается артериальное давление, учащается сердцебиение, а мозг начинает работать активнее. Например, щекотать малыша не только весело — это также помогает ему лучше воспринимать прикосновения. Помните, что смех — это первый шаг в развитии чувства юмора у малыша. 😊') WHERE id = '541bc5b2-12fd-4d41-9d69-7d5b93ee3f92';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этом возрасте малыш обычно любит находиться в сидячем положении. Даже если он пока не пытается сесть, это лишь вопрос времени! 😊 Сидя, малыш опирается на руки, чтобы сохранять равновесие и поддерживать себя. Поскольку мышцы спины ещё не полностью развиты, он может немного сутулиться. Некоторые врачи не рекомендуют начинать упражнения для освоения сидения до 6 месяцев. При этом другие специалисты могут придерживаться более гибкого подхода, учитывая желание малыша и особенности его развития. Тем не менее ради безопасности малыша лучше ненадолго усаживать его у себя на коленях. Хотя малыш с каждым днём становится сильнее, попытки сажать его без поддержки пока могут привести к нежелательным последствиям. Самую точную информацию о развитии малыша даст ваш врач. Поэтому по таким вопросам, как освоение сидения, прикорм и витамины, следует принимать решения после консультации с врачом. 😊') WHERE id = '3d5e88a5-68ba-47fd-b5a0-88c276587011';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Чтобы облегчить малышам период прорезывания зубов, часто используют гели для дёсен. Однако существует множество эффективных способов уменьшить симптомы прорезывания зубов, не прибегая к обезболивающим средствам и гелям. Прорезыватели станут полезными помощниками, которые наверняка понравятся малышу. Не забывайте, что они действуют эффективнее, если предварительно охладить их в холодильнике. 😊 Соприкасаясь с дёснами, такие прорезыватели оказывают массажный и охлаждающий эффект, благодаря чему могут облегчить боль у малыша. Также можно положить влажную или сухую салфетку для ухода за полостью рта малыша в холодильник на полчаса, а затем дать ему её пожевать. Прикосновение холодного предмета к дёснам может уменьшить боль, отёк и ощущение давления. Однако при использовании обоих способов важно учитывать риск заражения малыша микробами, поэтому рекомендуем тщательно стерилизовать все предметы. 😊') WHERE id = '61a39689-4f67-40ed-b7d3-3829e2076603';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этом месяце малыш спит в среднем 15 часов в сутки. Обычно 10 часов приходится на ночной сон, а 5 часов — на дневной. Однако по некоторым причинам малыш может спать меньше, испытывать трудности с засыпанием или часто просыпаться во время сна. Купание малыша перед сном — один из лучших ритуалов, помогающих ему легче уснуть. Кроме того, в вечерний ритуал можно включить расслабляющий массаж, чтение сказки или совместное рассматривание картинок в красочной книге. Приглушённый свет в комнате во время подготовки ко сну значительно облегчает засыпание малыша. В норме малыш может просыпаться ночью для кормления, если проголодается. Ночные кормления всё ещё очень важны для его развития. Поэтому не стоит беспокоиться: помните, что малыш пока находится в периоде быстрого роста.') WHERE id = '388b1d4a-2870-47fb-8a38-2987cb7bbaf9';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Игры и время, которое малыш проводит за ними, — это не только очень весёлое занятие, но и чрезвычайно важный процесс для его развития. Поэтому не следует воспринимать игру лишь как способ весело провести время вместе с малышом. Время, проведённое за играми, — это бесценный период обучения и познания. Кроме того, поскольку органы чувств малыша уже достаточно хорошо развиты, благодаря игре он правильно расходует энергию и знакомится с окружающим миром. Ещё одна важная функция игры — помогать малышу изучать предметы и понятия, а также сходства и различия между предметами. Таким образом, играя, малыш одновременно учится и осваивает определённые навыки. Соответствующее возрасту восприятие цветов, форм, названий и размеров в будущем поможет ему изучать взаимоотношения и социальные роли, осваивать подражание и развивать свою личность.') WHERE id = '64ce3005-26f0-4a9c-b4db-77907d346329';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Наблюдаются ли у малыша небольшое повышение температуры, желание тянуть в рот и жевать всё, что попадается под руку, потирание уха, снижение аппетита и обильное слюноотделение? Если да, поздравляем! Скоро у него появится пара жемчужных зубиков. 😊 Это признаки прорезывания зубов, и с наступлением 5-го месяца первые зубки малыша могут появиться в любой момент. Ещё до появления первых зубов болезненные, покрасневшие и опухшие дёсны могут причинять малышу дискомфорт. Эти симптомы возникают примерно за 3-7 дней до прорезывания, когда готовящийся появиться зуб начинает проходить сквозь десну. Хорошая новость заключается в том, что, как только зуб впервые покажется над поверхностью десны, эти неприятные симптомы быстро проходят. Важно помнить: если вы не уверены, что замеченные у малыша симптомы связаны с прорезыванием зубов, обязательно проконсультируйтесь с врачом.') WHERE id = 'd5ac321f-14e0-45ad-ab92-652807702fa6';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Хотя малыш быстро развивается, полезные микроорганизмы, защищающие его организм от вредных воздействий, то есть микрофлора кожи, ещё не сформировались полностью. Уровень pH его кожи по-прежнему остаётся высоким, а защитный кератиновый слой, покрывающий кожу, развит ещё не до конца. Из-за низкой кислотности и ещё не полностью сформированного защитного барьера кожа малыша более чувствительна к микробам и химическим веществам. Поэтому необходимо уделять особое внимание температуре стирки одежды, соприкасающейся с кожей малыша, а также выбору моющего средства и кондиционера. Например, чтобы избежать покраснения и зуда на чувствительной коже малыша, важно отдавать предпочтение средствам для стирки с натуральным составом. Также следует отказаться от кондиционеров для белья, поскольку они содержат множество химических веществ, включая ароматизаторы. Чтобы полностью удалить микробы с одежды малыша, не забывайте обязательно гладить её после стирки.') WHERE id = 'd86eb88e-f066-48c6-be2d-d43e207dbd2c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если у вас сын, вероятно, у вас есть вопросы о том, когда следует сделать ему обрезание. Обрезание — одна из древнейших операций, проводимых во всём мире. Во время этой процедуры удаляют крайнюю плоть — кожную складку, закрывающую головку полового члена и наружное отверстие мочеиспускательного канала. Согласно статистике, каждый третий мужчина в мире обрезан. Очень важно, когда, как и кем проводится обрезание. Вопрос об этой процедуре возникает уже с момента рождения малыша, однако существуют разные мнения относительно идеального возраста для её проведения. Хотя убедительных научных данных о наиболее подходящем возрасте нет, некоторые специалисты рекомендуют проводить обрезание в раннем возрасте, в частности чтобы избежать психологической травмы.') WHERE id = '05f311d5-ad4e-4d35-963b-6bea5a4bcff4';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Возможно, вы опасаетесь прикасаться к области родничка на голове малыша. Всего на голове находится 6 родничков, и поскольку эти участки не такие твёрдые, как остальные части черепа, мамы часто боятся к ним прикасаться. Однако родничок состоит из прочной соединительной ткани и надёжно защищает мозг малыша. Поэтому при купании малыша, расчёсывании его волос или поддерживании головы нет причин волноваться и избегать прикосновений к этой области. Родничок не только важен для безопасности малыша, но и выполняет роль защитного шлема при травмах черепа. Обычно родничок закрывается самостоятельно в возрасте от 9 до 18 месяцев и не требует вмешательства. Этот процесс может продлиться до 24 месяцев или завершиться раньше. Как правило, такие случаи не являются проблемой, однако для уверенности будет полезно проконсультироваться с врачом.') WHERE id = '8c311ff4-c1cb-4399-88d9-4dbb31f984b6';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Благодаря формированию связей между клетками головного мозга восприятие малыша значительно улучшилось. Теперь он приобретает новые навыки. И самое интересное — малыш уже понимает, когда вы произносите его имя и обращаетесь к нему! 😊 Если с самого рождения называть малыша по имени, его мозг запоминает эти звуки. Часто слыша одно и то же сочетание звуков, малыш со временем начинает узнавать своё имя. Ещё одно достижение в развитии — теперь он может отличать членов семьи от незнакомых людей. Поэтому при виде незнакомца малыш может насторожиться, поджать губы и заплакать, пытаясь понять происходящее. Он даже может устроить настоящий переполох. Будьте готовы — мы вас предупредили! 😊') WHERE id = '2af2018e-44d1-408e-a2eb-5673d76e91c6';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Мы знаем, что сейчас вам бывает трудно уложить малыша спать. В период новорождённости для хорошего сна было достаточно накормить малыша и вовремя сменить ему подгузник. Но теперь малыш лучше воспринимает окружающий мир, а его чувства активно развиваются, поэтому подготовить его ко сну может быть немного сложнее. Одного лишь удовлетворения физических потребностей уже недостаточно, чтобы он заснул самостоятельно. Когда вы готовите ко сну малыша, мозг которого очень активно работает, постарайтесь оградить его от любого шума. Звук телевизора или разговоры могут мешать ему заснуть. Чтобы малыш мог спокойно погрузиться в сон, необходимо устранить эти раздражители. Кроме того, слишком высокая или слишком низкая температура в комнате может замедлить засыпание и ухудшить качество сна. Идеальная температура в комнате, где спит малыш, составляет 22-24°C. Сладких снов! 😊') WHERE id = '1a8c9918-d018-4b4c-8f7f-c8a0898c2b43';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этом месяце есть много занятий, которыми вы можете заниматься вместе с малышом с учётом его уровня развития. Желаем вам весело провести время! 😊 Прежде всего, как насчёт игр с зеркалом для малыша, который проявляет к нему большой интерес? Возьмите зеркало и, стоя перед ним, поочерёдно вкладывайте игрушечный мячик в каждую руку малыша. Так через некоторое время он научится перекладывать игрушку из одной руки в другую. Для другого занятия возьмите яркий мячик, который привлечёт внимание малыша, и подбрасывайте его вверх-вниз над полом. Малыш быстро научится следить глазами за заинтересовавшим его мячиком. Затем покатите мячик к стене так, чтобы он ударился о неё и вернулся обратно. Наблюдая за тем, как мячик отскакивает от стены, малыш будет познавать окружающий мир.') WHERE id = 'd9644453-95a5-4346-bbea-e0599b06e143';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Сейчас, когда вы уже приближаетесь к периоду введения прикорма, один из важнейших вопросов, на который следует обратить внимание, — получает ли малыш достаточное количество пребиотиков. Пребиотики поддерживают иммунную систему малыша, повышают сопротивляемость организма заболеваниям и благотворно влияют на пищеварение. Кроме того, пребиотики, поступающие с прикормом, дополняют полезные свойства грудного молока — самого богатого источника пребиотиков. Одним из основных продуктов, богатых пребиотиками и пробиотиками, является йогурт. Йогурт — это белый кисломолочный продукт густой консистенции, который получают путём сквашивания молока. Он образуется в результате частичного превращения молочного сахара — лактозы — в молочную кислоту под действием йогуртовой закваски, из-за чего молоко свёртывается. Благодаря высокому содержанию кальция, белка, витаминов B12 и B6 йогурт наряду с грудным молоком является одним из важнейших продуктов, способствующих укреплению защитных сил организма малыша.') WHERE id = '67e55468-7559-4a60-ab60-67f55f552e34';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'При стирке одежды малыша важно учитывать несколько моментов. Самый важный из них — свойства и правильный выбор средств для стирки. Если учесть, что некоторые имеющиеся в продаже стиральные средства и виды мыла могут вызывать аллергию даже у взрослых, то для чувствительной кожи малыша этот риск ещё выше. Специалисты особо подчёркивают, что воздействие некоторых химических веществ в младенческом возрасте может вызвать аллергическую реакцию даже спустя годы. Поэтому при стирке одежды малыша следует избегать кондиционеров для белья, отбеливателей и ароматизированных средств, раздражающих кожу. В продаже представлено множество стиральных средств и гранулированного мыла, специально предназначенных для малышей. Отдавая предпочтение средствам без запаха, вы сможете снизить риск возможного раздражения кожи.') WHERE id = 'abaadbfc-c35e-4cb0-b8bc-31d98a9f8ecf';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Дневной сон очень важен для вашего малыша, и на этом этапе он должен спать днём в общей сложности 4-5 часов. Исследования показывают, что малыши, которые достаточно спят днём в соответствии со своим возрастом, могут гораздо дольше спать ночью. По мнению специалистов, особенно полезны первые два дневных сна. Они лучше всего помогают малышу восстановить силы и способствуют восстановлению организма. Кроме того, малышам легче заснуть во время первого дневного сна, чем во время последующих. Поэтому важно не упустить благоприятное для сна время в первой половине дня и помочь малышу заснуть, как только он начнёт подавать признаки усталости. Однако помните, что чрезмерно продолжительный дневной сон может негативно повлиять на ночной сон малыша.') WHERE id = '59732708-2d13-4639-9614-435d122c79cb';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, '6-й месяц — один из важнейших поворотных моментов в жизни малыша. Ваш малыш уже начинает осознавать себя как отдельную личность и учится тонкостям общения с окружающими. Так он впервые получает представление о собственной индивидуальности. Это очень важный этап умственного развития. 😊 Хотя малыш активно использует органы чувств, теперь он также начинает делать собственные выводы на основе накопленного опыта. Например, он уже может выбрать среди игрушек свою любимую и дать вам понять, какая именно ему нравится. Кроме того, хотя малыш уже некоторое время хорошо видит, начиная с этого месяца он способен воспринимать даже довольно сложные изображения. Благодаря этому он сможет уверенно различать новые формы и текстуры.') WHERE id = 'b6d7faf8-f7c6-4e9e-a7ff-43facd4aa9db';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этом месяце вас и малыша ждут новые впечатления и перемены. Чтобы защитить малыша от заболеваний, очень важно с рождения своевременно делать все необходимые прививки. Во время вакцинации в организм малыша вводят ослабленную форму бактерии или вируса, вызывающего заболевание, от которого необходимо сформировать защиту. Этот процесс направлен на выработку иммунитета, и организм малыша начинает производить антитела против соответствующего заболевания. Благодаря этому, если в будущем малыш столкнётся с этими возбудителями, его организм уже будет обладать эффективным механизмом защиты. В календарь вакцинации на 6-м месяце входят третья доза вакцины против гепатита B, третья доза пятикомпонентной комбинированной вакцины и первая доза ОПВ — оральной полиомиелитной вакцины. Также в календарь включена первая вакцинация малыша против полиомиелита. Таким образом завершается календарь вакцинации малыша за первые 6 месяцев.') WHERE id = '95f9ad1b-63d6-45ba-b708-bf282b104620';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Хотя прививки иногда могут вызывать беспокойство, рвоту, повышение температуры или плач, они необходимы, чтобы защитить малыша от серьёзных заболеваний, о которых мы расскажем ниже. Полиомиелит вызывается полиовирусом. Этот вирус поражает нервную систему и может привести к необратимому параличу и даже смерти. Заболевание встречается в любом возрасте, но особенно подвержены риску дети младше 3 лет, иммунитет которых ещё не полностью сформирован. К счастью, благодаря строгому контролю со стороны органов здравоохранения и кампаниям по вакцинации распространение этого заболевания удалось в значительной степени предотвратить. Дифтерия — серьёзное заболевание, которое поражает дыхательные пути, пищеварительную систему и сердце и может привести к смерти. Столбняк — опасное заболевание, которое может развиться при травмах, полученных от ржавого металла, загрязнённой почвы или колющих предметов, и непосредственно поражает нервную систему. Менингит не только связан с высоким риском смерти, но и может привести к таким тяжёлым последствиям, как инвалидность, задержка умственного развития, глухота и слепота. Поэтому вакцинация — самая надёжная защита здорового будущего вашего малыша.') WHERE id = '2ec370c7-9d55-4f76-86f5-a1d0c2080600';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш, который каждый день удивляет вас новыми движениями, благодаря укрепляющимся мышцам спины уже готовится сидеть без поддержки. Если вы видите, что он готов сидеть, и уверены в этом, можете немного ему помочь. Сначала посадите его к себе на колени, возьмите за руки и следите, чтобы он держал голову прямо. Затем можно посадить малыша на диван и разложить вокруг него подушки, чтобы помочь ему сохранять равновесие. Если во время этих упражнений малыш устанет и завалится набок, не беспокойтесь. По мере укрепления мышц и развития чувства равновесия он сможет сидеть всё дольше. Через некоторое время вы увидите, что малыш уже самостоятельно удерживает равновесие и сидит без поддержки. И тогда подушки ему больше не понадобятся! 😊') WHERE id = '4613232a-c667-47df-9951-c91586b62ee3';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, '6-й месяц — наполненный новыми событиями и сюрпризами поворотный этап как для вас, так и для малыша. Мы знаем, как вы рады тому, что скоро познакомите малыша с прикормом! ВОЗ и медицинские специалисты отмечают, что после достижения возраста 180 дней пищеварительная система малыша готова к введению прикорма. В течение первых 6 месяцев вы кормили малыша только грудным молоком или детской смесью. Теперь его организм познакомится с продуктами разного состава, поэтому возможны некоторые аллергические реакции. По этой причине рекомендуем вводить прикорм постепенно и не торопиться, чтобы не перегружать пищеварительную систему. Наш раздел «Рецепты» очень поможет вам в этом вкусном приключении. Приятного аппетита! 😊') WHERE id = '1057a1b2-3687-4581-b2fe-6f0fca8b4778';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Наступил очень интересный для вас и вашего малыша период введения прикорма! Но всё ли готово? Самый важный признак готовности малыша к прикорму — это, конечно же, умение сидеть. Поэтому вам понадобится хороший стульчик для кормления. Не стоит считать его просто предметом мебели: для малыша это не только место для приёма пищи. Есть много важных причин приучать малыша есть именно в стульчике для кормления. Прежде всего, такой стульчик позволяет ему сидеть за одним столом вместе с вами. Совместные семейные трапезы помогают вам больше общаться с малышом и укрепляют вашу связь. Выбирая стульчик для кормления, обязательно обратите внимание на его безопасность, удобство, небольшой вес и качество материалов.') WHERE id = 'f8f5f75d-b030-4498-b7d5-7b4bc417016c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Начиная с этого месяца общая продолжительность сна малыша составляет около 13 часов в сутки. Ожидается, что днём он будет спать два раза, а ночью сможет непрерывно спать 6-7 часов. По мере взросления потребность малыша во сне будет немного уменьшаться. Это связано с тем, что гормоны, обеспечивающие рост, выделяются именно во время ночного сна. На этом этапе также ожидается, что малыш начнёт привыкать засыпать самостоятельно. Если вы всё ещё укладываете его, укачивая, кормя грудью или нося на руках, рекомендуем постепенно сократить эти способы и в ближайшее время отказаться от них. Некоторые специалисты советуют не вмешиваться каждый раз, когда малыш плачет, чтобы у него сформировался здоровый режим ночного сна. Поэтому, если вы уверены, что малыш сыт, у него чистый подгузник и его ничто не беспокоит, не следует сразу же реагировать на каждый плач. Если брать малыша на руки всякий раз, когда он плачет, ему будет трудно научиться засыпать самостоятельно.') WHERE id = '790745e1-b64b-4611-b8ea-ced2bd5bd141';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Теперь, когда ваш малыш может сидеть более прямо, поле его зрения расширяется, и он активнее взаимодействует с окружающим миром. Это также способствует развитию сенсорных и двигательных навыков. По мере развития у малыша растёт интерес ко всему, что даёт возможность играть и исследовать. Например, благодаря развивающейся мелкой моторике он уже может захватывать небольшие предметы пальцами, в том числе большим пальцем. Кроме того, малыш может перекладывать предметы из одной руки в другую. Он способен тянуться к игрушкам, которые находятся не рядом, но в поле его зрения, и пытаться взять их. Если малыш не может самостоятельно поднять игрушку, которую уронил или выпустил из рук, он может жестом попросить вас подать её. Однако некоторые из этих навыков у вашего малыша могут пока отсутствовать. Это связано с тем, что каждый малыш развивается в своём темпе, поэтому беспокоиться не стоит.') WHERE id = '6730fee9-c4d4-4db1-af73-50d999349b75';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В течение этого месяца по рекомендации врача вам необходимо начать давать малышу препарат железа, назначенный врачом или полученный в поликлинике. Дефицит железа — наиболее распространённый во всём мире вид недостаточности питательных веществ и особенно важная проблема здравоохранения в развивающихся странах. Помимо анемии, одним из наиболее серьёзных последствий дефицита железа является его негативное влияние на интеллектуальное развитие малышей. Дефицит железа в младенческом возрасте, когда мозг быстро растёт и формируются основные психомоторные навыки, может замедлить интеллектуальное развитие. Согласно исследованиям, уровень IQ может необратимо снизиться примерно на 5 баллов по сравнению с ожидаемым уровнем. Поэтому ВОЗ рекомендует давать препараты железа малышам в возрасте 6-12 месяцев. Американская академия педиатрии также рекомендует в возрасте 9-12 месяцев однократно сдать анализ крови для проверки уровня железа у малыша.') WHERE id = 'da861e51-ae52-40b6-a6f0-c4e0e3afd9bf';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'При переходе на прикорм у малышей, особенно получавших легко усваиваемое грудное молоко или молочную смесь, нередко возникает запор. Если вы подозреваете у малыша запор, рекомендуем внимательно ознакомиться со следующими моментами. Прежде всего, пищеварительная система у каждого малыша развивается с разной скоростью. Даже если вы начали вводить прикорм после того, как малышу исполнилось 6 месяцев, у него может возникнуть запор. В таком случае можно на некоторое время прекратить прикорм, а затем попробовать снова. В этот период вы можете давать малышу жидкие супы или фруктовые соки. В начале введения прикорма следует с осторожностью предлагать продукты, способные вызвать запор, например бананы и картофель. Если вы заметили, что после них у малыша возник запор, на некоторое время исключите эти продукты. Кроме того, если у малыша запор и ему трудно опорожнить кишечник, причиной может быть трещина заднего прохода. В таких случаях важно обратиться к врачу.') WHERE id = '9037133c-00b1-4728-bfa8-d12451129dad';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Формирование кишечной микрофлоры малыша, также называемой микробиотой, близится к завершению. Чтобы поддерживать её баланс, следует учитывать несколько моментов. Если малыш родился путём кесарева сечения, бактерии, помогающие пищеварению, начинают заселять его кишечник с 8-го дня жизни, а после естественных родов — с 4-го дня. Среди микроорганизмов кишечной микрофлоры есть как полезные, так и потенциально вредные бактерии. Наличие обоих видов создаёт баланс в пищеварительной системе, не позволяя им чрезмерно размножаться. Для поддержки кишечной микрофлоры малыша можно использовать пробиотики и пребиотики. Эти добавки также стимулируют выработку серотонина, известного как гормон счастья. Вы можете включить в рацион малыша продукты, содержащие полезные бактерии, или проконсультироваться с врачом по поводу пробиотиков, которые продаются в пакетиках.') WHERE id = '9e82ffd7-d409-49b6-a002-4b2672efef01';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вакцины, включённые в календарь прививок малыша, искусственно формируют иммунитет в его организме. Для этого в организм малыша вводят микроорганизмы, вызывающие заболевание, чтобы иммунная система распознала их и активировалась. Поэтому при первом попадании микробов в организм малыш может почувствовать лёгкое недомогание, но одновременно у него формируется иммунитет к соответствующему заболеванию. Благодаря клеткам памяти при повторной встрече с тем же возбудителем иммунная система быстро его распознаёт. При вакцинации в организм малыша вводят ослабленные или убитые микроорганизмы. Таким образом иммунная система знакомится с ними, и в будущем, при встрече с настоящим возбудителем, организм будет готов активно защищаться. Хотя вакцины не защищают малыша от заболеваний на 100%, благодаря уже выработанным антителам он переносит их гораздо легче.') WHERE id = '6a597987-e8b8-4f14-a6ec-55936a1409ea';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В возрасте 6 месяцев ваш малыш может спать около 11 часов в сутки. Такая средняя продолжительность сна не означает, что малыш будет спать только ночью: дневной сон по-прежнему очень важен для него. По данным Американской академии педиатрии, именно с этого месяца наступает подходящее время для перехода малыша в отдельную комнату и самостоятельного сна. Это связано с тем, что после введения прикорма его зависимость от грудного молока становится несколько меньше, чем в первые месяцы. Однако слишком резкий переход может вызвать у малыша психологический дискомфорт. В частности, малыш может пугаться и плакать, просыпаясь ночью. Чтобы помочь ему привыкнуть к новой обстановке, дайте ему время и организуйте этот процесс постепенно и терпеливо.') WHERE id = '68a677bc-c6fd-496b-bd7c-d65d75f316ae';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Самым важным источником питания для малыша по-прежнему остаётся ваше грудное молоко или молочная смесь. В период введения прикорма ни в коем случае не следует пренебрегать грудным вскармливанием или сокращать его. С 6-го по 8-й месяц, если врач не рекомендовал иное, прикорм предлагают лишь для знакомства со вкусами и постепенного перехода к новой пище; основным питанием в этот период остаётся грудное молоко. При введении прикорма также следует обращать внимание на некоторые признаки развития малыша. Например, ожидается, что к этому времени он уже сможет уверенно держать голову, сидеть, а координация движений рук и глаз станет лучше. Впервые знакомясь с новыми вкусами, малыш может выталкивать пищу языком или отказываться от еды. Это совершенно нормально и связано с рефлексом, который со временем исчезнет. Постепенно малыш научится открывать рот, глотать и жевать. Поэтому в переходный период не следует заставлять его есть и важно помнить, что прикорм лишь дополняет грудное молоко.') WHERE id = '28ae02f7-da1a-49dd-85b2-b82676a86611';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'На этом этапе ваш малыш очень быстро развивается физически, а также в области восприятия и речи. Вероятно, каждое новое движение и навык, которые он осваивает, очень радуют и вас. В отличие от взрослых, малыши способны освоить важные навыки развития за очень короткое время. Например, ещё вчера малыш не мог сидеть без поддержки, а сегодня вы уже можете увидеть, как он сидит самостоятельно! 😊 При этом ваш малыш мог освоить одни навыки, ожидаемые в возрасте 6 месяцев, но ещё не овладеть другими. Это не должно вызывать беспокойства, ведь каждый малыш развивается в своём темпе. Если вам кажется, что малыш пока не умеет сидеть без поддержки или ещё не может уверенно сохранять равновесие, наберитесь терпения: совсем скоро вы увидите, как он освоит эти навыки! 😊') WHERE id = '6188303f-604c-4619-8980-cdb921290253';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Чтобы в период введения прикорма у малыша не возник запор, можно принять некоторые меры. Прежде всего проконсультируйтесь с врачом, чтобы выяснить, не связан ли запор с особенностями развития или проблемами со здоровьем. Кроме того, тёплая ванна и массаж живота помогут активизировать работу кишечника. По рекомендации врача можно добавить в меню продукты, помогающие при запоре: курагу (сушёный абрикос), чернослив, тёмно-зелёные листовые овощи и грушу. Также полезно замочить сухофрукты в тёплой воде и в течение дня понемногу давать малышу эту воду. Весь этот период следует часто кормить малыша грудью, а если вы не кормите грудью — не уменьшать объём молочной смеси и следить за достаточным потреблением жидкости. Не рекомендуется стимулировать область ануса, чтобы помочь малышу опорожнить кишечник, поскольку это может войти в привычку. От подобных манипуляций следует воздержаться.') WHERE id = 'e2db0876-de2c-4046-9525-ff64acf7b248';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В 6 месяцев ваш малыш уже может сидеть с поддержкой или без неё, переворачиваться и даже недолго стоять на ножках. Поскольку эти навыки у каждого малыша развиваются в разное время, при необходимости вы можете помочь ему с помощью некоторых занятий. Положите малыша на спину на пол или кровать и, оставаясь рядом, помогите ему перевернуться. Обнимите малыша, который тянется к вам, и похвалите его за успех. Если он не двигается, для поощрения можно перевернуть его на живот, а затем снова на спину. Кроме того, игры с руками развивают осязание и помогают малышу учиться развлекать себя самостоятельно. Посадите малыша напротив себя, поднесите пальцы к уровню его глаз, показывайте их по очереди и считайте по одному. Весёлых игр! 😊') WHERE id = '8d36fd03-563f-4c3d-92c7-c802cd459f32';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В период введения прикорма вы можете предложить малышу пюре и соки из таких фруктов, как яблоко, персик и груша, а также из таких овощей, как картофель, морковь и тыква. Кроме того, по рекомендации врача в домашний йогурт можно добавлять пробиотики в порошке, приобретённые в аптеке. В первую очередь следует избегать коровьего молока, а также продуктов с сахаром и солью. В раннем возрасте коровье молоко может стать причиной скрытых кишечных кровотечений. Кроме того, из-за недостаточного содержания железа и риска аллергии на содержащиеся в нём чужеродные белки его не следует давать до 1 года. Не забывайте, что готовым продуктам промышленного производства не место в меню малыша. Чтобы сделать пищу малыша слаще, вместо сахарного песка лучше использовать пекмез или фрукты.') WHERE id = 'bdbf69c9-7362-46c7-9230-c6195ba35de7';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Исследования показывают, что малыши лучше развиваются в среде с умеренным количеством стимулов. Поэтому знакомство малыша с разными текстурами, формами и звуками способствует поступлению в его мозг новой информации. Такие занятия для сенсорного восприятия очень важны для умственного развития вашего 6-месячного малыша. В этот период игра в «ку-ку», рифмованные колыбельные и пальчиковые куклы не только развлекут малыша, но и поддержат его развитие. Предлагайте малышу новые предметы, позволяйте самостоятельно исследовать их и давайте достаточно времени, чтобы познакомиться с их свойствами. Например, это могут быть стеклянный стакан и ложка. Дайте малышу по одному предмету в каждую руку, позвольте рассмотреть их и помогите понять, как с их помощью можно издавать звуки. Мы уверены, что это занятие очень развеселит малыша. Приятной игры! 😊') WHERE id = 'e926ea15-a8f6-4559-a5e9-18bd81abc58e';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Изучая информацию о введении прикорма, вы, возможно, встречали «правило трёх дней». Оно очень важно для выявления возможной аллергической реакции на продукты в начале введения прикорма. Благодаря этому, если у малыша возникнет аллергия, вы сможете легко понять, какой именно продукт её вызвал. Следуя этому правилу, вы можете наблюдать за малышом в течение 3 дней и определить, не оказал ли предложенный продукт какого-либо нежелательного воздействия. Кроме того, поскольку вы будете давать только один продукт, вам будет легче понять, понравился он малышу или нет. Аллергическая реакция после введения прикорма может проявляться покраснением кожи и сыпью. Возможными признаками аллергии также являются колики и связанный с ними плач, рвота, диарея, беспокойство и боль в животе.') WHERE id = 'e67b6585-697c-442b-94c4-f4bcc520b28d';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш уже не любит оставаться неподвижным. Поэтому совершенно нормально, что он постоянно двигается! 😊 В этот период ручки и ножки продолжают привлекать внимание малыша. Он может поочерёдно рассматривать свои ладошки и пальчики и с удовольствием узнавать, что можно с ними делать. Поднимать ножки вверх и пытаться схватить их руками — одно из его любимых занятий. Чтобы сделать эту игру ещё веселее, можно купить малышу яркие носочки, издающие звуки. Он будет пытаться дотянуться до забавных носочков на своих ножках и сможет самостоятельно развлекаться, играя с ними. Не забывайте также одевать любящего двигаться малыша в просторную и удобную одежду! 😊') WHERE id = '6e15d298-df96-4ac7-b6a2-ef5c565ec39c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Проведённые в последние годы подробные исследования здоровья кишечника показали важность пробиотиков. Кишечник уже называют вторым мозгом, и, поскольку он влияет на весь организм, его здоровье имеет большое значение для нормального развития малыша. Пробиотики поддерживают баланс кишечной микрофлоры и препятствуют размножению вредных микроорганизмов. Кроме того, наряду с грудным молоком пробиотики способствуют формированию иммунной системы и поддержанию внутреннего равновесия организма малыша, называемого гомеостазом. Пробиотики улучшают усвоение некоторых минералов и витаминов, регулируют уровень липидов и нормализуют проницаемость кишечника. Чтобы получить такую пользу, рекомендуется регулярно употреблять пробиотические продукты в соответствующем количестве. В период введения прикорма для здоровья кишечника очень важно, чтобы малыш регулярно получал продукты, содержащие пробиотики, например йогурт, кефир и суп тархана.') WHERE id = '092895c9-69ca-40db-8ca1-d44efd327a7d';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш 6-месячный малыш уже реагирует на изменения тона голоса, а любой предмет, издающий звуки, очень привлекает его внимание! Умственное развитие малыша уже позволяет ему наблюдать за мимикой и пытаться осмыслить увиденное. Это означает, что малыш уже может реагировать, когда вы говорите «нет». По выражению вашего лица он способен понять, что слово «нет» имеет отрицательное значение. Однако если слишком часто говорить малышу «нет», он может начать воспринимать мир как недоброжелательное и негативное место. Возможно, сейчас вы думаете: «Он ещё слишком мал и ничего не понимает». Но это научно доказанный факт. Хотя малыш пока не может полностью осмыслить всё, что слышит, видит и чувствует, его мозг сохраняет эту информацию, чтобы использовать её в дальнейшем. Поэтому постоянные запреты и привычка слышать «нет» могут привести к тому, что, повзрослев, ребёнок станет более негативно настроенным и будет избегать лидерской роли.') WHERE id = '2d11a5b6-a9e7-427f-af80-602cab8874a2';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш, который с рождения и до этого месяца питался исключительно молоком, в начале введения прикорма может отказываться от твёрдой пищи. Поэтому не стоит формировать неправильные привычки, например усаживать малыша перед телевизором во время кормления, чтобы отвлечь его. Начало прикорма — это период, когда важно дать малышу время и проявить понимание. Например, если во время кормления вы будете называть продукты и их цвета, это поможет развить восприятие малыша и повысит его интерес к еде. Чтобы малыш полюбил есть, достаточно проявить немного фантазии. Фигурки, сделанные из продуктов, привлекут его внимание и помогут вам приятно и с пользой провести время. Поскольку сейчас малыш активно знакомится со вкусами, важно предлагать разные продукты в отдельных ёмкостях, чтобы он мог лучше различать их вкус. Также в этот период безопаснее использовать небьющиеся тарелки, вилки и ложки.') WHERE id = 'b5fa9ff8-3ed0-4d85-920b-ca982ac76fc8';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Мы знаем, что временами с малышом вам бывает довольно непросто. Это нормально, особенно если учесть, что сейчас он очень активен и постоянно стремится открывать для себя что-то новое. Но как бы трудно ни было, не забывайте, что он всё ещё полностью зависит от вас и испытывает разные эмоции. Как и все живые существа, ваш малыш способен справляться со стрессом определённого характера и продолжительности. Например, когда малыш голоден или его подгузник испачкан, организм автоматически воспринимает это как угрозу. Сначала малыш начинает активнее двигаться и беспокоиться, а если его потребность не удовлетворяется, в организме выделяется гормон кортизол. Этот механизм стресса приводит к повышению артериального давления и ускорению кровотока. В эти месяцы, когда малыш проходит важный этап развития, чрезмерная выработка кортизола со временем может привести к истощению, замкнутости и отстранённости.') WHERE id = '79821ac2-93ff-4cf4-a7f8-8aab07a2bcca';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Благодаря значительному развитию умственных способностей малыш уже может своим поведением показать вам, хочет он есть или нет. Очень важно внимательно наблюдать за такими сигналами и стараться понимать малыша. Обычно, когда малыш голоден, он может капризничать, быть не в настроении и плакать. Если он слишком проголодался или кормление задержалось, а во время еды малыш плачет или отворачивает голову, не настаивайте: немного подождите и попробуйте снова. В начале кормления малыши нередко бывают настолько голодны, что могут плакать и вести себя так, словно не знают, что делать. Если это происходит с вашим малышом, сохраняйте спокойствие. Скорее всего, благодаря вашему спокойному поведению он расслабится, съев несколько ложек. Когда малыш насытится или больше не захочет какой-либо продукт, он отвернёт лицо и голову в сторону. В этот момент рекомендуем прекратить кормление, чтобы не сформировать у малыша негативное отношение к еде.') WHERE id = 'b20385d7-4579-4424-bf85-74e142637de4';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Хотя ваш малыш уже познакомился с прикормом, не забывайте, что в этот период основным источником питания для него по-прежнему остаётся грудное молоко или молочная смесь. Кроме того, следует с осторожностью давать малышу фруктовые соки. Особенно если у малыша уже прорезались зубы: содержащаяся во фруктовых соках фруктоза может привести к развитию кариеса. Поэтому рекомендуем давать такие содержащие сахар продукты не из бутылочки, а с ложки и под вашим контролем. Приготовленные для малыша пюре и жидкие блюда с небольшими кусочками также можно давать с ложки, внимательно наблюдая за ним. Теперь вы можете предложить ему фруктовые пюре из банана, яблока или персика, овощные пюре из картофеля, моркови или брокколи, а также каши из круп и йогурт. Самое важное — ни в коем случае не добавлять в эти блюда соль, сахар и специи. Приятного аппетита! 😊') WHERE id = '6bf67fbd-887e-4592-8237-816fbe1d635c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если вы очень требовательны к чистоте, малыш, переходящий на прикорм, может немного вас утомить. В этот период малыши непременно пачкают и себя, и всё вокруг. Это естественная часть познания мира, которой не стоит препятствовать. Помните, что чрезмерная озабоченность чистотой и ваша негативная реакция на случайные загрязнения во время еды могут вызвать у малыша напряжение. Конечно, нет ничего плохого в небольших мерах предосторожности, например в использовании нагрудника, но даже с ним малыш всё равно сумеет всё испачкать. В дальнейшем, когда он начнёт держать чашку, пользоваться ложкой и есть пальцами, вокруг станет ещё грязнее. Для многих малышей смешивать посуду, ложки и еду, а также бросать их на пол — это весёлая игра, которая повышает аппетит. Поэтому рекомендуем не слишком ограничивать малыша, а чтобы облегчить уборку, просто постелить на пол скатерть или покрытие! 😊') WHERE id = 'f21f46f4-fb93-42c1-b00e-d167770d53ea';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'С рождения и до 8-го месяца малыш надолго запоминает каждое слово, которое вы используете в повседневной жизни. Эти слова вносят большой вклад в развитие его речи и, следовательно, умственных способностей. Чтобы сделать этот процесс ещё эффективнее, чаще разговаривайте с малышом и используйте в беседах разные слова, которых он раньше не слышал. Например, когда вы вместе идёте в магазин за покупками, можно показывать ему продукты и рассказывать о них. Говоря о цвете, форме и размере предметов, вы можете знакомить малыша с новыми словами! В дни, когда нет возможности выйти на улицу, почитайте ему свою любимую книгу, напойте новую песню или расскажите короткую сказку. Так вы не только разовьёте навыки слушания малыша, но и весело проведёте время вместе, вкладываясь в его будущее! 😊') WHERE id = '6715507c-2cf7-4220-9f23-3cb7294e08b4';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Мы знаем, как сильно вы любите своего малыша и как внимательно заботитесь о его здоровье. Но даже при самом здоровом питании иммунная система малыша может не принимать некоторые продукты из-за пищевой аллергии, которая в наши дни встречается всё чаще. Особенно в период введения прикорма, когда малыш знакомится с разными продуктами, вам следует внимательно наблюдать за его реакцией. Признаки аллергии могут появиться сразу после приёма пищи или в течение 72 часов. Пищевая аллергия у малыша может проявляться кожной сыпью, покраснением вокруг анального отверстия, посинением губ, свистящим дыханием или нарушениями работы желудочно-кишечного тракта. При контакте с аллергенным продуктом пищеварительная система может отреагировать рвотой, диареей, кровью в стуле или запором. Поэтому рекомендуем с осторожностью давать малышу продукты, которые он пробует впервые, и при появлении любой нежелательной реакции немедленно обратиться к врачу.') WHERE id = 'd5afcb47-37bb-45af-b1be-9bc9b6cc67d8';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этом месяце стремление вашего малыша исследовать мир и его любознательность достигают пика. Хотя он всё ещё очень привязан к вам, малыш уже начинает расширять границы своей самостоятельности. В течение этого месяца вы можете увидеть результаты его попыток ползать 😊 Благодаря этим попыткам малыш начнёт лучше осознавать себя как самостоятельную личность. Помимо ползания, ещё одним новым достижением станет умение увереннее тянуться к предметам. По мере расширения пространства для движения растёт и желание малыша исследовать окружающий мир. Однако помните, что сейчас малыш находится на оральном этапе развития, то есть ему хочется тянуть в рот каждый предмет, с которым он знакомится. Поэтому хотим напомнить вам о необходимости принять соответствующие меры безопасности.') WHERE id = '79d6e9ac-e4be-4d51-9c67-149f74a4f03c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этом месяце календарём вакцинации малыша не предусмотрены какие-либо прививки. Однако во время планового осмотра врач измерит его вес, рост и окружность головы. К 7-му месяцу вес малыша обычно составляет от 5900 грамм до 9000 грамм. Средний вес 7-месячных малышей — 8100 грамм. Но помните, что у детей, родившихся раньше срока, этот средний показатель может быть ниже. В этом месяце рост малыша варьируется от 61 см до 75 см, а среднее значение составляет приблизительно 67 см. Окружность головы, которая даёт общее представление о развитии мозга малыша, в этом месяце составляет от 42.8 см до 44 см. Если вы считаете, что физическое развитие малыша не соответствует этим значениям, обратитесь к врачу, чтобы получить наиболее точную информацию.') WHERE id = '7ae42d6a-0c42-4144-b394-cfd8c4804b24';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Механизм распознавания голода и насыщения работает у малыша с момента рождения, и он обязательно тем или иным способом сообщает вам о своих потребностях. Поэтому не следует заставлять малыша есть и тревожиться, когда он отказывается от еды. Хотя малыш уже некоторое время получает прикорм, для полной адаптации ему может потребоваться ещё немного времени. Малыш, который с рождения питался грудным молоком или смесью, может не сразу принять твёрдую пищу и новые вкусы. Если вы считаете, что малыш мало весит или получает недостаточно питания, не следует давать ему высококалорийные, но бесполезные продукты лишь для того, чтобы он набрал вес. Развитие малыша определяется не только количеством получаемых калорий и его весом. Поэтому вместо пищи с пустыми калориями предлагайте ему полезные продукты с высокой питательной ценностью.') WHERE id = 'c7406d7d-33c9-4160-91a7-a354953cf5b3';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этот период малышу уже гораздо легче сидеть самостоятельно и без поддержки. Когда он начнёт самостоятельно сидеть и играть с игрушками без вашей помощи, это будет выглядеть невероятно мило. Для малыша, который научился свободно сидеть, этот период является важным этапом развития: он получает возможность смотреть на мир с нового ракурса и становится более самостоятельным. Благодаря этому перед малышом откроются новые возможности для исследований, и он начнёт видеть окружающий мир под другим углом. Мышцы спины и шеи малыша уже окрепли, и теперь он достаточно хорошо контролирует положение головы и ног. В будущем это облегчит ему освоение таких навыков, как ползание, вставание и ходьба. Однако не беспокойтесь, если малыш пока не может долго оставаться в вертикальном положении и иногда заваливается набок. 😊') WHERE id = 'c06b62a5-8d7b-4555-9d57-8340da61ad39';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этом месяце исполнился уже месяц с начала введения прикорма вашему малышу. За этот месяц он мог приобрести такие навыки, как жевание, глотание, поднесение еды ко рту и самостоятельный приём пищи. Если всё идёт не так, как вы представляли, не спешите беспокоиться. Не существует правила, согласно которому каждый малыш должен легко пройти этот этап. Помните, что многие мамы испытывают то же, что и вы. Если вам кажется, что малыш не проявляет интереса к прикорму, можно использовать некоторые игры, чтобы он ел с большим желанием и у него формировалось здоровое отношение к еде. Например, можно играть в «Самолётик летит» или кормить малыша под песенки. Одно из важнейших правил заключается в следующем: когда малыш показывает, что хочет остановиться, вам тоже следует остановиться и сделать небольшой перерыв.') WHERE id = 'ca27271b-d34b-4ce7-b5f9-f4505e118771';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этом месяце социальные навыки малыша будут активно развиваться. Поэтому он начнёт внимательно наблюдать за членами семьи, с которыми общается. Благодаря информации, накопленной в памяти к этому этапу, малыш учится устанавливать причинно-следственные связи. Не удивляйтесь, если он попытается повторять движения рук и ног и даже вашу мимику! 😊 Конечно, это накладывает на вас определённую ответственность — быть хорошим примером! Ведь любознательность малыша очень сильна, и он прилагает немало усилий, чтобы исследовать всё вокруг. Вы можете устанавливать ограничения в ситуациях, которые могут быть для него опасны, но не стоит переусердствовать. Например, если внимание малыша привлёк предмет, который он может проглотить, и он взял его в руки, чтобы рассмотреть, вместо того чтобы сразу отбирать предмет или резко реагировать, внимательно наблюдайте за малышом и вмешивайтесь только тогда, когда это действительно необходимо.') WHERE id = '84211613-fc78-4c1f-a816-22b155e0b89d';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Поскольку на 7-м месяце малыш всё ещё пробует разные продукты, он продолжает находиться на этапе введения прикорма. Это очень важный и ответственный период, который повлияет на пищевые привычки малыша в будущем и даже во взрослом возрасте. Иногда малыш может отказаться от блюда, которое пробует впервые. Это не значит, что он никогда не полюбит этот продукт. В такой ситуации отложите его и предложите снова через несколько дней. Иногда может помочь даже изменение способа подачи или приготовления в течение того же дня. В этот период, даже если у малыша ещё не прорезались зубы, он может разминать дёснами и есть пищу с небольшими мягкими кусочками. Поэтому не бойтесь включать такую пищу в меню. Кроме того, она способствует развитию мышц рта и языка, что в дальнейшем положительно скажется на речи малыша.') WHERE id = 'b07bfb17-d3e7-4626-8576-6365ec3ad72a';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Органы чувств малыша, вступившего в 7-й месяц жизни, развиты уже почти так же хорошо, как у взрослого человека. Его зрение можно считать практически полностью сформированным. Благодаря этому малыш достаточно чётко видит и различает людей и предметы, находящиеся на расстоянии. Он также может следить за быстрыми и сложными событиями вокруг и точно воспринимать происходящее. Поскольку восприятие глубины уже полностью сформировалось, малыш может следить за приближающимся к нему предметом и тянуться вперёд, чтобы схватить его. Слух 7-месячного малыша развит так же хорошо, как и зрение. Теперь он сразу понимает, откуда доносится звук, и может повернуться непосредственно в его сторону. Однако, прислушиваясь к тихим и далёким звукам, он некоторое время может оставаться спокойным и не проявлять никакой реакции.') WHERE id = 'e80c4140-2676-446b-a5dc-f1e0f240ee47';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Одна из самых распространённых ошибок при введении прикорма — предлагать малышам почти при каждом приёме пищи жидкие блюда, например супы. Безусловно, полезные свойства супов, особенно приготовленных на костном бульоне, трудно переоценить. Однако супы не должны составлять основу рациона малыша. Если пищу с небольшими мягкими кусочками и продукты, помогающие малышу учиться жевать, вводить позже, чем нужно, это может привести к нежелательным последствиям. Такая пища не только помогает формировать правильные пищевые привычки, но и развивает мышцы рта и языка. Поэтому не следует слишком долго давать малышу только измельчённую блендером до однородного пюре пищу. В противном случае в период прорезывания зубов переход к твёрдой пище может оказаться сложнее, а малыш может отказываться от еды с кусочками, потому что она будет для него непривычной.') WHERE id = '0eb37995-3090-4435-b8b9-edf48f0b68fb';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Теперь ваш малыш уже не произносит только отдельные гласные или согласные звуки, как в предыдущие месяцы. На 7-м месяце он начинает соединять гласные и согласные в слоги и может произносить такие звуки, как «бабабаба», «мамамама» и «какакака». Есть несколько занятий, которые помогут поддержать и стимулировать речевое развитие малыша. Например, когда он в хорошем настроении, вы можете повторять звуки, которые он произносит. Глядя на вас, малыш внимательно следит за тем, как вы говорите, и старается вам подражать. Старайтесь немного преувеличенно артикулировать: это поможет малышу наблюдать за движениями вашего языка, губ и нёба при произнесении звуков. Поэтому отложите дела на час-другой и приготовьтесь весело провести время вместе с малышом! Приятного времяпрепровождения 😊') WHERE id = '50599786-43fc-4007-9b26-bc49949f135e';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Помимо грудного молока или молочной смеси, ваш малыш уже начал получать прикорм. Поэтому вы можете предположить, что теперь он должен набирать больше веса. Однако это не совсем так. Малыш стал гораздо активнее, и хотя он продолжает расти, уже не ожидается, что он будет прибавлять в весе так же быстро, как в первые месяцы. В этом месяце малыш наберёт в среднем 350-400 грамм. Эти цифры являются усреднёнными показателями, помогающими следить за развитием. Помните, что каждый малыш развивается индивидуально, а генетика, пол и особенности обмена веществ могут влиять на показатели. Общепринятое правило таково: ожидается, что к 5 месяцам вес малыша удвоится по сравнению с весом при рождении, а к 12 месяцам — утроится.') WHERE id = '0bf43d37-a329-4f54-80f4-b9fdb2e13965';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'До сих пор вы познакомили малыша со множеством новых вкусов. Но у вас могут возникать вопросы о том, почему некоторые продукты ему пока давать нельзя. Это связано с развитием пищеварительной системы малыша и готовностью его кишечника. Например, многих родителей интересует, почему коровье молоко важно пока исключить из рациона. Хотя оно богато витаминами и минералами, коровье молоко создаёт чрезмерную нагрузку на ещё не полностью сформировавшиеся почки малыша. Кроме того, оно не может полностью обеспечить потребности детского организма в необходимых витаминах, что может привести к задержке развития и замедлению роста. Также в коровьем молоке мало йода и цинка, а это может отрицательно сказаться на умственном развитии малыша. По всем этим причинам правильнее начинать постепенно вводить коровье молоко в рацион после того, как малышу исполнится 12 месяцев.') WHERE id = 'e49d6509-b260-4b7c-8420-cc63289843b1';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Какой большой путь развития ваш малыш прошёл за столь короткое время — и он продолжит вас удивлять! 😊 К сожалению, не все эти изменения всегда будут вас радовать. Например, вы можете заметить, что малыш больше не хочет оставаться без вас и бурно на это реагирует. Такое поведение, которое может вас беспокоить, указывает на формирование у малыша тревоги при разлуке (страха разлуки). Некоторым мамам это может не казаться проблемой, однако без необходимых мер в будущем могут возникнуть трудности. Через некоторое время это может привести к тому, что в ваше отсутствие малыш будет чувствовать себя несчастным и незащищённым. Чтобы этого избежать, привлекайте членов семьи к уходу за малышом и постепенно приучайте его к такой ситуации. Например, сегодня вечером пусть вместо вас малыша покормит супруг, а после ужина проведёт с ним время наедине.') WHERE id = 'ee5d1f29-7924-4191-bd02-dbcf16926418';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Изучая информацию о прикорме, вы, вероятно, уже встречали понятие BLW. Этот метод, полное название которого — "Baby Led Weaning", а сокращённое — BLW, в последние годы стал одной из самых популярных тем среди родителей. BLW можно перевести как "прикорм под руководством малыша". Этот подход основан на принципе самостоятельного питания. Метод BLW подходит малышам, которые уверенно держат голову, сидят в стульчике для кормления без поддержки и могут самостоятельно подносить ко рту предложенную еду. Благодаря этому малыш может без посторонней помощи выбирать пищу и съедать столько, сколько захочет. Хотя BLW — относительно новый метод, наблюдения показывают, что он положительно влияет на развитие малышей.') WHERE id = '3224c721-5217-4489-ba14-724ab5302d3d';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш так быстро растёт прямо у вас на глазах, не правда ли? Не удивляйтесь, если увидите, что он начал ползать! 😊 Хотя это случается редко, некоторые малыши могут начать ползать уже в этом месяце. Но если ваш малыш пока не ползает, это не означает, что он отстаёт в развитии, поэтому не беспокойтесь. Мышцы рук, ног и спины малыша значительно окрепли, благодаря чему он уже почти полностью освоил повороты вокруг своей оси. Кроме того, если положить малыша на живот, он может резко поднять голову и с лёгкостью перевернуться, опираясь на руки. Иногда в этом возрасте малыши ещё не могут сидеть без поддержки. И в этом случае ваш малыш также не считается отстающим в развитии. Обычно способность уверенно сидеть без поддержки полностью формируется примерно к 8-му месяцу.') WHERE id = '2f3bbf20-95fe-4b29-88f7-dede7edfcc73';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Согласно исследованиям, малыши, которым родители часто поют песни и колыбельные, в последующие месяцы лучше воспринимают ритм речи. Ваш малыш учится всему, в том числе речи, через подражание, поэтому очень важно правильно и уместно использовать слова. Например, в холодный день вы можете сказать, что на улице холодно, и показать, будто мёрзнете. Благодаря этому малыш лучше запомнит значение слова и легче поймёт причинно-следственную связь. Чтобы подавать малышу хороший пример, не стоит говорить с ним на детском языке, искажая слова, как бы мило это ни звучало. Пусть он запоминает услышанные слова чётко и правильно. Чтобы сделать этот процесс веселее, вы можете повторять звуки, которые издаёт малыш. Ему это очень понравится, и вы весело проведёте время вместе.') WHERE id = '015590a4-be89-40bd-9634-b5bb65d23d50';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Применение метода BLW (самостоятельного прикорма под руководством малыша) во время введения прикорма внесёт большой вклад в его развитие. У этого метода есть определённые правила. В отличие от традиционного подхода, главное здесь не то, чтобы мама кормила малыша, а чтобы он ел самостоятельно. Если в первые 6 месяцев малыш получал только грудное молоко или молочную смесь, особенно в начале переходного периода не следует сразу давать ему прикорм 3 раза в день. Также не пытайтесь кормить малыша насильно и не настаивайте, если он отказывается. Начните с одного раза в день и постепенно увеличивайте количество приёмов пищи, предлагая продукты в такой форме, чтобы малыш мог легко брать их рукой. На протяжении всего этого времени ни в коем случае не оставляйте малыша одного и внимательно следите за каждым его действием. Цель метода — помочь малышу самостоятельно исследовать вкусы, развивать зрительно-моторную координацию и учиться есть без посторонней помощи.') WHERE id = 'b805a548-3277-455e-8a43-b5228959fd35';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Благодаря развивающемуся восприятию малыш уже может ясно показывать вам, когда он доволен, а когда испытывает дискомфорт. Он начинает выражать это движениями и мимикой. Чтобы общаться с вами, малыш продолжает издавать звуки, сообщая, что он весел или, наоборот, беспокоен. Если до сих пор основным средством общения малыша был плач, то теперь, по мере развития речи, он может произносить отдельные бессмысленные слоги и слова, чтобы выразить себя. Поскольку малыш начинает эффективнее использовать движения рта для речи, эти звуки становятся более отчётливыми. Способность произносить разные слова, даже пока не имеющие смысла, — важный этап в развитии малыша. Ведь эти звуки становятся началом его первых настоящих диалогов: он экспериментирует с ними, реагирует на окружающих и начинает устанавливать социальные связи.') WHERE id = '811dc858-78e1-4c23-aea6-584681b23792';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В период введения прикорма, особенно в самом начале, вероятность того, что малыш подавится, наверняка будет одним из ваших главных страхов. Если что-то мешает ему дышать, малыш постарается самостоятельно избавиться от препятствия. Если пища застряла у него в горле, но он может кашлять, плакать и издавать звуки, значит, дыхательные пути перекрыты не полностью. Скорее всего, малыш сможет справиться с этой ситуацией самостоятельно. Лучшее, что вы можете сделать в таком случае, — сохранять спокойствие и поддерживать малыша. Однако если у него появились признаки серьёзного удушья, необходимо вызвать скорую помощь и немедленно попытаться освободить дыхательные пути. Поэтому очень важно заранее изучить правила оказания первой помощи младенцам по надёжным источникам.') WHERE id = '880904da-8e52-4e39-93ed-5f35ec843a62';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если вам нужно вернуться к работе, вы можете беспокоиться о психологическом состоянии малыша и уходе за ним. Страх разлуки у малышей обычно появляется с 6-го месяца и достигает пика к 12-му месяцу. Не вините себя из-за этого, поскольку это нормальный этап развития малыша. Незадолго до выхода на работу полезно начать практиковать короткие расставания. Даже если малыш ещё не понимает, что вы уходите, попрощайтесь с ним ласково и непринуждённо и скажите, что обязательно вернётесь. Во время таких тренировок можно оставить малыша с близким человеком, которого хорошо знаете и вы, и он, чтобы малыш не чувствовал себя рядом с ним неуютно. Если вы заранее будете проводить время вместе с человеком, которому планируете доверить малыша, это значительно облегчит процесс.') WHERE id = '99e99257-b0ed-4e0f-b789-5eb260e3fd9d';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Питание — одна из важнейших физических потребностей малыша. Поэтому правильный и достаточный рацион является основным условием для его здорового роста и развития без задержек. Однако малыш не всегда может охотно соглашаться есть. Иногда полезные блюда, приготовленные вами с большой любовью, могут остаться нетронутыми и отправиться в мусор. Первое, чего не стоит делать в такой ситуации, — вступать с малышом в борьбу. Если вы будете настаивать, то можете ещё сильнее отвратить его от еды — естественной физиологической потребности. Кроме того, это способно вызвать отчуждение между вами и малышом. Поэтому проявляйте терпение, а при необходимости посоветуйтесь с врачом о том, что можно предпринять.') WHERE id = '2f28f952-bd75-47db-822c-9ba614e24ba2';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'На этапе формирования у малыша пищевых привычек и навыков поведения за столом важно правильно выбрать время, когда он начнёт участвовать в семейных трапезах. Специалисты считают, что не позднее 9-го месяца малыш должен сидеть за столом вместе с родителями. Поэтому во время приёма пищи, особенно если вся семья собирается за столом, вы можете приглашать к нему и малыша. Для этого идеально подойдёт детский стульчик, поставленный рядом со столом. Сидя в нём и наблюдая за тем, как едите вы и другие члены семьи, малыш получит очень полезный опыт. По мнению специалистов, наблюдение и подражание — важнейшие способы обучения малышей. Кроме того, если не включать телевизор во время еды и создать за столом приятную атмосферу, малыш будет есть с большим желанием.') WHERE id = '2c9b0188-9d07-406a-bc48-6a8ce20aef72';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Игровой коврик, который малыш так любил в первые месяцы после рождения, теперь может казаться ему скучным и тесным. Активному малышу, чьим любимым занятием стало исследование всего нового, очень не нравится, когда его свободу ограничивают. Поэтому, когда вы кладёте его на игровой коврик, он может не захотеть там оставаться и начать протестовать! В такой ситуации спокойно отнеситесь к тому, что малыш громко заявляет о своём желании свободно двигаться, и позвольте ему выражать свои эмоции. Вы можете сделать безопасной для малыша одну комнату или, по возможности, весь дом. Но даже если подготовленное пространство безопасно, всегда сохраняйте бдительность и не оставляйте малыша без присмотра. Если вам трудно заниматься делами рядом с активным малышом, постарайтесь выполнить часть задач, пока он спит или находится под присмотром другого человека.') WHERE id = '45a8e0d6-4932-4235-9823-06f0b7e8f85a';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, '7-й месяц — один из периодов, когда новые двигательные навыки малыша значительно совершенствуются. Поэтому вам следует уделить особое внимание тому, что в доме может быть опасно для маленького исследователя. Закройте электрические розетки, которые могут представлять опасность для малыша, стремящегося изучить всё, что привлекает его внимание. Не оставляйте полы мокрыми, уберите электрические провода, острые предметы и всё, что может причинить ему серьёзный вред. Для острых углов мебели и подоконников можно использовать доступные защитные накладки. Если в доме есть лестница, до которой малыш может добраться, обязательно установите защитные ограждения сверху и снизу. Цель всех этих мер — позволить малышу свободно исследовать окружающий мир в безопасных границах, установленных вами.') WHERE id = '616cd1ae-8a43-46fd-8952-aef7ae090d0b';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В период введения прикорма вам наверняка хочется давать малышу самые питательные продукты, полезные для его развития и здоровья. Однако пища, полезная для вас, может принести малышу больше вреда, чем пользы. Поэтому важно придерживаться плана, составленного вместе с врачом, и учитывать степень зрелости пищеварительной системы малыша. Например, кому не придёт в голову добавить немного соли в приготовленное картофельное пюре, опасаясь, что оно будет безвкусным? Однако специалисты категорически не рекомендуют давать соль малышам до достижения ими 1 года. На этом этапе малышу достаточно солей, которые естественным образом содержатся в овощах. Избыточное поступление соли в организм может отрицательно повлиять на работу почек малыша. Будьте осторожны!') WHERE id = '6b656aed-9031-4b22-b6b9-5ed9b49d2799';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Когда малыш начинает говорить, одновременно развиваются и его языковые навыки. Поначалу он ещё не осознаёт, что и как произносит, но со временем некоторые бессмысленные звуки превратятся в настоящие слова. Лепет не только ускоряет умственное развитие малыша, но и помогает ему учиться повторять и запоминать звуки. Так малыш вступает в период, когда начинает делать паузы, чтобы решить, что сказать, а также учится использовать речь и жесты для выражения своих желаний и потребностей. Однако ему может потребоваться ещё немного времени, чтобы начать произносить настоящие слова. Всё это время малыш продолжает изучать правила языка, наблюдая за вами и подражая вам. Поэтому очень важно говорить правильно, чётко и уместно употреблять слова.') WHERE id = '8f6d0ab5-b074-476e-95ce-1532c933bec4';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Крепкий скелет малыша формируется только при здоровом развитии костей. Этот процесс начинается ещё до рождения и особенно быстро протекает в течение первого года жизни. С 6-го месяца, когда малыш начинает получать прикорм, вам следует позаботиться об укреплении его костей. Хотя на этом этапе основной пищей малыша по-прежнему остаётся грудное молоко или детская смесь, вместе с прикормом он должен получать и продукты с высоким содержанием кальция. По мере расширения рациона количество витаминов и минералов, получаемых малышом из вашего молока, несколько уменьшается. Поэтому кальций особенно важен как минерал, в значительной степени способствующий укреплению костей малыша. Чтобы его организм получал достаточно кальция, можно составить меню из таких продуктов, как йогурт и зелёные листовые овощи.') WHERE id = '2697c6e2-7952-4ec2-98c7-54307a2fe921';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этот период ваша жизнь может стать более напряжённой и беспокойной, чем обычно. С малышом, который стал гораздо активнее, вам может быть сложно всё успевать и осуществлять свои планы. Есть множество способов облегчить повседневную жизнь на этом этапе. Воспользовавшись некоторыми из них, вы сможете немного разгрузить себя. Прежде всего постарайтесь организовать уход за малышом, заботу о себе и домашние дела. Пусть у вещей, которыми вы регулярно пользуетесь для ухода за малышом, будет постоянное место. Можно выделить в доме отдельную зону только для смены подгузника. Тогда вам не придётся каждый раз искать подгузник, влажные салфетки, пелёнку и другие необходимые принадлежности по отдельности. Не стоит также ждать момента выхода из дома, чтобы собрать вещи, которые понадобятся на прогулке с малышом. Можно всегда держать у двери готовую сумку для мамы и малыша.') WHERE id = 'f71171e4-2818-49d6-8552-7761b12126d4';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В эти дни у малыша может начаться продолжительный скачок развития. Поэтому он может отказываться от сна и еды, капризничать и часто проситься на руки. Шестой скачок развития приходится на период между 34-й и 37-й неделями, отсчитываемыми от предполагаемой даты рождения малыша. Ключевое слово этого скачка — «категория». Малыш, который уже некоторое время активно исследует всё вокруг и изучает каждое живое и неживое существо, теперь способен мысленно распределять их по категориям. Например, вы вместе с малышом встретили собаку. Вы показали ему собаку и сказали: «Гав-гав». Малыш по-своему отнёс её к определённой категории. Если через несколько дней на улице вам встретится кошка, малыш может и на неё отреагировать словами «гав-гав». Это происходит потому, что в своём восприятии он отнёс всех существ, передвигающихся на четырёх лапах, к одной категории. Кажется, что это неправильно. Однако малыш пока ещё не способен различать всё настолько точно, поэтому такая ошибка вполне естественна.') WHERE id = '18fded6c-68c1-4a2f-8a8c-2cce06aa19e7';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Хотя ваш малыш начал получать прикорм примерно 2 месяца назад, до 2 лет его основной пищей по-прежнему остаётся грудное молоко. Прикорм, который вы предлагаете, лишь заменяет промежуточные приёмы пищи. Поэтому сокращение грудного вскармливания может замедлить развитие малыша. Если в последнее время вам кажется, что у малыша нет аппетита, хотим напомнить, что вы не одиноки. 😊 Сейчас он вступил в период активных игр, поэтому может не хотеть тратить много времени на такие потребности, как питание и сон. Вы можете совместить его любимое занятие — игру — с приёмом пищи! Чтобы сделать еду увлекательнее, красиво и интересно оформляйте блюда, а во время кормления играйте с ним в «ку-ку» или «летит самолётик». Также вам могут помочь пальчиковые куклы. Весёлого времяпрепровождения! 😊') WHERE id = 'd21c1f6a-5fc9-4cad-8563-f3edc47a4f56';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Начиная с этого месяца нижняя граница окружности головы малыша составляет 41 см, а верхняя — 47 см. Средняя окружность головы 8-месячного малыша — примерно 44 см. Поскольку увеличение окружности головы является показателем развития мозга, её необходимо регулярно измерять. Рост малыша на 8-м месяце может составлять от 62 см до 77 см. Кроме того, в этот период вы можете заметить, что родничок малыша начинает закрываться. Обычно ожидается, что родничок закроется в период между 12-18 месяцами, однако у некоторых малышей этот процесс может начаться уже на 8-м месяце. Если развитие мозга продолжается нормально, это считается физиологической нормой и поводов для беспокойства нет.') WHERE id = '4019cfbc-4717-4ff6-83d7-b0dd34ad99d7';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш стал не только отличным игроком, но и внимательным наблюдателем. Он пристально следит за вами и другими членами семьи и может быстро повторять ваши действия и звуки. Например, когда папа уходит на работу, малыш может обратить внимание на то, как вы машете ему рукой на прощание, и тоже помахать вслед. Ведь теперь звуки и мимика начинают приобретать для него определённый смысл. Поэтому, когда ему что-то нужно, он чаще произносит слоги. Малыш всё лучше осознаёт происходящее вокруг, а врождённые рефлексы постепенно полностью сменяются осознанными и целенаправленными движениями. Это ещё одно доказательство того, насколько быстро он развивается за столь короткое время. 😊') WHERE id = '980f8f43-3138-49d0-a45d-59c21bfd0cd3';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш активен как никогда и, как многие другие малыши, может совсем не любить смену подгузника. 😊 Когда вы снимаете грязный подгузник, малыш чувствует облегчение. Поэтому, увидев, что вы собираетесь надеть чистый, он может начать сопротивляться руками и ногами. 😊 А если малыш уже начал ползать, возможно, вам даже придётся некоторое время побегать за ним, прежде чем вы сможете застегнуть подгузник. Не стоит вступать в противостояние с сопротивляющимся малышом — это может вызвать у него стресс. Постарайтесь сделать смену подгузника веселее, чтобы облегчить себе задачу. Самый простой способ — конечно же, отвлечь его внимание. Пойте во время смены подгузника, рассказывайте малышу, что вы делаете, или займите его любимой игрушкой — это значительно упростит процесс. 😊') WHERE id = 'fe2747a5-5b02-4aab-bf69-6b7fa1ec81f8';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш вступил в один из самых активных периодов умственного развития. Он не только отчётливо слышит звуки поблизости, но и уже способен, как взрослые, различать звуки, доносящиеся издалека. Зрение, слух и восприятие глубины значительно улучшились, поэтому период активного исследования мира продолжается. Вот почему руки и ноги малыша постоянно находятся в движении. Он умеет задействовать все пальцы для определённой цели и крепко удерживать предметы. Малыш также начинает активно использовать указательный палец, чтобы толкать всё, на что хватает сил, и исследовать небольшие отверстия. Поэтому вам следует принять меры безопасности, особенно в отношении таких опасных для малыша объектов, как электрические розетки.') WHERE id = '0856b508-32f1-46be-891e-90f4409ee60b';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш уже хорошо привык к прикорму. Если вы всё ещё предлагаете ему пищу в виде пюре, теперь можно постепенно переходить к еде с небольшими кусочками. Специалисты рекомендуют с этого месяца начинать давать более плотную пищу, поскольку у малышей формируется навык жевания. Если слишком долго кормить малыша только пюре и однородной пищей, в будущем это может привести к нарушениям пищевого поведения. Однако не стоит резко увеличивать плотность предлагаемой еды. Слишком быстрый переход может вызвать запор и другие проблемы с пищеварением. Поэтому каждый день понемногу увеличивайте размер и количество кусочков, чтобы переход был плавным.') WHERE id = '72760305-9a29-4db8-960b-c7c0f371cc22';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Начиная с этого месяца ваш малыш может самостоятельно сидеть без какой-либо поддержки. Благодаря укреплению мышц рук и ног ему уже легче ползать. Но помните, что это не означает, что каждый малыш обязательно должен ползать: если ваш малыш не ползает, это не считается задержкой развития. Кроме того, если в вашем доме есть лестница, необходимо принять соответствующие меры безопасности, поскольку активному малышу становится легче взбираться по ступенькам. В этом месяце малыш может пытаться встать, держась за какой-либо предмет, и обычно способен недолго стоять с опорой. Хотя он ещё не умеет ходить, если поддерживать его под мышки, он может совершать шаговые движения. Однако не следует его заставлять: желание самого малыша подскажет вам, как лучше поступить.') WHERE id = 'a563d702-5875-4391-a1d5-846178e0f653';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Теперь в рацион малыша можно добавить сушёные бобовые, чечевицу и рыбу. Благодаря развивающимся навыкам жевания и постепенному созреванию пищеварительной системы малыш уже готов к этим продуктам. Сушёные бобовые очень важны, поскольку помогают удовлетворить потребность в белке и служат богатым источником витаминов и минералов. Чечевица богата железом, витаминами группы B, фолиевой кислотой и различными минералами. По пищевой ценности она почти не уступает красному мясу и незаменима для здорового питания малыша. Кроме того, малышу, который осваивает новые навыки, очень нужны жирные кислоты Омега-3. Рыба, которую вы добавите в рацион, богата не только витаминами A и D, но и жирными кислотами Омега-3.') WHERE id = '5436fc4f-86ab-41cc-af9e-5a2f20f1be86';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Возможно, вам кажется, что у малыша отсутствуют некоторые навыки, характерные для его возраста. Однако темпы роста и развития у всех малышей различаются. Задержкой развития называют более медленное освоение таких навыков, как сидение, ползание, ходьба, способность стоять прямо и речь. Часто такая задержка носит временный характер, и большинство малышей вскоре догоняют сверстников. Хотя новые навыки обычно осваиваются в определённой последовательности, важно помнить, что у каждого малыша свой ритм развития. Например, у одних малышей раньше развиваются крупные моторные навыки, такие как умение сидеть, а у других — способность брать и удерживать предметы. Тем не менее, чтобы развеять сомнения, вы можете обсудить вызывающие беспокойство моменты с врачом.') WHERE id = '66787d5e-85c6-4974-9795-692e078d138d';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Большую часть времени бодрствования ваш малыш посвящает новым открытиям. Если во время таких исследований он встаёт, опираясь на что-либо, важно, чтобы его пятки касались пола. Это очень важно для развития мышц ног малыша и, вопреки распространённому мнению, не приводит к плоскостопию. Чтобы малыш не скользил на гладкой поверхности и не получил травму, можно надевать ему пинетки с нескользящей подошвой. На улице, даже если малыш ещё не умеет уверенно ходить, обувь может понадобиться, чтобы защитить его ноги от жары и холода. На этом этапе необязательно покупать специальную обувь для первых шагов. Достаточно выбрать обувь, которая хорошо облегает стопу малыша, охватывает и поддерживает голеностоп.') WHERE id = 'b84764db-feb1-47bf-b057-d7266054d43f';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Возможно, на протяжении беременности одним из самых интересующих вас вопросов было то, какого цвета будут глаза малыша. 😊 После рождения глаза малыша обычно имеют серо-голубой оттенок. Хотя он выглядит очень красиво, к сожалению, это временно. Причина в том, что цветная оболочка глаза ещё не завершила своё развитие, поэтому отражает свет практически без изменений. Начиная с этого месяца пигментация почти полностью формируется, и глаза малыша приобретают свой настоящий цвет. Если глаза малыша стали карими, вероятность того, что их цвет изменится, уже отсутствует. Но если они всё ещё имеют светлый оттенок, помните, что до достижения 12 месяцев цвет глаз ещё может измениться.') WHERE id = 'afcad808-5171-4e03-8941-cb9235ad0674';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'По мере того как малыш получает меньше грудного молока или молочной смеси, вы можете беспокоиться о том, достаточно ли витаминов он получает с пищей. Прежде всего, важно отметить, что перед применением любых витаминов или пищевых добавок необходимо обязательно проконсультироваться с врачом. Также следует избегать однообразного питания и стараться сделать меню малыша разнообразным. Удовлетворение потребности малыша в витаминах и минералах напрямую связано, в частности, с употреблением сезонных фруктов и овощей. Помните, что витамин D и препараты железа, например капли, обычно назначаются профилактически — это стандартная практика. Если малыш родился преждевременно, имеет низкую массу тела или задержку развития, врач может рекомендовать дополнительные препараты. Но каждый малыш индивидуален, поэтому наиболее подходящие рекомендации может дать только врач, знакомый с состоянием вашего малыша и особенностями вашей ситуации.') WHERE id = 'a7e33135-d849-4e1d-b626-072569cf1acd';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Решить, сколько жидкости давать малышу, вы можете, опираясь на рекомендации врача и собственные наблюдения. Заподозрить обезвоживание можно, если в течение дня малыш вялый, его рвёт и он отказывается от еды. При обезвоживании температура тела также может повышаться. Поэтому вам будет полезно регулярно измерять её. Общие признаки обезвоживания: редкое мочеиспускание и тёмная моча, сухость во рту, плач без слёз. Кроме того, значительное сокращение количества грудного молока или смеси в этот период также может привести к обезвоживанию. Чтобы предотвратить его, прежде всего следите за тем, чтобы малыш ежедневно получал достаточно жидкости.') WHERE id = '61c2e7d6-1d91-41c2-969b-396148013b25';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш продолжает непрерывно развиваться с невероятной скоростью! Теперь, когда ему исполнилось 8 месяцев, его действия становятся более осознанными и целенаправленными. Другими словами, малыш уже способен выражать разные желания без плача. Например, когда он проголодается, вместо беспокойства, хныканья и плача вы можете услышать, как он отчётливо произносит «ням» (еда). Когда он хочет пить, то радуется, увидев свою чашку, а наблюдая за тем, как вы готовите еду, приходит в восторг. Это важный этап в развитии малыша: теперь он уже может простым способом объяснить вам, чего хочет. Когда он невинно просит вас о чём-то, то понимает, что означают ваши ответы «да» и «нет». Но как поступить после такого ответа — он всё равно решает сам. 😊') WHERE id = '1886ab50-5a60-4760-b927-fa91d9c42779';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Теперь ваш малыш легко осваивает новые простые игры, соответствующие его уровню развития. Можно с уверенностью сказать, что вы вступили в период активных игр. Желаем вам терпения! 😊 Чтобы развивать этот навык малыша, чаще играйте с ним. Он будет с интересом наблюдать за вами и внимательно слушать. Кроме того, поскольку движения рук малыша стали гораздо увереннее, он может осознанно взять найденную на полу игрушку и самостоятельно играть с ней. Чувствуя себя более независимым, чем в первые месяцы, малыш ищет потерянные или упавшие игрушки и уже может сам их поднять, вместо того чтобы просить вас об этом. Он может трясти, ударять и бросать игрушки и найденные вокруг предметы, проверяя, издают ли они звуки. А если он ещё не закончил играть, то не позволит вам забрать игрушку и выразит протест.') WHERE id = 'fe525d42-0a0a-48cc-aa11-ecad88d56b2a';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'У вас могут возникнуть вопросы о том, когда начинать использовать для малыша обучающую чашку (поильник). Понять, что подходящее время наступило, можно, наблюдая за малышом. Если у него исчез рефлекс выталкивания языком, значит, он уже готов пользоваться обучающей чашкой. Рефлекс выталкивания языком — это автоматическое выталкивание языком постороннего предмета, попавшего в рот малыша в первые месяцы жизни. На самом деле этот рефлекс жизненно важен, поскольку защищает малыша от риска подавиться. В среднем он начинает ослабевать с 4-го месяца, а в период между 6-м и 8-м месяцами полностью исчезает. Исчезновение этого рефлекса также служит первым признаком того, что малыш уже может пить воду из чашки вместо бутылочки.') WHERE id = '52c260d9-9803-4e1b-9fc5-0c188ff2d7d3';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Средний вес малышей в возрасте 8 месяцев составляет около 8000 граммов. При этом он может варьироваться от 6300 до 11000 граммов. Однако именно в этом месяце из-за возросшей активности набор веса может замедлиться, и к концу месяца весы могут показать прибавку в среднем на 250-650 граммов. Если ваш малыш родился раньше срока, он уже может догнать сверстников. Но даже если этого пока не произошло, не волнуйтесь — ещё не поздно. Такой большой диапазон веса также связан с различиями в росте и весе девочек и мальчиков. Не предпринимайте никаких действий в связи с набором веса малыша или его замедлением без консультации с врачом. Помните, что каждый малыш развивается по-своему и даже дети, показатели которых находятся у нижней или верхней границы нормы, могут быть совершенно здоровы.') WHERE id = '639ac35e-714a-47fc-b5c3-a25af9dcd029';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш уже хорошо привык к прикорму, который вы начали вводить некоторое время назад, но при этом продолжает получать грудное молоко или смесь. Особенно в этот период бывает утомительно подсчитывать, сколько прикорма малыш должен съедать и сколько молока выпивать. Однако важно помнить, что ещё некоторое время его основной пищей будет ваше молоко или смесь. Начиная с этого месяца малышу требуется в среднем 850 калорий в день, хотя эта потребность может меняться в зависимости от его активности и скорости обмена веществ. Для поддержания здоровья кишечника малыш по-прежнему должен получать больше половины этих калорий из молока. Чтобы сохранить этот баланс и не запутаться, когда малыш проголодается, сначала покормите его грудью или дайте молоко. Затем предложите ему небольшую порцию сбалансированной и питательной пищи. На этом этапе вы можете увеличивать размер порции в зависимости от потребностей малыша.') WHERE id = 'aaf40c8d-b2ab-4458-8b62-ca1e766f4975';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш уже может самостоятельно сидеть без поддержки. Этот навык создаёт основу для того, чтобы ему было легче поворачиваться, приседать и ползать. Возможно, он уже начал ползать. 😊 Однако совершенно нормально, если некоторые малыши пропускают этап ползания и сразу начинают ходить. Ваш непоседа, заметив что-то интересное, постарается поползти или направиться в ту сторону. Добравшись до заинтересовавшего его предмета, он возьмёт его в руки, внимательно изучит и потянет в рот. Именно поэтому теперь за малышом нужно следить ещё внимательнее и, если вы пока этого не сделали, принять дома необходимые меры безопасности.') WHERE id = 'f711661c-b42b-4a2c-9389-6ca7cb481b26';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вероятно, ваш малыш всё ещё переживает скачок развития, поэтому некоторые трудности в этот период вполне естественны. Быстрый рост и освоение новых навыков иногда могут привести к снижению аппетита, однако у некоторых малышей, наоборот, наблюдается его заметное усиление. Поэтому в течение дня малыш может чаще просить грудь. В этот период вы также можете давать ему столько прикорма, сколько он хочет, поскольку для быстрого развития организму требуется дополнительная энергия; если эта потребность не удовлетворяется, малыш может беспокоиться. Кроме того, из-за усилившейся тревоги при разлуке он может не хотеть отпускать вас от себя. В такие моменты рекомендуем учитывать психологическое состояние малыша, стараться понять его и проявлять терпение. 😊') WHERE id = 'a8e0d4f7-6afa-42e9-8b05-07856071a068';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В некоторые периоды режим сна малыша может меняться. В этом месяце он спит примерно 14-15 часов в сутки, причём значительная часть этого времени приходится на ночной сон. Однако малышу также необходим дневной сон, поскольку он положительно влияет на развитие и помогает осваивать новые навыки. Последние исследования показывают, что первые два дневных сна особенно важны для развития малышей. Многие малыши настолько активны в течение дня, что уже могут спать всю ночь, не просыпаясь. Если ваш малыш пока ещё просыпается по ночам, не беспокойтесь — это тоже совершенно нормально.') WHERE id = '71a3cc6c-7792-4d5e-b2d9-206c74922dd9';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш всё ещё находится на этапе перехода к твёрдой пище, и каждое новое блюдо, которое он пробует, становится для него настоящим открытием. Если вы практикуете BLW (самоприкорм), этот период может пройти для вас ещё веселее. При таком подходе малыш самостоятельно и естественным образом знакомится с едой, пробуя её на практике. Хотя этот процесс бывает немного неопрятным, малыш учится лучше различать вкус, структуру и запах продуктов. Благодаря этому он осваивает такие понятия, как размер, форма, вес и текстура, порой лучше, чем с помощью многих дорогих развивающих игрушек. Кроме того, развивая таким образом зрительно-моторную координацию, малыш закладывает основу для будущих навыков мелкой моторики. А самое главное — вы помогаете ему обрести уверенность в себе! 😊') WHERE id = '55eccf49-79d1-4243-b6f7-4417e0ce8446';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Для малыша уже можно приобрести обучающую чашку! 😊 В целом переход от бутылочки к чашке может быть непростым. Ведь малыш привык сосать пальчики ещё до рождения, а после рождения — грудь или бутылочку. Однако длительное использование бутылочки после определённого возраста может негативно повлиять на формирование полости рта и зубов малыша. Поэтому, чтобы постепенно отказаться от бутылочки и перейти к питью воды из обычной чашки, стоит использовать такие вспомогательные средства, как обучающая чашка. Обычно специалисты рекомендуют сокращать использование бутылочки с 9-го месяца. Однако если вы начнёте знакомить малыша с обучающей чашкой уже сейчас, переход будет более плавным.') WHERE id = 'b7595fc9-0616-4fd7-9f1c-a33935df996a';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Пищеварительная система малыша и работа его ферментов уже достигли более зрелого уровня. Это значит, что пришло время знакомить малыша с новыми продуктами! 😊 Например, после консультации с врачом в этом месяце в рацион малыша можно добавить оливки, перец, стручковую фасоль, цветную капусту, вигну и натуральные специи. Многие врачи считают, что в этом месяце в рацион малыша также можно вводить мучные изделия. Однако именно лечащий врач лучше всего знает особенности развития и физического роста малыша, поэтому мы рекомендуем не вводить эти продукты без его одобрения. Кроме того, вы можете разделить такие полезные овощи, как брокколи и цветная капуста, на небольшие кусочки, размягчить их на пару и предложить малышу. Позвольте ему брать эти овощи руками и есть самостоятельно. Приятного аппетита! 😊') WHERE id = '8e3dae32-3e2f-4ba0-b882-845b799e8f32';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Хотя у некоторых малышей прорезывание зубов не вызывает никаких проблем, для большинства этот период может быть довольно беспокойным. Обычно первые зубы появляются у малышей в возрасте 4-8 месяцев. Однако все малыши разные, поэтому сроки могут отличаться. Возможно, во рту вашего малыша уже давно появились зубки, похожие на жемчужинки. В период прорезывания зубов малыш будет тянуть в рот руки и всё, что найдёт. Так он пытается надавить на зудящие дёсны и ненадолго облегчить дискомфорт. Чтобы помочь малышу в этот период, вы можете давать ему твёрдые охлаждённые продукты, предварительно некоторое время подержав их в холодильнике. Также полезно всегда держать под рукой прорезыватель для зубов.') WHERE id = 'fb599c82-fab1-4307-ae9d-156ed7a53d22';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'По мере развития мелкой моторики малыш начинает увереннее захватывать предметы руками. В этот период вы можете заметить, как он пытается взять и использовать ложку, которую вы положили перед ним. Скорее всего, пока у него не всё получится, и через некоторое время, устав, он снова начнёт есть руками. Когда малыш разминает еду руками и изучает её, он привыкает к разной текстуре продуктов. Поэтому пока не нужно мешать малышу есть руками. Можно позволить ему немного испачкать всё вокруг, но во время таких тренировок вполне уместно надеть на него нагрудник и постелить покрытие под место, где он сидит. В пределах отведённого вами пространства позвольте малышу действовать так, как ему хочется, и старайтесь не вмешиваться без необходимости. 😊') WHERE id = '42d35bcf-5e08-438b-ab99-312796c2146c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш уже очень хочет стоять и ходить. 😊 На этом этапе вы можете задуматься о покупке его первой обуви. Правильно подобранная первая обувь для малыша, начинающего ходить, очень важна для развития стоп и позвоночника. Организм малыша и, соответственно, его скелет быстро растут, поэтому с началом ходьбы ему особенно нужна обувь, которая будет поддерживать это развитие. Однако важно не торопиться с её использованием. Специалисты рекомендуют малышам, которые только готовятся ходить, дома передвигаться босиком. Так малыш сможет лучше чувствовать поверхность и легче освоит ходьбу.') WHERE id = '073f0168-833f-4ba2-9b9a-e5fecf81e92a';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вероятно, как и многим мамам, вам очень нравится наблюдать за тем, как малыш ест. Однако его мозг сейчас особенно готов обрабатывать информацию, а сам малыш как никогда открыт к изучению эмоций. Поэтому, наблюдая за ним, очень важно следить за своей мимикой и реакциями. Например, если малыш вместо еды долго играет с пищей, ваша реакция может побудить его делать это ещё чаще. Точно так же, если он разбрасывает еду и радуется этому, необычная или резкая реакция с вашей стороны может только усугубить ситуацию. Бурная реакция очень интересна малышу, и он может начать разбрасывать еду ещё активнее, лишь бы снова её увидеть. Если вы не хотите, чтобы это вошло в привычку, можно на некоторое время убрать еду или покормить малыша самостоятельно.') WHERE id = '27035cad-7cd4-42d9-90d6-1a67f36eaafc';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вы думаете купить ходунки, чтобы помочь малышу научиться ходить? Однако покупать ходунки сразу после того, как малыш начал вставать на ноги, — большая ошибка. Исследования показали, что ходунки не помогают быстрее освоить ходьбу и, напротив, могут даже немного задержать этот процесс. У малышей, которых сажают в ходунки, могут возникнуть проблемы с позвоночником из-за неправильной позы и неравномерного распределения веса. Кроме того, давление на тазобедренные суставы и отталкивание пальцами ног, когда стопы ещё не достают до пола полностью, могут привести к неравномерному развитию мышц ног. Согласно исследованию, проведённому в Соединённых Штатах Америки, в 90% случаев травмы черепа, полученные малышами в течение первого года жизни, были связаны с происшествиями в ходунках. В нашей стране практически все врачи также единодушно выступают против использования ходунков.') WHERE id = '98a525b0-85c4-44ad-bd1f-bf93b8cfb809';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этот период основу рациона малыша постепенно начинает составлять твёрдая пища. Если вы всё ещё готовите некоторые продукты в виде пюре, теперь их следует предлагать кусочками, которые малыш сможет самостоятельно взять в руку. Это поможет развить навыки жевания и захвата, а также укрепить мышцы кистей и пальцев. Некоторые твёрдые продукты могут вызвать у малыша неожиданную реакцию. Поэтому новые продукты следует давать по отдельности и переходить к следующему продукту только спустя как минимум три дня, убедившись в отсутствии аллергической реакции. Обычно аллергия проявляется высыпаниями на коже малыша и изменением консистенции стула. Поэтому особенно важно не давать продукты с подтверждённым риском аллергии и знакомить малыша с новыми продуктами поочерёдно.') WHERE id = 'e4b85e6a-69c4-455d-9f99-5bcc0f9dfafa';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В период прорезывания зубов дёсны малыша становятся особенно чувствительными. Поэтому прикосновение ложки или пищи к дёснам может вызывать у него дискомфорт. Из-за этого малыш может отказываться от еды и даже от сосания. В целом снижение аппетита у малышей в период прорезывания зубов считается нормальным. Если это состояние не затягивается слишком надолго, беспокоиться не стоит. Если малыш отказывается от еды, ни в коем случае не кормите его насильно. Это может сформировать негативное отношение к пище и в будущем привести к проблемам с питанием. Чтобы легче пережить этот непростой период, вы можете предлагать малышу супы с йогуртом и свежевыжатые фруктовые соки.') WHERE id = '2db32885-0a8a-4d2a-bc4e-74c38a2ae5a1';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Для умственного развития малыша в этом месяце вы можете подобрать развивающие игрушки, соответствующие его возрасту. Особенно полезны сборно-разборные игрушки: они помогут ему сформировать представление о размере предметов. Ударяя игрушками рукой или стуча ими друг о друга, малыш будет открывать для себя новые звуки. Кроме того, соединяя детали, он будет активно развивать мелкую моторику. Но для этого вовсе не обязательно покупать дорогие игрушки. Например, вы можете вместе с малышом встать перед зеркалом, поочерёдно показывать его пальчики и называть их. Благодаря этому совместному занятию он сможет одновременно веселиться и учиться. Приятного времяпрепровождения! 😊') WHERE id = '39e8f843-aca7-42e5-9c7e-60770bf6f46e';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В период прорезывания зубов малыш может быть немного беспокойным. Спокойная и комфортная обстановка поможет облегчить этот процесс. Вы можете массировать дёсны малыша с помощью прорезывателя. Поскольку холодные предметы особенно хорошо успокаивают дёсны, отдавайте предпочтение наполненным жидкостью прорезывателям, которые можно хранить в холодильнике. В период прорезывания зубов режим питания и сна малыша может нарушиться. Это может ослабить его иммунную систему и повысить восприимчивость к инфекциям. Если вы заметите у малыша температуру выше 38 градусов, чрезмерное беспокойство или диарею, обязательно проконсультируйтесь с врачом. Вопреки распространённому мнению, эти симптомы не всегда могут быть связаны с прорезыванием зубов.') WHERE id = 'fd3bdcfc-5254-4510-b9f7-837898a606a0';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Для развития малыша очень важны близкие и качественные отношения с человеком, который за ним ухаживает. Многие родители не знают, как выстроить такие отношения и чем заниматься вместе с малышом. На самом деле даже простая игра в «ку-ку» помогает достичь этой цели. Игра поддерживает развитие умственных функций малыша и даже может оказывать терапевтическое воздействие. Совместные игры очень важны для его социального, эмоционального, физического, умственного и речевого развития. Кроме того, частое общение, песенки, колыбельные и даже искренняя улыбка стимулируют работу мозга малыша. Такая умственная активность вносит большой вклад в развитие мозга. Поэтому рекомендуем вам использовать для этого каждую возможность.') WHERE id = '8bad6496-e337-421c-9a82-679470e2639c';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'С наступлением 9-го месяца для развития жевательного рефлекса малышу следует предлагать больше пищи с неоднородной текстурой и небольшими кусочками. Поэтому продукты прикорма нужно готовить так, чтобы малыш мог легко брать их рукой и есть небольшими порциями. Благодаря этому он также будет развивать навыки самостоятельного приёма пищи. Если у малыша ещё не прорезались зубы, вы можете подумать, что без них он не сможет жевать. Но это не так: малыш может легко разминать дёснами такие продукты, как приготовленные овощи и фрукты. Поэтому пища с неоднородной текстурой и небольшими кусочками очень полезна для развития как навыков жевания, так и умения захватывать предметы. Для этого можно отдавать предпочтение продуктам, которые обычно используются в методе BLW (самостоятельного прикорма малыша).') WHERE id = '01dbba01-d87e-4015-9ad4-7f2d6dcf5bd6';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Режим питания малыша, который вы старались сформировать до этого момента, начиная с этого месяца может полностью измениться. Главная причина — стремление малыша к самостоятельности. В частности, если вместо пюре, которыми вы кормили его с ложки, малыш начинает есть самостоятельно, возможно, режим придётся выстраивать заново. Некоторым малышам сложно адаптироваться к этим изменениям. Поэтому малыш может решительно отказываться от предложенной еды или не хотеть есть с ложки. В такой ситуации важно проявить терпение и с пониманием отнестись к желанию малыша есть самостоятельно. Создайте для него подходящие условия и положите перед ним часть еды или всю порцию. Поначалу малыш может не уметь выбирать кусочки подходящего размера. Если вы почувствуете, что ему нужна помощь, поддержите его.') WHERE id = 'f4238778-2de3-481f-be1b-95a62161c1ba';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш быстро развивается благодаря играм и недавно приобретённым навыкам, например ползанию. Во время этих занятий различные мышцы его тела непрерывно работают. Игры, в которых задействованы мелкие группы мышц (например, нанизывание и снятие предметов, застёгивание пуговиц), способствуют развитию мелкой моторики. А работа крупных групп мышц создаёт основу для таких будущих навыков, как ходьба, прыжки и подъём по лестнице. Во время движения дыхание становится глубже и чаще, поэтому в организм малыша поступает больше кислорода. Кроме того, ускорение кровообращения при этих метаболических изменениях помогает доставлять к тканям больше питательных веществ. Поэтому можно с уверенностью сказать, что активные игры очень важны как для умственного, так и для физического развития малыша.') WHERE id = 'a8bbe7da-d7ed-4f71-bc81-f38a911b0996';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Начиная с этого месяца вы уже можете постепенно приобщать малыша к семейным трапезам. Мы не сомневаемся, что это будет очень весело! 😊 Привычка сидеть за столом вместе со всей семьёй помогает малышу почувствовать себя её частью и способствует его социализации. Кроме того, наблюдая, как едят другие члены семьи, он может охотнее принимать предложенную вами пищу. Иногда малыш может предпочесть не есть, а наблюдать за другими. В таких случаях не следует заставлять его. Сделайте небольшой перерыв, а затем снова предложите еду, чтобы он смог насытиться. Помните: то, что малыш сидит с вами за одним столом, не означает, что ему можно есть все домашние блюда. Особенно до достижения 3 лет важно давать малышу пищу, соответствующую возможностям его пищеварительной системы. Это поможет предотвратить многие проблемы со здоровьем в будущем.') WHERE id = '88647028-f25e-4ac9-8691-df916cfbec6e';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Хотя ваш малыш за короткое время прошёл большой путь в развитии, он всё ещё находится в младенческом возрасте. В этот период его любимое занятие — играть с частями своего тела и интересными предметами вокруг. Поэтому вы можете добавить в окружающее пространство яркие, звучащие и движущиеся предметы. Ещё одно прекрасное совместное занятие — после купания дать малышу возможность побыть без одежды и исследовать своё тело. Пусть он по очереди рассматривает пальчики ног и пробует познакомиться с ними, поднося ко рту. Исследование собственного тела помогает малышу осознать его границы и обрести уверенность в своих возможностях. После этого вы можете спеть ему песенку и сделать лёгкий расслабляющий массаж. Приятного времяпрепровождения! 😊') WHERE id = '15555c9e-8608-4e1e-a198-d3137b747de5';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Хотя ваш малыш уже не растёт так стремительно, как в первые месяцы, он продолжает активно расти и развиваться. Чтобы поддержать его развитие и сохранить здоровье, необходимо тщательно выбирать правильные продукты, соответствующие возрасту. Основную часть рациона по-прежнему должны составлять грудное молоко или детская молочная смесь. Дополнительно в меню можно включать не измельчённые в пюре, а мягкие кусочки фруктов и овощей, макаронные изделия из полезных злаков, домашнее печенье и другую легко перевариваемую пищу, которую малыш сможет держать в руке. Для быстро развивающихся мышц также важно правильно рассчитывать суточную потребность в белке. В рацион малыша можно включать рыбу, хорошо приготовленное мясо, чечевицу и фасоль. В этот период новые продукты следует вводить постепенно, по одному за раз, чтобы вовремя заметить возможную аллергическую реакцию.') WHERE id = '89bec816-5357-4575-bfde-092fc39e99a9';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Когда вы кормите малыша или сидите с ним за столом, следует убрать всё, что может отвлечь вас обоих. Это правило важно соблюдать не только сейчас, когда малыш активно познаёт мир, но и в дальнейшем. Совместные семейные трапезы, в которых участвует малыш, укрепляют общение в семье и помогают осознанно относиться к количеству съеденной пищи. Поэтому во время еды телевизор должен быть выключен, а в руках у малыша не должно быть телефона или планшета. Также держите малыша рядом во время подготовки к приёму пищи, чтобы он мог наблюдать за этим процессом. Благодаря развитой способности к подражанию для него это становится наглядным обучением. Мыть руки перед едой, всей семьёй накрывать на стол и убирать со стола, есть в приятной атмосфере — все эти привычки вы можете привить малышу без особых усилий, просто подавая ему пример.') WHERE id = '6cc71e92-a6d5-4d2d-bf55-9c74e24a03af';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Чтобы стимулировать умственное развитие малыша, вы можете играть с ним в игры, направленные на сенсорное развитие. На первый взгляд этот термин может показаться сложным, но на самом деле это один из лучших способов поддержать развитие малыша, обладающий даже терапевтическим эффектом. Такие игры помогают малышу активно познавать мир и развиваться в разных направлениях. Давайте объясню на простом примере: посадите малыша в центре и ходите вокруг него или встаньте перед ним и двигайте интересные предметы к себе и от себя. Можно положить малыша на спину и привязать к его ножке воздушные шарики, чтобы он пинал их. А для развития осязания познакомьте его с пушистыми поверхностями и материалами различной фактуры. Уверена, вашему малышу будет очень весело! 😊') WHERE id = '69152415-f884-484c-9ae7-d7f46f63d572';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Наблюдать за тем, как малыш растёт с невероятной скоростью, наверняка приносит огромное счастье и вам, и вашим близким. А что может быть прекраснее, когда к улыбкам малыша добавляется ещё и звонкий смех? 😊 В этот период малыш освоил множество новых навыков, и вам может быть непросто уследить за всеми изменениями. Например, теперь он может уверенно сидеть без посторонней помощи и поддержки. Учитывая, что он уже хорошо освоил ползание, вполне естественно, что ему хочется постоянно практиковать этот новый навык. Многие мамы отмечают, что в эти недели их малыши уже могут ненадолго вставать, держась за опору. Однако возраст, в котором малыш начинает вставать, может различаться в зависимости от развития мышц. Поэтому рекомендуем не заставлять малыша, пока он сам не начнёт пробовать это делать. 😊') WHERE id = 'e8faa9c0-7a4a-4a69-af25-bd6473750397';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Вы вступаете в период, когда малыш постепенно начинает наслаждаться ощущением самостоятельности. Если он уже начал ползать, впереди вас ждёт очень активное время. Если малыш ещё не ползает, вполне возможно, что он начнёт делать это в этом месяце. Благодаря ползанию теперь он может в любое время добраться до своих игрушек и играть с ними так, как ему хочется. Однако с этого возраста некоторым малышам начинают надоедать игрушки, с которыми они играли уже некоторое время. Поэтому, если привычные игрушки больше не привлекают его внимания, он может начать исследовать и перебирать содержимое всех шкафов и ящиков, которые обнаружит дома! Ведь теперь малыш ищет новые открытия и с большим интересом стремится познакомиться с каждым незнакомым предметом. Поэтому рекомендуем прежде всего позаботиться о безопасности малыша и по возможности постоянно присматривать за ним.') WHERE id = '5cb2c5a3-52c5-4353-87cf-7a048de6a6ae';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Всемирная организация здравоохранения (ВОЗ) регулярно публикует рекомендации в связи со вспышками заболеваний в разных странах Европейского региона. Согласно решениям Консультативного совета по иммунизации, в рамках стратегии контроля рассматривается вакцинация малышей в возрасте 9-11 месяцев. В соответствии с установленными правилами малышам старше 9 и младше 12 месяцев по рекомендации врача может быть сделана дополнительная прививка от кори. Эту дозу вводят с интервалом не менее четырёх недель после предыдущей прививки от кори. Поскольку эта доза не является плановой, в системе её обычно отмечают как дополнительную вакцинацию. Не забудьте уточнить наиболее достоверную информацию по этому вопросу у своего участкового врача.') WHERE id = 'b6d3d34d-c066-4ccc-9ded-29b02d7dbff4';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этом месяце во время планового осмотра врач может назначить некоторые анализы, чтобы оценить общее состояние малыша. Некоторые врачи назначают их и в 12-м месяце — это полностью зависит от темпов развития и роста малыша. Прежде всего врач измерит его рост и вес. Если вы заметите, что малыш набрал мало веса, не волнуйтесь. В этом возрасте прибавка в весе у малышей значительно замедляется, поскольку сейчас они активны как никогда и постоянно исследуют окружающий мир. Из-за непрерывного движения малыш расходует значительную часть получаемых калорий. Средний вес 9-месячного малыша составляет 8400 граммов, однако он может варьироваться от 6600 граммов до 10.000 граммов. Нормальной считается прибавка примерно на 250-600 граммов в месяц. Помните, что каждый малыш уникален, поэтому эти показатели могут отличаться у разных детей.') WHERE id = '4fead597-2916-4787-ba40-6051f71308e8';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В период введения прикорма мягкая пища в виде пюре помогает малышу привыкнуть к новому питанию. Однако его пищеварительная система и двигательные навыки уже некоторое время готовы и к более твёрдой пище. Например, нарезанный так, чтобы малыш мог держать его в руке, банан — прекрасный вариант, который легко подготовить и не нужно готовить. Яблоко — ещё один фрукт, который мамы часто предлагают малышам в этот период. Поскольку оно твёрже банана, его можно немного размягчить на пару, нарезать ломтиками и предлагать малышу. А на ужин отличным и очень вкусным вариантом станут кусочки специально приготовленных для него фрикаделек. Приятного аппетита! 😊') WHERE id = '366b1717-cbe7-42c2-825f-799a14209342';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Начиная с этого месяца вы можете заметить значительный прогресс в речевых навыках малыша. Почти все малыши в этот период начинают произносить множество осмысленных и пока ещё бессмысленных слов. Проснувшись и не увидев вас рядом, малыш может даже осознанно заплакать и позвать маму. Будьте готовы! 😊 Ведь в этот период его способность выражать себя значительно улучшилась. Например, когда вы проявляете к нему любовь, он может ответить вам тем же, а если расстроится, то даст вам это понять. Даже заметив, что вам грустно, малыш может подойти, наблюдать за вами и пытаться понять, что происходит. И хотя он пока ещё не умеет произносить многие слова, это вовсе не означает, что он не понимает их значения! 😊') WHERE id = '248a2f1b-11a9-4475-98d2-8e5dbff40ba0';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Хотя пищеварительная система малыша уже готова, для его здоровья в будущем очень важно пока не давать ему некоторые продукты. Например, одно из главных правил здорового питания — исключить из рациона малыша любые блюда из белой муки. Вы можете выбирать хлеб и макаронные изделия из цельнозерновой или ржаной муки. Кроме того, если в этот период не знакомить малыша с готовыми упакованными продуктами и сладостями, в дальнейшем вам будет гораздо проще формировать у него здоровые пищевые привычки. Например, не следует добавлять сахар в еду, думая, что малыш отказывается от некоторых овощей из-за их вкуса. Вкусовые предпочтения малыша ещё только формируются, поэтому ему может понравиться то, что кажется безвкусным вам. Если с самого начала давать малышу продукты, подслащённые сахаром, впоследствии ограничить их будет сложно, а иногда даже невозможно.') WHERE id = 'f1f06dfe-2ed9-46d2-a946-2592a01f6371';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если ваш малыш ещё не ползает на четвереньках, то, скорее всего, он уже начал тренироваться. Его попытки ползать во время таких тренировок наверняка покажутся вам очень забавными и интересными. 😊 Ведь малыш ещё не полностью освоил этот навык. Он будет искать наиболее удобное положение и, как многие малыши, поначалу попытается передвигаться, подтягиваясь только на руках. Это связано с тем, что мышцы рук у него пока сильнее мышц ног. Совсем скоро соотношение сил изменится в пользу ног, но малышу ещё нужно время. Поэтому не беспокойтесь, если увидите, как он ползёт по полу, а устав, ненадолго останавливается и отдыхает.') WHERE id = '53bde760-576b-4b67-a81b-6b925c4d3fda';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Начиная с этого месяца память малыша выходит на новый уровень развития. Поэтому вам следует быть внимательнее к некоторым моментам. Теперь малыш способен запоминать конкретную информацию, например где находятся его игрушки. Он также может вспомнить и повторить действия, которые видел некоторое время назад. Например, увидев за обедом, как вы пользуетесь ложкой, вечером он может попытаться есть ложкой, а не руками. Малыш запоминает коробку, в которую вы складываете игрушки, или ящик, где вы их храните, и при первой же возможности может отправиться за ними. Хотя всё это кажется прекрасными признаками развития, одновременно наступает период, связанный с некоторыми рисками. Например, увидев курящего человека, малыш впоследствии может найти предмет, похожий на сигарету, поднести его ко рту и попытаться повторить увиденное. Поэтому вам необходимо быть внимательнее, чем когда-либо, и стараться подавать малышу хороший пример.') WHERE id = 'e01a8401-6796-4fd1-8eb2-bb5e93fe04db';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш уже некоторое время не проводит дни так, как в период новорождённости, когда он в основном только ел и спал. С момента его появления на свет прошло ровно 9 месяцев, и теперь он с каждым днём всё активнее социализируется, общается с вами и окружающими людьми. У малыша начинают появляться собственные привычки, а значит, его характер формируется всё быстрее. Если у него сейчас нет скачка развития, прорезывания зубов или каких-либо проблем со здоровьем, возможно, ночной сон уже начал налаживаться. Поскольку днём малыш активно расходует энергию, ночью он обычно не просыпается или просыпается очень редко. Поэтому, если режим сна пока не сформировался, сейчас особенно подходящий период, чтобы его наладить. Возможно, вам нужно будет помочь малышу привыкнуть к определённому времени сна. Например, вы можете каждый день в одно и то же время относить его в комнату и некоторое время оставаться рядом, пока он не заснёт.') WHERE id = '4172e48e-6df4-4725-923e-07d5217e37c6';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Начиная с этого месяца 50% ежедневного рациона малыша составляет грудное молоко (или смесь), а остальные 50% — прикорм. Если до сих пор вы давали малышу прикорм два раза в день, теперь можете увеличить количество приёмов до трёх. Кроме того, если врач не рекомендовал иное, можно позволять малышу есть столько, сколько он хочет. Однако по мере увеличения количества прикорма малыш может получать меньше грудного молока, если вы продолжаете кормить его грудью. Чтобы этого избежать, можно покормить малыша грудью не более чем за час до приёма прикорма. Некоторые мамы добавляют сцеженное грудное молоко в приготовленные ими овощные и фруктовые пюре. Благодаря этому способу вы не только предлагаете малышу более полезную пищу, но и помогаете ему есть такие блюда с аппетитом.') WHERE id = 'da5cb5a7-cf3b-4e4d-80b2-ebbc83c6520d';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Избирательное восприятие малыша уже значительно развилось. Благодаря этому он может определить источник звука, даже не поворачивая голову в его поисках. Если это ещё не началось, с этого месяца малыш может стать настороженным по отношению к незнакомым людям и сторониться их. В этот период малыши способны демонстрировать самые разные и интересные реакции. Однако обычно незнакомые люди вызывают у них беспокойство, которое они выражают плачем. Для малыша это временный этап, поэтому не следует заставлять его контактировать с незнакомыми людьми, на которых он реагирует плачем. Особенно если в незнакомой обстановке малыш тревожится и не хочет идти к кому-то на руки, вам следует уважать его решение и просить окружающих поступать так же. Кроме того, совершенно естественно, если в этот период малыш хочет, чтобы рядом находились только вы и его папа. Поскольку страх разлуки усиливается, рекомендуем не оставлять малыша одного надолго, а при необходимости вообще не отходить от него.') WHERE id = '21e5fb9b-957f-4246-8c1d-e631e7b5dd81';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если к этому этапу ваш малыш ещё не научился ползать, вы можете помочь ему освоить этот навык. Один из самых популярных способов побудить малыша к ползанию — положить интересные предметы или его любимую игрушку на таком расстоянии, чтобы он мог до них дотянуться. Также важно, чтобы в течение дня малыш проводил достаточно времени на полу. Для этого положите его на поверхность, которая не будет ни слишком твёрдой, ни слишком мягкой, и позвольте ему свободно двигаться в пределах безопасной зоны. Развитие мышц спины также значительно помогает малышу научиться ползать. Для этого можно регулярно выкладывать его на животик. Кроме того, рекомендуем отказаться от таких приспособлений, как ходунки, поскольку они могут замедлить освоение навыка ползания.') WHERE id = 'c3473c70-f7b4-432f-afbf-5ede71de258f';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Добро пожаловать в месяцы, наполненные активными хлопотами! Кажется, ваш малыш родился только вчера... Как быстро летит время, правда? Пока вы начинаете представлять, как отметите его приближающийся день рождения, он уже в этом месяце может удивить вас, встав на ножки. В этом месяце малыш может начать самостоятельно стоять несколько секунд и делать один-два шага. Вместе с этим предметы, которые казались ему огромными, становятся привычнее, а уверенность в себе растёт. Некоторые малыши в этом месяце могут даже начать ходить. Однако пока ещё рано торопить события, и не следует заставлять малыша ходить. Но если он сам проявляет большое желание научиться ходить, вы наверняка задумываетесь, как поддержать его развитие. В таком случае по рекомендации врача можно присмотреться к каталке для первых шагов или игрушке-опоре для ходьбы.') WHERE id = '8ad14916-224e-43df-b050-f067ba32923b';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В этом месяце темпы развития малыша примерно такие же, как и в предыдущем. Не переживайте, если он растёт уже не так быстро, как в первые месяцы. Поскольку малыш стал очень активным, за этот месяц он может набрать в среднем 300-500 грамм. По данным ВОЗ, средний вес 10-месячного малыша составляет примерно 8800 грамм. Однако этот показатель может различаться в зависимости от пола, активности, веса при рождении и индивидуальных особенностей развития малыша. Поэтому ваш малыш может весить как 6500 грамм, так и более 12500 грамм. Начиная с этого месяца рост малыша в среднем продолжает увеличиваться на 1 см. Окружность головы растёт примерно такими же темпами.') WHERE id = '789568fd-44f2-4cb3-9877-cd0130c94687';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш уже очень активен. Он без конца улыбается, переворачивается, ползает и пытается говорить! 😊 Новые навыки, которые он приобретает с момента рождения, одновременно удивляют, волнуют и радуют вас. Попытки встать на ножки и переход к ходьбе — ещё один захватывающий этап развития... Как и всегда, в этот период главная поддержка малыша — вы и ваш супруг. Вместе вы можете помочь ему получать больше удовольствия от освоения ходьбы и смело делать шаги, чувствуя уверенность в себе. Учитывая, что в это время возможны небольшие происшествия, важно принять некоторые меры безопасности. Например, начните с того, чтобы не оставлять малыша одного на кровати, пеленальном столике, диване и других высоких поверхностях без необходимых мер предосторожности. 😊') WHERE id = 'b038be51-87de-40aa-81e8-34eb440fed27';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'На этом этапе ваш малыш должен продолжать получать грудное молоко или смесь 3-5 раз в день. Помните, что для полного перехода на твёрдую пищу ему ещё нужно время. В этот период можно составить для малыша рацион прикорма из 3 основных приёмов пищи и 3 перекусов. Если вы кормите грудью, можете давать малышу грудное молоко в течение дня столько, сколько он хочет. Малышам на искусственном вскармливании будет достаточно как минимум 200 ml смеси три раза в день. Некоторые мамы могут решить, что малыш уже получил достаточно грудного молока, и захотеть постепенно сократить кормления. Однако это ошибочное мнение, поскольку ваше молоко всё ещё приносит малышу большую пользу. Молочные железы изменяют состав молока в соответствии с потребностями растущего малыша. Например, в этом возрасте жирность грудного молока значительно выше, чем в первые месяцы.') WHERE id = '40235f48-568d-4e7c-b429-24fa27331c60';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Иногда аппетит малыша может внезапно усилиться или пропасть, он может совсем не хотеть спать или, наоборот, проспать несколько часов подряд. Даже его настроение может резко меняться. Если вам знакомы такие ситуации, причина одна: вы всё ещё переживаете период скачка развития! Этот период, который называют «кризисом», «скачком развития» или «периодом роста», может звучать пугающе из-за нарушения привычного режима. Но у всего этого есть причина: во время каждого скачка развития малыш приобретает новые навыки и делает важный шаг в умственном развитии. Одним словом, можно сказать: «Расти нелегко!» Поэтому, сосредоточившись на положительных сторонах этого периода и новых навыках малыша, вы сможете пройти его спокойнее. Например, во время этого скачка развития малыш начинает ревновать вас. Звучит очень мило, правда? Когда ваш супруг возвращается с работы, малыш может рассердиться, если вы его поцелуете, ведь он не хочет ни с кем делить вас.') WHERE id = 'b4a75895-ae96-4823-9d66-151563acf366';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если малыш часто болеет, не вините себя и не считайте, что вы что-то делаете не так. Иммунная система малыша ещё не полностью сформирована, поэтому простуда и грипп могут возникать довольно часто. Большинство малышей в первые два года жизни простужаются примерно десять раз. Этот процесс, который в первые месяцы может казаться сложным, обычно лишь временно вызывает у малыша дискомфорт. Ваша задача — помочь ему как можно легче пережить этот период и обеспечить максимальный комфорт. Например, во время болезни организму малыша требуется больше сна. Поэтому расслабляющий массаж после купания поможет ему гораздо легче уснуть. Если у малыша заложен нос, во время сна можно слегка приподнять изголовье. Помните, что при простуде потребность малыша в жидкости возрастает, поэтому важно давать ему достаточно воды, а также продолжать грудное вскармливание или кормление смесью.') WHERE id = '0c97a7c0-87cb-4c6d-bccc-18d59ae9a64f';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Поскольку двигательные навыки, эмоциональная сфера и умственное развитие малыша заметно продвинулись, он вступает в период повышенной активности. На этом этапе малыш может осваивать новые навыки, в том числе хватать всё, до чего способен дотянуться. Любой предмет, который ему по силам поднять, он может начать трясти, ударять им о другие предметы, ронять или бросать. Обнаружив, что ему хватает сил для таких действий, малыш может долго и не уставая повторять их. Поэтому помните, что сейчас необходимо быть особенно внимательной. Значительная часть травм головы происходит именно в эти месяцы. Чтобы обезопасить малыша, можно установить для него определённые границы в доме. Например, не позволяйте ему самостоятельно покидать комнату, в которой находитесь вы, и прежде всего уберите из неё предметы, способные причинить ему вред.') WHERE id = 'af4167d5-e075-447d-a653-bf92fb79d76e';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Пищеварительная система малыша уже достаточно развита, поэтому теперь он вполне может присоединиться к семейному завтраку. Например, после кормления грудью или вместе со стаканом смеси, если малыш находится на искусственном вскармливании, вы можете предложить ему сыр, оливки, зерновой хлеб и даже натуральное сливочное масло. Однако малыш ещё не готов есть абсолютно всё. Поэтому в этот период по-прежнему следует избегать баклажанов, яичного белка, мёда, коровьего и козьего молока, а также фруктов, известных как потенциальные аллергены. Чтобы свести риск аллергии у малыша к минимуму, рекомендуется избегать генетически модифицированных продуктов, продуктов, подвергавшихся интенсивной обработке пестицидами, а также пищи с вызывающими привыкание вкусовыми добавками и консервантами. После такой обработки продукты теряют свою натуральность и могут восприниматься обменом веществ малыша как чужеродные вещества. К продуктам, чаще всего вызывающим аллергию, относятся переработанные консервы, некоторые генетически модифицированные продукты из пшеницы, фрукты с остатками химических веществ и молочные продукты. Поэтому очень важно не давать малышу консервированные продукты и выбирать натуральные фрукты и овощи, чтобы снизить риск аллергии.') WHERE id = '7dcfd4f4-9aee-4c8d-9828-a2d3f2df221d';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если вам предстоит путешествие с малышом, будьте готовы к небольшим трудностям. Он уже хорошо привык к своему окружению, дому и членам семьи, которых видит каждый день, и у него сформировался определённый режим. Дорога, разлука с привычной обстановкой и новые места поначалу могут немного напугать малыша. Кроме того, большое количество незнакомых людей может вызвать у него чувство незащищённости и беспокойство. Чтобы успокоить малыша во время путешествия, возьмите с собой несколько вещей, которые смогут его отвлечь. Это могут быть книжки с картинками, звучащие игрушки, пальчиковые куклы и некоторые любимые продукты. Если, несмотря на всё это, малыш продолжает беспокоиться, поговорите с ним и постарайтесь объяснить происходящее, даже если он ещё не до конца понимает, что такое путешествие.') WHERE id = '4ae1b5f1-3350-4a7e-9ecb-70e54028f264';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Помимо питания, здоровья и физического развития малыша, не менее важно позаботиться о том, чтобы в будущем он получил хорошее образование. Образование имеет огромное значение для будущего малыша, и мы знаем, что вы уже много об этом думаете. Но знаете ли вы, что можно делать уже сейчас? Если вы ещё не знакомы с понятием Монтессори, мы хотели бы рассказать вам об этой образовательной системе. Система Монтессори — это метод, который учитывает индивидуальный темп обучения малыша, его способности и меняющиеся интересы. Если вы решите применять этот подход, подготовьте и аккуратно сгруппируйте вокруг малыша развивающие материалы. Это могут быть приспособления для завязывания и развязывания узлов, сортеры с фигурными блоками или разноцветные стаканчики, которые вставляются друг в друга. Важно правильно сгруппировать подготовленные материалы и разместить их там, где малыш сможет самостоятельно до них дотянуться.') WHERE id = 'b4fbd7bc-5bea-4328-9444-1bbb7e0b93ab';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Малыш вырос в мгновение ока, и завершение 9-го месяца, когда в его рационе помимо грудного молока уже появился прикорм, означает, что переходный этап в питании остался позади. Начиная с этого месяца вы можете знакомить малыша с мясом и рыбой, блюдами из пшеницы, различными крупами и яйцами. Белок особенно важен для питания малыша, мышцы которого быстро развиваются. Поэтому один раз в день обязательно предлагайте ему мясо или мясные продукты. Однако помните, что темпы развития у каждого малыша индивидуальны. В этот важный период одни малыши едят охотно и с аппетитом, а другие проявляют меньше интереса к пище. Даже отказ от новых продуктов на этом этапе считается нормальным. Поэтому внимательно наблюдайте за малышом и учитывайте его потребности. Продолжайте вводить каждый новый продукт по правилу трёх дней, отслеживая реакцию организма. По мере увеличения количества прикорма могут возникать запор, газообразование и рефлюкс — это также считается нормальным. Со временем эти неприятные проявления уменьшатся.') WHERE id = '38f9d9e1-4776-4187-abf9-e1f1ad116098';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'В течение этого месяца малышу необходимо давать не менее 500 ml грудного молока в день. Если грудного молока нет, после консультации с врачом следует подобрать наиболее подходящую смесь для последующего кормления. Пищеварительная система малыша уже достаточно развита для перехода от жидкой пищи к твёрдой. Однако, чтобы не перегружать кишечник, он должен получать не более 3 баночек детского прикорма в день. Если давать больше прикорма, малыш может не получать достаточного количества грудного молока — своей основной пищи. Установив баланс между твёрдой пищей и грудным молоком (или смесью для последующего кормления при его отсутствии), необходимо составить оптимальный рацион для здорового роста малыша. Важны не только количество пищи, но и здоровые способы её приготовления. Поэтому при приготовлении еды для малыша следует отдавать предпочтение таким способам, как приготовление на пару, варка или запекание в духовке.') WHERE id = '2fad46fb-e452-4335-9758-a95de808e8f1';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Ваш малыш уже некоторое время ползает, и ему, возможно, наскучило постоянно находиться в одной и той же обстановке. Особенно когда он видит, что все вокруг ходят, ему тоже захочется встать на ноги. Сначала он будет пытаться подняться, держась за опору. Возможно, первые попытки окажутся неудачными, а может быть, у него всё получится с первого раза. Это зависит от индивидуальных особенностей развития малыша и окружающей обстановки. Вы заметите, что сначала малыш пытается встать, держась за стоящую рядом мебель. Поняв, что у него получается, он начнёт пробовать стоять без опоры. Однако для этого ему понадобится ещё немного времени. Чтобы поддержать малыша на этом этапе, можно класть привлекающие его внимание игрушки на кресло, стул или другие предметы, за которые он сможет держаться.') WHERE id = '02985c47-f203-4125-957b-15eb60906ec2';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Переодевание непоседливого малыша, который полон энергии и постоянно находится в движении, может сильно утомлять вас, как и многих других мам. Скорее всего, малыш не любит одеваться, и каждое переодевание превращается для вас обоих в настоящую борьбу. 😊 Справиться с этой ситуацией помогут несколько хитростей. Поскольку малыш уже получает прикорм, он часто пачкает одежду. Поэтому при покупке одежды отдавайте предпочтение тканям, на которых не остаются пятна, — это значительно облегчит вам жизнь. Чтобы отвлечь малыша во время переодевания, можно дать ему любимую игрушку или интересный предмет. Также полезно выбирать футболки и рубашки с эластичной и достаточно широкой горловиной.') WHERE id = '80933d1b-7705-420b-8df2-38fff58443d1';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Уход за зубами малыша так же важен, как и для любого взрослого. Особенно важно, чтобы недавно появившиеся зубы росли здоровыми, ведь от этого зависит их состояние в будущем. Чтобы у малыша сформировалась привычка чистить зубы, следует начать уже сейчас и сделать это частью ежедневного ухода. В первое время у вас могут возникнуть вопросы о том, как правильно ухаживать за зубами малыша. После появления первого зуба его можно очищать марлей или силиконовой щёткой, надеваемой на палец. После 1 года можно дать малышу зубную щётку и, встав перед ним, показать, как правильно чистить зубы. Даже если сначала у него не будет получаться, подражая вам, он быстро научится. Однако важно помнить, что использовать зубную пасту пока рано.') WHERE id = '37f66307-1b67-498c-b0b6-20e87a8898b8';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Чтобы с очень активным малышом не произошёл несчастный случай, необходимо принять некоторые меры предосторожности. Например, следует сразу убирать упавшие на пол лекарства, орехи, оторвавшиеся пуговицы, монеты и другие мелкие предметы, которые малыш может проглотить. Острые углы стола, журнального столика и другой мебели могут быть опасны для малыша, который пытается встать, держась за опору. Поэтому такую мебель можно убрать из комнаты, где находится малыш, или установить на её углы специальные защитные накладки. Для любознательного малыша, который стремится всё исследовать, можно приобрести защитные заглушки для электрических розеток. Следует убрать глубокие корзины для игрушек, в которые малыш может упасть, целлофановые пакеты, которые он может надеть на голову, а также провода, создающие риск удушения. Кроме того, потенциальные опасности помогут устранить закрытые двери и защитные замки на окнах, шкафах и выдвижных ящиках.') WHERE id = '6dba7d69-27ca-40ac-b3c1-c74bcff813bb';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Размять картофель, который вы так долго готовили, опустить руку в суп, бросить на пол предложенную морковь... Вам всё это знакомо? Не переживайте, вы не одиноки! 😊 На этом этапе приём пищи для малыша — это не только утоление голода, но и увлекательная игра. Вас может озадачивать то, что тщательно приготовленная еда оказывается не в животике малыша, а разбросанной вокруг. Однако строгая реакция на такое поведение может отбить у него интерес к еде. Поэтому вам может захотеться забрать у малыша еду и покормить его самостоятельно. И всё же важно помнить, что это лишь один из этапов развития и благодаря таким исследованиям малыш узнаёт новое.') WHERE id = 'cffb22db-240d-4023-8834-7c4c580e8149';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Если вы кормите малыша грудью или молочной смесью, на этом этапе примерно половина его суточной потребности в калориях по-прежнему покрывается за счёт молока. В среднем грудное молоко состоит из 88% воды, 55% жиров, 37% углеводов и 8% белков. Основной углевод в грудном молоке — лактоза. Она обеспечивает около 40% калорийности молока. Этот богатый источник энергии также создаёт в кишечнике малыша кислую среду, препятствующую размножению вредных бактерий. Способствуя росту полезных кишечных бактерий, лактоза помогает формированию сбалансированной микрофлоры кишечника. Поэтому важно продолжать грудное вскармливание малыша, который всё ещё находится в периоде активного развития, так долго, как вы можете. При отсутствии грудного молока специалисты рекомендуют таким же образом продолжать давать последующие молочные смеси как минимум до 1 года.') WHERE id = '005de367-3aa8-4500-87f0-c7f5b37b1fe4';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Как же быстро вырос ваш малыш, правда? Оглядываясь назад, вы видите, какой большой путь уже пройден, хотя время пролетело незаметно. С момента рождения малыша ещё не прошло и 1 года, но за это время он добился невероятных успехов в развитии. Например, малыш уже перешёл от плача к произнесению отдельных звуков, а затем — к осмысленным словам. Теперь всё ближе время, когда он начнёт говорить. Вы можете помочь ему подготовиться к этому стремительно приближающемуся этапу. Например, дома или на улице называйте каждый предмет, которым вы пользуетесь или который встречаете. Чтобы малышу было легче запоминать названия предметов, можно использовать звукоподражания. Например, увидев собаку, укажите на неё и скажите «собака», а затем добавьте: «гав-гав».') WHERE id = '19fabca3-1b22-4b94-9659-be47ebeb9069';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Совершенно естественно, если в период введения твёрдой пищи малыш не хочет есть некоторые полезные овощи. Ведь его вкусовые предпочтения уже давно начали формироваться. Поэтому он может отказываться от продуктов, вкус которых ему не нравится. В таких случаях некоторые врачи рекомендуют добавлять хорошо знакомое малышу грудное молоко или молочную смесь. Молоко делает вкус более привычным, и малыш может согласиться съесть продукт, от которого раньше отказывался. Для этого сначала добавьте совсем небольшое количество продукта в молоко, чтобы его вкус не изменился, а затем постепенно увеличивайте порцию. Например, если малыш не любит морковь, попробуйте этот рецепт: смешайте немного тёплой воды с овсяной мукой и сварите. Когда смесь загустеет, добавьте сливочное масло, а после того как она немного остынет, разведите её грудным молоком или молочной смесью. Скорее всего, малыш даже не заметит небольшое количество добавленной моркови. Приятного аппетита!') WHERE id = 'b6baae80-bfde-4969-a04d-a53ffef941a8';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Со временем, если малыша ничего не беспокоит, режим его сна станет более упорядоченным. Если ваш малыш часто просыпается и с трудом засыпает снова, у нас для вас хорошая новость: начиная с этого месяца его сон будет прерываться гораздо реже! 😊 Такой режим налаживается по многим причинам. Например, фазы сна в мозге малыша теперь завершаются в течение более длительного времени. Благодаря этому он будет реже просыпаться, особенно ночью, и легче засыпать снова после пробуждения. Иногда в периоды скачков развития или в дни, когда малыша что-то беспокоит, ему может быть трудно заснуть. В такой ситуации рекомендуем успокоить малыша и провести с ним время в полутёмной комнате. Тёплая расслабляющая ванна перед сном, а затем массаж с маслами также помогут малышу легче заснуть.') WHERE id = '9263dfdf-7d11-40a3-a89c-aa51842213c4';
UPDATE public.baby_daily_info SET info_ru = COALESCE(info_ru, 'Уход за зубами малыша очень важен. Поскольку его зубы очень чувствительны, необходимо тщательно выбирать средства для ухода за ними. Прежде всего, выбирая зубную щётку, обязательно убедитесь, что она подходит для полости рта малыша. Ведь щётки для взрослых, какими бы качественными они ни были, не соответствуют особенностям полости рта малыша. Кроме того, дёсны малыша пока очень чувствительны, поэтому следует отдавать предпочтение щёткам с мягкой щетиной. В этот период вам могут пригодиться специальные детские зубные щётки, которые надеваются на палец. Если малыш не любит чистить зубы, во время ухода можно отвлечь его любимыми игрушками. Помимо домашнего ухода за полостью рта, очень важно регулярно водить малыша к стоматологу, которого порекомендует его врач. Это поможет сохранить зубы здоровыми в будущем.') WHERE id = '56bcb0b3-2ef0-42fc-b5f4-45a3b8d99519';